	public abstract class EscherRecord : ICloneable
	{
		internal class DeleteEscherRecordHeader
		{
			private short options;

			private short recordId;

			private int remainingBytes;

			public short Options => options;

			public virtual short RecordId => recordId;

			public int RemainingBytes => remainingBytes;

			private DeleteEscherRecordHeader()
			{
			}

			public static DeleteEscherRecordHeader ReadHeader(byte[] data, int offset)
			{
				DeleteEscherRecordHeader deleteEscherRecordHeader = new DeleteEscherRecordHeader();
				deleteEscherRecordHeader.options = LittleEndian.GetShort(data, offset);
				deleteEscherRecordHeader.recordId = LittleEndian.GetShort(data, offset + 2);
				deleteEscherRecordHeader.remainingBytes = LittleEndian.GetInt(data, offset + 4);
				return deleteEscherRecordHeader;
			}

			public override string ToString()
			{
				return "EscherRecordHeader{options=" + options + ", recordId=" + recordId + ", remainingBytes=" + remainingBytes + "}";
			}
		}

		private static BitField fInstance = BitFieldFactory.GetInstance(65520);

		private static BitField fVersion = BitFieldFactory.GetInstance(15);

		private short _options;

		private short _recordId;

		public bool IsContainerRecord => Version == 15;

		internal virtual short Options
		{
			get
			{
				return _options;
			}
			set
			{
				Version = fVersion.GetShortValue(value);
				Instance = fInstance.GetShortValue(value);
				_options = value;
			}
		}

		public abstract int RecordSize { get; }

		public virtual short RecordId
		{
			get
			{
				return _recordId;
			}
			set
			{
				_recordId = value;
			}
		}

		public virtual List<EscherRecord> ChildRecords
		{
			get
			{
				return new List<EscherRecord>();
			}
			set
			{
				throw new ArgumentException("This record does not support child records.");
			}
		}

		public abstract string RecordName { get; }

		public virtual short Instance
		{
			get
			{
				return fInstance.GetShortValue(_options);
			}
			set
			{
				_options = fInstance.SetShortValue(_options, value);
			}
		}

		public virtual short Version
		{
			get
			{
				return fVersion.GetShortValue(_options);
			}
			set
			{
				_options = fVersion.SetShortValue(_options, value);
			}
		}

		public EscherRecord()
		{
		}

		public int FillFields(byte[] data, IEscherRecordFactory f)
		{
			return FillFields(data, 0, f);
		}

		public abstract int FillFields(byte[] data, int offset, IEscherRecordFactory recordFactory);

		protected int ReadHeader(byte[] data, int offset)
		{
			_options = LittleEndian.GetShort(data, offset);
			_recordId = LittleEndian.GetShort(data, offset + 2);
			return LittleEndian.GetInt(data, offset + 4);
		}

		protected static short ReadInstance(byte[] data, int offset)
		{
			short @short = LittleEndian.GetShort(data, offset);
			return fInstance.GetShortValue(@short);
		}

		public byte[] Serialize()
		{
			byte[] array = new byte[RecordSize];
			Serialize(0, array);
			return array;
		}

		public int Serialize(int offset, byte[] data)
		{
			return Serialize(offset, data, new NullEscherSerializationListener());
		}

		public abstract int Serialize(int offset, byte[] data, EscherSerializationListener listener);

		public object Clone()
		{
			throw new Exception("The class " + GetType().Name + " needs to define a clone method");
		}

		public EscherRecord GetChild(int index)
		{
			return ChildRecords[index];
		}

		public virtual void Display(int indent)
		{
			for (int i = 0; i < indent * 4; i++)
			{
				Console.Write(' ');
			}
			Console.WriteLine(RecordName);
		}

		public virtual string ToXml(string tab)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(tab).Append("<").Append(GetType().Name)
				.Append(">\n")
				.Append(tab)
				.Append("\t")
				.Append("<RecordId>0x")
				.Append(HexDump.ToHex(_recordId))
				.Append("</RecordId>\n")
				.Append(tab)
				.Append("\t")
				.Append("<Options>")
				.Append(_options)
				.Append("</Options>\n")
				.Append(tab)
				.Append("</")
				.Append(GetType().Name)
				.Append(">\n");
			return stringBuilder.ToString();
		}

		protected string FormatXmlRecordHeader(string className, string recordId, string version, string instance)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("<").Append(className).Append(" recordId=\"0x")
				.Append(recordId)
				.Append("\" version=\"0x")
				.Append(version)
				.Append("\" instance=\"0x")
				.Append(instance)
				.Append("\" size=\"")
				.Append(RecordSize)
				.Append("\">\n");
			return stringBuilder.ToString();
		}

		public string ToXml()
		{
			return ToXml("");
		}
	}
	public abstract class AbstractEscherOptRecord : EscherRecord
	{
		internal class EscherPropertyComparer : IComparer<EscherProperty>
		{
			public int Compare(EscherProperty p1, EscherProperty p2)
			{
				short propertyNumber = p1.PropertyNumber;
				short propertyNumber2 = p2.PropertyNumber;
				if (propertyNumber >= propertyNumber2)
				{
					if (propertyNumber != propertyNumber2)
					{
						return 1;
					}
					return 0;
				}
				return -1;
			}
		}

		protected List<EscherProperty> properties = new List<EscherProperty>();

		public List<EscherProperty> EscherProperties => properties;

		private int PropertiesSize
		{
			get
			{
				int num = 0;
				foreach (EscherProperty property in properties)
				{
					num += property.PropertySize;
				}
				return num;
			}
		}

		public override int RecordSize => 8 + PropertiesSize;

		public void AddEscherProperty(EscherProperty prop)
		{
			properties.Add(prop);
		}

		public override int FillFields(byte[] data, int offset, IEscherRecordFactory recordFactory)
		{
			int num = ReadHeader(data, offset);
			short numProperties = EscherRecord.ReadInstance(data, offset);
			int offset2 = offset + 8;
			EscherPropertyFactory escherPropertyFactory = new EscherPropertyFactory();
			properties = escherPropertyFactory.CreateProperties(data, offset2, numProperties);
			return num + 8;
		}

		public EscherProperty GetEscherProperty(int index)
		{
			return properties[index];
		}

		public EscherProperty Lookup(int propId)
		{
			foreach (EscherProperty property in properties)
			{
				if (property.PropertyNumber == propId)
				{
					return property;
				}
			}
			return null;
		}

		public override int Serialize(int offset, byte[] data, EscherSerializationListener listener)
		{
			listener.BeforeRecordSerialize(offset, RecordId, this);
			LittleEndian.PutShort(data, offset, Options);
			LittleEndian.PutShort(data, offset + 2, RecordId);
			LittleEndian.PutInt(data, offset + 4, PropertiesSize);
			int num = offset + 8;
			foreach (EscherProperty property in properties)
			{
				num += property.SerializeSimplePart(data, num);
			}
			foreach (EscherProperty property2 in properties)
			{
				num += property2.SerializeComplexPart(data, num);
			}
			listener.AfterRecordSerialize(num, RecordId, num - offset, this);
			return num - offset;
		}

		public void SortProperties()
		{
			properties.Sort(new EscherPropertyComparer());
		}

		public void SetEscherProperty(EscherProperty value)
		{
			List<EscherProperty> list = new List<EscherProperty>();
			IEnumerator<EscherProperty> enumerator = properties.GetEnumerator();
			while (enumerator.MoveNext())
			{
				EscherProperty current = enumerator.Current;
				if (current.Id == value.Id)
				{
					list.Add(current);
				}
			}
			foreach (EscherProperty item in list)
			{
				EscherProperties.Remove(item);
			}
			properties.Add(value);
			SortProperties();
		}

		public void RemoveEscherProperty(int num)
		{
			List<EscherProperty> list = new List<EscherProperty>();
			IEnumerator<EscherProperty> enumerator = EscherProperties.GetEnumerator();
			while (enumerator.MoveNext())
			{
				EscherProperty current = enumerator.Current;
				if (current.PropertyNumber == num)
				{
					list.Add(current);
				}
			}
			foreach (EscherProperty item in list)
			{
				EscherProperties.Remove(item);
			}
		}

		public override string ToString()
		{
			string newLine = Environment.NewLine;
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(GetType().Name);
			stringBuilder.Append(":");
			stringBuilder.Append(newLine);
			stringBuilder.Append("  isContainer: ");
			stringBuilder.Append(base.IsContainerRecord);
			stringBuilder.Append(newLine);
			stringBuilder.Append("  version: 0x");
			stringBuilder.Append(HexDump.ToHex(Version));
			stringBuilder.Append(newLine);
			stringBuilder.Append("  instance: 0x");
			stringBuilder.Append(HexDump.ToHex(Instance));
			stringBuilder.Append(newLine);
			stringBuilder.Append("  recordId: 0x");
			stringBuilder.Append(HexDump.ToHex(RecordId));
			stringBuilder.Append(newLine);
			stringBuilder.Append("  numchildren: ");
			stringBuilder.Append(ChildRecords.Count);
			stringBuilder.Append(newLine);
			stringBuilder.Append("  properties:");
			stringBuilder.Append(newLine);
			foreach (EscherProperty property in properties)
			{
				stringBuilder.Append("    " + property.ToString() + newLine);
			}
			return stringBuilder.ToString();
		}

		public override string ToXml(string tab)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(tab).Append(FormatXmlRecordHeader(GetType().Name, HexDump.ToHex(RecordId), HexDump.ToHex(Version), HexDump.ToHex(Instance)));
			foreach (EscherProperty escherProperty in EscherProperties)
			{
				stringBuilder.Append(escherProperty.ToXml(tab + "\t"));
			}
			stringBuilder.Append(tab).Append("</").Append(GetType().Name)
				.Append(">\n");
			return stringBuilder.ToString();
		}
	}
