namespace NPOI.HPSF
{
	public class Array
	{
		internal class ArrayDimension
		{
			public const int SIZE = 8;

			private int _indexOffset;

			internal long _size;

			public ArrayDimension(byte[] data, int offset)
			{
				_size = LittleEndian.GetUInt(data, offset);
				_indexOffset = LittleEndian.GetInt(data, offset + 4);
			}
		}

		internal class ArrayHeader
		{
			private ArrayDimension[] _dimensions;

			internal int _type;

			public long NumberOfScalarValues
			{
				get
				{
					long num = 1L;
					ArrayDimension[] dimensions = _dimensions;
					foreach (ArrayDimension arrayDimension in dimensions)
					{
						num *= arrayDimension._size;
					}
					return num;
				}
			}

			public int Size => 8 + _dimensions.Length * 8;

			public int Type => _type;

			public ArrayHeader(byte[] data, int startOffset)
			{
				int num = startOffset;
				_type = LittleEndian.GetInt(data, num);
				num += 4;
				long uInt = LittleEndian.GetUInt(data, num);
				num += 4;
				if (1 > uInt || uInt > 31)
				{
					throw new IllegalPropertySetDataException("Array dimension number " + uInt + " is not in [1; 31] range");
				}
				int num2 = (int)uInt;
				_dimensions = new ArrayDimension[num2];
				for (int i = 0; i < num2; i++)
				{
					_dimensions[i] = new ArrayDimension(data, num);
					num += 8;
				}
			}
		}

		private ArrayHeader _header;

		private TypedPropertyValue[] _values;

		public Array()
		{
		}

		public Array(byte[] data, int offset)
		{
			Read(data, offset);
		}

		public int Read(byte[] data, int startOffset)
		{
			int num = startOffset;
			_header = new ArrayHeader(data, num);
			num += _header.Size;
			long numberOfScalarValues = _header.NumberOfScalarValues;
			if (numberOfScalarValues > int.MaxValue)
			{
				throw new InvalidOperationException("Sorry, but POI can't store array of properties with size of " + numberOfScalarValues + " in memory");
			}
			int num2 = (int)numberOfScalarValues;
			_values = new TypedPropertyValue[num2];
			int type = _header._type;
			if (type == 12)
			{
				for (int i = 0; i < num2; i++)
				{
					TypedPropertyValue typedPropertyValue = new TypedPropertyValue();
					num += typedPropertyValue.Read(data, num);
				}
			}
			else
			{
				for (int j = 0; j < num2; j++)
				{
					TypedPropertyValue typedPropertyValue2 = new TypedPropertyValue(type, null);
					num += typedPropertyValue2.ReadValuePadded(data, num);
				}
			}
			return num - startOffset;
		}
	}
	internal class Blob
	{
		private byte[] _value;

		public int Size => 4 + _value.Length;

		public Blob(byte[] data, int offset)
		{
			int @int = LittleEndian.GetInt(data, offset);
			if (@int == 0)
			{
				_value = new byte[0];
			}
			else
			{
				_value = LittleEndian.GetByteArray(data, offset + 4, @int);
			}
		}
	}
	public class ClipboardData
	{
		private int _format;

		private byte[] _value;

		public int Size => 8 + _value.Length;

		public byte[] Value => _value;

		public ClipboardData(byte[] data, int offset)
		{
			int @int = LittleEndian.GetInt(data, offset);
			if (@int < 4)
			{
				_format = 0;
				_value = new byte[0];
			}
			else
			{
				_format = LittleEndian.GetInt(data, offset + 4);
				_value = LittleEndian.GetByteArray(data, offset + 8, @int - 4);
			}
		}

		public byte[] ToByteArray()
		{
			byte[] array = new byte[Size];
			LittleEndian.PutInt(array, 0, 4 + _value.Length);
			LittleEndian.PutInt(array, 4, _format);
			System.Array.Copy(_value, 0, array, 8, _value.Length);
			return array;
		}

		public int Write(Stream out1)
		{
			LittleEndian.PutInt(4 + _value.Length, out1);
			LittleEndian.PutInt(_format, out1);
			out1.Write(_value, 0, _value.Length);
			return 8 + _value.Length;
		}
	}
	public class CodePageString
	{
		private byte[] _value;

		public int Size => 4 + _value.Length;

		public CodePageString(byte[] data, int startOffset)
		{
			int num = startOffset;
			int @int = LittleEndian.GetInt(data, num);
			num += 4;
			_value = LittleEndian.GetByteArray(data, num, @int);
			if (@int != 0 && _value[@int - 1] != 0)
			{
				Console.WriteLine("CodePageString started at offset #" + num + " is not NULL-terminated");
			}
		}

		public CodePageString(string aString, int codepage)
		{
			SetJavaValue(aString, codepage);
		}

		public string GetJavaValue(int codepage)
		{
			string text = ((codepage != -1) ? Encoding.GetEncoding(codepage).GetString(_value) : Encoding.UTF8.GetString(_value));
			int num = text.IndexOf('\0');
			if (num == -1)
			{
				return text;
			}
			_ = text.Length - 1;
			return text.Substring(0, num);
		}

		public void SetJavaValue(string aString, int codepage)
		{
			if (codepage == -1)
			{
				_value = Encoding.UTF8.GetBytes(aString + "\0");
			}
			else
			{
				_value = Encoding.GetEncoding(codepage).GetBytes(aString + "\0");
			}
		}

		public int Write(Stream out1)
		{
			LittleEndian.PutInt(_value.Length, out1);
			out1.Write(_value, 0, _value.Length);
			return 4 + _value.Length;
		}
	}
