		public GUID(byte[] data, int offset)
		{
			_data1 = LittleEndian.GetInt(data, offset);
			_data2 = LittleEndian.GetShort(data, offset + 4);
			_data3 = LittleEndian.GetShort(data, offset + 6);
			_data4 = LittleEndian.GetLong(data, offset + 8);
		}
