	public class VariantBool
	{
		public const int SIZE = 2;

		private bool _value;

		public bool Value
		{
			get
			{
				return _value;
			}
			set
			{
				_value = value;
			}
		}

		public VariantBool(byte[] data, int offset)
		{
			_value = LittleEndian.GetShort(data, offset) != 0;
		}
	}
	public class Vector
	{
		private short _type;

		private TypedPropertyValue[] _values;

		public TypedPropertyValue[] Values => _values;

		public Vector(byte[] data, int startOffset, short type)
		{
			_type = type;
			Read(data, startOffset);
		}

		public Vector(short type)
		{
			_type = type;
		}

		public int Read(byte[] data, int startOffset)
		{
			int num = startOffset;
			long uInt = LittleEndian.GetUInt(data, num);
			num += 4;
			if (uInt > int.MaxValue)
			{
				throw new InvalidOperationException("Vector is too long -- " + uInt);
			}
			int num2 = (int)uInt;
			_values = new TypedPropertyValue[num2];
			if (_type == 12)
			{
				for (int i = 0; i < num2; i++)
				{
					TypedPropertyValue typedPropertyValue = new TypedPropertyValue();
					num += typedPropertyValue.Read(data, num);
					_values[i] = typedPropertyValue;
				}
			}
			else
			{
				for (int j = 0; j < num2; j++)
				{
					TypedPropertyValue typedPropertyValue2 = new TypedPropertyValue(_type, null);
					num += typedPropertyValue2.ReadValue(data, num);
					_values[j] = typedPropertyValue2;
				}
			}
			return num - startOffset;
		}
	}
	public class VersionedStream
	{
		private GUID _versionGuid;

		private IndirectPropertyName _streamName;

		public int Size => 16 + _streamName.Size;

		public VersionedStream(byte[] data, int offset)
		{
			_versionGuid = new GUID(data, offset);
			_streamName = new IndirectPropertyName(data, offset + 16);
		}
	}
