namespace NPOI.HSSF.Extractor
{
	public class OldExcelExtractor
	{
		private RecordInputStream ris;

		private Stream streamInput;

		private NPOIFSFileSystem fsInput;

		private int biffVersion;

		private int fileType;

		public int BiffVersion => biffVersion;

		public int FileType => fileType;

		public string Text
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder();
				CodepageRecord codePage = null;
				while (ris.HasNextRecord)
				{
					int nextSid = ris.GetNextSid();
					ris.NextRecord();
					switch (nextSid)
					{
					case 133:
					{
						OldSheetRecord oldSheetRecord = new OldSheetRecord(ris);
						oldSheetRecord.SetCodePage(codePage);
						stringBuilder.Append("Sheet: ");
						stringBuilder.Append(oldSheetRecord.Sheetname);
						stringBuilder.Append('\n');
						break;
					}
					case 4:
					case 516:
					{
						OldLabelRecord oldLabelRecord = new OldLabelRecord(ris);
						oldLabelRecord.SetCodePage(codePage);
						stringBuilder.Append(oldLabelRecord.Value);
						stringBuilder.Append('\n');
						break;
					}
					case 7:
					case 519:
					{
						OldStringRecord oldStringRecord = new OldStringRecord(ris);
						oldStringRecord.SetCodePage(codePage);
						stringBuilder.Append(oldStringRecord.GetString());
						stringBuilder.Append('\n');
						break;
					}
					case 515:
					{
						NumberRecord numberRecord = new NumberRecord(ris);
						handleNumericCell(stringBuilder, numberRecord.Value);
						break;
					}
					case 6:
					case 518:
					case 1030:
						if (biffVersion == 5)
						{
							FormulaRecord formulaRecord = new FormulaRecord(ris);
							if (formulaRecord.CachedResultType == CellType.Numeric)
							{
								handleNumericCell(stringBuilder, formulaRecord.Value);
							}
						}
						else
						{
							OldFormulaRecord oldFormulaRecord = new OldFormulaRecord(ris);
							if (oldFormulaRecord.GetCachedResultType() == CellType.Numeric)
							{
								handleNumericCell(stringBuilder, oldFormulaRecord.Value);
							}
						}
						break;
					case 638:
					{
						RKRecord rKRecord = new RKRecord(ris);
						handleNumericCell(stringBuilder, rKRecord.RKNumber);
						break;
					}
					case 66:
						codePage = new CodepageRecord(ris);
						break;
					default:
						ris.ReadFully(new byte[ris.Remaining]);
						break;
					}
				}
				ris = null;
				Close();
				return stringBuilder.ToString();
			}
		}

		public OldExcelExtractor(Stream input)
		{
			BufferedStream bufferedStream = new BufferedStream(input, 8);
			if (NPOIFSFileSystem.HasPOIFSHeader(bufferedStream))
			{
				Open(new NPOIFSFileSystem(bufferedStream));
			}
			else
			{
				Open(bufferedStream);
			}
		}

		public OldExcelExtractor(FileInfo f)
		{
			try
			{
				Open(new NPOIFSFileSystem(f, readOnly: true));
			}
			catch (OldExcelFormatException)
			{
				Open(new FileStream(f.FullName, FileMode.Open, FileAccess.Read));
			}
			catch (NotOLE2FileException)
			{
				Open(new FileStream(f.FullName, FileMode.Open, FileAccess.Read));
			}
		}

		public OldExcelExtractor(NPOIFSFileSystem fs)
		{
			Open(fs);
		}

		public OldExcelExtractor(DirectoryNode directory)
		{
			Open(directory);
		}

		private void Open(Stream biffStream)
		{
			streamInput = biffStream;
			ris = new RecordInputStream(biffStream);
			Prepare();
		}

		private void Open(NPOIFSFileSystem fs)
		{
			fsInput = fs;
			Open(fs.Root);
		}

		private void Open(DirectoryNode directory)
		{
			DocumentNode documentNode = (DocumentNode)directory.GetEntry("Book");
			if (documentNode == null)
			{
				throw new IOException("No Excel 5/95 Book stream found");
			}
			ris = new RecordInputStream(directory.CreateDocumentInputStream(documentNode));
			Prepare();
		}

		public static void main(string[] args)
		{
			if (args.Length < 1)
			{
				Console.WriteLine("Use:");
				Console.WriteLine("   OldExcelExtractor <filename>");
			}
			else
			{
				OldExcelExtractor oldExcelExtractor = new OldExcelExtractor(new FileInfo(args[0]));
				Console.WriteLine(oldExcelExtractor.Text);
				oldExcelExtractor.Close();
			}
		}

		private void Prepare()
		{
			if (!ris.HasNextRecord)
			{
				throw new ArgumentException("File Contains no records!");
			}
			ris.NextRecord();
			int sid = ris.Sid;
			switch (sid)
			{
			case 9:
				biffVersion = 2;
				break;
			case 521:
				biffVersion = 3;
				break;
			case 1033:
				biffVersion = 4;
				break;
			case 2057:
				biffVersion = 5;
				break;
			default:
				throw new ArgumentException("File does not begin with a BOF, found sid of " + sid);
			}
			BOFRecord bOFRecord = new BOFRecord(ris);
			fileType = (int)bOFRecord.Type;
		}

		protected void handleNumericCell(StringBuilder text, double value)
		{
			text.Append(value);
			text.Append('\n');
		}

		public void Close()
		{
			if (streamInput != null)
			{
				try
				{
					streamInput.Close();
				}
				catch (IOException)
				{
				}
				streamInput = null;
			}
			if (fsInput != null)
			{
				try
				{
					fsInput.Close();
				}
				catch (Exception)
				{
				}
				fsInput = null;
			}
		}
	}
}
namespace NPOI.HSSF.Record
{
	public abstract class RecordBase
	{
		public abstract int RecordSize { get; }

		public abstract int Serialize(int offset, byte[] data);
	}
}
namespace NPOI.HSSF.Record.Aggregates
{
	[Serializable]
	public abstract class RecordAggregate : RecordBase
	{
		private class SerializingRecordVisitor : RecordVisitor
		{
			private byte[] _data;

			private int _startOffset;

			private int _countBytesWritten;

			public SerializingRecordVisitor(byte[] data, int startOffset)
			{
				_data = data;
				_startOffset = startOffset;
				_countBytesWritten = 0;
			}

			public int CountBytesWritten()
			{
				return _countBytesWritten;
			}

			public void VisitRecord(Record r)
			{
				int offset = _startOffset + _countBytesWritten;
				_countBytesWritten += r.Serialize(offset, _data);
			}
		}

		private class RecordSizingVisitor : RecordVisitor
		{
			private int _totalSize;

			public int TotalSize => _totalSize;

			public RecordSizingVisitor()
			{
				_totalSize = 0;
			}

			public void VisitRecord(Record r)
			{
				_totalSize += r.RecordSize;
			}
		}

		public virtual short Sid
		{
			get
			{
				throw new NotImplementedException("Should not be called");
			}
		}

		public override int RecordSize
		{
			get
			{
				RecordSizingVisitor recordSizingVisitor = new RecordSizingVisitor();
				VisitContainedRecords(recordSizingVisitor);
				return recordSizingVisitor.TotalSize;
			}
		}

		public abstract void VisitContainedRecords(RecordVisitor rv);

		public override int Serialize(int offset, byte[] data)
		{
			SerializingRecordVisitor serializingRecordVisitor = new SerializingRecordVisitor(data, offset);
			VisitContainedRecords(serializingRecordVisitor);
			return serializingRecordVisitor.CountBytesWritten();
		}

		public virtual Record CloneViaReserialise()
		{
			throw new NotImplementedException("Please implement it in subclass");
		}
	}
	public interface RecordVisitor
	{
		void VisitRecord(Record r);
	}
}
namespace NPOI.HSSF.Record.Aggregates.Chart
{
	public abstract class ChartRecordAggregate : RecordAggregate
	{
		private class StartBlockStack
		{
			private List<StartBlockRecord> blockList = new List<StartBlockRecord>(16);

			public int Count => blockList.Count;

			public void Push(StartBlockRecord item)
			{
				blockList.Add(item);
			}

			public StartBlockRecord Pop()
			{
				if (blockList.Count == 0)
				{
					return null;
				}
				StartBlockRecord result = blockList[blockList.Count - 1];
				blockList.RemoveAt(blockList.Count - 1);
				return result;
			}

			public StartBlockRecord Peek()
			{
				if (blockList.Count == 0)
				{
					return null;
				}
				return blockList[blockList.Count - 1];
			}

			public bool Contains(ObjectKind objectKind)
			{
				foreach (StartBlockRecord block in blockList)
				{
					if (block.ObjectKind == objectKind)
					{
						return true;
					}
				}
				return false;
			}
		}

		public const string RuleName_DAT = "DAT";

		public const string RuleName_TEXTPROPS = "TEXTPROPS";

		public const string RuleName_SS = "SS";

		public const string RuleName_SHAPEPROPS = "SHAPEPROPS";

		public const string RuleName_SERIESFORMAT = "SERIESFORMAT";

		public const string RuleName_SERIESAXIS = "SERIESAXIS";

		public const string RuleName_LD = "LD";

		public const string RuleName_IVAXIS = "IVAXIS";

		public const string RuleName_GELFRAME = "GELFRAME";

		public const string RuleName_FRAME = "FRAME";

		public const string RuleName_FONTLIST = "FONTLIST";

		public const string RuleName_DVAXIS = "DVAXIS";

		public const string RuleName_DROPBAR = "DROPBAR";

		public const string RuleName_DFTTEXT = "DFTTEXT";

		public const string RuleName_CRTMLFRT = "CRTMLFRT";

		public const string RuleName_CRT = "CRT";

		public const string RuleName_CHARTFOMATS = "CHARTFOMATS";

		public const string RuleName_AXS = "AXS";

		public const string RuleName_AXM = "AXM";

		public const string RuleName_AXISPARENT = "AXISPARENT";

		public const string RuleName_AXES = "AXES";

		public const string RuleName_ATTACHEDLABEL = "ATTACHEDLABEL";

		public const string RuleName_LEGENDEXCEPTION = "LEGENDEXCEPTION";

		public const string RuleName_CHARTSHEET = "CHARTSHEET";

		public const short ChartSpecificFutureRecordLowerSid = 2048;

		public const short ChartSpecificFutureRecordHigherSid = 2303;

		private string _rulename;

		private ChartRecordAggregate _container;

		private static StartBlockStack blocks = new StartBlockStack();

		private bool _isInStartObject;

		protected string RuleName
		{
			get
			{
				return _rulename;
			}
			private set
			{
				_rulename = value;
			}
		}

		protected ChartRecordAggregate Container
		{
			get
			{
				return _container;
			}
			private set
			{
				_container = value;
			}
		}

		protected bool IsInStartObject
		{
			get
			{
				return _isInStartObject;
			}
			set
			{
				_isInStartObject = value;
			}
		}

		protected ChartRecordAggregate(string ruleName, ChartRecordAggregate container)
		{
			RuleName = ruleName;
			Container = container;
		}

		protected virtual bool ShoudWriteStartBlock()
		{
			return false;
		}

		private bool IsInRule(string ruleName)
		{
			for (ChartRecordAggregate chartRecordAggregate = this; chartRecordAggregate != null; chartRecordAggregate = chartRecordAggregate.Container)
			{
				if (chartRecordAggregate.RuleName == ruleName)
				{
					return true;
				}
			}
			return false;
		}

		protected T GetContainer<T>(string ruleName) where T : ChartRecordAggregate
		{
			ChartRecordAggregate chartRecordAggregate = this;
			while (chartRecordAggregate != null && !(chartRecordAggregate.RuleName == ruleName))
			{
				chartRecordAggregate = chartRecordAggregate.Container;
			}
			return chartRecordAggregate as T;
		}

		protected void WriteStartBlock(RecordVisitor rv)
		{
			if (IsInStartObject)
			{
				return;
			}
			StartBlockRecord startBlockRecord = null;
			if (blocks.Count == 0)
			{
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.Sheet);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("DAT") && !blocks.Contains(ObjectKind.DatRecord))
			{
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.DatRecord);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("SERIESFORMAT") && !blocks.Contains(ObjectKind.Series))
			{
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.Series, 0, GetContainer<SeriesFormatAggregate>("SERIESFORMAT").SeriesIndex);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("SS") && !blocks.Contains(ObjectKind.DataFormatRecord))
			{
				SSAggregate container = GetContainer<SSAggregate>("SS");
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.DataFormatRecord, container.DataFormat.SeriesIndex, container.DataFormat.PointNumber);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("LEGENDEXCEPTION") && !blocks.Contains(ObjectKind.LegendException))
			{
				SeriesFormatAggregate.LegendExceptionAggregate container2 = GetContainer<SeriesFormatAggregate.LegendExceptionAggregate>("LEGENDEXCEPTION");
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.LegendException, 0, container2.LegendException.LegendEntry);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("AXISPARENT") && !blocks.Contains(ObjectKind.AxisGroup))
			{
				AxisParentAggregate container3 = GetContainer<AxisParentAggregate>("AXISPARENT");
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.AxisGroup, 0, container3.AxisParent.AxisType);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("CRT") && !blocks.Contains(ObjectKind.ChartGroup))
			{
				AxisParentAggregate container4 = GetContainer<AxisParentAggregate>("AXISPARENT");
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.ChartGroup, 0, container4.AxisParent.AxisType);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("AXES") && !blocks.Contains(ObjectKind.Axis))
			{
				if (IsInRule("IVAXIS"))
				{
					startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.Axis, 0, 0);
					blocks.Push(startBlockRecord);
					rv.VisitRecord(startBlockRecord);
				}
				if (IsInRule("SERIESAXIS"))
				{
					startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.Axis, 0, 2);
					blocks.Push(startBlockRecord);
					rv.VisitRecord(startBlockRecord);
				}
				if (IsInRule("DVAXIS"))
				{
					DVAxisAggregate container5 = GetContainer<DVAxisAggregate>("DVAXIS");
					startBlockRecord = ((container5.Axis.AxisType != 0) ? StartBlockRecord.CreateStartBlock(ObjectKind.Axis, 0, 3) : StartBlockRecord.CreateStartBlock(ObjectKind.Axis, 0, 1));
					blocks.Push(startBlockRecord);
					rv.VisitRecord(startBlockRecord);
				}
			}
			if (IsInRule("DROPBAR") && !blocks.Contains(ObjectKind.DropBarRecord))
			{
				startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.DropBarRecord);
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("LD") && !blocks.Contains(ObjectKind.Legend))
			{
				startBlockRecord = ((!IsInRule("CRT")) ? StartBlockRecord.CreateStartBlock(ObjectKind.Legend, 0) : StartBlockRecord.CreateStartBlock(ObjectKind.Legend, 1));
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("ATTACHEDLABEL") && !blocks.Contains(ObjectKind.AttachedLabelRecord))
			{
				if (IsInRule("DFTTEXT"))
				{
					DFTTextAggregate container6 = GetContainer<DFTTextAggregate>("DFTTEXT");
					startBlockRecord = ((!IsInRule("CRT") || container6.DefaultText.FormatType < TextFormatInfo.FontScaleNotSet) ? StartBlockRecord.CreateStartBlock(ObjectKind.AttachedLabelRecord, 2, (short)container6.DefaultText.FormatType) : StartBlockRecord.CreateStartBlock(ObjectKind.AttachedLabelRecord, 2, -1));
				}
				else
				{
					AttachedLabelAggregate container7 = GetContainer<AttachedLabelAggregate>("ATTACHEDLABEL");
					startBlockRecord = ((container7.ObjectLink.Link1 == 3) ? StartBlockRecord.CreateStartBlock(ObjectKind.AttachedLabelRecord, 4, 0) : ((container7.ObjectLink.Link1 == 2) ? StartBlockRecord.CreateStartBlock(ObjectKind.AttachedLabelRecord, 4, 1) : ((container7.ObjectLink.Link1 == 7) ? StartBlockRecord.CreateStartBlock(ObjectKind.AttachedLabelRecord, 4, 2) : ((!container7.IsFirst) ? StartBlockRecord.CreateStartBlock(ObjectKind.AttachedLabelRecord, 5, container7.ObjectLink.Link1, container7.ObjectLink.Link2) : StartBlockRecord.CreateStartBlock(ObjectKind.AttachedLabelRecord, 0)))));
				}
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
			if (IsInRule("FRAME") && !blocks.Contains(ObjectKind.Frame))
			{
				if (IsInRule("ATTACHEDLABEL") || IsInRule("LD"))
				{
					startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.Frame, 0, 0);
				}
				else if (IsInRule("AXES"))
				{
					startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.Frame, 1, 0);
				}
				else if (IsInRule("CHARTSHEET"))
				{
					startBlockRecord = StartBlockRecord.CreateStartBlock(ObjectKind.Frame, 2, 0);
				}
				blocks.Push(startBlockRecord);
				rv.VisitRecord(startBlockRecord);
			}
		}

		protected void WriteEndBlock(RecordVisitor rv)
		{
			if (!IsInStartObject)
			{
				StartBlockRecord startBlockRecord = blocks.Peek();
				if (RuleName == "AXISPARENT" && startBlockRecord.ObjectKind == ObjectKind.AxisGroup)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.AxisGroup));
					blocks.Pop();
				}
				else if (RuleName == "ATTACHEDLABEL" && startBlockRecord.ObjectKind == ObjectKind.AttachedLabelRecord)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.AttachedLabelRecord));
					blocks.Pop();
				}
				else if ((RuleName == "IVAXIS" || RuleName == "DVAXIS" || RuleName == "SERIESAXIS") && startBlockRecord.ObjectKind == ObjectKind.Axis)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.Axis));
					blocks.Pop();
				}
				else if (RuleName == "CRT" && startBlockRecord.ObjectKind == ObjectKind.ChartGroup)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.ChartGroup));
					blocks.Pop();
				}
				else if (RuleName == "DAT" && startBlockRecord.ObjectKind == ObjectKind.DatRecord)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.DatRecord));
					blocks.Pop();
				}
				else if (RuleName == "FRAME" && startBlockRecord.ObjectKind == ObjectKind.Frame)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.Frame));
					blocks.Pop();
				}
				else if (RuleName == "LD" && startBlockRecord.ObjectKind == ObjectKind.Legend)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.Legend));
					blocks.Pop();
				}
				else if (RuleName == "LEGENDEXCEPTION" && startBlockRecord.ObjectKind == ObjectKind.LegendException)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.LegendException));
					blocks.Pop();
				}
				else if (RuleName == "SERIESFORMAT" && startBlockRecord.ObjectKind == ObjectKind.Series)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.Series));
					blocks.Pop();
				}
				else if (RuleName == "CHARTFOMATS" && startBlockRecord.ObjectKind == ObjectKind.Sheet)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.Sheet));
					blocks.Pop();
				}
				else if (RuleName == "SS" && startBlockRecord.ObjectKind == ObjectKind.DataFormatRecord)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.DataFormatRecord));
					blocks.Pop();
				}
				else if (RuleName == "DROPBAR" && startBlockRecord.ObjectKind == ObjectKind.DropBarRecord)
				{
					rv.VisitRecord(EndBlockRecord.CreateEndBlock(ObjectKind.DropBarRecord));
					blocks.Pop();
				}
			}
		}
	}
	public class AttachedLabelAggregate : ChartRecordAggregate
	{
		private TextRecord text;

		private PosRecord pos;

		private FontXRecord fontX;

		private AlRunsRecord alRuns;

		private BRAIRecord brai;

		private SeriesTextRecord seriesText;

		private FrameAggregate frame;

		private ObjectLinkRecord objectLink;

		private DataLabExtContentsRecord dataLab;

		private CrtLayout12Record crtLayout;

		private TextPropsAggregate textProps;

		private CrtMlFrtAggregate crtMlFrt;

		private bool _isFirst;

		public bool IsFirst
		{
			get
			{
				return _isFirst;
			}
			set
			{
				_isFirst = value;
			}
		}

		public ObjectLinkRecord ObjectLink => objectLink;

		public AttachedLabelAggregate(RecordStream rs, ChartRecordAggregate container)
			: base("ATTACHEDLABEL", container)
		{
			ChartSheetAggregate container2 = GetContainer<ChartSheetAggregate>("CHARTSHEET");
			_isFirst = container2.AttachLabelCount == 0;
			container2.AttachLabelCount++;
			text = (TextRecord)rs.GetNext();
			rs.GetNext();
			pos = (PosRecord)rs.GetNext();
			if (rs.PeekNextChartSid() == 4134)
			{
				fontX = (FontXRecord)rs.GetNext();
			}
			if (rs.PeekNextChartSid() == 4176)
			{
				alRuns = (AlRunsRecord)rs.GetNext();
			}
			brai = (BRAIRecord)rs.GetNext();
			if (rs.PeekNextChartSid() == 4109)
			{
				seriesText = (SeriesTextRecord)rs.GetNext();
			}
			if (rs.PeekNextChartSid() == 4146)
			{
				frame = new FrameAggregate(rs, this);
			}
			if (rs.PeekNextChartSid() == 4135)
			{
				objectLink = (ObjectLinkRecord)rs.GetNext();
			}
			if (rs.PeekNextChartSid() == 2155)
			{
				dataLab = (DataLabExtContentsRecord)rs.GetNext();
			}
			if (rs.PeekNextChartSid() == 2205)
			{
				crtLayout = (CrtLayout12Record)rs.GetNext();
			}
			if (rs.PeekNextChartSid() == 2213)
			{
				textProps = new TextPropsAggregate(rs, this);
			}
			if (rs.PeekNextChartSid() == 2206)
			{
				crtMlFrt = new CrtMlFrtAggregate(rs, this);
			}
			rs.GetNext();
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			rv.VisitRecord(text);
			rv.VisitRecord(BeginRecord.instance);
			rv.VisitRecord(pos);
			if (fontX != null)
			{
				rv.VisitRecord(fontX);
			}
			if (alRuns != null)
			{
				rv.VisitRecord(alRuns);
			}
			rv.VisitRecord(brai);
			if (seriesText != null)
			{
				rv.VisitRecord(seriesText);
			}
			if (frame != null)
			{
				frame.VisitContainedRecords(rv);
			}
			if (objectLink != null)
			{
				rv.VisitRecord(objectLink);
			}
			if (dataLab != null)
			{
				rv.VisitRecord(dataLab);
			}
			if (crtLayout != null)
			{
				rv.VisitRecord(crtLayout);
			}
			if (textProps != null)
			{
				textProps.VisitContainedRecords(rv);
			}
			if (crtMlFrt != null)
			{
				crtMlFrt.VisitContainedRecords(rv);
			}
			WriteEndBlock(rv);
			rv.VisitRecord(EndRecord.instance);
		}
	}
	public class AxesAggregate : ChartRecordAggregate
	{
		private IVAxisAggregate ivaxis;

		private DVAxisAggregate dvaxis;

		private DVAxisAggregate dvaxisSecond;

		private SeriesAxisAggregate seriesAxis;

		private List<AttachedLabelAggregate> attachedLabelList = new List<AttachedLabelAggregate>();

		private PlotAreaRecord plotArea;

		private FrameAggregate frame;

		public AxesAggregate(RecordStream rs, ChartRecordAggregate container)
			: base("AXES", container)
		{
			if (rs.PeekNextChartSid() != 4125)
			{
				return;
			}
			AxisRecord axis = (AxisRecord)rs.GetNext();
			rs.GetNext();
			int num = rs.PeekNextChartSid();
			switch (num)
			{
			case 4128:
				ivaxis = new IVAxisAggregate(rs, this, axis);
				break;
			case 4127:
				dvaxis = new DVAxisAggregate(rs, this, axis);
				break;
			default:
				throw new InvalidOperationException($"Invalid record sid=0x{num:X}. Shoud be CatSerRangeRecord or ValueRangeRecord");
			}
			dvaxisSecond = new DVAxisAggregate(rs, this, null);
			if (rs.PeekNextChartSid() == 4125)
			{
				seriesAxis = new SeriesAxisAggregate(rs, this);
			}
			while (rs.PeekNextChartSid() == 4133)
			{
				attachedLabelList.Add(new AttachedLabelAggregate(rs, this));
			}
			if (rs.PeekNextChartSid() == 4149)
			{
				plotArea = (PlotAreaRecord)rs.GetNext();
				if (rs.PeekNextChartSid() == 4146)
				{
					frame = new FrameAggregate(rs, this);
				}
			}
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			if (ivaxis != null)
			{
				ivaxis.VisitContainedRecords(rv);
			}
			if (dvaxis != null)
			{
				dvaxis.VisitContainedRecords(rv);
			}
			dvaxisSecond.VisitContainedRecords(rv);
			if (seriesAxis != null)
			{
				seriesAxis.VisitContainedRecords(rv);
			}
			foreach (AttachedLabelAggregate attachedLabel in attachedLabelList)
			{
				attachedLabel.VisitContainedRecords(rv);
			}
			if (plotArea != null)
			{
				rv.VisitRecord(plotArea);
				if (frame != null)
				{
					frame.VisitContainedRecords(rv);
				}
			}
		}
	}
	public class AxisParentAggregate : ChartRecordAggregate
	{
		private AxisParentRecord axisPraent;

		private PosRecord pos;

		private AxesAggregate axes;

		private List<CRTAggregate> crtList = new List<CRTAggregate>();

		public AxisParentRecord AxisParent => axisPraent;

		public AxisParentAggregate(RecordStream rs, ChartRecordAggregate container)
			: base("AXISPARENT", container)
		{
			axisPraent = (AxisParentRecord)rs.GetNext();
			rs.GetNext();
			pos = (PosRecord)rs.GetNext();
			if (4116 != rs.PeekNextChartSid())
			{
				try
				{
					axes = new AxesAggregate(rs, this);
				}
				catch
				{
					axes = null;
				}
			}
			while (4116 == rs.PeekNextChartSid())
			{
				crtList.Add(new CRTAggregate(rs, this));
			}
			rs.GetNext();
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			rv.VisitRecord(axisPraent);
			rv.VisitRecord(BeginRecord.instance);
			rv.VisitRecord(pos);
			if (axes != null)
			{
				axes.VisitContainedRecords(rv);
			}
			foreach (CRTAggregate crt in crtList)
			{
				crt.VisitContainedRecords(rv);
			}
			WriteEndBlock(rv);
			rv.VisitRecord(EndRecord.instance);
		}
	}
