namespace NPOI.POIFS.FileSystem
{
	public class EntryUtils
	{
		public static void CopyNodeRecursively(Entry entry, DirectoryEntry target)
		{
			DirectoryEntry directoryEntry = null;
			if (entry.IsDirectoryEntry)
			{
				DirectoryEntry directoryEntry2 = (DirectoryEntry)entry;
				directoryEntry = target.CreateDirectory(entry.Name);
				directoryEntry.StorageClsid = directoryEntry2.StorageClsid;
				IEnumerator<Entry> entries = directoryEntry2.Entries;
				while (entries.MoveNext())
				{
					CopyNodeRecursively(entries.Current, directoryEntry);
				}
			}
			else
			{
				DocumentEntry documentEntry = (DocumentEntry)entry;
				DocumentInputStream documentInputStream = new DocumentInputStream(documentEntry);
				target.CreateDocument(documentEntry.Name, documentInputStream);
				documentInputStream.Close();
			}
		}

		public static void CopyNodes(DirectoryEntry sourceRoot, DirectoryEntry targetRoot)
		{
			foreach (Entry item in sourceRoot)
			{
				CopyNodeRecursively(item, targetRoot);
			}
		}

		public static void CopyNodes(FilteringDirectoryNode filteredSource, FilteringDirectoryNode filteredTarget)
		{
			CopyNodes((DirectoryEntry)filteredSource, (DirectoryEntry)filteredTarget);
		}

		[Obsolete]
		public static void CopyNodes(DirectoryEntry sourceRoot, DirectoryEntry targetRoot, List<string> excepts)
		{
			IEnumerator entries = sourceRoot.Entries;
			while (entries.MoveNext())
			{
				Entry entry = (Entry)entries.Current;
				if (!excepts.Contains(entry.Name))
				{
					CopyNodeRecursively(entry, targetRoot);
				}
			}
		}

		public static void CopyNodes(POIFSFileSystem source, POIFSFileSystem target)
		{
			CopyNodes(source.Root, target.Root);
		}

		public static void CopyNodes(POIFSFileSystem source, POIFSFileSystem target, List<string> excepts)
		{
			CopyNodes(new FilteringDirectoryNode(source.Root, excepts), new FilteringDirectoryNode(target.Root, excepts));
		}

		public static bool AreDirectoriesIdentical(DirectoryEntry dirA, DirectoryEntry dirB)
		{
			if (!dirA.Name.Equals(dirB.Name))
			{
				return false;
			}
			if (dirA.EntryCount != dirB.EntryCount)
			{
				return false;
			}
			Dictionary<string, int> dictionary = new Dictionary<string, int>();
			int num = -12345;
			foreach (Entry item in dirA)
			{
				string name = item.Name;
				if (item.IsDirectoryEntry)
				{
					dictionary.Add(name, num);
				}
				else
				{
					dictionary.Add(name, ((DocumentNode)item).Size);
				}
			}
			foreach (Entry item2 in dirB)
			{
				string name2 = item2.Name;
				if (!dictionary.ContainsKey(name2))
				{
					return false;
				}
				int num2 = ((!item2.IsDirectoryEntry) ? ((DocumentNode)item2).Size : num);
				if (num2 != dictionary[name2])
				{
					return false;
				}
				dictionary.Remove(name2);
			}
			if (dictionary.Count != 0)
			{
				return false;
			}
			foreach (Entry item3 in dirA)
			{
				try
				{
					Entry entry = dirB.GetEntry(item3.Name);
					if (!((!item3.IsDirectoryEntry) ? AreDocumentsIdentical((DocumentEntry)item3, (DocumentEntry)entry) : AreDirectoriesIdentical((DirectoryEntry)item3, (DirectoryEntry)entry)))
					{
						return false;
					}
				}
				catch (FileNotFoundException)
				{
					return false;
				}
				catch (IOException)
				{
					return false;
				}
			}
			return true;
		}

		public static bool AreDocumentsIdentical(DocumentEntry docA, DocumentEntry docB)
		{
			if (!docA.Name.Equals(docB.Name))
			{
				return false;
			}
			if (docA.Size != docB.Size)
			{
				return false;
			}
			bool result = true;
			DocumentInputStream documentInputStream = null;
			DocumentInputStream documentInputStream2 = null;
			try
			{
				documentInputStream = new DocumentInputStream(docA);
				documentInputStream2 = new DocumentInputStream(docB);
				int num;
				int num2;
				do
				{
					num = documentInputStream.Read();
					num2 = documentInputStream2.Read();
					if (num != num2)
					{
						result = false;
						break;
					}
				}
				while (num != -1 && num2 != -1);
			}
			finally
			{
				documentInputStream?.Close();
				documentInputStream2?.Close();
			}
			return result;
		}
	}
	public interface Entry
	{
		string Name { get; }

		bool IsDirectoryEntry { get; }

		bool IsDocumentEntry { get; }

		DirectoryEntry Parent { get; }

		bool Delete();

		bool RenameTo(string newName);
	}
	public interface DirectoryEntry : Entry, IEnumerable<Entry>, IEnumerable
	{
		IEnumerator<Entry> Entries { get; }

		List<string> EntryNames { get; }

		bool IsEmpty { get; }

		int EntryCount { get; }

		ClassID StorageClsid { get; set; }

		Entry GetEntry(string name);

		DocumentEntry CreateDocument(string name, Stream stream);

		DocumentEntry CreateDocument(string name, int size, POIFSWriterListener writer);

		DirectoryEntry CreateDirectory(string name);

		bool HasEntry(string name);
	}
	public class FilteringDirectoryNode : DirectoryEntry, Entry, IEnumerable<Entry>, IEnumerable
	{
		private class FilteringIterator : IEnumerator<Entry>, IDisposable, IEnumerator
		{
			private IEnumerator<Entry> parent;

			private Entry next;

			private DirectoryEntry directory;

			private FilteringDirectoryNode filtering;

			public Entry Current => next;

			object IEnumerator.Current => next;

			public FilteringIterator(FilteringDirectoryNode filtering)
			{
				this.filtering = filtering;
				directory = filtering.directory;
				parent = directory.Entries;
			}

			public void Remove()
			{
				throw new InvalidOperationException("Remove not supported");
			}

			public void Dispose()
			{
			}

			public bool MoveNext()
			{
				next = null;
				while (parent.MoveNext())
				{
					Entry current = parent.Current;
					if (!filtering.excludes.Contains(current.Name))
					{
						next = filtering.WrapEntry(current);
						break;
					}
				}
				return next != null;
			}

			public void Reset()
			{
				throw new NotImplementedException();
			}
		}

		private List<string> excludes;

		private Dictionary<string, List<string>> childExcludes;

		private DirectoryEntry directory;

		public IEnumerator<Entry> Entries => GetEntries();

		public List<string> EntryNames
		{
			get
			{
				List<string> list = new List<string>();
				foreach (string entryName in directory.EntryNames)
				{
					if (!excludes.Contains(entryName))
					{
						list.Add(entryName);
					}
				}
				return list;
			}
		}

		public bool IsEmpty => EntryCount == 0;

		public int EntryCount
		{
			get
			{
				int num = directory.EntryCount;
				foreach (string exclude in excludes)
				{
					if (directory.HasEntry(exclude))
					{
						num--;
					}
				}
				return num;
			}
		}

		public ClassID StorageClsid
		{
			get
			{
				return directory.StorageClsid;
			}
			set
			{
				directory.StorageClsid = value;
			}
		}

		public string Name => directory.Name;

		public bool IsDirectoryEntry => true;

		public bool IsDocumentEntry => false;

		public DirectoryEntry Parent => directory.Parent;

		public FilteringDirectoryNode(DirectoryEntry directory, ICollection<string> excludes)
		{
			this.directory = directory;
			this.excludes = new List<string>();
			childExcludes = new Dictionary<string, List<string>>();
			foreach (string exclude in excludes)
			{
				int num = exclude.IndexOf('/');
				if (num == -1)
				{
					this.excludes.Add(exclude);
					continue;
				}
				string key = exclude.Substring(0, num);
				string item = exclude.Substring(num + 1);
				if (!childExcludes.ContainsKey(key))
				{
					childExcludes.Add(key, new List<string>());
				}
				childExcludes[key].Add(item);
			}
		}

		public bool HasEntry(string name)
		{
			if (excludes.Contains(name))
			{
				return false;
			}
			return directory.HasEntry(name);
		}

		public IEnumerator<Entry> GetEntries()
		{
			return new FilteringIterator(this);
		}

		public Entry GetEntry(string name)
		{
			if (excludes.Contains(name))
			{
				throw new FileNotFoundException(name);
			}
			Entry entry = directory.GetEntry(name);
			return WrapEntry(entry);
		}

		private Entry WrapEntry(Entry entry)
		{
			string name = entry.Name;
			if (childExcludes.ContainsKey(name) && entry is DirectoryEntry)
			{
				return new FilteringDirectoryNode((DirectoryEntry)entry, childExcludes[name]);
			}
			return entry;
		}

		public DocumentEntry CreateDocument(string name, Stream stream)
		{
			return directory.CreateDocument(name, stream);
		}

		public DocumentEntry CreateDocument(string name, int size, POIFSWriterListener writer)
		{
			return directory.CreateDocument(name, size, writer);
		}

		public DirectoryEntry CreateDirectory(string name)
		{
			return directory.CreateDirectory(name);
		}

		public bool Delete()
		{
			return directory.Delete();
		}

		public bool RenameTo(string newName)
		{
			return directory.RenameTo(newName);
		}

		public IEnumerator<Entry> GetEnumerator()
		{
			return new FilteringIterator(this);
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return new FilteringIterator(this);
		}
	}
	public class NDocumentOutputStream : MemoryStream
	{
		private int _document_size;

		private bool _closed;

		private NPOIFSDocument _document;

		private DocumentProperty _property;

		private MemoryStream _buffer = new MemoryStream(4096);

		private NPOIFSStream _stream;

		private Stream _stream_output;

		public NDocumentOutputStream(DocumentEntry document)
		{
			if (!(document is DocumentNode))
			{
				throw new IOException(string.Concat("Cannot open internal document storage, ", document, " not a Document Node"));
			}
			_document_size = 0;
			_closed = false;
			_property = (DocumentProperty)((DocumentNode)document).Property;
			_document = new NPOIFSDocument((DocumentNode)document);
			_document.Free();
		}

		public NDocumentOutputStream(DirectoryEntry parent, string name)
		{
			if (!(parent is DirectoryNode))
			{
				throw new IOException(string.Concat("Cannot open internal directory storage, ", parent, " not a Directory Node"));
			}
			_document_size = 0;
			_closed = false;
			DocumentEntry documentEntry = parent.CreateDocument(name, new MemoryStream(new byte[0]));
			_property = (DocumentProperty)((DocumentNode)documentEntry).Property;
			_document = new NPOIFSDocument((DocumentNode)documentEntry);
		}

		private void dieIfClosed()
		{
			if (_closed)
			{
				throw new IOException("cannot perform requested operation on a closed stream");
			}
		}

		private void CheckBufferSize()
		{
			if (_buffer.Length > 4096)
			{
				byte[] array = _buffer.ToArray();
				_buffer = null;
				Write(array, 0, array.Length);
			}
		}

		public void Write(int b)
		{
			dieIfClosed();
			if (_buffer != null)
			{
				_buffer.WriteByte((byte)b);
				CheckBufferSize();
			}
			else
			{
				Write(new byte[1] { (byte)b });
			}
		}

		public void Write(byte[] b)
		{
			dieIfClosed();
			if (_buffer != null)
			{
				_buffer.Write(b, 0, b.Length);
				CheckBufferSize();
			}
			else
			{
				Write(b, 0, b.Length);
			}
		}

		public override void Write(byte[] b, int off, int len)
		{
			dieIfClosed();
			if (_buffer != null)
			{
				_buffer.Write(b, off, len);
				CheckBufferSize();
				return;
			}
			if (_stream == null)
			{
				_stream = new NPOIFSStream(_document.FileSystem);
				_stream_output = _stream.GetOutputStream();
			}
			_stream_output.Write(b, off, len);
			_document_size += len;
		}

		public override void Close()
		{
			base.Close();
			if (_buffer != null)
			{
				_document.ReplaceContents(new MemoryStream(_buffer.ToArray()));
			}
			else
			{
				_stream_output.Close();
				_property.UpdateSize(_document_size);
				_property.StartBlock = _stream.GetStartBlock();
			}
			_closed = true;
		}
	}
