				int workdays = (int)Math.Floor(evaluator.EvaluateNumberArg(args[1], rowIndex, columnIndex));
				ValueEval arg = ((args.Length == 3) ? args[2] : null);
				double[] holidays = evaluator.EvaluateDatesArg(arg, rowIndex, columnIndex);
