	public interface IDStarAlgorithm
	{
		ValueEval Result { get; }

		void Reset();

		bool ProcessMatch(ValueEval Eval);
	}
	public class DGet : IDStarAlgorithm
	{
		private ValueEval result;

		public ValueEval Result
		{
			get
			{
				if (result == null)
				{
					return ErrorEval.VALUE_INVALID;
				}
				return result;
			}
		}

		public void Reset()
		{
			result = null;
		}

		public bool ProcessMatch(ValueEval eval)
		{
			if (result == null)
			{
				result = eval;
				return true;
			}
			result = ErrorEval.NUM_ERROR;
			return false;
		}
	}
	public class DMin : IDStarAlgorithm
	{
		private ValueEval minimumValue;

		public ValueEval Result
		{
			get
			{
				if (minimumValue == null)
				{
					return NumberEval.ZERO;
				}
				return minimumValue;
			}
		}

		public void Reset()
		{
			minimumValue = null;
		}

		public bool ProcessMatch(ValueEval eval)
		{
			if (eval is NumericValueEval)
			{
				if (minimumValue == null)
				{
					minimumValue = eval;
				}
				else
				{
					double numberValue = ((NumericValueEval)eval).NumberValue;
					double numberValue2 = ((NumericValueEval)minimumValue).NumberValue;
					if (numberValue < numberValue2)
					{
						minimumValue = eval;
					}
				}
			}
			return true;
		}
	}
	public class DStarRunner : Function3Arg, Function
	{
		private enum Operator
		{
			largerThan,
			largerEqualThan,
			smallerThan,
			smallerEqualThan,
			equal
		}

		private IDStarAlgorithm algorithm;

		public DStarRunner(IDStarAlgorithm algorithm)
		{
			this.algorithm = algorithm;
		}

		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			if (args.Length == 3)
			{
				return Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2]);
			}
			return ErrorEval.VALUE_INVALID;
		}

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval database, ValueEval filterColumn, ValueEval conditionDatabase)
		{
			if (!(database is TwoDEval) || !(conditionDatabase is TwoDEval))
			{
				return ErrorEval.VALUE_INVALID;
			}
			TwoDEval twoDEval = (TwoDEval)database;
			TwoDEval cdb = (TwoDEval)conditionDatabase;
			int columnForName;
			try
			{
				columnForName = GetColumnForName(filterColumn, twoDEval);
			}
			catch (EvaluationException)
			{
				return ErrorEval.VALUE_INVALID;
			}
			if (columnForName == -1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			algorithm.Reset();
			for (int i = 1; i < twoDEval.Height; i++)
			{
				bool flag = true;
				try
				{
					flag = FullFillsConditions(twoDEval, i, cdb);
				}
				catch (EvaluationException)
				{
					return ErrorEval.VALUE_INVALID;
				}
				if (!flag)
				{
					continue;
				}
				try
				{
					ValueEval eval = solveReference(twoDEval.GetValue(i, columnForName));
					if (!algorithm.ProcessMatch(eval))
					{
						break;
					}
				}
				catch (EvaluationException ex3)
				{
					return ex3.GetErrorEval();
				}
			}
			return algorithm.Result;
		}

		private static ValueEval solveReference(ValueEval field)
		{
			if (field is RefEval)
			{
				RefEval refEval = (RefEval)field;
				if (refEval.NumberOfSheets > 1)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
				return solveReference(refEval.GetInnerValueEval(refEval.FirstSheetIndex));
			}
			return field;
		}

		private static int GetColumnForTag(ValueEval nameValueEval, TwoDEval db)
		{
			int num = -1;
			if (nameValueEval is NumericValueEval)
			{
				double numberValue = ((NumericValueEval)nameValueEval).NumberValue;
				num = (int)numberValue;
				if (numberValue - (double)num != 0.0)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
				return num - 1;
			}
			return GetColumnForName(nameValueEval, db);
		}

		private static int GetColumnForName(ValueEval nameValueEval, TwoDEval db)
		{
			string stringFromValueEval = GetStringFromValueEval(nameValueEval);
			return GetColumnForString(db, stringFromValueEval);
		}

		private static int GetColumnForString(TwoDEval db, string name)
		{
			int result = -1;
			for (int i = 0; i < db.Width; i++)
			{
				ValueEval value = db.GetValue(0, i);
				string stringFromValueEval = GetStringFromValueEval(value);
				if (name.Equals(stringFromValueEval))
				{
					result = i;
					break;
				}
			}
			return result;
		}

		private static bool FullFillsConditions(TwoDEval db, int row, TwoDEval cdb)
		{
			for (int i = 1; i < cdb.Height; i++)
			{
				bool flag = true;
				for (int j = 0; j < cdb.Width; j++)
				{
					bool flag2 = true;
					ValueEval valueEval = null;
					try
					{
						valueEval = solveReference(cdb.GetValue(i, j));
					}
					catch (Exception)
					{
						flag2 = false;
					}
					if (!(valueEval is BlankEval))
					{
						ValueEval field = solveReference(cdb.GetValue(0, j));
						field = solveReference(field);
						if (!(field is StringValueEval))
						{
							flag2 = false;
						}
						else if (GetColumnForName(field, db) == -1)
						{
							flag2 = false;
						}
						if (!flag2)
						{
							throw new NotImplementedException("D* function with formula conditions");
						}
						ValueEval value = db.GetValue(row, GetColumnForName(field, db));
						string stringFromValueEval = GetStringFromValueEval(valueEval);
						if (!testNormalCondition(value, stringFromValueEval))
						{
							flag = false;
							break;
						}
					}
				}
				if (flag)
				{
					return true;
				}
			}
			return false;
		}

		private static bool testNormalCondition(ValueEval value, string condition)
		{
			if (condition.StartsWith("<"))
			{
				string text = condition.Substring(1);
				if (text.StartsWith("="))
				{
					text = text.Substring(1);
					return testNumericCondition(value, Operator.smallerEqualThan, text);
				}
				return testNumericCondition(value, Operator.smallerThan, text);
			}
			if (condition.StartsWith(">"))
			{
				string text2 = condition.Substring(1);
				if (text2.StartsWith("="))
				{
					text2 = text2.Substring(1);
					return testNumericCondition(value, Operator.largerEqualThan, text2);
				}
				return testNumericCondition(value, Operator.largerThan, text2);
			}
			if (condition.StartsWith("="))
			{
				string text3 = condition.Substring(1);
				bool flag = false;
				try
				{
					int.Parse(text3);
					flag = true;
				}
				catch (FormatException)
				{
					try
					{
						double.Parse(text3);
						flag = true;
					}
					catch (FormatException)
					{
						flag = false;
					}
				}
				if (flag)
				{
					return testNumericCondition(value, Operator.equal, text3);
				}
				string stringFromValueEval = GetStringFromValueEval(value);
				return text3.Equals(stringFromValueEval);
			}
			string stringFromValueEval2 = GetStringFromValueEval(value);
			return stringFromValueEval2.StartsWith(condition);
		}

		private static bool testNumericCondition(ValueEval valueEval, Operator op, string condition)
		{
			if (!(valueEval is NumericValueEval))
			{
				return false;
			}
			double numberValue = ((NumericValueEval)valueEval).NumberValue;
			double num = 0.0;
			try
			{
				int num2 = int.Parse(condition);
				num = num2;
			}
			catch (FormatException)
			{
				try
				{
					num = double.Parse(condition);
				}
				catch (FormatException)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
			}
			int num3 = NumberComparer.Compare(numberValue, num);
			return op switch
			{
				Operator.largerThan => num3 > 0, 
				Operator.largerEqualThan => num3 >= 0, 
				Operator.smallerThan => num3 < 0, 
				Operator.smallerEqualThan => num3 <= 0, 
				Operator.equal => num3 == 0, 
				_ => false, 
			};
		}

		private static string GetStringFromValueEval(ValueEval value)
		{
			value = solveReference(value);
			if (value is BlankEval)
			{
				return "";
			}
			if (!(value is StringValueEval))
			{
				throw new EvaluationException(ErrorEval.VALUE_INVALID);
			}
			return ((StringValueEval)value).StringValue;
		}
	}
	public class EOMonth : FreeRefFunction
	{
		public static FreeRefFunction instance = new EOMonth();

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length != 2)
			{
				return ErrorEval.VALUE_INVALID;
			}
			try
			{
				double num = NumericFunction.SingleOperandEvaluate(args[0], ec.RowIndex, ec.ColumnIndex);
				int months = (int)NumericFunction.SingleOperandEvaluate(args[1], ec.RowIndex, ec.ColumnIndex);
				if (num >= 0.0 && num < 1.0)
				{
					num = 1.0;
				}
				DateTime dateTime = DateUtil.GetJavaDate(num, use1904windowing: false).AddMonths(months).AddMonths(1);
				dateTime = new DateTime(dateTime.Year, dateTime.Month, 1).AddDays(-1.0);
				return new NumberEval(DateUtil.GetExcelDate(dateTime));
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}
	}
	public class Errortype : Fixed1ArgFunction
	{
		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0)
		{
			try
			{
				OperandResolver.GetSingleValue(arg0, srcRowIndex, srcColumnIndex);
				return ErrorEval.NA;
			}
			catch (EvaluationException ex)
			{
				int num = TranslateErrorCodeToErrorTypeValue(ex.GetErrorEval().ErrorCode);
				return new NumberEval(num);
			}
		}

		private int TranslateErrorCodeToErrorTypeValue(int errorCode)
		{
			return errorCode switch
			{
				0 => 1, 
				7 => 2, 
				15 => 3, 
				23 => 4, 
				29 => 5, 
				36 => 6, 
				42 => 7, 
				_ => throw new ArgumentException("Invalid error code (" + errorCode + ")"), 
			};
		}
	}
	public class FactDouble : Fixed1ArgFunction, FreeRefFunction
	{
		public static FreeRefFunction instance = new FactDouble();

		private static Dictionary<int, BigInteger> cache = new Dictionary<int, BigInteger>();

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval numberVE)
		{
			int num;
			try
			{
				num = OperandResolver.CoerceValueToInt(numberVE);
			}
			catch (EvaluationException)
			{
				return ErrorEval.VALUE_INVALID;
			}
			if (num < 0)
			{
				return ErrorEval.NUM_ERROR;
			}
			return new NumberEval(factorial(num).LongValue());
		}

		public static BigInteger factorial(int n)
		{
			if (n == 0 || n < 0)
			{
				return BigInteger.One;
			}
			if (cache.ContainsKey(n))
			{
				return cache[n];
			}
			BigInteger bigInteger = BigInteger.ValueOf(n).Multiply(factorial(n - 2));
			cache.Add(n, bigInteger);
			return bigInteger;
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length != 1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			return Evaluate(ec.RowIndex, ec.ColumnIndex, args[0]);
		}
	}
	public class Finance
	{
		public static double PMT(double r, int nper, double pv, double fv, int type)
		{
			return (0.0 - r) * (pv * Math.Pow(1.0 + r, nper) + fv) / ((1.0 + r * (double)type) * (Math.Pow(1.0 + r, nper) - 1.0));
		}

		public static double PMT(double r, int nper, double pv, double fv)
		{
			return PMT(r, nper, pv, fv, 0);
		}

		public static double PMT(double r, int nper, double pv)
		{
			return PMT(r, nper, pv, 0.0);
		}

		public static double IPMT(double r, int per, int nper, double pv, double fv, int type)
		{
			double num = FV(r, per - 1, PMT(r, nper, pv, fv, type), pv, type) * r;
			if (type == 1)
			{
				num /= 1.0 + r;
			}
			return num;
		}

		public static double IPMT(double r, int per, int nper, double pv, double fv)
		{
			return IPMT(r, per, nper, pv, fv, 0);
		}

		public static double IPMT(double r, int per, int nper, double pv)
		{
			return IPMT(r, per, nper, pv, 0.0);
		}

		public static double PPMT(double r, int per, int nper, double pv, double fv, int type)
		{
			return PMT(r, nper, pv, fv, type) - IPMT(r, per, nper, pv, fv, type);
		}

		public static double PPMT(double r, int per, int nper, double pv, double fv)
		{
			return PMT(r, nper, pv, fv) - IPMT(r, per, nper, pv, fv);
		}

		public static double PPMT(double r, int per, int nper, double pv)
		{
			return PMT(r, nper, pv) - IPMT(r, per, nper, pv);
		}

		public static double FV(double r, int nper, double pmt, double pv, int type)
		{
			return 0.0 - (pv * Math.Pow(1.0 + r, nper) + pmt * (1.0 + r * (double)type) * (Math.Pow(1.0 + r, nper) - 1.0) / r);
		}

		public static double FV(double r, int nper, double c, double pv)
		{
			return FV(r, nper, c, pv, 0);
		}
	}
	public class Fixed : Function1Arg, Function2Arg, Function3Arg, Function
	{
		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			return doFixed(arg0, arg1, arg2, srcRowIndex, srcColumnIndex);
		}

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			return doFixed(arg0, arg1, BoolEval.FALSE, srcRowIndex, srcColumnIndex);
		}

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0)
		{
			return doFixed(arg0, new NumberEval(2.0), BoolEval.FALSE, srcRowIndex, srcColumnIndex);
		}

		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			return args.Length switch
			{
				1 => doFixed(args[0], new NumberEval(2.0), BoolEval.FALSE, srcRowIndex, srcColumnIndex), 
				2 => doFixed(args[0], args[1], BoolEval.FALSE, srcRowIndex, srcColumnIndex), 
				3 => doFixed(args[0], args[1], args[2], srcRowIndex, srcColumnIndex), 
				_ => ErrorEval.VALUE_INVALID, 
			};
		}

		private ValueEval doFixed(ValueEval numberParam, ValueEval placesParam, ValueEval skipThousandsSeparatorParam, int srcRowIndex, int srcColumnIndex)
		{
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(numberParam, srcRowIndex, srcColumnIndex);
				decimal d = (decimal)OperandResolver.CoerceValueToDouble(singleValue);
				ValueEval singleValue2 = OperandResolver.GetSingleValue(placesParam, srcRowIndex, srcColumnIndex);
				int num = OperandResolver.CoerceValueToInt(singleValue2);
				ValueEval singleValue3 = OperandResolver.GetSingleValue(skipThousandsSeparatorParam, srcRowIndex, srcColumnIndex);
				bool? flag = OperandResolver.CoerceValueToBoolean(singleValue3, stringsAreBlanks: false);
				if (num < 0)
				{
					d /= (decimal)Math.Pow(10.0, -num);
					d = Math.Round(d, 0);
					d *= (decimal)Math.Pow(10.0, -num);
				}
				else
				{
					d = Math.Round(d, num);
				}
				string value = ((flag.HasValue && flag.Value) ? d.ToString((num > 0) ? ("F" + num) : "F0") : d.ToString((num > 0) ? ("N" + num) : "N0", CultureInfo.InvariantCulture));
				return new StringEval(value);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}
	}
