	public class LinearRegressionFunction : Fixed2ArgFunction
	{
		private abstract class ValueArray : ValueVector
		{
			private int _size;

			public int Size => _size;

			protected ValueArray(int size)
			{
				_size = size;
			}

			public ValueEval GetItem(int index)
			{
				if (index < 0 || index > _size)
				{
					throw new ArgumentException("Specified index " + index + " is outside range (0.." + (_size - 1) + ")");
				}
				return GetItemInternal(index);
			}

			protected abstract ValueEval GetItemInternal(int index);
		}

		private class SingleCellValueArray : ValueArray
		{
			private ValueEval _value;

			public SingleCellValueArray(ValueEval value)
				: base(1)
			{
				_value = value;
			}

			protected override ValueEval GetItemInternal(int index)
			{
				return _value;
			}
		}

		private class RefValueArray : ValueArray
		{
			private RefEval _ref;

			private int _width;

			public RefValueArray(RefEval ref1)
				: base(ref1.NumberOfSheets)
			{
				_ref = ref1;
				_width = ref1.NumberOfSheets;
			}

			protected override ValueEval GetItemInternal(int index)
			{
				int sheetIndex = index % _width + _ref.FirstSheetIndex;
				return _ref.GetInnerValueEval(sheetIndex);
			}
		}

		private class AreaValueArray : ValueArray
		{
			private TwoDEval _ae;

			private int _width;

			public AreaValueArray(TwoDEval ae)
				: base(ae.Width * ae.Height)
			{
				_ae = ae;
				_width = ae.Width;
			}

			protected override ValueEval GetItemInternal(int index)
			{
				int rowIndex = index / _width;
				int columnIndex = index % _width;
				return _ae.GetValue(rowIndex, columnIndex);
			}
		}

		public enum FUNCTION
		{
			INTERCEPT,
			SLOPE
		}

		public FUNCTION function;

		public LinearRegressionFunction(FUNCTION function)
		{
			this.function = function;
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			double num;
			try
			{
				ValueVector valueVector = CreateValueVector(arg0);
				ValueVector valueVector2 = CreateValueVector(arg1);
				int size = valueVector2.Size;
				if (size == 0 || valueVector.Size != size)
				{
					return ErrorEval.NA;
				}
				num = EvaluateInternal(valueVector2, valueVector, size);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			if (double.IsNaN(num) || double.IsInfinity(num))
			{
				return ErrorEval.NUM_ERROR;
			}
			return new NumberEval(num);
		}

		private double EvaluateInternal(ValueVector x, ValueVector y, int size)
		{
			ErrorEval errorEval = null;
			ErrorEval errorEval2 = null;
			bool flag = false;
			double num = 0.0;
			double num2 = 0.0;
			for (int i = 0; i < size; i++)
			{
				ValueEval item = x.GetItem(i);
				ValueEval item2 = y.GetItem(i);
				if (item is ErrorEval && errorEval == null)
				{
					errorEval = (ErrorEval)item;
				}
				else if (item2 is ErrorEval && errorEval2 == null)
				{
					errorEval2 = (ErrorEval)item2;
				}
				else if (item is NumberEval && item2 is NumberEval)
				{
					flag = true;
					NumberEval numberEval = (NumberEval)item;
					NumberEval numberEval2 = (NumberEval)item2;
					num += numberEval.NumberValue;
					num2 += numberEval2.NumberValue;
				}
			}
			double num3 = num / (double)size;
			double num4 = num2 / (double)size;
			double num5 = 0.0;
			double num6 = 0.0;
			for (int j = 0; j < size; j++)
			{
				ValueEval item3 = x.GetItem(j);
				ValueEval item4 = y.GetItem(j);
				if (item3 is ErrorEval && errorEval == null)
				{
					errorEval = (ErrorEval)item3;
				}
				else if (item4 is ErrorEval && errorEval2 == null)
				{
					errorEval2 = (ErrorEval)item4;
				}
				else if (item3 is NumberEval && item4 is NumberEval)
				{
					NumberEval numberEval3 = (NumberEval)item3;
					NumberEval numberEval4 = (NumberEval)item4;
					num5 += (numberEval3.NumberValue - num3) * (numberEval3.NumberValue - num3);
					num6 += (numberEval3.NumberValue - num3) * (numberEval4.NumberValue - num4);
				}
			}
			double num7 = num6 / num5;
			double result = num4 - num7 * num3;
			if (errorEval != null)
			{
				throw new EvaluationException(errorEval);
			}
			if (errorEval2 != null)
			{
				throw new EvaluationException(errorEval2);
			}
			if (!flag)
			{
				throw new EvaluationException(ErrorEval.DIV_ZERO);
			}
			if (function == FUNCTION.INTERCEPT)
			{
				return result;
			}
			return num7;
		}

		private ValueVector CreateValueVector(ValueEval arg)
		{
			if (arg is ErrorEval)
			{
				throw new EvaluationException((ErrorEval)arg);
			}
			if (arg is TwoDEval)
			{
				return new AreaValueArray((TwoDEval)arg);
			}
			if (arg is RefEval)
			{
				return new RefValueArray((RefEval)arg);
			}
			return new SingleCellValueArray(arg);
		}
	}
	public interface ValueVector
	{
		int Size { get; }

		ValueEval GetItem(int index);
	}
	public abstract class MultiOperandNumericFunction : Function
	{
		private class DoubleList
		{
			private double[] _array;

			private int _Count;

			public DoubleList()
			{
				_array = new double[8];
				_Count = 0;
			}

			public double[] ToArray()
			{
				if (_Count < 1)
				{
					return EMPTY_DOUBLE_ARRAY;
				}
				double[] array = new double[_Count];
				System.Array.Copy(_array, 0, array, 0, _Count);
				return array;
			}

			public void Add(double[] values)
			{
				int num = values.Length;
				EnsureCapacity(_Count + num);
				System.Array.Copy(values, 0, _array, _Count, num);
				_Count += num;
			}

			private void EnsureCapacity(int reqSize)
			{
				if (reqSize > _array.Length)
				{
					int num = reqSize * 3 / 2;
					double[] array = new double[num];
					System.Array.Copy(_array, 0, array, 0, _Count);
					_array = array;
				}
			}

			public void Add(double value)
			{
				EnsureCapacity(_Count + 1);
				_array[_Count] = value;
				_Count++;
			}
		}

		private const int DEFAULT_MAX_NUM_OPERANDS = 30;

		private static double[] EMPTY_DOUBLE_ARRAY = new double[0];

		private bool _isReferenceBoolCounted;

		private bool _isBlankCounted;

		protected virtual int MaxNumOperands => 30;

		public virtual bool IsSubtotalCounted => true;

		protected MultiOperandNumericFunction(bool isReferenceBoolCounted, bool isBlankCounted)
		{
			_isReferenceBoolCounted = isReferenceBoolCounted;
			_isBlankCounted = isBlankCounted;
		}

		protected internal abstract double Evaluate(double[] values);

		public ValueEval Evaluate(ValueEval[] args, int srcCellRow, int srcCellCol)
		{
			double num;
			try
			{
				double[] numberArray = GetNumberArray(args);
				num = Evaluate(numberArray);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			if (double.IsNaN(num) || double.IsInfinity(num))
			{
				return ErrorEval.NUM_ERROR;
			}
			return new NumberEval(num);
		}

		private void CollectValues(ValueEval operand, DoubleList temp)
		{
			if (operand is ThreeDEval)
			{
				ThreeDEval threeDEval = (ThreeDEval)operand;
				for (int i = threeDEval.FirstSheetIndex; i <= threeDEval.LastSheetIndex; i++)
				{
					int width = threeDEval.Width;
					int height = threeDEval.Height;
					for (int j = 0; j < height; j++)
					{
						for (int k = 0; k < width; k++)
						{
							ValueEval value = threeDEval.GetValue(i, j, k);
							if (IsSubtotalCounted || !threeDEval.IsSubTotal(j, k))
							{
								CollectValue(value, isViaReference: true, temp);
							}
						}
					}
				}
			}
			else if (operand is TwoDEval)
			{
				TwoDEval twoDEval = (TwoDEval)operand;
				int width2 = twoDEval.Width;
				int height2 = twoDEval.Height;
				for (int l = 0; l < height2; l++)
				{
					for (int m = 0; m < width2; m++)
					{
						ValueEval value2 = twoDEval.GetValue(l, m);
						if (IsSubtotalCounted || !twoDEval.IsSubTotal(l, m))
						{
							CollectValue(value2, isViaReference: true, temp);
						}
					}
				}
			}
			else if (operand is RefEval)
			{
				RefEval refEval = (RefEval)operand;
				for (int n = refEval.FirstSheetIndex; n <= refEval.LastSheetIndex; n++)
				{
					CollectValue(refEval.GetInnerValueEval(n), isViaReference: true, temp);
				}
			}
			else
			{
				CollectValue(operand, isViaReference: false, temp);
			}
		}

		private void CollectValue(ValueEval ve, bool isViaReference, DoubleList temp)
		{
			if (ve == null)
			{
				throw new ArgumentException("ve must not be null");
			}
			if (ve is BoolEval)
			{
				if (!isViaReference || _isReferenceBoolCounted)
				{
					BoolEval boolEval = (BoolEval)ve;
					temp.Add(boolEval.NumberValue);
				}
				return;
			}
			if (ve is NumberEval)
			{
				NumberEval numberEval = (NumberEval)ve;
				temp.Add(numberEval.NumberValue);
				return;
			}
			if (ve is StringEval)
			{
				if (!isViaReference)
				{
					string stringValue = ((StringEval)ve).StringValue;
					double num = OperandResolver.ParseDouble(stringValue);
					if (double.IsNaN(num))
					{
						throw new EvaluationException(ErrorEval.VALUE_INVALID);
					}
					temp.Add(num);
				}
				return;
			}
			if (ve is ErrorEval)
			{
				throw new EvaluationException((ErrorEval)ve);
			}
			if (ve == BlankEval.instance)
			{
				if (_isBlankCounted)
				{
					temp.Add(0.0);
				}
				return;
			}
			throw new InvalidOperationException(string.Concat("Invalid ValueEval type passed for conversion: (", ve.GetType(), ")"));
		}

		protected double[] GetNumberArray(ValueEval[] operands)
		{
			if (operands.Length > MaxNumOperands)
			{
				throw EvaluationException.InvalidValue();
			}
			DoubleList doubleList = new DoubleList();
			int i = 0;
			for (int num = operands.Length; i < num; i++)
			{
				CollectValues(operands[i], doubleList);
			}
			return doubleList.ToArray();
		}

		protected static bool AreSubArraysConsistent(double[][] values)
		{
			if (values == null || values.Length < 1)
			{
				return true;
			}
			if (values[0] == null)
			{
				return false;
			}
			int num = values.Length;
			int num2 = values[0].Length;
			for (int i = 1; i < num; i++)
			{
				double[] array = values[i];
				if (array == null)
				{
					return false;
				}
				if (num2 != array.Length)
				{
					return false;
				}
			}
			return true;
		}
	}
	public class Mirr : MultiOperandNumericFunction
	{
		protected override int MaxNumOperands => 3;

		public Mirr()
			: base(isReferenceBoolCounted: false, isBlankCounted: false)
		{
		}

		protected internal override double Evaluate(double[] values)
		{
			double financeRate = values[^1];
			double reinvestRate = values[^2];
			double[] array = new double[values.Length - 2];
			System.Array.Copy(values, 0, array, 0, array.Length);
			bool flag = true;
			double[] array2 = array;
			foreach (double num in array2)
			{
				flag = flag && num < 0.0;
			}
			if (flag)
			{
				return -1.0;
			}
			bool flag2 = true;
			double[] array3 = array;
			foreach (double num2 in array3)
			{
				flag2 = flag2 && num2 > 0.0;
			}
			if (flag2)
			{
				throw new EvaluationException(ErrorEval.DIV_ZERO);
			}
			return mirr(array, financeRate, reinvestRate);
		}

		private static double mirr(double[] in1, double financeRate, double reinvestRate)
		{
			double result = 0.0;
			int num = in1.Length - 1;
			double num2 = 0.0;
			double num3 = 0.0;
			int num4 = 0;
			foreach (double num5 in in1)
			{
				if (num5 < 0.0)
				{
					num2 += num5 / Math.Pow(1.0 + financeRate + reinvestRate, num4++);
				}
			}
			foreach (double num6 in in1)
			{
				if (num6 > 0.0)
				{
					num3 += num6 * Math.Pow(1.0 + financeRate, num - num4++);
				}
			}
			if (num3 != 0.0 && num2 != 0.0)
			{
				result = Math.Pow((0.0 - num3) / num2, 1.0 / (double)num) - 1.0;
			}
			return result;
		}
	}
