	public class Rank : Var2or3ArgFunction
	{
		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			double num;
			AreaEval aeRange;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(arg0, srcRowIndex, srcColumnIndex);
				num = OperandResolver.CoerceValueToDouble(singleValue);
				if (double.IsNaN(num) || double.IsInfinity(num))
				{
					throw new EvaluationException(ErrorEval.NUM_ERROR);
				}
				aeRange = ConvertRangeArg(arg1);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return eval(srcRowIndex, srcColumnIndex, num, aeRange, descending_order: true);
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			bool flag = false;
			double num;
			AreaEval aeRange;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(arg0, srcRowIndex, srcColumnIndex);
				num = OperandResolver.CoerceValueToDouble(singleValue);
				if (double.IsNaN(num) || double.IsInfinity(num))
				{
					throw new EvaluationException(ErrorEval.NUM_ERROR);
				}
				aeRange = ConvertRangeArg(arg1);
				singleValue = OperandResolver.GetSingleValue(arg2, srcRowIndex, srcColumnIndex);
				flag = OperandResolver.CoerceValueToInt(singleValue) switch
				{
					0 => true, 
					1 => false, 
					_ => throw new EvaluationException(ErrorEval.NUM_ERROR), 
				};
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return eval(srcRowIndex, srcColumnIndex, num, aeRange, flag);
		}

		private static ValueEval eval(int srcRowIndex, int srcColumnIndex, double arg0, AreaEval aeRange, bool descending_order)
		{
			int num = 1;
			int height = aeRange.Height;
			int width = aeRange.Width;
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					double value = GetValue(aeRange, i, j);
					if (!double.IsNaN(value) && ((descending_order && value > arg0) || (!descending_order && value < arg0)))
					{
						num++;
					}
				}
			}
			return new NumberEval(num);
		}

		private static double GetValue(AreaEval aeRange, int relRowIndex, int relColIndex)
		{
			ValueEval relativeValue = aeRange.GetRelativeValue(relRowIndex, relColIndex);
			if (relativeValue is NumberEval)
			{
				return ((NumberEval)relativeValue).NumberValue;
			}
			return double.NaN;
		}

		private static AreaEval ConvertRangeArg(ValueEval eval)
		{
			if (eval is AreaEval)
			{
				return (AreaEval)eval;
			}
			if (eval is RefEval)
			{
				return ((RefEval)eval).Offset(0, 0, 0, 0);
			}
			throw new EvaluationException(ErrorEval.VALUE_INVALID);
		}
	}
	public class Rate : Function
	{
		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			if (args.Length < 3)
			{
				return ErrorEval.VALUE_INVALID;
			}
			double fv = 0.0;
			double type = 0.0;
			double guess = 0.1;
			double num;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(args[0], srcRowIndex, srcColumnIndex);
				ValueEval singleValue2 = OperandResolver.GetSingleValue(args[1], srcRowIndex, srcColumnIndex);
				ValueEval singleValue3 = OperandResolver.GetSingleValue(args[2], srcRowIndex, srcColumnIndex);
				ValueEval ev = null;
				if (args.Length >= 4)
				{
					ev = OperandResolver.GetSingleValue(args[3], srcRowIndex, srcColumnIndex);
				}
				ValueEval ev2 = null;
				if (args.Length >= 5)
				{
					ev2 = OperandResolver.GetSingleValue(args[4], srcRowIndex, srcColumnIndex);
				}
				ValueEval ev3 = null;
				if (args.Length >= 6)
				{
					ev3 = OperandResolver.GetSingleValue(args[5], srcRowIndex, srcColumnIndex);
				}
				double nper = OperandResolver.CoerceValueToDouble(singleValue);
				double pmt = OperandResolver.CoerceValueToDouble(singleValue2);
				double pv = OperandResolver.CoerceValueToDouble(singleValue3);
				if (args.Length >= 4)
				{
					fv = OperandResolver.CoerceValueToDouble(ev);
				}
				if (args.Length >= 5)
				{
					type = OperandResolver.CoerceValueToDouble(ev2);
				}
				if (args.Length >= 6)
				{
					guess = OperandResolver.CoerceValueToDouble(ev3);
				}
				num = CalculateRate(nper, pmt, pv, fv, type, guess);
				CheckValue(num);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(num);
		}

		private double CalculateRate(double nper, double pmt, double pv, double fv, double type, double guess)
		{
			int num = 20;
			double num2 = 1E-07;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = guess;
			if (Math.Abs(num6) < num2)
			{
				double num7 = pv * (1.0 + nper * num6) + pmt * (1.0 + num6 * type) * nper + fv;
			}
			else
			{
				num4 = Math.Exp(nper * Math.Log(1.0 + num6));
				double num7 = pv * num4 + pmt * (1.0 / num6 + type) * (num4 - 1.0) + fv;
			}
			double num8 = pv + pmt * nper + fv;
			double num9 = pv * num4 + pmt * (1.0 / num6 + type) * (num4 - 1.0) + fv;
			double num10;
			num5 = (num10 = 0.0);
			num3 = num6;
			while (Math.Abs(num8 - num9) > num2 && num5 < (double)num)
			{
				num6 = (num9 * num10 - num8 * num3) / (num9 - num8);
				num10 = num3;
				num3 = num6;
				double num7;
				if (Math.Abs(num6) < num2)
				{
					num7 = pv * (1.0 + nper * num6) + pmt * (1.0 + num6 * type) * nper + fv;
				}
				else
				{
					num4 = Math.Exp(nper * Math.Log(1.0 + num6));
					num7 = pv * num4 + pmt * (1.0 / num6 + type) * (num4 - 1.0) + fv;
				}
				num8 = num9;
				num9 = num7;
				num5 += 1.0;
			}
			return num6;
		}

		private static void CheckValue(double result)
		{
			if (double.IsNaN(result) || double.IsInfinity(result))
			{
				throw new EvaluationException(ErrorEval.NUM_ERROR);
			}
		}
	}
