	public abstract class SingleArgTextFunc : TextFunction
	{
		public override ValueEval EvaluateFunc(ValueEval[] args, int srcCellRow, int srcCellCol)
		{
			if (args.Length != 1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			string arg = TextFunction.EvaluateStringArg(args[0], srcCellRow, srcCellCol);
			return Evaluate(arg);
		}

		public abstract ValueEval Evaluate(string arg);
	}
	public class Proper : SingleArgTextFunc
	{
		public override ValueEval Evaluate(string text)
		{
			StringBuilder stringBuilder = new StringBuilder();
			bool flag = true;
			string text2 = text.ToLower();
			string text3 = text.ToUpper();
			bool flag2 = char.IsLetter(text[0]);
			stringBuilder.Append(text3[0]);
			for (int i = 1; i < text.Length; i++)
			{
				if (!flag2)
				{
					stringBuilder.Append(text3[i]);
				}
				else
				{
					stringBuilder.Append(text2[i]);
				}
				flag2 = char.IsLetter(text[i]);
			}
			return new StringEval(stringBuilder.ToString());
		}
	}
	public class WeekdayFunc : Function
	{
		public static Function instance = new WeekdayFunc();

		private WeekdayFunc()
		{
		}

		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			try
			{
				if (args.Length < 1 || args.Length > 2)
				{
					return ErrorEval.VALUE_INVALID;
				}
				ValueEval singleValue = OperandResolver.GetSingleValue(args[0], srcRowIndex, srcColumnIndex);
				double num = OperandResolver.CoerceValueToDouble(singleValue);
				if (!DateUtil.IsValidExcelDate(num))
				{
					return ErrorEval.NUM_ERROR;
				}
				int dayOfWeek = (int)DateUtil.GetJavaCalendar(num, use1904windowing: false).DayOfWeek;
				int num2 = 1;
				if (args.Length == 2)
				{
					ValueEval singleValue2 = OperandResolver.GetSingleValue(args[1], srcRowIndex, srcColumnIndex);
					if (singleValue2 == MissingArgEval.instance || singleValue2 == BlankEval.instance)
					{
						return ErrorEval.NUM_ERROR;
					}
					num2 = OperandResolver.CoerceValueToInt(singleValue2);
					if (num2 == 2)
					{
						num2 = 11;
					}
				}
				double value;
				switch (num2)
				{
				case 1:
					value = dayOfWeek;
					break;
				case 3:
					value = (dayOfWeek + 6 - 1) % 7;
					break;
				case 11:
				case 12:
				case 13:
				case 14:
				case 15:
				case 16:
				case 17:
					value = (dayOfWeek + 6 - (num2 - 10)) % 7 + 1;
					break;
				default:
					return ErrorEval.NUM_ERROR;
				}
				return new NumberEval(value);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}
	}
	public class WeekNum : Fixed2ArgFunction, FreeRefFunction
	{
		public static FreeRefFunction instance = new WeekNum();

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval serialNumVE, ValueEval returnTypeVE)
		{
			double num = 0.0;
			try
			{
				num = NumericFunction.SingleOperandEvaluate(serialNumVE, srcRowIndex, srcColumnIndex);
			}
			catch (EvaluationException)
			{
				return ErrorEval.VALUE_INVALID;
			}
			DateTime javaDate = DateUtil.GetJavaDate(num, use1904windowing: false);
			int num2 = 0;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(returnTypeVE, srcRowIndex, srcColumnIndex);
				num2 = OperandResolver.CoerceValueToInt(singleValue);
			}
			catch (EvaluationException)
			{
				return ErrorEval.NUM_ERROR;
			}
			if (num2 != 1 && num2 != 2)
			{
				return ErrorEval.NUM_ERROR;
			}
			return new NumberEval(getWeekNo(javaDate, num2));
		}

		public int getWeekNo(DateTime dt, int weekStartOn)
		{
			GregorianCalendar gregorianCalendar = new GregorianCalendar();
			if (weekStartOn == 1)
			{
				return gregorianCalendar.GetWeekOfYear(dt, CalendarWeekRule.FirstDay, DayOfWeek.Sunday);
			}
			return gregorianCalendar.GetWeekOfYear(dt, CalendarWeekRule.FirstDay, DayOfWeek.Monday);
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length == 2)
			{
				return Evaluate(ec.RowIndex, ec.ColumnIndex, args[0], args[1]);
			}
			return ErrorEval.VALUE_INVALID;
		}
	}
