namespace NPOI.Util
{
	public interface ILittleEndianInput
	{
		int Available();

		int ReadByte();

		int ReadUByte();

		short ReadShort();

		int ReadUShort();

		int ReadInt();

		long ReadLong();

		double ReadDouble();

		void ReadFully(byte[] buf);

		void ReadFully(byte[] buf, int off, int len);
	}
}
namespace NPOI.HSSF.Record.Cont
{
	public class ContinuableRecordInput : ILittleEndianInput
	{
		private RecordInputStream _in;

		public ContinuableRecordInput(RecordInputStream in1)
		{
			_in = in1;
		}

		public int Available()
		{
			return _in.Available();
		}

		public int ReadByte()
		{
			return _in.ReadByte();
		}

		public int ReadUByte()
		{
			return _in.ReadUByte();
		}

		public short ReadShort()
		{
			return _in.ReadShort();
		}

		public int ReadUShort()
		{
			int num = ReadUByte();
			int num2 = ReadUByte();
			return (num2 << 8) + num;
		}

		public int ReadInt()
		{
			int num = _in.ReadUByte();
			int num2 = _in.ReadUByte();
			int num3 = _in.ReadUByte();
			int num4 = _in.ReadUByte();
			return (num4 << 24) + (num3 << 16) + (num2 << 8) + num;
		}

		public long ReadLong()
		{
			int num = _in.ReadUByte();
			int num2 = _in.ReadUByte();
			int num3 = _in.ReadUByte();
			int num4 = _in.ReadUByte();
			int num5 = _in.ReadUByte();
			int num6 = _in.ReadUByte();
			int num7 = _in.ReadUByte();
			int num8 = _in.ReadUByte();
			return ((long)num8 << 56) + ((long)num7 << 48) + ((long)num6 << 40) + ((long)num5 << 32) + ((long)num4 << 24) + (num3 << 16) + (num2 << 8) + num;
		}

		public double ReadDouble()
		{
			return _in.ReadDouble();
		}

		public void ReadFully(byte[] buf)
		{
			_in.ReadFully(buf);
		}

		public void ReadFully(byte[] buf, int off, int len)
		{
			_in.ReadFully(buf, off, len);
		}
	}
}
namespace NPOI.HSSF.Record
{
	public class FeatHdrRecord : StandardRecord
	{
		public const int SHAREDFEATURES_ISFPROTECTION = 2;

		public const int SHAREDFEATURES_ISFFEC2 = 3;

		public const int SHAREDFEATURES_ISFFACTOID = 4;

		public const int SHAREDFEATURES_ISFLIST = 5;

		public const short sid = 2151;

		private FtrHeader futureHeader;

		private int isf_sharedFeatureType;

		private byte reserved;

		private long cbHdrData;

		private byte[] rgbHdrData;

		public override short Sid => 2151;

		protected override int DataSize => 19 + rgbHdrData.Length;

		public FeatHdrRecord()
		{
			futureHeader = new FtrHeader();
			futureHeader.RecordType = 2151;
		}

		public FeatHdrRecord(RecordInputStream in1)
		{
			futureHeader = new FtrHeader(in1);
			isf_sharedFeatureType = in1.ReadShort();
			reserved = (byte)in1.ReadByte();
			cbHdrData = in1.ReadInt();
			rgbHdrData = in1.ReadRemainder();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[FEATURE HEADER]\n");
			stringBuilder.Append("[/FEATURE HEADER]\n");
			return stringBuilder.ToString();
		}

		public override void Serialize(ILittleEndianOutput out1)
		{
			futureHeader.Serialize(out1);
			out1.WriteShort(isf_sharedFeatureType);
			out1.WriteByte(reserved);
			out1.WriteInt((int)cbHdrData);
			out1.Write(rgbHdrData);
		}

		public override object Clone()
		{
			return CloneViaReserialise();
		}
	}
	public class FeatRecord : StandardRecord
	{
		public const short sid = 2152;

		private static POILogger logger = POILogFactory.GetLogger(typeof(FeatRecord));

		private FtrHeader futureHeader;

		private int isf_sharedFeatureType;

		private byte reserved1;

		private long reserved2;

		private long cbFeatData;

		private int reserved3;

		private CellRangeAddress[] cellRefs;

		private SharedFeature sharedFeature;

		public override short Sid => 2152;

		protected override int DataSize => 27 + cellRefs.Length * 8 + sharedFeature.DataSize;

		public int Isf_sharedFeatureType => isf_sharedFeatureType;

		public long CbFeatData
		{
			get
			{
				return cbFeatData;
			}
			set
			{
				cbFeatData = value;
			}
		}

		public CellRangeAddress[] CellRefs
		{
			get
			{
				return cellRefs;
			}
			set
			{
				cellRefs = value;
			}
		}

		public SharedFeature SharedFeature
		{
			get
			{
				return sharedFeature;
			}
			set
			{
				sharedFeature = value;
				if (value is FeatProtection)
				{
					isf_sharedFeatureType = 2;
				}
				if (value is FeatFormulaErr2)
				{
					isf_sharedFeatureType = 3;
				}
				if (value is FeatSmartTag)
				{
					isf_sharedFeatureType = 4;
				}
				if (isf_sharedFeatureType == 3)
				{
					cbFeatData = sharedFeature.DataSize;
				}
				else
				{
					cbFeatData = 0L;
				}
			}
		}

		public FeatRecord()
		{
			futureHeader = new FtrHeader();
			futureHeader.RecordType = 2152;
		}

		public FeatRecord(RecordInputStream in1)
		{
			futureHeader = new FtrHeader(in1);
			isf_sharedFeatureType = in1.ReadShort();
			reserved1 = (byte)in1.ReadByte();
			reserved2 = in1.ReadInt();
			int num = in1.ReadUShort();
			cbFeatData = in1.ReadInt();
			reserved3 = in1.ReadShort();
			cellRefs = new CellRangeAddress[num];
			for (int i = 0; i < cellRefs.Length; i++)
			{
				cellRefs[i] = new CellRangeAddress(in1);
			}
			switch (isf_sharedFeatureType)
			{
			case 2:
				sharedFeature = new FeatProtection(in1);
				break;
			case 3:
				sharedFeature = new FeatFormulaErr2(in1);
				break;
			case 4:
				sharedFeature = new FeatSmartTag(in1);
				break;
			default:
				logger.Log(7, "Unknown Shared Feature " + isf_sharedFeatureType + " found!");
				break;
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[SHARED FEATURE]\n");
			stringBuilder.Append("[/SHARED FEATURE]\n");
			return stringBuilder.ToString();
		}

		public override void Serialize(ILittleEndianOutput out1)
		{
			futureHeader.Serialize(out1);
			out1.WriteShort(isf_sharedFeatureType);
			out1.WriteByte(reserved1);
			out1.WriteInt((int)reserved2);
			out1.WriteShort(cellRefs.Length);
			out1.WriteInt((int)cbFeatData);
			out1.WriteShort(reserved3);
			for (int i = 0; i < cellRefs.Length; i++)
			{
				cellRefs[i].Serialize(out1);
			}
			sharedFeature.Serialize(out1);
		}

		public override object Clone()
		{
			return CloneViaReserialise();
		}
	}
	public class FtCblsSubRecord : SubRecord
	{
		public const short sid = 12;

		private const int ENCODED_SIZE = 20;

		private byte[] reserved;

		public override int DataSize => reserved.Length;

		public override short Sid => 12;

		public FtCblsSubRecord()
		{
			reserved = new byte[20];
		}

		public FtCblsSubRecord(ILittleEndianInput in1, int size)
		{
			if (size != 20)
			{
				throw new RecordFormatException("Unexpected size (" + size + ")");
			}
			byte[] buf = new byte[size];
			in1.ReadFully(buf);
			reserved = buf;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[FtCbls ]").Append("\n");
			stringBuilder.Append("  size     = ").Append(DataSize).Append("\n");
			stringBuilder.Append("  reserved = ").Append(HexDump.ToHex(reserved)).Append("\n");
			stringBuilder.Append("[/FtCbls ]").Append("\n");
			return stringBuilder.ToString();
		}

		public override void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteShort(12);
			out1.WriteShort(reserved.Length);
			out1.Write(reserved);
		}

		public override object Clone()
		{
			FtCblsSubRecord ftCblsSubRecord = new FtCblsSubRecord();
			byte[] array = new byte[reserved.Length];
			System.Array.Copy(reserved, 0, array, 0, array.Length);
			ftCblsSubRecord.reserved = array;
			return ftCblsSubRecord;
		}
	}
