namespace NPOI.HSSF.UserModel
{
	public class DVConstraint : IDataValidationConstraint
	{
		public class FormulaPair
		{
			private Ptg[] _formula1;

			private Ptg[] _formula2;

			public Ptg[] Formula1 => _formula1;

			public Ptg[] Formula2 => _formula2;

			public FormulaPair(Ptg[] formula1, Ptg[] formula2)
			{
				_formula1 = formula1;
				_formula2 = formula2;
			}
		}

		private class FormulaValuePair
		{
			internal string _formula;

			internal string _value;

			public double Value
			{
				get
				{
					if (_value == null)
					{
						return double.NaN;
					}
					return double.Parse(_value);
				}
			}

			public string formula()
			{
				return _formula;
			}

			public string AsString()
			{
				if (_formula != null)
				{
					return _formula;
				}
				if (_value != null)
				{
					return _value;
				}
				return null;
			}
		}

		private int _validationType;

		private int _operator;

		private string[] _explicitListValues;

		private string _formula1;

		private string _formula2;

		private double _value1;

		private double _value2;

		public bool IsListValidationType => _validationType == 3;

		public bool IsExplicitList
		{
			get
			{
				if (_validationType == 3)
				{
					return _explicitListValues != null;
				}
				return false;
			}
		}

		public int Operator
		{
			get
			{
				return _operator;
			}
			set
			{
				_operator = value;
			}
		}

		public string[] ExplicitListValues
		{
			get
			{
				return _explicitListValues;
			}
			set
			{
				if (_validationType != 3)
				{
					throw new InvalidOperationException("Cannot setExplicitListValues on non-list constraint");
				}
				_formula1 = null;
				_explicitListValues = value;
			}
		}

		public string Formula1
		{
			get
			{
				return _formula1;
			}
			set
			{
				_value1 = double.NaN;
				_explicitListValues = null;
				_formula1 = value;
			}
		}

		public string Formula2
		{
			get
			{
				return _formula2;
			}
			set
			{
				_value2 = double.NaN;
				_formula2 = value;
			}
		}

		public double Value1
		{
			get
			{
				return _value1;
			}
			set
			{
				_formula1 = null;
				_value1 = value;
			}
		}

		public double Value2
		{
			get
			{
				return _value2;
			}
			set
			{
				_formula2 = null;
				_value2 = value;
			}
		}

		private DVConstraint(int validationType, int comparisonOperator, string formulaA, string formulaB, double value1, double value2, string[] excplicitListValues)
		{
			_validationType = validationType;
			_operator = comparisonOperator;
			_formula1 = formulaA;
			_formula2 = formulaB;
			_value1 = value1;
			_value2 = value2;
			_explicitListValues = excplicitListValues;
		}

		private DVConstraint(string listFormula, string[] excplicitListValues)
			: this(3, 0, listFormula, null, double.NaN, double.NaN, excplicitListValues)
		{
		}

		public static DVConstraint CreateNumericConstraint(int validationType, int comparisonOperator, string expr1, string expr2)
		{
			switch (validationType)
			{
			case 0:
				if (expr1 != null || expr2 != null)
				{
					throw new ArgumentException("expr1 and expr2 must be null for validation type 'any'");
				}
				break;
			case 1:
			case 2:
			case 6:
				if (expr1 == null)
				{
					throw new ArgumentException("expr1 must be supplied");
				}
				OperatorType.ValidateSecondArg(comparisonOperator, expr2);
				break;
			default:
				throw new ArgumentException("Validation Type (" + validationType + ") not supported with this method");
			}
			string formulaFromTextExpression = GetFormulaFromTextExpression(expr1);
			double value = ((formulaFromTextExpression == null) ? ConvertNumber(expr1) : double.NaN);
			string formulaFromTextExpression2 = GetFormulaFromTextExpression(expr2);
			double value2 = ((formulaFromTextExpression2 == null) ? ConvertNumber(expr2) : double.NaN);
			return new DVConstraint(validationType, comparisonOperator, formulaFromTextExpression, formulaFromTextExpression2, value, value2, null);
		}

		public static DVConstraint CreateFormulaListConstraint(string listFormula)
		{
			return new DVConstraint(listFormula, null);
		}

		public static DVConstraint CreateExplicitListConstraint(string[] explicitListValues)
		{
			return new DVConstraint(null, explicitListValues);
		}

		public static DVConstraint CreateTimeConstraint(int comparisonOperator, string expr1, string expr2)
		{
			if (expr1 == null)
			{
				throw new ArgumentException("expr1 must be supplied");
			}
			OperatorType.ValidateSecondArg(comparisonOperator, expr1);
			string formulaFromTextExpression = GetFormulaFromTextExpression(expr1);
			double value = ((formulaFromTextExpression == null) ? ConvertTime(expr1) : double.NaN);
			string formulaFromTextExpression2 = GetFormulaFromTextExpression(expr2);
			double value2 = ((formulaFromTextExpression2 == null) ? ConvertTime(expr2) : double.NaN);
			return new DVConstraint(5, comparisonOperator, formulaFromTextExpression, formulaFromTextExpression2, value, value2, null);
		}

		public static DVConstraint CreateDateConstraint(int comparisonOperator, string expr1, string expr2, string dateFormat)
		{
			if (expr1 == null)
			{
				throw new ArgumentException("expr1 must be supplied");
			}
			OperatorType.ValidateSecondArg(comparisonOperator, expr2);
			SimpleDateFormat dateFormat2 = ((dateFormat == null) ? null : new SimpleDateFormat(dateFormat));
			string formulaFromTextExpression = GetFormulaFromTextExpression(expr1);
			double value = ((formulaFromTextExpression == null) ? ConvertDate(expr1, dateFormat2) : double.NaN);
			string formulaFromTextExpression2 = GetFormulaFromTextExpression(expr2);
			double value2 = ((formulaFromTextExpression2 == null) ? ConvertDate(expr2, dateFormat2) : double.NaN);
			return new DVConstraint(4, comparisonOperator, formulaFromTextExpression, formulaFromTextExpression2, value, value2, null);
		}

		private static string GetFormulaFromTextExpression(string textExpr)
		{
			if (textExpr == null)
			{
				return null;
			}
			if (textExpr.Length < 1)
			{
				throw new ArgumentException("Empty string is not a valid formula/value expression");
			}
			if (textExpr[0] == '=')
			{
				return textExpr.Substring(1);
			}
			return null;
		}

		private static double ConvertNumber(string numberStr)
		{
			if (numberStr == null)
			{
				return double.NaN;
			}
			try
			{
				return double.Parse(numberStr, CultureInfo.CurrentCulture);
			}
			catch (FormatException)
			{
				throw new InvalidOperationException("The supplied text '" + numberStr + "' could not be parsed as a number");
			}
		}

		private static double ConvertTime(string timeStr)
		{
			if (timeStr == null)
			{
				return double.NaN;
			}
			return DateUtil.ConvertTime(timeStr);
		}

		private static double ConvertDate(string dateStr, SimpleDateFormat dateFormat)
		{
			if (dateStr == null)
			{
				return double.NaN;
			}
			DateTime date;
			if (dateFormat == null)
			{
				date = DateUtil.ParseYYYYMMDDDate(dateStr);
			}
			else
			{
				try
				{
					date = DateTime.Parse(dateStr, CultureInfo.CurrentCulture);
				}
				catch (FormatException innerException)
				{
					throw new InvalidOperationException(string.Concat("Failed to parse date '", dateStr, "' using specified format '", dateFormat, "'"), innerException);
				}
			}
			return DateUtil.GetExcelDate(date);
		}

		public static DVConstraint CreateCustomFormulaConstraint(string formula)
		{
			if (formula == null)
			{
				throw new ArgumentException("formula must be supplied");
			}
			return new DVConstraint(7, 0, formula, null, double.NaN, double.NaN, null);
		}

		public int GetValidationType()
		{
			return _validationType;
		}

		public FormulaPair CreateFormulas(HSSFSheet sheet)
		{
			Ptg[] formula;
			Ptg[] formula2;
			if (IsListValidationType)
			{
				formula = CreateListFormula(sheet);
				formula2 = Ptg.EMPTY_PTG_ARRAY;
			}
			else
			{
				formula = ConvertDoubleFormula(_formula1, _value1, sheet);
				formula2 = ConvertDoubleFormula(_formula2, _value2, sheet);
			}
			return new FormulaPair(formula, formula2);
		}

		private Ptg[] CreateListFormula(HSSFSheet sheet)
		{
			if (_explicitListValues == null)
			{
				IWorkbook workbook = sheet.Workbook;
				return HSSFFormulaParser.Parse(_formula1, (HSSFWorkbook)workbook, FormulaType.DataValidationList, workbook.GetSheetIndex(sheet));
			}
			StringBuilder stringBuilder = new StringBuilder(_explicitListValues.Length * 16);
			for (int i = 0; i < _explicitListValues.Length; i++)
			{
				if (i > 0)
				{
					stringBuilder.Append('\0');
				}
				stringBuilder.Append(_explicitListValues[i]);
			}
			return new Ptg[1]
			{
				new StringPtg(stringBuilder.ToString())
			};
		}

		private static Ptg[] ConvertDoubleFormula(string formula, double value, HSSFSheet sheet)
		{
			if (formula == null)
			{
				if (double.IsNaN(value))
				{
					return Ptg.EMPTY_PTG_ARRAY;
				}
				return new Ptg[1]
				{
					new NumberPtg(value)
				};
			}
			if (!double.IsNaN(value))
			{
				throw new InvalidOperationException("Both formula and value cannot be present");
			}
			IWorkbook workbook = sheet.Workbook;
			return HSSFFormulaParser.Parse(formula, (HSSFWorkbook)workbook, FormulaType.Cell, workbook.GetSheetIndex(sheet));
		}

		internal static DVConstraint CreateDVConstraint(DVRecord dvRecord, IFormulaRenderingWorkbook book)
		{
			switch (dvRecord.DataType)
			{
			case 0:
				return new DVConstraint(0, dvRecord.ConditionOperator, null, null, double.NaN, double.NaN, null);
			case 1:
			case 2:
			case 4:
			case 5:
			case 6:
			{
				FormulaValuePair formulaValuePair = toFormulaString(dvRecord.Formula1, book);
				FormulaValuePair formulaValuePair2 = toFormulaString(dvRecord.Formula2, book);
				return new DVConstraint(dvRecord.DataType, dvRecord.ConditionOperator, formulaValuePair.formula(), formulaValuePair2.formula(), formulaValuePair.Value, formulaValuePair2.Value, null);
			}
			case 3:
			{
				if (dvRecord.ListExplicitFormula)
				{
					string text = toFormulaString(dvRecord.Formula1, book).AsString();
					if (text.StartsWith("\""))
					{
						text = text.Substring(1);
					}
					if (text.EndsWith("\""))
					{
						text = text.Substring(0, text.Length - 1);
					}
					string[] explicitListValues = text.Split("\0".ToCharArray());
					return CreateExplicitListConstraint(explicitListValues);
				}
				string listFormula = toFormulaString(dvRecord.Formula1, book).AsString();
				return CreateFormulaListConstraint(listFormula);
			}
			case 7:
				return CreateCustomFormulaConstraint(toFormulaString(dvRecord.Formula1, book).AsString());
			default:
				throw new InvalidOperationException($"validationType={dvRecord.DataType}");
			}
		}

		private static FormulaValuePair toFormulaString(Ptg[] ptgs, IFormulaRenderingWorkbook book)
		{
			FormulaValuePair formulaValuePair = new FormulaValuePair();
			if (ptgs != null && ptgs.Length > 0)
			{
				string text = FormulaRenderer.ToFormulaString(book, ptgs);
				if (ptgs.Length == 1 && ptgs[0].GetType() == typeof(NumberPtg))
				{
					formulaValuePair._value = text;
				}
				else
				{
					formulaValuePair._formula = text;
				}
			}
			return formulaValuePair;
		}
	}
}
namespace NPOI.SS.UserModel
{
	public class DataFormatter
	{
		private static string defaultFractionWholePartFormat;

		private static string defaultFractionFractionPartFormat;

		private static string numPattern;

		private static string daysAsText;

		private static string amPmPattern;

		private static string localePatternGroup;

		private static Regex colorPattern;

		private static Regex fractionPattern;

		private static Regex fractionStripper;

		private static string invalidDateTimeString;

		private static DecimalFormat generalWholeNumFormat;

		private static DecimalFormat generalDecimalNumFormat;

		private FormatBase defaultNumFormat;

		private CultureInfo currentCulture;

		private Hashtable formats;

		private bool emulateCsv;

		private static readonly Regex RegexDoubleBackslashAny;

		private static readonly Regex RegexContinueWs;

		private static readonly Regex RegexAnyInDoubleQuote;

		static DataFormatter()
		{
			defaultFractionWholePartFormat = "#";
			defaultFractionFractionPartFormat = "#/##";
			numPattern = "[0#]+";
			daysAsText = "([d]{3,})";
			amPmPattern = "((A|P)[M/P]*)";
			localePatternGroup = "(\\[\\$[^-\\]]*-[0-9A-Z]+\\])";
			colorPattern = new Regex("(\\[BLACK\\])|(\\[BLUE\\])|(\\[CYAN\\])|(\\[GREEN\\])|(\\[MAGENTA\\])|(\\[RED\\])|(\\[WHITE\\])|(\\[YELLOW\\])|(\\[COLOR\\s*\\d\\])|(\\[COLOR\\s*[0-5]\\d\\])", RegexOptions.IgnoreCase);
			fractionPattern = new Regex("(?:([#\\d]+)\\s+)?(#+)\\s*\\/\\s*([#\\d]+)");
			fractionStripper = new Regex("(\"[^\"]*\")|([^ \\?#\\d\\/]+)");
			generalWholeNumFormat = new DecimalFormat("0");
			generalDecimalNumFormat = new DecimalFormat("#.##########");
			RegexDoubleBackslashAny = new Regex("\\\\.");
			RegexContinueWs = new Regex("\\s");
			RegexAnyInDoubleQuote = new Regex("\"[^\"]*\"");
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < 255; i++)
			{
				stringBuilder.Append('#');
			}
			invalidDateTimeString = stringBuilder.ToString();
		}

		public DataFormatter()
			: this(emulateCsv: false)
		{
		}

		public DataFormatter(CultureInfo culture)
		{
			currentCulture = culture;
			formats = new Hashtable();
			FormatBase instance = ZipPlusFourFormat.instance;
			AddFormat("00000\\-0000", instance);
			AddFormat("00000-0000", instance);
			FormatBase instance2 = PhoneFormat.instance;
			AddFormat("[<=9999999]###\\-####;\\(###\\)\\ ###\\-####", instance2);
			AddFormat("[<=9999999]###-####;(###) ###-####", instance2);
			AddFormat("###\\-####;\\(###\\)\\ ###\\-####", instance2);
			AddFormat("###-####;(###) ###-####", instance2);
			FormatBase instance3 = SSNFormat.instance;
			AddFormat("000\\-00\\-0000", instance3);
			AddFormat("000-00-0000", instance3);
		}

		public DataFormatter(bool emulateCsv)
			: this(CultureInfo.CurrentCulture)
		{
			this.emulateCsv = emulateCsv;
		}

		public DataFormatter(CultureInfo locale, bool emulateCsv)
			: this(locale)
		{
			this.emulateCsv = emulateCsv;
		}

		private FormatBase GetFormat(ICell cell)
		{
			if (cell.CellStyle == null)
			{
				return null;
			}
			int dataFormat = cell.CellStyle.DataFormat;
			string dataFormatString = cell.CellStyle.GetDataFormatString();
			if (dataFormatString == null || dataFormatString.Trim().Length == 0)
			{
				return null;
			}
			return GetFormat(cell.NumericCellValue, dataFormat, dataFormatString);
		}

		private FormatBase GetFormat(double cellValue, int formatIndex, string formatStrIn)
		{
			string text = formatStrIn;
			int num = text.IndexOf(';');
			int num2 = text.LastIndexOf(';');
			if (num != -1 && num != num2)
			{
				int num3 = text.IndexOf(';', num + 1);
				text = ((num3 == num2) ? ((cellValue != 0.0) ? text.Substring(0, num2) : text.Substring(num2 + 1)) : ((cellValue != 0.0) ? text.Substring(0, num3) : text.Substring(num3 + 1, num2 - (num3 + 1))));
			}
			if (emulateCsv && cellValue == 0.0 && text.Contains("#") && !text.Contains("0"))
			{
				text = text.Replace("#", "");
			}
			FormatBase formatBase = (FormatBase)formats[text];
			if (formatBase != null)
			{
				return formatBase;
			}
			if (text.Equals("General", StringComparison.CurrentCultureIgnoreCase) || "@".Equals(text))
			{
				if (IsWholeNumber(cellValue))
				{
					return generalWholeNumFormat;
				}
				return generalDecimalNumFormat;
			}
			formatBase = CreateFormat(cellValue, formatIndex, text);
			formats[text] = formatBase;
			return formatBase;
		}

		public FormatBase CreateFormat(ICell cell)
		{
			int dataFormat = cell.CellStyle.DataFormat;
			string dataFormatString = cell.CellStyle.GetDataFormatString();
			return CreateFormat(cell.NumericCellValue, dataFormat, dataFormatString);
		}

		private FormatBase CreateFormat(double cellValue, int formatIndex, string sFormat)
		{
			string text = colorPattern.Replace(sFormat, "");
			MatchCollection matchCollection = Regex.Matches(text, localePatternGroup);
			foreach (System.Text.RegularExpressions.Match item in matchCollection)
			{
				string value = item.Value;
				int num = value.IndexOf('$') + 1;
				int num2 = value.IndexOf('-');
				string text2 = value.Substring(num, num2 - num);
				if (text2.IndexOf('$') > -1)
				{
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.Append(text2.Substring(0, text2.IndexOf('$')));
					stringBuilder.Append('\\');
					stringBuilder.Append(text2.Substring(text2.IndexOf('$'), text2.Length));
					text2 = stringBuilder.ToString();
				}
				value = Regex.Replace(value, localePatternGroup, text2);
				text = text.Remove(item.Index, item.Length);
				text = text.Insert(item.Index, value);
			}
			if (text == null || text.Trim().Length == 0)
			{
				return GetDefaultFormat(cellValue);
			}
			if ("General".Equals(text, StringComparison.CurrentCultureIgnoreCase) || "@".Equals(text))
			{
				if (IsWholeNumber(cellValue))
				{
					return generalWholeNumFormat;
				}
				return generalDecimalNumFormat;
			}
			if (DateUtil.IsADateFormat(formatIndex, text) && DateUtil.IsValidExcelDate(cellValue))
			{
				return CreateDateFormat(text, cellValue);
			}
			if (text.IndexOf("#/") >= 0 || text.IndexOf("?/") >= 0)
			{
				string[] array = text.Split(";".ToCharArray());
				for (int i = 0; i < array.Length; i++)
				{
					string input = array[i].Replace("?", "#");
					input = fractionStripper.Replace(input, " ");
					input = input.Replace(" +", " ");
					System.Text.RegularExpressions.Match match2 = fractionPattern.Match(input);
					if (match2.Success)
					{
						string wholePartFormatString = ((match2.Groups[1] == null || !match2.Groups[1].Success) ? "" : defaultFractionWholePartFormat);
						return new FractionFormat(wholePartFormatString, match2.Groups[3].Value);
					}
				}
				return new FractionFormat(defaultFractionWholePartFormat, defaultFractionFractionPartFormat);
			}
			if (Regex.IsMatch(text, numPattern))
			{
				return CreateNumberFormat(text, cellValue);
			}
			if (emulateCsv)
			{
				return new ConstantStringFormat(cleanFormatForNumber(text));
			}
			return null;
		}

		private int IndexOfFraction(string format)
		{
			int num = format.IndexOf("#/#");
			int num2 = format.IndexOf("?/?");
			if (num != -1)
			{
				if (num2 != -1)
				{
					return Math.Min(num, num2);
				}
				return num;
			}
			return num2;
		}

		private int LastIndexOfFraction(string format)
		{
			int num = format.LastIndexOf("#/#");
			int num2 = format.LastIndexOf("?/?");
			if (num != -1)
			{
				if (num2 != -1)
				{
					return Math.Max(num, num2);
				}
				return num;
			}
			return num2;
		}

		private FormatBase CreateDateFormat(string pformatStr, double cellValue)
		{
			string text = pformatStr;
			text = text.Replace("\\-", "-");
			text = text.Replace("\\,", ",");
			text = text.Replace("\\.", ".");
			text = text.Replace("\\ ", " ");
			text = text.Replace("\\/", "/");
			text = text.Replace(";@", "");
			text = text.Replace("\"/\"", "/");
			text = text.Replace("\"\"", "'");
			text = text.Replace("\\\\T", "'T'");
			bool flag = Regex.IsMatch(text, amPmPattern);
			if (flag)
			{
				text = Regex.Replace(text, amPmPattern, "@");
			}
			text = text.Replace("@", "tt");
			MatchCollection matchCollection = Regex.Matches(text, daysAsText);
			if (matchCollection.Count > 0)
			{
				string replacement = matchCollection[0].Groups[0].Value.ToUpper().Replace("D", "E");
				text = Regex.Replace(text, daysAsText, replacement);
			}
			StringBuilder stringBuilder = new StringBuilder();
			char[] array = text.ToCharArray();
			bool flag2 = true;
			bool flag3 = false;
			ArrayList arrayList = new ArrayList();
			for (int i = 0; i < array.Length; i++)
			{
				char c = array[i];
				switch (c)
				{
				case '\'':
					stringBuilder.Append(c);
					for (i++; i < array.Length; i++)
					{
						c = array[i];
						stringBuilder.Append(c);
						if (c == '\'')
						{
							break;
						}
					}
					continue;
				case '[':
					if (!flag3)
					{
						flag3 = true;
						flag2 = false;
						stringBuilder.Append(c);
						continue;
					}
					break;
				}
				if (c == ']' && flag3)
				{
					flag3 = false;
					stringBuilder.Append(c);
					continue;
				}
				if (flag3)
				{
					switch (c)
					{
					case 'H':
					case 'h':
						stringBuilder.Append('H');
						break;
					case 'M':
					case 'm':
						stringBuilder.Append('m');
						break;
					case 'S':
					case 's':
						stringBuilder.Append('s');
						break;
					default:
						stringBuilder.Append(c);
						break;
					}
					continue;
				}
				switch (c)
				{
				case 'H':
				case 'h':
					flag2 = false;
					if (flag)
					{
						stringBuilder.Append('h');
					}
					else
					{
						stringBuilder.Append('H');
					}
					continue;
				case 'M':
				case 'm':
					if (flag2)
					{
						stringBuilder.Append('M');
						arrayList.Add(stringBuilder.Length - 1);
					}
					else
					{
						stringBuilder.Append('m');
					}
					continue;
				case 'S':
				case 's':
				{
					stringBuilder.Append('s');
					for (int j = 0; j < arrayList.Count; j++)
					{
						int index = (int)arrayList[j];
						if (stringBuilder[index] == 'M')
						{
							stringBuilder[index] = 'm';
						}
					}
					flag2 = true;
					arrayList.Clear();
					continue;
				}
				}
				if (char.IsLetter(c))
				{
					flag2 = true;
					arrayList.Clear();
					switch (c)
					{
					case 'Y':
					case 'y':
						stringBuilder.Append('y');
						break;
					case 'D':
					case 'd':
						stringBuilder.Append('d');
						break;
					default:
						stringBuilder.Append(c);
						break;
					}
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			text = stringBuilder.ToString();
			try
			{
				return new ExcelStyleDateFormatter(text);
			}
			catch (ArgumentException)
			{
				return GetDefaultFormat(cellValue);
			}
		}

		private string cleanFormatForNumber(string formatStr)
		{
			StringBuilder stringBuilder = new StringBuilder(formatStr);
			if (emulateCsv)
			{
				for (int i = 0; i < stringBuilder.Length; i++)
				{
					char c = stringBuilder[i];
					if ((c != '_' && c != '*' && c != '?') || (i > 0 && stringBuilder[i - 1] == '\\'))
					{
						continue;
					}
					if (c == '?')
					{
						stringBuilder[i] = ' ';
					}
					else if (i < stringBuilder.Length - 1)
					{
						if (c == '_')
						{
							stringBuilder[i + 1] = ' ';
						}
						else
						{
							stringBuilder.Remove(i + 1, 1);
						}
						stringBuilder.Remove(i, 1);
						i--;
					}
				}
			}
			else
			{
				for (int j = 0; j < stringBuilder.Length; j++)
				{
					char c2 = stringBuilder[j];
					if ((c2 == '_' || c2 == '*') && (j <= 0 || stringBuilder[j - 1] != '\\'))
					{
						if (j < stringBuilder.Length - 1)
						{
							stringBuilder.Remove(j + 1, 1);
						}
						stringBuilder.Remove(j, 1);
						j--;
					}
				}
			}
			for (int k = 0; k < stringBuilder.Length; k++)
			{
				switch (stringBuilder[k])
				{
				case '"':
				case '\\':
					stringBuilder.Remove(k, 1);
					k--;
					break;
				case '+':
					if (k > 0 && stringBuilder[k - 1] == 'E')
					{
						stringBuilder.Remove(k, 1);
						k--;
					}
					break;
				}
			}
			return stringBuilder.ToString();
		}

		private FormatBase CreateNumberFormat(string formatStr, double cellValue)
		{
			string pattern = cleanFormatForNumber(formatStr);
			try
			{
				return new DecimalFormat(pattern);
			}
			catch (ArgumentException)
			{
				return GetDefaultFormat(cellValue);
			}
		}

		private static bool IsWholeNumber(double d)
		{
			return d == Math.Floor(d);
		}

		public FormatBase GetDefaultFormat(ICell cell)
		{
			return GetDefaultFormat(cell.NumericCellValue);
		}

		private FormatBase GetDefaultFormat(double cellValue)
		{
			if (defaultNumFormat != null)
			{
				return defaultNumFormat;
			}
			if (IsWholeNumber(cellValue))
			{
				return generalWholeNumFormat;
			}
			return generalDecimalNumFormat;
		}

		private string GetFormattedDateString(ICell cell)
		{
			FormatBase format = GetFormat(cell);
			DateTime dateCellValue = cell.DateCellValue;
			if (format != null)
			{
				return format.Format(dateCellValue, currentCulture);
			}
			return dateCellValue.ToString();
		}

		private string GetFormattedNumberString(ICell cell)
		{
			FormatBase format = GetFormat(cell);
			double numericCellValue = cell.NumericCellValue;
			if (format == null)
			{
				return numericCellValue.ToString(currentCulture);
			}
			return format.Format(numericCellValue, currentCulture);
		}

		public string FormatRawCellContents(double value, int formatIndex, string formatString)
		{
			return FormatRawCellContents(value, formatIndex, formatString, use1904Windowing: false);
		}

		private string PerformDateFormatting(DateTime d, FormatBase dateFormat)
		{
			if (dateFormat != null)
			{
				return dateFormat.Format(d, currentCulture);
			}
			return d.ToString();
		}

		public string FormatRawCellContents(double value, int formatIndex, string formatString, bool use1904Windowing)
		{
			if (DateUtil.IsADateFormat(formatIndex, formatString))
			{
				if (DateUtil.IsValidExcelDate(value))
				{
					FormatBase format = GetFormat(value, formatIndex, formatString);
					if (format is ExcelStyleDateFormatter)
					{
						((ExcelStyleDateFormatter)format).SetDateToBeFormatted(value);
					}
					DateTime javaDate = DateUtil.GetJavaDate(value, use1904Windowing);
					return PerformDateFormatting(javaDate, format);
				}
				if (emulateCsv)
				{
					return invalidDateTimeString;
				}
			}
			FormatBase format2 = GetFormat(value, formatIndex, formatString);
			if (format2 == null)
			{
				return value.ToString(currentCulture);
			}
			string text = NumberToTextConverter.ToText(value);
			string text2 = ((text.IndexOf('E') <= -1) ? format2.Format(text) : format2.Format(value));
			if (text2.Contains("E") && !text2.Contains("E-"))
			{
				text2 = text2.Replace("E", "E+");
			}
			return text2;
		}

		public string FormatCellValue(ICell cell)
		{
			return FormatCellValue(cell, null);
		}

		public string FormatCellValue(ICell cell, IFormulaEvaluator evaluator)
		{
			if (cell == null)
			{
				return "";
			}
			CellType cellType = cell.CellType;
			if (evaluator != null && cellType == CellType.Formula)
			{
				if (evaluator == null)
				{
					return cell.CellFormula;
				}
				cellType = evaluator.EvaluateFormulaCell(cell);
			}
			switch (cellType)
			{
			case CellType.Formula:
				return cell.CellFormula;
			case CellType.Numeric:
				if (DateUtil.IsCellDateFormatted(cell))
				{
					return GetFormattedDateString(cell);
				}
				return GetFormattedNumberString(cell);
			case CellType.String:
				return cell.RichStringCellValue.String;
			case CellType.Boolean:
				return cell.BooleanCellValue.ToString().ToUpper();
			case CellType.Blank:
				return "";
			case CellType.Error:
				return FormulaError.ForInt(cell.ErrorCellValue).String;
			default:
				throw new Exception(string.Concat("Unexpected celltype (", cellType, ")"));
			}
		}

		public void SetDefaultNumberFormat(FormatBase format)
		{
			IEnumerator enumerator = formats.Keys.GetEnumerator();
			while (enumerator.MoveNext())
			{
				string key = (string)enumerator.Current;
				if (formats[key] == generalDecimalNumFormat || formats[key] == generalWholeNumFormat)
				{
					formats[key] = format;
				}
			}
			defaultNumFormat = format;
		}

		public void AddFormat(string excelformatStr, FormatBase format)
		{
			formats[excelformatStr] = format;
		}
	}
