namespace NPOI.DDF
{
	public interface IEscherRecordFactory
	{
		EscherRecord CreateRecord(byte[] data, int offset);
	}
	public class DefaultEscherRecordFactory : IEscherRecordFactory
	{
		private static Type[] escherRecordClasses = new Type[12]
		{
			typeof(EscherBSERecord),
			typeof(EscherOptRecord),
			typeof(EscherTertiaryOptRecord),
			typeof(EscherClientAnchorRecord),
			typeof(EscherDgRecord),
			typeof(EscherSpgrRecord),
			typeof(EscherSpRecord),
			typeof(EscherClientDataRecord),
			typeof(EscherDggRecord),
			typeof(EscherSplitMenuColorsRecord),
			typeof(EscherChildAnchorRecord),
			typeof(EscherTextboxRecord)
		};

		private static Dictionary<short, ConstructorInfo> recordsMap = RecordsToMap(escherRecordClasses);

		public virtual EscherRecord CreateRecord(byte[] data, int offset)
		{
			short @short = LittleEndian.GetShort(data, offset);
			short short2 = LittleEndian.GetShort(data, offset + 2);
			if (IsContainer(@short, short2))
			{
				EscherContainerRecord escherContainerRecord = new EscherContainerRecord();
				escherContainerRecord.RecordId = short2;
				escherContainerRecord.Options = @short;
				return escherContainerRecord;
			}
			if (short2 >= -4072 && short2 <= -3817)
			{
				EscherBlipRecord escherBlipRecord;
				switch (short2)
				{
				case -4067:
				case -4066:
				case -4065:
					escherBlipRecord = new EscherBitmapBlip();
					break;
				case -4070:
				case -4069:
				case -4068:
					escherBlipRecord = new EscherMetafileBlip();
					break;
				default:
					escherBlipRecord = new EscherBlipRecord();
					break;
				}
				escherBlipRecord.RecordId = short2;
				escherBlipRecord.Options = @short;
				return escherBlipRecord;
			}
			ConstructorInfo constructorInfo = null;
			if (recordsMap.ContainsKey(short2))
			{
				constructorInfo = recordsMap[short2];
			}
			EscherRecord escherRecord = null;
			if (constructorInfo == null)
			{
				return new UnknownEscherRecord();
			}
			try
			{
				escherRecord = (EscherRecord)constructorInfo.Invoke(new object[0]);
			}
			catch (Exception)
			{
				return new UnknownEscherRecord();
			}
			escherRecord.RecordId = short2;
			escherRecord.Options = @short;
			return escherRecord;
		}

		private static Dictionary<short, ConstructorInfo> RecordsToMap(Type[] records)
		{
			Dictionary<short, ConstructorInfo> dictionary = new Dictionary<short, ConstructorInfo>();
			Type[] types = new Type[0];
			foreach (Type type in records)
			{
				short num = 0;
				try
				{
					num = (short)type.GetField("RECORD_ID").GetValue(null);
				}
				catch (Exception)
				{
					throw new RecordFormatException("Unable to determine record types");
				}
				ConstructorInfo constructor;
				try
				{
					constructor = type.GetConstructor(types);
				}
				catch (Exception e)
				{
					throw new RuntimeException(e);
				}
				dictionary.Add(num, constructor);
			}
			return dictionary;
		}

		public static bool IsContainer(short options, short recordId)
		{
			if (recordId >= -4096 && recordId <= -4091)
			{
				return true;
			}
			if (recordId == -4083)
			{
				return false;
			}
			return (options & 0xF) == 15;
		}
	}
	public abstract class EscherProperty
	{
		protected short id;

		public virtual short Id => id;

		public virtual short PropertyNumber => (short)(id & 0x3FFF);

		public virtual bool IsComplex => (id & -32768) != 0;

		public virtual bool IsBlipId => (id & 0x4000) != 0;

		public virtual string Name => EscherProperties.GetPropertyName(PropertyNumber);

		public virtual int PropertySize => 6;

		public EscherProperty(short id)
		{
			this.id = id;
		}

		public EscherProperty(short propertyNumber, bool isComplex, bool isBlipId)
		{
			id = (short)(propertyNumber + (isComplex ? (-32768) : 0) + (isBlipId ? 16384 : 0));
		}

		public virtual string ToXml(string tab)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(tab).Append("<").Append(GetType().Name)
				.Append(" id=\"")
				.Append(Id)
				.Append("\" name=\"")
				.Append(Name)
				.Append("\" blipId=\"")
				.Append(IsBlipId)
				.Append("\"/>\n");
			return stringBuilder.ToString();
		}

		public abstract int SerializeSimplePart(byte[] data, int pos);

		public abstract int SerializeComplexPart(byte[] data, int pos);
	}
	public class EscherComplexProperty : EscherProperty
	{
		protected byte[] _complexData = new byte[0];

		public byte[] ComplexData => _complexData;

		public override int PropertySize => 6 + _complexData.Length;

		public EscherComplexProperty(short id, byte[] complexData)
			: base(id)
		{
			_complexData = complexData;
		}

		public EscherComplexProperty(short propertyNumber, bool isBlipId, byte[] complexData)
			: base(propertyNumber, isComplex: true, isBlipId)
		{
			_complexData = complexData;
		}

		public override int SerializeSimplePart(byte[] data, int pos)
		{
			LittleEndian.PutShort(data, pos, Id);
			LittleEndian.PutInt(data, pos + 2, _complexData.Length);
			return 6;
		}

		public override int SerializeComplexPart(byte[] data, int pos)
		{
			System.Array.Copy(_complexData, 0, data, pos, _complexData.Length);
			return _complexData.Length;
		}

		public override bool Equals(object o)
		{
			if (this == o)
			{
				return true;
			}
			if (!(o is EscherComplexProperty))
			{
				return false;
			}
			EscherComplexProperty escherComplexProperty = (EscherComplexProperty)o;
			if (!Arrays.Equals(_complexData, escherComplexProperty._complexData))
			{
				return false;
			}
			return true;
		}

		public override int GetHashCode()
		{
			return Id * 11;
		}

		public override string ToString()
		{
			string text;
			using (MemoryStream memoryStream = new MemoryStream())
			{
				try
				{
					HexDump.Dump(_complexData, 0L, memoryStream, 0);
					text = memoryStream.ToString();
				}
				catch (Exception ex)
				{
					text = ex.ToString();
				}
			}
			return "propNum: " + PropertyNumber + ", propName: " + EscherProperties.GetPropertyName(PropertyNumber) + ", complex: " + IsComplex + ", blipId: " + IsBlipId + ", data: " + Environment.NewLine + text;
		}

		public override string ToXml(string tab)
		{
			HexDump.ToHex(_complexData, 32);
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(tab).Append("<").Append(GetType().Name)
				.Append(" id=\"0x")
				.Append(HexDump.ToHex(Id))
				.Append("\" name=\"")
				.Append(Name)
				.Append("\" blipId=\"")
				.Append(IsBlipId)
				.Append("\">\n");
			stringBuilder.Append(tab).Append("</").Append(GetType().Name)
				.Append(">\n");
			return stringBuilder.ToString();
		}
	}
	public class EscherArrayProperty : EscherComplexProperty, IEnumerable<byte[]>, IEnumerable
	{
		private class EscherArrayEnumerator : IEnumerator<byte[]>, IDisposable, IEnumerator
		{
			private EscherArrayProperty dataHolder;

			private int idx = -1;

			public byte[] Current
			{
				get
				{
					if (idx < 0 || idx > dataHolder.NumberOfElementsInArray)
					{
						throw new IndexOutOfRangeException();
					}
					return dataHolder.GetElement(idx);
				}
			}

			object IEnumerator.Current => Current;

			public EscherArrayEnumerator(EscherArrayProperty eap)
			{
				dataHolder = eap;
			}

			public void Dispose()
			{
				throw new NotImplementedException();
			}

			public bool MoveNext()
			{
				idx++;
				return idx < dataHolder.NumberOfElementsInArray;
			}

			public void Reset()
			{
				throw new NotImplementedException();
			}
		}

		private const int FIXED_SIZE = 6;

		private bool sizeIncludesHeaderSize = true;

		private bool emptyComplexPart;

		public int NumberOfElementsInArray
		{
			get
			{
				if (emptyComplexPart)
				{
					return 0;
				}
				return LittleEndian.GetUShort(_complexData, 0);
			}
			set
			{
				int num = value * GetActualSizeOfElements(SizeOfElements) + 6;
				if (num != _complexData.Length)
				{
					byte[] array = new byte[num];
					System.Array.Copy(_complexData, 0, array, 0, _complexData.Length);
					_complexData = array;
				}
				LittleEndian.PutShort(_complexData, 0, (short)value);
			}
		}

		public int NumberOfElementsInMemory
		{
			get
			{
				return LittleEndian.GetUShort(_complexData, 2);
			}
			set
			{
				int num = value * GetActualSizeOfElements(SizeOfElements) + 6;
				if (num != _complexData.Length)
				{
					byte[] array = new byte[num];
					System.Array.Copy(_complexData, 0, array, 0, num);
					_complexData = array;
				}
				LittleEndian.PutShort(_complexData, 2, (short)value);
			}
		}

		public short SizeOfElements
		{
			get
			{
				return LittleEndian.GetShort(_complexData, 4);
			}
			set
			{
				LittleEndian.PutShort(_complexData, 4, value);
				int num = NumberOfElementsInArray * GetActualSizeOfElements(SizeOfElements) + 6;
				if (num != _complexData.Length)
				{
					byte[] array = new byte[num];
					System.Array.Copy(_complexData, 0, array, 0, 6);
					_complexData = array;
				}
			}
		}

		public EscherArrayProperty(short id, byte[] complexData)
			: base(id, CheckComplexData(complexData))
		{
			emptyComplexPart = complexData.Length == 0;
		}

		public EscherArrayProperty(short propertyNumber, bool isBlipId, byte[] complexData)
			: base(propertyNumber, isBlipId, CheckComplexData(complexData))
		{
		}

		private static byte[] CheckComplexData(byte[] complexData)
		{
			if (complexData == null || complexData.Length == 0)
			{
				complexData = new byte[6];
			}
			return complexData;
		}

		public byte[] GetElement(int index)
		{
			int actualSizeOfElements = GetActualSizeOfElements(SizeOfElements);
			byte[] array = new byte[actualSizeOfElements];
			System.Array.Copy(_complexData, 6 + index * actualSizeOfElements, array, 0, array.Length);
			return array;
		}

		public void SetElement(int index, byte[] element)
		{
			int actualSizeOfElements = GetActualSizeOfElements(SizeOfElements);
			System.Array.Copy(element, 0, _complexData, 6 + index * actualSizeOfElements, actualSizeOfElements);
		}

		public override string ToString()
		{
			string newLine = Environment.NewLine;
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("    {EscherArrayProperty:" + newLine);
			stringBuilder.Append("     Num Elements: " + NumberOfElementsInArray + newLine);
			stringBuilder.Append("     Num Elements In Memory: " + NumberOfElementsInMemory + newLine);
			stringBuilder.Append("     Size of elements: " + SizeOfElements + newLine);
			for (int i = 0; i < NumberOfElementsInArray; i++)
			{
				stringBuilder.Append("     Element " + i + ": " + HexDump.ToHex(GetElement(i)) + newLine);
			}
			stringBuilder.Append("}" + newLine);
			return "propNum: " + PropertyNumber + ", propName: " + EscherProperties.GetPropertyName(PropertyNumber) + ", complex: " + IsComplex + ", blipId: " + IsBlipId + ", data: " + newLine + stringBuilder.ToString();
		}

		public override string ToXml(string tab)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(tab).Append("<").Append(GetType().Name)
				.Append(" id=\"0x")
				.Append(HexDump.ToHex(Id))
				.Append("\" name=\"")
				.Append(Name)
				.Append("\" blipId=\"")
				.Append(IsBlipId)
				.Append("\">\n");
			for (int i = 0; i < NumberOfElementsInArray; i++)
			{
				stringBuilder.Append("\t").Append(tab).Append("<Element>")
					.Append(HexDump.ToHex(GetElement(i)))
					.Append("</Element>\n");
			}
			stringBuilder.Append(tab).Append("</").Append(GetType().Name)
				.Append(">\n");
			return stringBuilder.ToString();
		}

		public int SetArrayData(byte[] data, int offset)
		{
			if (emptyComplexPart)
			{
				_complexData = new byte[0];
			}
			else
			{
				short @short = LittleEndian.GetShort(data, offset);
				LittleEndian.GetShort(data, offset + 2);
				short short2 = LittleEndian.GetShort(data, offset + 4);
				int num = GetActualSizeOfElements(short2) * @short;
				if (num == _complexData.Length)
				{
					_complexData = new byte[num + 6];
					sizeIncludesHeaderSize = false;
				}
				System.Array.Copy(data, offset, _complexData, 0, _complexData.Length);
			}
			return _complexData.Length;
		}

		public override int SerializeSimplePart(byte[] data, int pos)
		{
			LittleEndian.PutShort(data, pos, Id);
			int num = _complexData.Length;
			if (!sizeIncludesHeaderSize)
			{
				num -= 6;
			}
			LittleEndian.PutInt(data, pos + 2, num);
			return 6;
		}

		public static int GetActualSizeOfElements(short sizeOfElements)
		{
			if (sizeOfElements < 0)
			{
				return (short)(-sizeOfElements >> 2);
			}
			return sizeOfElements;
		}

		public IEnumerator<byte[]> GetEnumerator()
		{
			return new EscherArrayEnumerator(this);
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
