		public override string RecordName => RecordId switch
		{
			-4096 => "DggContainer", 
			-4095 => "BStoreContainer", 
			-4094 => "DgContainer", 
			-4093 => "SpgrContainer", 
			-4092 => "SpContainer", 
			-4091 => "SolverContainer", 
