		public PropertySet(Stream stream)
		{
			if (IsPropertySetStream(stream))
			{
				int num = (stream as ByteArrayInputStream).Available();
				byte[] array = new byte[num];
				stream.Read(array, 0, array.Length);
				init(array, 0, array.Length);
