		protected static string GetPropertyStringValue(object propertyValue)
		{
			if (propertyValue == null)
			{
				return null;
			}
			if (propertyValue is string)
			{
				return (string)propertyValue;
			}
			if (propertyValue is byte[])
			{
				byte[] array = (byte[])propertyValue;
				if (array.Length == 0)
				{
					return "";
				}
				if (array.Length == 1)
