					return LittleEndian.GetUShort(array).ToString();
				}
				if (array.Length == 4)
				{
					return LittleEndian.GetUInt(array).ToString();
				}
				return Encoding.UTF8.GetString(array);
			}
			return propertyValue.ToString();
		}

