				return (int)GetProperty(1L);
			}
		}

		protected Section()
		{
		}

		public Section(byte[] src, int offset)
		{
			int num = offset;
			formatID = new ClassID(src, num);
			num += 16;
			this.offset = LittleEndian.GetUInt(src, num);
			num = (int)this.offset;
			size = (int)LittleEndian.GetUInt(src, num);
			num += 4;
			int num2 = (int)LittleEndian.GetUInt(src, num);
			num += 4;
			properties = new Property[num2];
			int num3 = num;
			ArrayList arrayList = new ArrayList(num2);
			for (int i = 0; i < properties.Length; i++)
			{
				PropertyListEntry propertyListEntry = new PropertyListEntry
				{
					id = (int)LittleEndian.GetUInt(src, num3)
				};
				num3 += 4;
				propertyListEntry.offset = (int)LittleEndian.GetUInt(src, num3);
				num3 += 4;
				arrayList.Add(propertyListEntry);
			}
			arrayList.Sort();
			for (int j = 0; j < num2 - 1; j++)
			{
				PropertyListEntry propertyListEntry2 = (PropertyListEntry)arrayList[j];
				PropertyListEntry propertyListEntry3 = (PropertyListEntry)arrayList[j + 1];
				propertyListEntry2.Length = propertyListEntry3.offset - propertyListEntry2.offset;
			}
			if (num2 > 0)
			{
				PropertyListEntry propertyListEntry = (PropertyListEntry)arrayList[num2 - 1];
				propertyListEntry.Length = size - propertyListEntry.offset;
			}
			int num4 = -1;
			IEnumerator enumerator = arrayList.GetEnumerator();
			while (num4 == -1 && enumerator.MoveNext())
			{
				PropertyListEntry propertyListEntry = (PropertyListEntry)enumerator.Current;
				if (propertyListEntry.id == 1)
				{
					int num5 = (int)(this.offset + propertyListEntry.offset);
					long uInt = LittleEndian.GetUInt(src, num5);
					num5 += 4;
					if (uInt != 2)
					{
						throw new HPSFRuntimeException("Value type of property ID 1 is not VT_I2 but " + uInt + ".");
					}
					num4 = LittleEndian.GetUShort(src, num5);
				}
			}
			int num6 = 0;
			IEnumerator enumerator2 = arrayList.GetEnumerator();
			while (enumerator2.MoveNext())
			{
				PropertyListEntry propertyListEntry = (PropertyListEntry)enumerator2.Current;
				Property property = new Property(propertyListEntry.id, src, this.offset + propertyListEntry.offset, propertyListEntry.Length, num4);
				if (property.ID == 1)
				{
					property = new Property(property.ID, property.Type, num4);
				}
				properties[num6++] = property;
			}
			dictionary = (IDictionary)GetProperty(0L);
		}

		public virtual object GetProperty(long id)
		{
			wasNull = false;
			for (int i = 0; i < properties.Length; i++)
			{
				if (id == properties[i].ID)
				{
					return properties[i].Value;
				}
			}
			wasNull = true;
			return null;
		}

		public virtual int GetPropertyIntValue(long id)
		{
			object property = GetProperty(id);
			if (property == null)
			{
				return 0;
			}
			if (!(property is long) && !(property is int))
			{
				throw new HPSFRuntimeException("This property is not an integer type, but " + property.GetType().Name + ".");
			}
			return (int)property;
		}

		public virtual bool GetPropertyBooleanValue(int id)
		{
			object property = GetProperty(id);
			if (property != null)
			{
				return (bool)GetProperty(id);
			}
			return false;
		}

		public string GetPIDString(long pid)
		{
			string text = null;
			if (dictionary != null)
			{
				text = (string)dictionary[pid];
			}
			if (text == null)
			{
				text = SectionIDMap.GetPIDString(FormatID.Bytes, pid);
			}
			if (text == null)
			{
				text = "[undefined]";
			}
			return text;
		}

		public override bool Equals(object o)
		{
			if (o == null || !(o is Section))
			{
				return false;
			}
			Section section = (Section)o;
			if (!section.FormatID.Equals(FormatID))
			{
				return false;
			}
			Property[] array = new Property[Properties.Length];
			Property[] array2 = new Property[section.Properties.Length];
			System.Array.Copy(Properties, 0, array, 0, array.Length);
			System.Array.Copy(section.Properties, 0, array2, 0, array2.Length);
			Property property = null;
			Property property2 = null;
			for (int i = 0; i < array.Length; i++)
			{
				long iD = array[i].ID;
				if (iD == 0)
				{
					property = array[i];
					array = Remove(array, i);
					i--;
				}
				if (iD == 1)
				{
					array = Remove(array, i);
					i--;
				}
			}
			for (int j = 0; j < array2.Length; j++)
			{
				long iD2 = array2[j].ID;
				if (iD2 == 0)
				{
					property2 = array2[j];
					array2 = Remove(array2, j);
					j--;
				}
				if (iD2 == 1)
				{
					array2 = Remove(array2, j);
					j--;
				}
			}
			if (array.Length != array2.Length)
			{
				return false;
			}
			bool flag = true;
			if (property != null && property2 != null)
			{
				Hashtable hashtable = (Hashtable)property.Value;
				Hashtable hashtable2 = (Hashtable)property2.Value;
				flag = hashtable.Count == hashtable2.Count;
			}
			else if (property != null || property2 != null)
			{
				flag = false;
			}
			if (!flag)
			{
				return false;
			}
			return Util.AreEqual(array, array2);
		}

		private Property[] Remove(Property[] pa, int i)
		{
			Property[] array = new Property[pa.Length - 1];
			if (i > 0)
			{
				System.Array.Copy(pa, 0, array, 0, i);
			}
			System.Array.Copy(pa, i + 1, array, i, array.Length - i);
			return array;
		}

		public override int GetHashCode()
		{
			long num = 0L;
			num += FormatID.GetHashCode();
			Property[] array = Properties;
			for (int i = 0; i < array.Length; i++)
			{
				num += array[i].GetHashCode();
			}
			return (int)(num & 0xFFFFFFFFu);
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			Property[] array = Properties;
			stringBuilder.Append(GetType().Name);
			stringBuilder.Append('[');
			stringBuilder.Append("formatID: ");
			stringBuilder.Append(FormatID);
			stringBuilder.Append(", offset: ");
			stringBuilder.Append(OffSet);
			stringBuilder.Append(", propertyCount: ");
			stringBuilder.Append(PropertyCount);
			stringBuilder.Append(", size: ");
			stringBuilder.Append(Size);
			stringBuilder.Append(", properties: [\n");
			for (int i = 0; i < array.Length; i++)
			{
				stringBuilder.Append(array[i].ToString());
				stringBuilder.Append(",\n");
			}
			stringBuilder.Append(']');
			stringBuilder.Append(']');
			return stringBuilder.ToString();
		}
	}
	public class MutableSection : Section
	{
		private class PropertyComparer : IComparer
		{
			int IComparer.Compare(object o1, object o2)
			{
				Property property = (Property)o1;
				Property property2 = (Property)o2;
				if (property.ID < property2.ID)
				{
					return -1;
				}
				if (property.ID == property2.ID)
				{
					return 0;
				}
				return 1;
			}
		}

		private bool dirty = true;

		private ArrayList preprops;

		private byte[] sectionBytes;

		public override int Size
		{
			get
			{
				if (dirty)
				{
					try
					{
						size = CalcSize();
						dirty = false;
					}
					catch (Exception)
					{
						throw;
					}
				}
				return size;
			}
		}

		public override int PropertyCount => preprops.Count;

		public override Property[] Properties
		{
			get
			{
				EnsureProperties();
				return properties;
			}
		}

		public override IDictionary Dictionary
		{
			get
			{
				return dictionary;
			}
			set
			{
				if (value != null)
				{
					IEnumerator enumerator = value.Keys.GetEnumerator();
					while (enumerator.MoveNext())
					{
						if (!(enumerator.Current is long) && !(enumerator.Current is int))
						{
							throw new IllegalPropertySetDataException(string.Concat("Dictionary keys must be of type long. but it's ", enumerator.Current, ",", enumerator.Current.GetType().Name, " now"));
						}
					}
					dictionary = value;
					SetProperty(0, -1L, value);
					if (GetProperty(1L) == null)
					{
						SetProperty(1, 2L, 1200);
					}
				}
				else
				{
					RemoveProperty(0L);
				}
			}
		}

		public new int Codepage
		{
			get
			{
				return base.Codepage;
			}
			set
			{
				SetProperty(1, 2L, value);
			}
		}

		public MutableSection()
		{
			dirty = true;
			formatID = null;
			offset = -1L;
			preprops = new ArrayList();
		}

		public MutableSection(Section s)
		{
			SetFormatID(s.FormatID);
			Property[] array = s.Properties;
			MutableProperty[] array2 = new MutableProperty[array.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array2[i] = new MutableProperty(array[i]);
			}
			SetProperties(array2);
			Dictionary = s.Dictionary;
		}

		public void SetFormatID(ClassID formatID)
		{
			base.formatID = formatID;
		}

		public void SetFormatID(byte[] formatID)
		{
			ClassID classID = base.FormatID;
			if (classID == null)
			{
				classID = new ClassID();
				SetFormatID(classID);
			}
			classID.Bytes = formatID;
		}

		public void SetProperties(Property[] properties)
		{
			base.properties = properties;
			preprops = new ArrayList();
			for (int i = 0; i < properties.Length; i++)
			{
				preprops.Add(properties[i]);
			}
			dirty = true;
		}

		public void SetProperty(int id, string value)
		{
			SetProperty(id, 31L, value);
			dirty = true;
		}

		public void SetProperty(int id, int value)
		{
			SetProperty(id, 3L, value);
			dirty = true;
		}

		public void SetProperty(int id, long value)
		{
			SetProperty(id, 20L, value);
			dirty = true;
		}

		public void SetProperty(int id, bool value)
		{
			SetProperty(id, 11L, value);
			dirty = true;
		}

		public void SetProperty(int id, long variantType, object value)
		{
			MutableProperty mutableProperty = new MutableProperty();
			mutableProperty.ID = id;
			mutableProperty.Type = variantType;
			mutableProperty.Value = value;
			SetProperty(mutableProperty);
			dirty = true;
		}

		public void SetProperty(Property p)
		{
			long iD = p.ID;
			RemoveProperty(iD);
			preprops.Add(p);
			dirty = true;
		}

		public void RemoveProperty(long id)
		{
			IEnumerator enumerator = preprops.GetEnumerator();
			while (enumerator.MoveNext())
			{
				if (((Property)enumerator.Current).ID == id)
				{
					preprops.Remove(enumerator.Current);
					break;
				}
			}
			dirty = true;
		}

		protected void SetPropertyBooleanValue(int id, bool value)
		{
			SetProperty(id, 11L, value);
		}

		private int CalcSize()
		{
			using MemoryStream memoryStream = new MemoryStream();
			Write(memoryStream);
			sectionBytes = Util.Pad4(memoryStream.ToArray());
			return sectionBytes.Length;
		}

		public int Write(Stream out1)
		{
			if (!dirty && sectionBytes != null)
			{
				out1.Write(sectionBytes, 0, sectionBytes.Length);
				return sectionBytes.Length;
			}
			using MemoryStream memoryStream2 = new MemoryStream();
			using MemoryStream memoryStream = new MemoryStream();
			int num = 0;
			num += 8 + PropertyCount * 2 * 4;
			int num2 = -1;
			if (GetProperty(0L) != null)
			{
				object property = GetProperty(1L);
				if (property != null)
				{
					if (!(property is int))
					{
						throw new IllegalPropertySetDataException("The codepage property (ID = 1) must be an Integer object.");
					}
				}
				else
				{
					SetProperty(1, 2L, 1200);
				}
				num2 = Codepage;
			}
			preprops.Sort(new PropertyComparer());
			for (int i = 0; i < preprops.Count; i++)
			{
				MutableProperty mutableProperty = (MutableProperty)preprops[i];
				long iD = mutableProperty.ID;
				TypeWriter.WriteUIntToStream(memoryStream, (uint)mutableProperty.ID);
				TypeWriter.WriteUIntToStream(memoryStream, (uint)num);
				if (iD != 0)
				{
					num += mutableProperty.Write(memoryStream2, Codepage);
					continue;
				}
				if (num2 == -1)
				{
					throw new IllegalPropertySetDataException("Codepage (property 1) is undefined.");
				}
				num += WriteDictionary(memoryStream2, dictionary, num2);
			}
			memoryStream2.Flush();
			memoryStream.Flush();
			byte[] array = memoryStream.ToArray();
			byte[] array2 = memoryStream2.ToArray();
			TypeWriter.WriteToStream(out1, 8 + array.Length + array2.Length);
			TypeWriter.WriteToStream(out1, PropertyCount);
			out1.Write(array, 0, array.Length);
			out1.Write(array2, 0, array2.Length);
			return 8 + array.Length + array2.Length;
		}

		private static int WriteDictionary(Stream out1, IDictionary dictionary, int codepage)
		{
			int num = TypeWriter.WriteUIntToStream(out1, (uint)dictionary.Count);
			IEnumerator enumerator = dictionary.Keys.GetEnumerator();
			while (enumerator.MoveNext())
			{
				long num2 = Convert.ToInt64(enumerator.Current, CultureInfo.InvariantCulture);
				string text = (string)dictionary[num2];
				if (text == null)
				{
					text = (string)dictionary[(int)num2];
				}
				if (codepage == 1200)
				{
					int num3 = text.Length + 1;
					if (num3 % 2 == 1)
					{
						num3++;
					}
					num += TypeWriter.WriteUIntToStream(out1, (uint)num2);
					num += TypeWriter.WriteUIntToStream(out1, (uint)num3);
					byte[] bytes = Encoding.GetEncoding(codepage).GetBytes(text);
					for (int i = 0; i < bytes.Length; i++)
					{
						out1.WriteByte(bytes[i]);
						num++;
					}
					for (num3 -= text.Length; num3 > 0; num3--)
					{
						out1.WriteByte(0);
						out1.WriteByte(0);
						num += 2;
					}
					continue;
				}
				num += TypeWriter.WriteUIntToStream(out1, (uint)num2);
				num += TypeWriter.WriteUIntToStream(out1, (uint)(text.Length + 1));
				try
				{
					byte[] bytes2 = Encoding.GetEncoding(codepage).GetBytes(text);
					for (int j = 0; j < bytes2.Length; j++)
					{
						out1.WriteByte(bytes2[j]);
						num++;
					}
				}
				catch (Exception reason)
				{
					throw new IllegalPropertySetDataException(reason);
				}
				out1.WriteByte(0);
				num++;
			}
			return num;
		}

		public void EnsureProperties()
		{
			properties = (Property[])preprops.ToArray(typeof(Property));
		}

		public override object GetProperty(long id)
		{
			EnsureProperties();
			return base.GetProperty(id);
		}

		public void SetProperty(int id, object value)
		{
			if (value is string)
			{
				SetProperty(id, (string)value);
				return;
			}
			if (value is long)
			{
				SetProperty(id, (long)value);
				return;
			}
			if (value is int)
			{
				SetProperty(id, value);
				return;
			}
			if (value is short)
			{
				SetProperty(id, (short)value);
				return;
			}
			if (value is bool)
			{
				SetProperty(id, (bool)value);
				return;
			}
			if (value is DateTime)
			{
				SetProperty(id, 64L, value);
				return;
			}
			throw new HPSFRuntimeException("HPSF does not support properties of type " + value.GetType().Name + ".");
		}

		public void Clear()
		{
			Property[] array = Properties;
			foreach (Property property in array)
			{
				RemoveProperty(property.ID);
			}
		}
	}
