	public class EventWorkbookBuilder
	{
		public class SheetRecordCollectingListener : IHSSFListener
		{
			private IHSSFListener childListener;

			private ArrayList boundSheetRecords = new ArrayList();

			private ArrayList externSheetRecords = new ArrayList();

			private SSTRecord sstRecord;

			public SheetRecordCollectingListener(IHSSFListener childListener)
			{
				this.childListener = childListener;
			}

			public BoundSheetRecord[] GetBoundSheetRecords()
			{
				return (BoundSheetRecord[])boundSheetRecords.ToArray(typeof(BoundSheetRecord));
			}

			public ExternSheetRecord[] GetExternSheetRecords()
			{
				return (ExternSheetRecord[])externSheetRecords.ToArray(typeof(ExternSheetRecord));
			}

			public SSTRecord GetSSTRecord()
			{
				return sstRecord;
			}

			public HSSFWorkbook GetStubHSSFWorkbook()
			{
				HSSFWorkbook hSSFWorkbook = HSSFWorkbook.Create(GetStubWorkbook());
				foreach (BoundSheetRecord boundSheetRecord in boundSheetRecords)
				{
					hSSFWorkbook.CreateSheet(boundSheetRecord.Sheetname);
				}
				return hSSFWorkbook;
			}

			public InternalWorkbook GetStubWorkbook()
			{
				return CreateStubWorkbook(GetExternSheetRecords(), GetBoundSheetRecords(), GetSSTRecord());
			}

			public void ProcessRecord(NPOI.HSSF.Record.Record record)
			{
				ProcessRecordInternally(record);
				childListener.ProcessRecord(record);
			}

			public void ProcessRecordInternally(NPOI.HSSF.Record.Record record)
			{
				if (record is BoundSheetRecord)
				{
					boundSheetRecords.Add(record);
				}
				else if (record is ExternSheetRecord)
				{
					externSheetRecords.Add(record);
				}
				else if (record is SSTRecord)
				{
					sstRecord = (SSTRecord)record;
				}
			}
		}

		public static InternalWorkbook CreateStubWorkbook(ExternSheetRecord[] externs, BoundSheetRecord[] bounds, SSTRecord sst)
		{
			List<NPOI.HSSF.Record.Record> list = new List<NPOI.HSSF.Record.Record>();
			if (bounds != null)
			{
				for (int i = 0; i < bounds.Length; i++)
				{
					list.Add(bounds[i]);
				}
			}
			if (sst != null)
			{
				list.Add(sst);
			}
			if (externs != null)
			{
				list.Add(SupBookRecord.CreateInternalReferences((short)externs.Length));
				for (int j = 0; j < externs.Length; j++)
				{
					list.Add(externs[j]);
				}
			}
			list.Add(EOFRecord.instance);
			return InternalWorkbook.CreateWorkbook(list);
		}

		public static InternalWorkbook CreateStubWorkbook(ExternSheetRecord[] externs, BoundSheetRecord[] bounds)
		{
			return CreateStubWorkbook(externs, bounds, null);
		}
	}
	public class FormatTrackingHSSFListener : IHSSFListener
	{
		private static POILogger logger = POILogFactory.GetLogger(typeof(FormatTrackingHSSFListener));

		private IHSSFListener childListener;

		private Dictionary<int, FormatRecord> customFormatRecords = new Dictionary<int, FormatRecord>();

		private DataFormatter formatter = new DataFormatter();

		private List<ExtendedFormatRecord> xfRecords = new List<ExtendedFormatRecord>();

		public int NumberOfCustomFormats => customFormatRecords.Count;

		public int NumberOfExtendedFormats => xfRecords.Count;

		public FormatTrackingHSSFListener(IHSSFListener childListener)
		{
			this.childListener = childListener;
		}

		public void ProcessRecord(NPOI.HSSF.Record.Record record)
		{
			ProcessRecordInternally(record);
			childListener.ProcessRecord(record);
		}

		public void ProcessRecordInternally(NPOI.HSSF.Record.Record record)
		{
			if (record is FormatRecord)
			{
				FormatRecord formatRecord = (FormatRecord)record;
				customFormatRecords[formatRecord.IndexCode] = formatRecord;
			}
			else if (record is ExtendedFormatRecord)
			{
				ExtendedFormatRecord item = (ExtendedFormatRecord)record;
				xfRecords.Add(item);
			}
		}

		public string FormatNumberDateCell(CellValueRecordInterface cell)
		{
			double value;
			if (cell is NumberRecord)
			{
				value = ((NumberRecord)cell).Value;
			}
			else
			{
				if (!(cell is FormulaRecord))
				{
					throw new ArgumentException("Unsupported CellValue Record passed in " + cell);
				}
				value = ((FormulaRecord)cell).Value;
			}
			int formatIndex = GetFormatIndex(cell);
			string formatString = GetFormatString(cell);
			if (formatString == null)
			{
				return value.ToString(CultureInfo.InvariantCulture);
			}
			return formatter.FormatRawCellContents(value, formatIndex, formatString);
		}

		public string GetFormatString(int formatIndex)
		{
			string result = null;
			if (formatIndex >= HSSFDataFormat.NumberOfBuiltinBuiltinFormats)
			{
				FormatRecord formatRecord = customFormatRecords[formatIndex];
				if (formatRecord == null)
				{
					logger.Log(7, "Requested format at index " + formatIndex + ", but it wasn't found");
				}
				else
				{
					result = formatRecord.FormatString;
				}
			}
			else
			{
				result = HSSFDataFormat.GetBuiltinFormat((short)formatIndex);
			}
			return result;
		}

		public string GetFormatString(CellValueRecordInterface cell)
		{
			int formatIndex = GetFormatIndex(cell);
			if (formatIndex == -1)
			{
				return null;
			}
			return GetFormatString(formatIndex);
		}

		public int GetFormatIndex(CellValueRecordInterface cell)
		{
			ExtendedFormatRecord extendedFormatRecord = xfRecords[cell.XFIndex];
			if (extendedFormatRecord == null)
			{
				logger.Log(7, "Cell " + cell.Row + "," + cell.Column + " uses XF with index " + cell.XFIndex + ", but we don't have that");
				return -1;
			}
			return extendedFormatRecord.FormatIndex;
		}
	}
	public class HSSFEventFactory
	{
		public void ProcessWorkbookEvents(HSSFRequest req, POIFSFileSystem fs)
		{
			Stream @in = fs.CreateDocumentInputStream("Workbook");
			ProcessEvents(req, @in);
		}

		public short AbortableProcessWorkbookEvents(HSSFRequest req, POIFSFileSystem fs)
		{
			Stream @in = fs.CreateDocumentInputStream("Workbook");
			return AbortableProcessEvents(req, @in);
		}

		public void ProcessEvents(HSSFRequest req, Stream in1)
		{
			try
			{
				GenericProcessEvents(req, new RecordInputStream(in1));
			}
			catch (HSSFUserException)
			{
			}
		}

		public short AbortableProcessEvents(HSSFRequest req, Stream in1)
		{
			return GenericProcessEvents(req, new RecordInputStream(in1));
		}

		protected short GenericProcessEvents(HSSFRequest req, RecordInputStream in1)
		{
			bool flag = true;
			short num = 0;
			NPOI.HSSF.Record.Record record = null;
			HSSFRecordStream hSSFRecordStream = new HSSFRecordStream(in1);
			while (flag)
			{
				record = hSSFRecordStream.NextRecord();
				if (record != null)
				{
					num = req.ProcessRecord(record);
					if (num != 0)
					{
						break;
					}
				}
				else
				{
					flag = false;
				}
			}
			return num;
		}
	}
	public class HSSFRecordStream
	{
		private RecordInputStream in1;

		private bool hitEOS;

		private bool complete;

		private ArrayList bonusRecords;

		private NPOI.HSSF.Record.Record rec;

		private NPOI.HSSF.Record.Record lastRec;

		private DrawingRecord lastDrawingRecord = new DrawingRecord();

		public HSSFRecordStream(RecordInputStream inp)
		{
			in1 = inp;
		}

		public NPOI.HSSF.Record.Record NextRecord()
		{
			NPOI.HSSF.Record.Record record = null;
			while (record == null && !complete)
			{
				record = GetBonusRecord();
				if (record == null)
				{
					record = GetNextRecord();
				}
			}
			return record;
		}

		private NPOI.HSSF.Record.Record GetBonusRecord()
		{
			if (bonusRecords != null)
			{
				NPOI.HSSF.Record.Record result = (NPOI.HSSF.Record.Record)bonusRecords[0];
				bonusRecords.RemoveAt(0);
				if (bonusRecords.Count == 0)
				{
					bonusRecords = null;
				}
				return result;
			}
			return null;
		}

		private NPOI.HSSF.Record.Record GetNextRecord()
		{
			NPOI.HSSF.Record.Record result = null;
			if (in1.HasNextRecord)
			{
				in1.NextRecord();
				short sid = in1.Sid;
				if (sid == 0)
				{
					return null;
				}
				if (rec != null && sid != 60)
				{
					result = rec;
				}
				if (sid != 60)
				{
					NPOI.HSSF.Record.Record[] array = RecordFactory.CreateRecord(in1);
					if (array.Length > 1)
					{
						bonusRecords = new ArrayList(array.Length - 1);
						for (int i = 0; i < array.Length - 1; i++)
						{
							bonusRecords.Add(array[i]);
						}
					}
					rec = array[^1];
				}
				else
				{
					NPOI.HSSF.Record.Record[] array2 = RecordFactory.CreateRecord(in1);
					ContinueRecord continueRecord = (ContinueRecord)array2[0];
					if (lastRec is ObjRecord || lastRec is TextObjectRecord)
					{
						lastDrawingRecord.ProcessContinueRecord(continueRecord.Data);
						rec = lastDrawingRecord;
					}
					else if (lastRec is DrawingGroupRecord)
					{
						((DrawingGroupRecord)lastRec).ProcessContinueRecord(continueRecord.Data);
						rec = lastRec;
					}
					else if (!(rec is UnknownRecord))
					{
						throw new RecordFormatException("Records should handle ContinueRecord internally. Should not see this exception");
					}
				}
				lastRec = rec;
				if (rec is DrawingRecord)
				{
					lastDrawingRecord = (DrawingRecord)rec;
				}
			}
			else
			{
				hitEOS = true;
			}
			if (hitEOS)
			{
				complete = true;
				if (rec != null)
				{
					result = rec;
					rec = null;
				}
			}
			return result;
		}
	}
	public class HSSFRequest
	{
		private Hashtable records;

		public HSSFRequest()
		{
			records = new Hashtable(50);
		}

		public void AddListener(IHSSFListener lsnr, short sid)
		{
			IList list = null;
			object obj = records[sid];
			if (obj != null)
			{
				list = (IList)obj;
				return;
			}
			list = new ArrayList(1);
			list.Add(lsnr);
			records[sid] = list;
		}

		public void AddListenerForAllRecords(IHSSFListener lsnr)
		{
			short[] allKnownRecordSIDs = RecordFactory.GetAllKnownRecordSIDs();
			for (int i = 0; i < allKnownRecordSIDs.Length; i++)
			{
				AddListener(lsnr, allKnownRecordSIDs[i]);
			}
		}

		public short ProcessRecord(NPOI.HSSF.Record.Record rec)
		{
			object obj = records[rec.Sid];
			short num = 0;
			if (obj != null)
			{
				IList list = (IList)obj;
				for (int i = 0; i < list.Count; i++)
				{
					object obj2 = list[i];
					if (obj2 is AbortableHSSFListener)
					{
						AbortableHSSFListener abortableHSSFListener = (AbortableHSSFListener)obj2;
						num = abortableHSSFListener.AbortableProcessRecord(rec);
						if (num != 0)
						{
							break;
						}
					}
					else
					{
						IHSSFListener iHSSFListener = (IHSSFListener)obj2;
						iHSSFListener.ProcessRecord(rec);
					}
				}
			}
			return num;
		}
	}
	[Serializable]
	public class HSSFUserException : Exception
	{
		public HSSFUserException()
		{
		}

		public HSSFUserException(string msg)
			: base(msg)
		{
		}

		public HSSFUserException(Exception reason)
		{
		}

		public HSSFUserException(string msg, Exception reason)
			: base(msg, reason)
		{
		}
	}
	public class MissingRecordAwareHSSFListener : IHSSFListener
	{
		private IHSSFListener childListener;

		private int lastRowRow;

		private int lastCellRow;

		private int lastCellColumn;

		public MissingRecordAwareHSSFListener(IHSSFListener listener)
		{
			ResetCounts();
			childListener = listener;
		}

		public void ProcessRecord(NPOI.HSSF.Record.Record record)
		{
			CellValueRecordInterface[] array = null;
			int num;
			int num2;
			if (record is CellValueRecordInterface)
			{
				CellValueRecordInterface cellValueRecordInterface = (CellValueRecordInterface)record;
				num = cellValueRecordInterface.Row;
				num2 = cellValueRecordInterface.Column;
			}
			else
			{
				if (record is StringRecord)
				{
					childListener.ProcessRecord(record);
					return;
				}
				num = -1;
				num2 = -1;
				switch (record.Sid)
				{
				case 2057:
				{
					BOFRecord bOFRecord = (BOFRecord)record;
					if (bOFRecord.Type == BOFRecordType.Workbook || bOFRecord.Type == BOFRecordType.Worksheet)
					{
						ResetCounts();
					}
					break;
				}
				case 520:
				{
					RowRecord rowRecord = (RowRecord)record;
					if (lastRowRow + 1 < rowRecord.RowNumber)
					{
						for (int i = lastRowRow + 1; i < rowRecord.RowNumber; i++)
						{
							MissingRowDummyRecord record2 = new MissingRowDummyRecord(i);
							childListener.ProcessRecord(record2);
						}
					}
					lastRowRow = rowRecord.RowNumber;
					break;
				}
				case 1212:
					childListener.ProcessRecord(record);
					return;
				case 190:
				{
					MulBlankRecord mbk = (MulBlankRecord)record;
					array = RecordFactory.ConvertBlankRecords(mbk);
					break;
				}
				case 189:
				{
					MulRKRecord mrk = (MulRKRecord)record;
					array = RecordFactory.ConvertRKRecords(mrk);
					break;
				}
				case 28:
				{
					NoteRecord noteRecord = (NoteRecord)record;
					num = noteRecord.Row;
					num2 = noteRecord.Column;
					break;
				}
				}
			}
			if (array != null && array.Length > 0)
			{
				num = array[0].Row;
				num2 = array[0].Column;
			}
			if (num != lastCellRow && lastCellRow > -1)
			{
				for (int j = lastCellRow; j < num; j++)
				{
					int lastColumnNumber = -1;
					if (j == lastCellRow)
					{
						lastColumnNumber = lastCellColumn;
					}
					childListener.ProcessRecord(new LastCellOfRowDummyRecord(j, lastColumnNumber));
				}
			}
			if (lastCellRow != -1 && lastCellColumn != -1 && num == -1)
			{
				childListener.ProcessRecord(new LastCellOfRowDummyRecord(lastCellRow, lastCellColumn));
				lastCellRow = -1;
				lastCellColumn = -1;
			}
			if (num != lastCellRow)
			{
				lastCellColumn = -1;
			}
			if (lastCellColumn != num2 - 1)
			{
				for (int k = lastCellColumn + 1; k < num2; k++)
				{
					childListener.ProcessRecord(new MissingCellDummyRecord(num, k));
				}
			}
			if (array != null && array.Length > 0)
			{
				num2 = array[^1].Column;
			}
			if (num2 != -1)
			{
				lastCellColumn = num2;
				lastCellRow = num;
			}
			if (array != null && array.Length > 0)
			{
				CellValueRecordInterface[] array2 = array;
				foreach (CellValueRecordInterface cellValueRecordInterface2 in array2)
				{
					childListener.ProcessRecord((NPOI.HSSF.Record.Record)cellValueRecordInterface2);
				}
			}
			else
			{
				childListener.ProcessRecord(record);
			}
		}

		private void ResetCounts()
		{
			lastRowRow = -1;
			lastCellRow = -1;
			lastCellColumn = -1;
		}
	}
}
