namespace NPOI.HSSF.Extractor
{
	public class ExcelExtractor : POIOLE2TextExtractor, IExcelExtractor
	{
		private HSSFWorkbook wb;

		private HSSFDataFormatter _formatter;

		private bool includeSheetNames = true;

		private bool formulasNotResults;

		private bool includeCellComments;

		private bool includeBlankCells;

		private bool includeHeaderFooter = true;

		public bool IncludeHeaderFooter
		{
			get
			{
				return includeHeaderFooter;
			}
			set
			{
				includeHeaderFooter = value;
			}
		}

		public bool IncludeSheetNames
		{
			get
			{
				return includeSheetNames;
			}
			set
			{
				includeSheetNames = value;
			}
		}

		public bool FormulasNotResults
		{
			get
			{
				return formulasNotResults;
			}
			set
			{
				formulasNotResults = value;
			}
		}

		public bool IncludeCellComments
		{
			get
			{
				return includeCellComments;
			}
			set
			{
				includeCellComments = value;
			}
		}

		public bool IncludeBlankCells
		{
			get
			{
				return includeBlankCells;
			}
			set
			{
				includeBlankCells = value;
			}
		}

		public override string Text
		{
			get
			{
				StringBuilder stringBuilder = new StringBuilder();
				wb.MissingCellPolicy = MissingCellPolicy.RETURN_BLANK_AS_NULL;
				for (int i = 0; i < wb.NumberOfSheets; i++)
				{
					HSSFSheet hSSFSheet = (HSSFSheet)wb.GetSheetAt(i);
					if (hSSFSheet == null)
					{
						continue;
					}
					if (includeSheetNames)
					{
						string sheetName = wb.GetSheetName(i);
						if (sheetName != null)
						{
							stringBuilder.Append(sheetName);
							stringBuilder.Append("\n");
						}
					}
					if (hSSFSheet.Header != null && includeHeaderFooter)
					{
						stringBuilder.Append(ExtractHeaderFooter(hSSFSheet.Header));
					}
					int firstRowNum = hSSFSheet.FirstRowNum;
					int lastRowNum = hSSFSheet.LastRowNum;
					for (int j = firstRowNum; j <= lastRowNum; j++)
					{
						IRow row = hSSFSheet.GetRow(j);
						if (row == null)
						{
							continue;
						}
						int num = row.FirstCellNum;
						int lastCellNum = row.LastCellNum;
						if (includeBlankCells)
						{
							num = 0;
						}
						for (int k = num; k < lastCellNum; k++)
						{
							ICell cell = row.GetCell(k);
							bool flag = true;
							if (cell == null)
							{
								flag = includeBlankCells;
							}
							else
							{
								switch (cell.CellType)
								{
								case CellType.String:
									stringBuilder.Append(cell.RichStringCellValue.String);
									break;
								case CellType.Numeric:
									stringBuilder.Append(_formatter.FormatCellValue(cell));
									break;
								case CellType.Boolean:
									stringBuilder.Append(cell.BooleanCellValue);
									break;
								case CellType.Error:
									stringBuilder.Append(ErrorEval.GetText(cell.ErrorCellValue));
									break;
								case CellType.Formula:
									if (formulasNotResults)
									{
										stringBuilder.Append(cell.CellFormula);
										break;
									}
									switch (cell.CachedFormulaResultType)
									{
									case CellType.String:
									{
										IRichTextString richStringCellValue = cell.RichStringCellValue;
										if (richStringCellValue != null && richStringCellValue.Length > 0)
										{
											stringBuilder.Append(richStringCellValue.ToString());
										}
										break;
									}
									case CellType.Numeric:
									{
										HSSFCellStyle hSSFCellStyle = (HSSFCellStyle)cell.CellStyle;
										if (hSSFCellStyle == null)
										{
											stringBuilder.Append(cell.NumericCellValue);
										}
										else
										{
											stringBuilder.Append(_formatter.FormatRawCellContents(cell.NumericCellValue, hSSFCellStyle.DataFormat, hSSFCellStyle.GetDataFormatString()));
										}
										break;
									}
									case CellType.Boolean:
										stringBuilder.Append(cell.BooleanCellValue);
										break;
									case CellType.Error:
										stringBuilder.Append(ErrorEval.GetText(cell.ErrorCellValue));
										break;
									}
									break;
								default:
									throw new Exception(string.Concat("Unexpected cell type (", cell.CellType, ")"));
								}
								IComment cellComment = cell.CellComment;
								if (includeCellComments && cellComment != null)
								{
									string text = cellComment.String.String.Replace('\n', ' ');
									stringBuilder.Append(" Comment by " + cellComment.Author + ": " + text);
								}
							}
							if (flag && k < lastCellNum - 1)
							{
								stringBuilder.Append("\t");
							}
						}
						stringBuilder.Append("\n");
					}
					if (hSSFSheet.Footer != null && includeHeaderFooter)
					{
						stringBuilder.Append(ExtractHeaderFooter(hSSFSheet.Footer));
					}
				}
				return stringBuilder.ToString();
			}
		}

		public ExcelExtractor(HSSFWorkbook wb)
			: base(wb)
		{
			this.wb = wb;
			_formatter = new HSSFDataFormatter();
		}

		public ExcelExtractor(POIFSFileSystem fs)
			: this(new HSSFWorkbook(fs))
		{
		}

		public static string ExtractHeaderFooter(IHeaderFooter hf)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (hf.Left != null)
			{
				stringBuilder.Append(hf.Left);
			}
			if (hf.Center != null)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append("\t");
				}
				stringBuilder.Append(hf.Center);
			}
			if (hf.Right != null)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append("\t");
				}
				stringBuilder.Append(hf.Right);
			}
			if (stringBuilder.Length > 0)
			{
				stringBuilder.Append("\n");
			}
			return stringBuilder.ToString();
		}
	}
}
namespace NPOI.HSSF.Model
{
	[Obsolete]
	public abstract class AbstractShape
	{
		public abstract EscherContainerRecord SpContainer { get; }

		public abstract ObjRecord ObjRecord { get; }

		public static AbstractShape CreateShape(HSSFShape hssfShape, int shapeId)
		{
			AbstractShape abstractShape;
			if (hssfShape is HSSFComment)
			{
				abstractShape = new CommentShape((HSSFComment)hssfShape, shapeId);
			}
			else if (hssfShape is HSSFTextbox)
			{
				abstractShape = new TextboxShape((HSSFTextbox)hssfShape, shapeId);
			}
			else if (hssfShape is HSSFPolygon)
			{
				abstractShape = new PolygonShape((HSSFPolygon)hssfShape, shapeId);
			}
			else
			{
				if (!(hssfShape is HSSFSimpleShape))
				{
					throw new ArgumentException("Unknown shape type");
				}
				HSSFSimpleShape hSSFSimpleShape = (HSSFSimpleShape)hssfShape;
				switch (hSSFSimpleShape.ShapeType)
				{
				case 75:
					abstractShape = new PictureShape(hSSFSimpleShape, shapeId);
					break;
				case 20:
					abstractShape = new LineShape(hSSFSimpleShape, shapeId);
					break;
				case 1:
				case 3:
					abstractShape = new SimpleFilledShape(hSSFSimpleShape, shapeId);
					break;
				case 201:
					abstractShape = new ComboboxShape(hSSFSimpleShape, shapeId);
					break;
				default:
					throw new ArgumentException("Do not know how to handle this type of shape");
				}
			}
			EscherSpRecord escherSpRecord = (EscherSpRecord)abstractShape.SpContainer.GetChildById(-4086);
			if (hssfShape.Parent != null)
			{
				escherSpRecord.Flags |= 2;
			}
			return abstractShape;
		}

		protected virtual EscherRecord CreateAnchor(HSSFAnchor userAnchor)
		{
			return ConvertAnchor.CreateAnchor(userAnchor);
		}

		protected virtual int AddStandardOptions(HSSFShape shape, EscherOptRecord opt)
		{
			opt.AddEscherProperty(new EscherBoolProperty(191, 524288));
			if (shape.IsNoFill)
			{
				opt.AddEscherProperty(new EscherBoolProperty(447, 1114112));
			}
			else
			{
				opt.AddEscherProperty(new EscherBoolProperty(447, 65536));
			}
			opt.AddEscherProperty(new EscherRGBProperty(385, shape.FillColor));
			opt.AddEscherProperty(new EscherBoolProperty(959, 524288));
			opt.AddEscherProperty(new EscherRGBProperty(448, shape.LineStyleColor));
			int num = 5;
			if (shape.LineWidth != 9525)
			{
				opt.AddEscherProperty(new EscherSimpleProperty(459, shape.LineWidth));
				num++;
			}
			if (shape.LineStyle != 0)
			{
				opt.AddEscherProperty(new EscherSimpleProperty(462, (int)shape.LineStyle));
				opt.AddEscherProperty(new EscherSimpleProperty(471, 0));
				if (shape.LineStyle == LineStyle.None)
				{
					opt.AddEscherProperty(new EscherBoolProperty(511, 524288));
				}
				else
				{
					opt.AddEscherProperty(new EscherBoolProperty(511, 524296));
				}
				num += 3;
			}
			opt.SortProperties();
			return num;
		}

		protected virtual int GetCmoObjectId(int shapeId)
		{
			return shapeId - 1024;
		}
	}
	[Obsolete]
	public class ComboboxShape : AbstractShape
	{
		private EscherContainerRecord spContainer;

		private ObjRecord objRecord;

		public override EscherContainerRecord SpContainer => spContainer;

		public override ObjRecord ObjRecord => objRecord;

		public ComboboxShape(HSSFSimpleShape hssfShape, int shapeId)
		{
			spContainer = CreateSpContainer(hssfShape, shapeId);
			objRecord = CreateObjRecord(hssfShape, shapeId);
		}

		private ObjRecord CreateObjRecord(HSSFSimpleShape shape, int shapeId)
		{
			ObjRecord objRecord = new ObjRecord();
			CommonObjectDataSubRecord commonObjectDataSubRecord = new CommonObjectDataSubRecord();
			commonObjectDataSubRecord.ObjectType = CommonObjectType.ComboBox;
			commonObjectDataSubRecord.ObjectId = shapeId;
			commonObjectDataSubRecord.IsLocked = true;
			commonObjectDataSubRecord.IsPrintable = false;
			commonObjectDataSubRecord.IsAutoFill = true;
			commonObjectDataSubRecord.IsAutoline = false;
			FtCblsSubRecord o = new FtCblsSubRecord();
			LbsDataSubRecord o2 = LbsDataSubRecord.CreateAutoFilterInstance();
			EndSubRecord o3 = new EndSubRecord();
			objRecord.AddSubRecord(commonObjectDataSubRecord);
			objRecord.AddSubRecord(o);
			objRecord.AddSubRecord(o2);
			objRecord.AddSubRecord(o3);
			return objRecord;
		}

		private EscherContainerRecord CreateSpContainer(HSSFSimpleShape shape, int shapeId)
		{
			EscherContainerRecord escherContainerRecord = new EscherContainerRecord();
			EscherSpRecord escherSpRecord = new EscherSpRecord();
			EscherOptRecord escherOptRecord = new EscherOptRecord();
			EscherClientDataRecord escherClientDataRecord = new EscherClientDataRecord();
			escherContainerRecord.RecordId = -4092;
			escherContainerRecord.Options = 15;
			escherSpRecord.RecordId = -4086;
			escherSpRecord.Options = 3218;
			escherSpRecord.ShapeId = shapeId;
			escherSpRecord.Flags = 2560;
			escherOptRecord.RecordId = -4085;
			escherOptRecord.AddEscherProperty(new EscherBoolProperty(127, 17039620));
			escherOptRecord.AddEscherProperty(new EscherBoolProperty(191, 524296));
			escherOptRecord.AddEscherProperty(new EscherBoolProperty(511, 524288));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(959, 131072));
			HSSFClientAnchor hSSFClientAnchor = (HSSFClientAnchor)shape.Anchor;
			hSSFClientAnchor.AnchorType = (AnchorType)1;
			EscherRecord record = CreateAnchor(hSSFClientAnchor);
			escherClientDataRecord.RecordId = -4079;
			escherClientDataRecord.Options = 0;
			escherContainerRecord.AddChildRecord(escherSpRecord);
			escherContainerRecord.AddChildRecord(escherOptRecord);
			escherContainerRecord.AddChildRecord(record);
			escherContainerRecord.AddChildRecord(escherClientDataRecord);
			return escherContainerRecord;
		}
	}
	[Obsolete]
	public class TextboxShape : AbstractShape
	{
		private EscherContainerRecord spContainer;

		private TextObjectRecord textObjectRecord;

		private ObjRecord objRecord;

		private EscherTextboxRecord escherTextbox;

		public override EscherContainerRecord SpContainer => spContainer;

		public override ObjRecord ObjRecord => objRecord;

		public TextObjectRecord TextObjectRecord => textObjectRecord;

		public EscherRecord EscherTextbox => escherTextbox;

		public TextboxShape(HSSFTextbox hssfShape, int shapeId)
		{
			spContainer = CreateSpContainer(hssfShape, shapeId);
			objRecord = CreateObjRecord(hssfShape, shapeId);
			textObjectRecord = CreateTextObjectRecord(hssfShape, shapeId);
		}

		private ObjRecord CreateObjRecord(HSSFTextbox hssfShape, int shapeId)
		{
			ObjRecord objRecord = new ObjRecord();
			CommonObjectDataSubRecord commonObjectDataSubRecord = new CommonObjectDataSubRecord();
			commonObjectDataSubRecord.ObjectType = (CommonObjectType)((HSSFSimpleShape)hssfShape).ShapeType;
			commonObjectDataSubRecord.ObjectId = GetCmoObjectId(shapeId);
			commonObjectDataSubRecord.IsLocked = true;
			commonObjectDataSubRecord.IsPrintable = true;
			commonObjectDataSubRecord.IsAutoFill = true;
			commonObjectDataSubRecord.IsAutoline = true;
			EndSubRecord o = new EndSubRecord();
			objRecord.AddSubRecord(commonObjectDataSubRecord);
			objRecord.AddSubRecord(o);
			return objRecord;
		}

		private EscherContainerRecord CreateSpContainer(HSSFTextbox hssfShape, int shapeId)
		{
			EscherContainerRecord escherContainerRecord = new EscherContainerRecord();
			EscherSpRecord escherSpRecord = new EscherSpRecord();
			EscherOptRecord escherOptRecord = new EscherOptRecord();
			EscherRecord escherRecord = new EscherClientAnchorRecord();
			EscherClientDataRecord escherClientDataRecord = new EscherClientDataRecord();
			escherTextbox = new EscherTextboxRecord();
			escherContainerRecord.RecordId = -4092;
			escherContainerRecord.Options = 15;
			escherSpRecord.RecordId = -4086;
			escherSpRecord.Options = 3234;
			escherSpRecord.ShapeId = shapeId;
			escherSpRecord.Flags = 2560;
			escherOptRecord.RecordId = -4085;
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(128, 0));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(129, hssfShape.MarginLeft));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(131, hssfShape.MarginRight));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(132, hssfShape.MarginBottom));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(130, hssfShape.MarginTop));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(133, 0));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(135, 0));
			escherOptRecord.AddEscherProperty(new EscherSimpleProperty(959, 524288));
			AddStandardOptions(hssfShape, escherOptRecord);
			HSSFAnchor anchor = hssfShape.Anchor;
			escherRecord = CreateAnchor(anchor);
			escherClientDataRecord.RecordId = -4079;
			escherClientDataRecord.Options = 0;
			escherTextbox.RecordId = -4083;
			escherTextbox.Options = 0;
			escherContainerRecord.AddChildRecord(escherSpRecord);
			escherContainerRecord.AddChildRecord(escherOptRecord);
			escherContainerRecord.AddChildRecord(escherRecord);
			escherContainerRecord.AddChildRecord(escherClientDataRecord);
			escherContainerRecord.AddChildRecord(escherTextbox);
			return escherContainerRecord;
		}

		private TextObjectRecord CreateTextObjectRecord(HSSFTextbox hssfShape, int shapeId)
		{
			TextObjectRecord textObjectRecord = new TextObjectRecord();
			textObjectRecord.HorizontalTextAlignment = hssfShape.HorizontalAlignment;
			textObjectRecord.VerticalTextAlignment = hssfShape.VerticalAlignment;
			textObjectRecord.IsTextLocked = true;
			textObjectRecord.TextOrientation = TextOrientation.None;
			_ = hssfShape.String.NumFormattingRuns;
			textObjectRecord.Str = hssfShape.String;
			return textObjectRecord;
		}
	}
	[Obsolete]
	public class CommentShape : TextboxShape
	{
		private NoteRecord note;

		public NoteRecord NoteRecord => note;

		public CommentShape(HSSFComment hssfShape, int shapeId)
			: base(hssfShape, shapeId)
		{
			note = CreateNoteRecord(hssfShape, shapeId);
			ObjRecord objRecord = ObjRecord;
			List<SubRecord> subRecords = objRecord.SubRecords;
			int num = 0;
			for (int i = 0; i < subRecords.Count; i++)
			{
				object obj = subRecords[i];
				if (obj is CommonObjectDataSubRecord)
				{
					CommonObjectDataSubRecord commonObjectDataSubRecord = (CommonObjectDataSubRecord)obj;
					commonObjectDataSubRecord.IsAutoFill = false;
					num = i;
				}
			}
			NoteStructureSubRecord element = new NoteStructureSubRecord();
			objRecord.AddSubRecord(num + 1, element);
		}

		private NoteRecord CreateNoteRecord(HSSFComment shape, int shapeId)
		{
			NoteRecord noteRecord = new NoteRecord();
			noteRecord.Column = shape.Column;
			noteRecord.Row = shape.Row;
			noteRecord.Flags = (short)(shape.Visible ? 2 : 0);
			noteRecord.ShapeId = shapeId;
			noteRecord.Author = ((shape.Author == null) ? "" : shape.Author);
			return noteRecord;
		}

		protected override int AddStandardOptions(HSSFShape shape, EscherOptRecord opt)
		{
			base.AddStandardOptions(shape, opt);
			for (int i = 0; i < opt.EscherProperties.Count; i++)
			{
				EscherProperty escherProperty = opt.EscherProperties[i];
				switch (escherProperty.Id)
				{
				case 129:
				case 130:
				case 131:
				case 132:
				case 387:
				case 448:
				case 959:
					opt.EscherProperties.Remove(escherProperty);
					i--;
					break;
				}
			}
			HSSFComment hSSFComment = (HSSFComment)shape;
			opt.AddEscherProperty(new EscherSimpleProperty(959, hSSFComment.Visible ? 655360 : 655362));
			opt.AddEscherProperty(new EscherSimpleProperty(575, 196611));
			opt.AddEscherProperty(new EscherSimpleProperty(513, 0));
			opt.SortProperties();
			return opt.EscherProperties.Count;
		}

		protected override int GetCmoObjectId(int shapeId)
		{
			return shapeId;
		}
	}
	public class ConvertAnchor
	{
		public static EscherRecord CreateAnchor(HSSFAnchor userAnchor)
		{
			if (userAnchor is HSSFClientAnchor)
			{
				HSSFClientAnchor hSSFClientAnchor = (HSSFClientAnchor)userAnchor;
				EscherClientAnchorRecord escherClientAnchorRecord = new EscherClientAnchorRecord();
				escherClientAnchorRecord.RecordId = -4080;
				escherClientAnchorRecord.Options = 0;
				escherClientAnchorRecord.Flag = (short)hSSFClientAnchor.AnchorType;
				escherClientAnchorRecord.Col1 = (short)Math.Min(hSSFClientAnchor.Col1, hSSFClientAnchor.Col2);
				escherClientAnchorRecord.Dx1 = (short)hSSFClientAnchor.Dx1;
				escherClientAnchorRecord.Row1 = (short)Math.Min(hSSFClientAnchor.Row1, hSSFClientAnchor.Row2);
				escherClientAnchorRecord.Dy1 = (short)hSSFClientAnchor.Dy1;
				escherClientAnchorRecord.Col2 = (short)Math.Max(hSSFClientAnchor.Col1, hSSFClientAnchor.Col2);
				escherClientAnchorRecord.Dx2 = (short)hSSFClientAnchor.Dx2;
				escherClientAnchorRecord.Row2 = (short)Math.Max(hSSFClientAnchor.Row1, hSSFClientAnchor.Row2);
				escherClientAnchorRecord.Dy2 = (short)hSSFClientAnchor.Dy2;
				return escherClientAnchorRecord;
			}
			HSSFChildAnchor hSSFChildAnchor = (HSSFChildAnchor)userAnchor;
			EscherChildAnchorRecord escherChildAnchorRecord = new EscherChildAnchorRecord();
			escherChildAnchorRecord.RecordId = -4081;
			escherChildAnchorRecord.Options = 0;
			escherChildAnchorRecord.Dx1 = (short)Math.Min(hSSFChildAnchor.Dx1, hSSFChildAnchor.Dx2);
			escherChildAnchorRecord.Dy1 = (short)Math.Min(hSSFChildAnchor.Dy1, hSSFChildAnchor.Dy2);
			escherChildAnchorRecord.Dx2 = (short)Math.Max(hSSFChildAnchor.Dx2, hSSFChildAnchor.Dx1);
			escherChildAnchorRecord.Dy2 = (short)Math.Max(hSSFChildAnchor.Dy2, hSSFChildAnchor.Dy1);
			return escherChildAnchorRecord;
		}
	}
	public class DrawingManager
	{
		private EscherDggRecord dgg;

		private Hashtable dgMap = new Hashtable();

		public EscherDggRecord Dgg => dgg;

		public DrawingManager(EscherDggRecord dgg)
		{
			this.dgg = dgg;
		}

		public EscherDgRecord CreateDgRecord()
		{
			EscherDgRecord escherDgRecord = new EscherDgRecord();
			escherDgRecord.RecordId = -4088;
			short num = FindNewDrawingGroupId();
			escherDgRecord.Options = (short)(num << 4);
			escherDgRecord.NumShapes = 0;
			escherDgRecord.LastMSOSPID = -1;
			dgg.AddCluster(num, 0);
			dgg.DrawingsSaved += 1;
			dgMap[num] = escherDgRecord;
			return escherDgRecord;
		}

		public int AllocateShapeId(short drawingGroupId)
		{
			EscherDgRecord escherDgRecord = (EscherDgRecord)dgMap[drawingGroupId];
			int lastMSOSPID = escherDgRecord.LastMSOSPID;
			int num = 0;
			if (lastMSOSPID % 1024 == 1023)
			{
				num = FindFreeSPIDBlock();
				dgg.AddCluster(drawingGroupId, 1);
			}
			else
			{
				for (int i = 0; i < dgg.FileIdClusters.Length; i++)
				{
					EscherDggRecord.FileIdCluster fileIdCluster = dgg.FileIdClusters[i];
					if (fileIdCluster.DrawingGroupId == drawingGroupId && fileIdCluster.NumShapeIdsUsed != 1024)
					{
						fileIdCluster.IncrementShapeId();
					}
					num = ((escherDgRecord.LastMSOSPID != -1) ? (escherDgRecord.LastMSOSPID + 1) : FindFreeSPIDBlock());
				}
			}
			dgg.NumShapesSaved += 1;
			if (num >= dgg.ShapeIdMax)
			{
				dgg.ShapeIdMax = num + 1;
			}
			escherDgRecord.LastMSOSPID = num;
			escherDgRecord.IncrementShapeCount();
			return num;
		}

		public short FindNewDrawingGroupId()
		{
			short num = 1;
			while (DrawingGroupExists(num))
			{
				num++;
			}
			return num;
		}

		public bool DrawingGroupExists(short dgId)
		{
			for (int i = 0; i < dgg.FileIdClusters.Length; i++)
			{
				if (dgg.FileIdClusters[i].DrawingGroupId == dgId)
				{
					return true;
				}
			}
			return false;
		}

		public int FindFreeSPIDBlock()
		{
			int shapeIdMax = dgg.ShapeIdMax;
			return (shapeIdMax / 1024 + 1) * 1024;
		}
	}
	public class DrawingManager2
	{
		private EscherDggRecord dgg;

		private IList drawingGroups = new ArrayList();

		public DrawingManager2(EscherDggRecord dgg)
		{
			this.dgg = dgg;
		}

		public void ClearDrawingGroups()
		{
			drawingGroups.Clear();
		}

		public virtual EscherDgRecord CreateDgRecord()
		{
			EscherDgRecord escherDgRecord = new EscherDgRecord();
			escherDgRecord.RecordId = -4088;
			short num = FindNewDrawingGroupId();
			escherDgRecord.Options = (short)(num << 4);
			escherDgRecord.NumShapes = 0;
			escherDgRecord.LastMSOSPID = -1;
			drawingGroups.Add(escherDgRecord);
			dgg.AddCluster(num, 0);
			dgg.DrawingsSaved += 1;
			return escherDgRecord;
		}

		public virtual int AllocateShapeId(short drawingGroupId)
		{
			EscherDgRecord drawingGroup = GetDrawingGroup(drawingGroupId);
			return AllocateShapeId(drawingGroupId, drawingGroup);
		}

		public virtual int AllocateShapeId(short drawingGroupId, EscherDgRecord dg)
		{
			dgg.NumShapesSaved += 1;
			for (int i = 0; i < dgg.FileIdClusters.Length; i++)
			{
				EscherDggRecord.FileIdCluster fileIdCluster = dgg.FileIdClusters[i];
				if (fileIdCluster.DrawingGroupId == drawingGroupId && fileIdCluster.NumShapeIdsUsed != 1024)
				{
					int num = fileIdCluster.NumShapeIdsUsed + 1024 * (i + 1);
					fileIdCluster.IncrementShapeId();
					dg.NumShapes++;
					dg.LastMSOSPID = num;
					if (num >= dgg.ShapeIdMax)
					{
						dgg.ShapeIdMax = num + 1;
					}
					return num;
				}
			}
			dgg.AddCluster(drawingGroupId, 0);
			dgg.FileIdClusters[dgg.FileIdClusters.Length - 1].IncrementShapeId();
			dg.NumShapes++;
			int num3 = (dg.LastMSOSPID = 1024 * dgg.FileIdClusters.Length);
			if (num3 >= dgg.ShapeIdMax)
			{
				dgg.ShapeIdMax = num3 + 1;
			}
			return num3;
		}

		public short FindNewDrawingGroupId()
		{
			short num = 1;
			while (DrawingGroupExists(num))
			{
				num++;
			}
			return num;
		}

		private EscherDgRecord GetDrawingGroup(int drawingGroupId)
		{
			return (EscherDgRecord)drawingGroups[drawingGroupId - 1];
		}

		private bool DrawingGroupExists(short dgId)
		{
			for (int i = 0; i < dgg.FileIdClusters.Length; i++)
			{
				if (dgg.FileIdClusters[i].DrawingGroupId == dgId)
				{
					return true;
				}
			}
			return false;
		}

		private int FindFreeSPIDBlock()
		{
			int shapeIdMax = dgg.ShapeIdMax;
			return (shapeIdMax / 1024 + 1) * 1024;
		}

		public EscherDggRecord GetDgg()
		{
			return dgg;
		}

		public void IncrementDrawingsSaved()
		{
			dgg.DrawingsSaved += 1;
		}
	}
