	public class RecordOrderer
	{
		private RecordOrderer()
		{
		}

		public static void AddNewSheetRecord(List<RecordBase> sheetRecords, RecordBase newRecord)
		{
			int index = FindSheetInsertPos(sheetRecords, newRecord.GetType());
			sheetRecords.Insert(index, newRecord);
		}

		private static int FindSheetInsertPos(List<RecordBase> records, Type recClass)
		{
			if (recClass == typeof(DataValidityTable))
			{
				return FindDataValidationTableInsertPos(records);
			}
			if (recClass == typeof(MergedCellsTable))
			{
				return FindInsertPosForNewMergedRecordTable(records);
			}
			if (recClass == typeof(ConditionalFormattingTable))
			{
				return FindInsertPosForNewCondFormatTable(records);
			}
			if (recClass == typeof(GutsRecord))
			{
				return GetGutsRecordInsertPos(records);
			}
			if (recClass == typeof(PageSettingsBlock))
			{
				return GetPageBreakRecordInsertPos(records);
			}
			if (recClass == typeof(WorksheetProtectionBlock))
			{
				return GetWorksheetProtectionBlockInsertPos(records);
			}
			throw new InvalidOperationException("Unexpected record class (" + recClass.Name + ")");
		}

		private static int GetWorksheetProtectionBlockInsertPos(List<RecordBase> records)
		{
			int num = GetDimensionsIndex(records);
			while (num > 0)
			{
				num--;
				object rb = records[num];
				if (!IsProtectionSubsequentRecord(rb))
				{
					return num + 1;
				}
			}
			throw new InvalidOperationException("did not find insert pos for protection block");
		}

		private static bool IsProtectionSubsequentRecord(object rb)
		{
			if (rb is ColumnInfoRecordsAggregate)
			{
				return true;
			}
			if (rb is NPOI.HSSF.Record.Record)
			{
				NPOI.HSSF.Record.Record record = (NPOI.HSSF.Record.Record)rb;
				short sid = record.Sid;
				if (sid == 85 || sid == 144)
				{
					return true;
				}
			}
			return false;
		}

		private static int GetPageBreakRecordInsertPos(List<RecordBase> records)
		{
			int dimensionsIndex = GetDimensionsIndex(records);
			int num = dimensionsIndex - 1;
			while (num > 0)
			{
				num--;
				RecordBase rb = records[num];
				if (IsPageBreakPriorRecord(rb))
				{
					return num + 1;
				}
			}
			throw new InvalidOperationException("Did not Find insert point for GUTS");
		}

		private static bool IsPageBreakPriorRecord(RecordBase rb)
		{
			if (rb is NPOI.HSSF.Record.Record)
			{
				NPOI.HSSF.Record.Record record = (NPOI.HSSF.Record.Record)rb;
				switch (record.Sid)
				{
				case 12:
				case 13:
				case 14:
				case 15:
				case 16:
				case 17:
				case 34:
				case 42:
				case 43:
				case 94:
				case 95:
				case 129:
				case 130:
				case 523:
				case 549:
				case 2057:
					return true;
				}
			}
			return false;
		}

		private static int FindInsertPosForNewCondFormatTable(List<RecordBase> records)
		{
			for (int num = records.Count - 2; num >= 0; num--)
			{
				object obj = records[num];
				if (obj is MergedCellsTable)
				{
					return num + 1;
				}
				if (!(obj is DataValidityTable))
				{
					NPOI.HSSF.Record.Record record = (NPOI.HSSF.Record.Record)obj;
					switch (record.Sid)
					{
					case 29:
					case 65:
					case 153:
					case 160:
					case 239:
					case 351:
					case 574:
						return num + 1;
					}
				}
			}
			throw new InvalidOperationException("Did not Find Window2 record");
		}

		private static int FindInsertPosForNewMergedRecordTable(List<RecordBase> records)
		{
			for (int num = records.Count - 2; num >= 0; num--)
			{
				object obj = records[num];
				if (obj is NPOI.HSSF.Record.Record)
				{
					NPOI.HSSF.Record.Record record = (NPOI.HSSF.Record.Record)obj;
					switch (record.Sid)
					{
					case 29:
					case 65:
					case 153:
					case 160:
					case 574:
						return num + 1;
					}
				}
			}
			throw new InvalidOperationException("Did not Find Window2 record");
		}

		private static int FindDataValidationTableInsertPos(List<RecordBase> records)
		{
			int num = records.Count - 1;
			if (!(records[num] is EOFRecord))
			{
				throw new InvalidOperationException("Last sheet record should be EOFRecord");
			}
			while (num > 0)
			{
				num--;
				RecordBase recordBase = records[num];
				if (IsDVTPriorRecord(recordBase))
				{
					NPOI.HSSF.Record.Record record = (NPOI.HSSF.Record.Record)records[num + 1];
					if (!IsDVTSubsequentRecord(record.Sid))
					{
						throw new InvalidOperationException("Unexpected (" + record.GetType().Name + ") found after (" + recordBase.GetType().Name + ")");
					}
					return num + 1;
				}
				NPOI.HSSF.Record.Record record2 = (NPOI.HSSF.Record.Record)recordBase;
				if (!IsDVTSubsequentRecord(record2.Sid))
				{
					throw new InvalidOperationException("Unexpected (" + record2.GetType().Name + ") while looking for DV Table insert pos");
				}
			}
			return 0;
		}

		private static bool IsDVTPriorRecord(RecordBase rb)
		{
			if (rb is MergedCellsTable || rb is ConditionalFormattingTable)
			{
				return true;
			}
			switch (((NPOI.HSSF.Record.Record)rb).Sid)
			{
			case 29:
			case 65:
			case 153:
			case 160:
			case 239:
			case 351:
			case 440:
			case 574:
			case 2048:
				return true;
			default:
				return false;
			}
		}

		private static bool IsDVTSubsequentRecord(short sid)
		{
			switch (sid)
			{
			case 10:
			case 2146:
			case 2151:
			case 2152:
			case 2248:
				return true;
			default:
				return false;
			}
		}

		private static int GetDimensionsIndex(List<RecordBase> records)
		{
			int count = records.Count;
			for (int i = 0; i < count; i++)
			{
				if (records[i] is DimensionsRecord)
				{
					return i;
				}
			}
			throw new InvalidOperationException("DimensionsRecord not found");
		}

		private static int GetGutsRecordInsertPos(List<RecordBase> records)
		{
			int dimensionsIndex = GetDimensionsIndex(records);
			int num = dimensionsIndex - 1;
			while (num > 0)
			{
				num--;
				RecordBase rb = records[num];
				if (IsGutsPriorRecord(rb))
				{
					return num + 1;
				}
			}
			throw new InvalidOperationException("Did not Find insert point for GUTS");
		}

		private static bool IsGutsPriorRecord(RecordBase rb)
		{
			if (rb is NPOI.HSSF.Record.Record)
			{
				NPOI.HSSF.Record.Record record = (NPOI.HSSF.Record.Record)rb;
				switch (record.Sid)
				{
				case 12:
				case 13:
				case 14:
				case 15:
				case 16:
				case 17:
				case 34:
				case 42:
				case 43:
				case 94:
				case 95:
				case 130:
				case 523:
				case 2057:
					return true;
				}
			}
			return false;
		}

		public static bool IsEndOfRowBlock(int sid)
		{
			switch (sid)
			{
			case 61:
			case 93:
			case 125:
			case 128:
			case 176:
			case 236:
			case 237:
			case 438:
			case 574:
				return true;
			case 434:
				return true;
			case 10:
				throw new InvalidOperationException("Found EOFRecord before WindowTwoRecord was encountered");
			default:
				return PageSettingsBlock.IsComponentRecord(sid);
			}
		}

		public static bool IsRowBlockRecord(int sid)
		{
			switch (sid)
			{
			case 6:
			case 253:
			case 513:
			case 515:
			case 516:
			case 517:
			case 520:
			case 545:
			case 566:
			case 638:
			case 1212:
				return true;
			default:
				return false;
			}
		}
	}
	public class RecordStream
	{
		private IList _list;

		private int _nextIndex;

		private int _endIx;

		private int _countRead;

		public RecordStream(IList inputList, int startIndex, int endIx)
		{
			_list = inputList;
			_nextIndex = startIndex;
			_endIx = endIx;
			_countRead = 0;
		}

		public RecordStream(IList records, int startIx)
			: this(records, startIx, records.Count)
		{
		}

		public bool HasNext()
		{
			return _nextIndex < _endIx;
		}

		public NPOI.HSSF.Record.Record GetNext()
		{
			if (_nextIndex >= _list.Count)
			{
				throw new Exception("Attempt to Read past end of record stream");
			}
			_countRead++;
			return (NPOI.HSSF.Record.Record)_list[_nextIndex++];
		}

		public int PeekNextSid()
		{
			if (!HasNext())
			{
				return -1;
			}
			return ((NPOI.HSSF.Record.Record)_list[_nextIndex]).Sid;
		}

		public Type PeekNextClass()
		{
			if (_nextIndex >= _list.Count)
			{
				return null;
			}
			return _list[_nextIndex].GetType();
		}

		public int GetCountRead()
		{
			return _countRead;
		}

		public int PeekNextChartSid()
		{
			if (!HasNext())
			{
				return -1;
			}
			while (PeekNextSid() == StartBlockRecord.sid || PeekNextSid() == 2131)
			{
				GetNext();
			}
			return PeekNextSid();
		}

		public void FindChartSubStream()
		{
			while (PeekNextSid() > -1)
			{
				NPOI.HSSF.Record.Record next = GetNext();
				if (next.Sid == 2057 && (next as BOFRecord).Type == BOFRecordType.Chart)
				{
					_nextIndex--;
					_countRead--;
					break;
				}
			}
		}
	}
	public class RowBlocksReader
	{
		private ArrayList _plainRecords;

		private SharedValueManager _sfm;

		private MergeCellsRecord[] _mergedCellsRecords;

		public MergeCellsRecord[] LooseMergedCells => _mergedCellsRecords;

		public SharedValueManager SharedFormulaManager => _sfm;

		public RecordStream PlainRecordStream => new RecordStream(_plainRecords, 0);

		public RowBlocksReader(RecordStream rs)
		{
			ArrayList arrayList = new ArrayList();
			ArrayList arrayList2 = new ArrayList();
			ArrayList arrayList3 = new ArrayList();
			ArrayList arrayList4 = new ArrayList();
			ArrayList arrayList5 = new ArrayList();
			List<CellReference> list = new List<CellReference>();
			NPOI.HSSF.Record.Record record = null;
			while (!RecordOrderer.IsEndOfRowBlock(rs.PeekNextSid()))
			{
				if (!rs.HasNext())
				{
					throw new InvalidOperationException("Failed to find end of row/cell records");
				}
				NPOI.HSSF.Record.Record next = rs.GetNext();
				ArrayList arrayList6;
				switch (next.Sid)
				{
				case 229:
					arrayList6 = arrayList5;
					break;
				case 1212:
				{
					arrayList6 = arrayList2;
					if (!(record is FormulaRecord))
					{
						throw new Exception("Shared formula record should follow a FormulaRecord");
					}
					FormulaRecord formulaRecord = (FormulaRecord)record;
					list.Add(new CellReference(formulaRecord.Row, formulaRecord.Column));
					break;
				}
				case 545:
					arrayList6 = arrayList3;
					break;
				case 566:
					arrayList6 = arrayList4;
					break;
				default:
					arrayList6 = arrayList;
					break;
				}
				arrayList6.Add(next);
				record = next;
			}
			SharedFormulaRecord[] array = new SharedFormulaRecord[arrayList2.Count];
			List<ArrayRecord> list2 = new List<ArrayRecord>(arrayList3.Count);
			List<TableRecord> list3 = new List<TableRecord>(arrayList4.Count);
			array = (SharedFormulaRecord[])arrayList2.ToArray(typeof(SharedFormulaRecord));
			CellReference[] array2 = new CellReference[list.Count];
			array2 = list.ToArray();
			list2 = new List<ArrayRecord>((ArrayRecord[])arrayList3.ToArray(typeof(ArrayRecord)));
			list3 = new List<TableRecord>((TableRecord[])arrayList4.ToArray(typeof(TableRecord)));
			_plainRecords = arrayList;
			_sfm = SharedValueManager.Create(array, array2, list2, list3);
			_mergedCellsRecords = new MergeCellsRecord[arrayList5.Count];
			_mergedCellsRecords = (MergeCellsRecord[])arrayList5.ToArray(typeof(MergeCellsRecord));
		}
	}
	[Serializable]
	public class InternalSheet
	{
		private class RecordCloner : RecordVisitor
		{
			private IList _destList;

