			bool isHidden = false;
			bool isVeryHidden = false;
			switch (hidden)
			{
			case 1:
				isHidden = true;
				break;
			case 2:
				isVeryHidden = true;
				break;
			default:
				throw new ArgumentException("Invalid hidden flag " + hidden + " given, must be 0, 1 or 2");
