				externsheetPos = value;
			}
		}

		public void Add(int pos, NPOI.HSSF.Record.Record r)
		{
			records.Insert(pos, r);
			if (Protpos >= pos)
			{
				Protpos = protpos + 1;
			}
			if (Bspos >= pos)
			{
				Bspos = bspos + 1;
			}
			if (Tabpos >= pos)
			{
				Tabpos = tabpos + 1;
			}
			if (Fontpos >= pos)
			{
				Fontpos = fontpos + 1;
			}
			if (Xfpos >= pos)
			{
				Xfpos = xfpos + 1;
			}
			if (Backuppos >= pos)
			{
				Backuppos = backuppos + 1;
			}
			if (Namepos >= pos)
			{
				Namepos = namepos + 1;
			}
			if (Supbookpos >= pos)
			{
				Supbookpos = supbookpos + 1;
			}
			if (Palettepos != -1 && Palettepos >= pos)
			{
				Palettepos = palettepos + 1;
			}
			if (ExternsheetPos >= pos)
			{
				ExternsheetPos++;
			}
		}

		public IEnumerator<NPOI.HSSF.Record.Record> GetEnumerator()
		{
			return records.GetEnumerator();
		}

		public void Remove(NPOI.HSSF.Record.Record record)
		{
			int pos = records.IndexOf(record);
			Remove(pos);
		}

		public void Remove(int pos)
		{
			records.RemoveAt(pos);
			if (Protpos >= pos)
			{
				Protpos = protpos - 1;
			}
			if (Bspos >= pos)
			{
				Bspos = bspos - 1;
			}
			if (Tabpos >= pos)
			{
				Tabpos = tabpos - 1;
			}
			if (Fontpos >= pos)
			{
				Fontpos = fontpos - 1;
			}
			if (Xfpos >= pos)
			{
				Xfpos = xfpos - 1;
			}
			if (Backuppos >= pos)
			{
				Backuppos = backuppos - 1;
			}
			if (Namepos >= pos)
			{
				Namepos--;
			}
			if (Supbookpos >= pos)
			{
				Supbookpos--;
			}
			if (Palettepos != -1 && Palettepos >= pos)
			{
				Palettepos = palettepos - 1;
			}
			if (ExternsheetPos >= pos)
			{
				ExternsheetPos--;
			}
		}
	}
