namespace NPOI.HSSF.Record
{
	public abstract class AbstractEscherHolderRecord : Record
	{
		private static bool DESERIALISE;

		private List<EscherRecord> escherRecords;

		private LazilyConcatenatedByteArray rawDataContainer = new LazilyConcatenatedByteArray();

		protected abstract string RecordName { get; }

		public override int RecordSize
		{
			get
			{
				byte[] rawData = RawData;
				if (escherRecords.Count == 0 && rawData != null)
				{
					return rawData.Length + 4;
				}
				int num = 4;
				foreach (EscherRecord escherRecord in escherRecords)
				{
					num += escherRecord.RecordSize;
				}
				return num;
			}
		}

		public List<EscherRecord> EscherRecords => escherRecords;

		public byte[] RawData
		{
			get
			{
				return rawDataContainer.ToArray();
			}
			set
			{
				rawDataContainer.Clear();
				rawDataContainer.Concatenate(value);
			}
		}

		static AbstractEscherHolderRecord()
		{
			DESERIALISE = false;
		}

		public AbstractEscherHolderRecord()
		{
			escherRecords = new List<EscherRecord>();
		}

		public AbstractEscherHolderRecord(RecordInputStream in1)
		{
			escherRecords = new List<EscherRecord>();
			if (!DESERIALISE)
			{
				rawDataContainer.Concatenate(in1.ReadRemainder());
				return;
			}
			byte[] array = in1.ReadAllContinuedRemainder();
			ConvertToEscherRecords(0, array.Length, array);
		}

		protected void ConvertRawBytesToEscherRecords()
		{
			if (!DESERIALISE)
			{
				byte[] rawData = RawData;
				ConvertToEscherRecords(0, rawData.Length, rawData);
			}
		}

		private void ConvertToEscherRecords(int offset, int size, byte[] data)
		{
			escherRecords.Clear();
			IEscherRecordFactory escherRecordFactory = new DefaultEscherRecordFactory();
			int num;
			for (int i = offset; i < offset + size; i += num)
			{
				EscherRecord escherRecord = escherRecordFactory.CreateRecord(data, i);
				num = escherRecord.FillFields(data, i, escherRecordFactory);
				escherRecords.Add(escherRecord);
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			string newLine = Environment.NewLine;
			stringBuilder.Append('[' + RecordName + ']' + newLine);
			if (escherRecords.Count == 0)
			{
				stringBuilder.Append("No Escher Records Decoded" + newLine);
			}
			foreach (EscherRecord escherRecord in escherRecords)
			{
				stringBuilder.Append(escherRecord.ToString());
			}
			stringBuilder.Append("[/" + RecordName + ']' + newLine);
			return stringBuilder.ToString();
		}

		public override int Serialize(int offset, byte[] data)
		{
			LittleEndian.PutShort(data, offset, Sid);
			LittleEndian.PutShort(data, 2 + offset, (short)(RecordSize - 4));
			byte[] rawData = RawData;
			if (escherRecords.Count == 0 && rawData != null)
			{
				LittleEndian.PutShort(data, offset, Sid);
				LittleEndian.PutShort(data, 2 + offset, (short)(RecordSize - 4));
				System.Array.Copy(rawData, 0, data, 4 + offset, rawData.Length);
				return rawData.Length + 4;
			}
			LittleEndian.PutShort(data, offset, Sid);
			LittleEndian.PutShort(data, 2 + offset, (short)(RecordSize - 4));
			int num = offset + 4;
			foreach (EscherRecord escherRecord in escherRecords)
			{
				num += escherRecord.Serialize(num, data, new NullEscherSerializationListener());
			}
			return RecordSize;
		}

		public override object Clone()
		{
			return CloneViaReserialise();
		}

		public void AddEscherRecord(int index, EscherRecord element)
		{
			escherRecords.Insert(index, element);
		}

		public bool AddEscherRecord(EscherRecord element)
		{
			escherRecords.Add(element);
			return true;
		}

		public void ClearEscherRecords()
		{
			escherRecords.Clear();
		}

		public EscherContainerRecord GetEscherContainer()
		{
			IEnumerator enumerator = escherRecords.GetEnumerator();
			while (enumerator.MoveNext())
			{
				object current = enumerator.Current;
				if (current is EscherContainerRecord)
				{
					return (EscherContainerRecord)current;
				}
			}
			return null;
		}

		public EscherRecord FindFirstWithId(short id)
		{
			return FindFirstWithId(id, EscherRecords);
		}

		private EscherRecord FindFirstWithId(short id, List<EscherRecord> records)
		{
			IEnumerator enumerator = records.GetEnumerator();
			while (enumerator.MoveNext())
			{
				EscherRecord escherRecord = (EscherRecord)enumerator.Current;
				if (escherRecord.RecordId == id)
				{
					return escherRecord;
				}
			}
			IEnumerator enumerator2 = records.GetEnumerator();
			while (enumerator2.MoveNext())
			{
				EscherRecord escherRecord2 = (EscherRecord)enumerator2.Current;
				if (escherRecord2.IsContainerRecord)
				{
					EscherRecord escherRecord3 = FindFirstWithId(id, escherRecord2.ChildRecords);
					if (escherRecord3 != null)
					{
						return escherRecord3;
					}
				}
			}
			return null;
		}

		public EscherRecord GetEscherRecord(int index)
		{
			return escherRecords[index];
		}

		public void Join(AbstractEscherHolderRecord record)
		{
			rawDataContainer.Concatenate(record.RawData);
		}

		public void ProcessContinueRecord(byte[] record)
		{
			rawDataContainer.Concatenate(record);
		}

		public void Decode()
		{
			if (escherRecords == null || escherRecords.Count == 0)
			{
				byte[] rawData = RawData;
				ConvertToEscherRecords(0, rawData.Length, rawData);
			}
		}
	}
}
namespace NPOI.HSSF.Record.Aggregates
{
	public class CFRecordsAggregate : RecordAggregate
	{
		private const int MAX_97_2003_CONDTIONAL_FORMAT_RULES = 3;

		public const short sid = -2008;

		private CFHeaderRecord header;

		private List<CFRuleRecord> rules;

		public override short Sid => -2008;

		public CFHeaderRecord Header => header;

		public int NumberOfRules => rules.Count;

		private CFRecordsAggregate(CFHeaderRecord pHeader, CFRuleRecord[] pRules)
		{
			if (pHeader == null)
			{
				throw new ArgumentException("header must not be null");
			}
			if (pRules == null)
			{
				throw new ArgumentException("rules must not be null");
			}
			if (pRules.Length > 3)
			{
				Console.WriteLine("Excel versions before 2007 require that No more than " + 3 + " rules may be specified, " + pRules.Length + " were found, this file will cause problems with old Excel versions");
			}
			header = pHeader;
			rules = new List<CFRuleRecord>(3);
			for (int i = 0; i < pRules.Length; i++)
			{
				rules.Add(pRules[i]);
			}
		}

		public CFRecordsAggregate(CellRangeAddress[] regions, CFRuleRecord[] rules)
			: this(new CFHeaderRecord(regions, rules.Length), rules)
		{
		}

		public static CFRecordsAggregate CreateCFAggregate(RecordStream rs)
		{
			Record next = rs.GetNext();
			if (next.Sid != 432)
			{
				throw new InvalidOperationException("next record sid was " + next.Sid + " instead of " + (short)432 + " as expected");
			}
			CFHeaderRecord cFHeaderRecord = (CFHeaderRecord)next;
			int numberOfConditionalFormats = cFHeaderRecord.NumberOfConditionalFormats;
			CFRuleRecord[] array = new CFRuleRecord[numberOfConditionalFormats];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = (CFRuleRecord)rs.GetNext();
			}
			return new CFRecordsAggregate(cFHeaderRecord, array);
		}

		public static CFRecordsAggregate CreateCFAggregate(IList recs, int pOffset)
		{
			Record record = (Record)recs[pOffset];
			if (record.Sid != 432)
			{
				throw new InvalidOperationException("next record sid was " + record.Sid + " instead of " + (short)432 + " as expected");
			}
			CFHeaderRecord cFHeaderRecord = (CFHeaderRecord)record;
			int numberOfConditionalFormats = cFHeaderRecord.NumberOfConditionalFormats;
			CFRuleRecord[] array = new CFRuleRecord[numberOfConditionalFormats];
			int num = pOffset;
			int i;
			for (i = 0; i < array.Length; i++)
			{
				num++;
				if (num >= recs.Count)
				{
					break;
				}
				record = (Record)recs[num];
				if (!(record is CFRuleRecord))
				{
					break;
				}
				array[i] = (CFRuleRecord)record;
			}
			if (i < numberOfConditionalFormats)
			{
				cFHeaderRecord.NumberOfConditionalFormats = numberOfConditionalFormats;
				CFRuleRecord[] array2 = new CFRuleRecord[i];
				System.Array.Copy(array, 0, array2, 0, i);
				array = array2;
			}
			return new CFRecordsAggregate(cFHeaderRecord, array);
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			rv.VisitRecord(header);
			for (int i = 0; i < rules.Count; i++)
			{
				CFRuleRecord r = rules[i];
				rv.VisitRecord(r);
			}
		}

		public CFRecordsAggregate CloneCFAggregate()
		{
			CFRuleRecord[] array = new CFRuleRecord[rules.Count];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = (CFRuleRecord)GetRule(i).Clone();
			}
			return new CFRecordsAggregate((CFHeaderRecord)header.Clone(), array);
		}

		public override int Serialize(int offset, byte[] data)
		{
			int count = rules.Count;
			header.NumberOfConditionalFormats = count;
			int num = offset;
			num += header.Serialize(num, data);
			for (int i = 0; i < count; i++)
			{
				num += GetRule(i).Serialize(num, data);
			}
			return num - offset;
		}

		private void CheckRuleIndex(int idx)
		{
			if (idx < 0 || idx >= rules.Count)
			{
				throw new ArgumentException("Bad rule record index (" + idx + ") nRules=" + rules.Count);
			}
		}

		public CFRuleRecord GetRule(int idx)
		{
			CheckRuleIndex(idx);
			return rules[idx];
		}

		public void SetRule(int idx, CFRuleRecord r)
		{
			CheckRuleIndex(idx);
			rules[idx] = r;
		}

		public bool UpdateFormulasAfterCellShift(FormulaShifter shifter, int currentExternSheetIx)
		{
			CellRangeAddress[] cellRanges = header.CellRanges;
			bool flag = false;
			List<CellRangeAddress> list = new List<CellRangeAddress>();
			foreach (CellRangeAddress cellRangeAddress in cellRanges)
			{
				CellRangeAddress cellRangeAddress2 = ShiftRange(shifter, cellRangeAddress, currentExternSheetIx);
				if (cellRangeAddress2 == null)
				{
					flag = true;
					continue;
				}
				list.Add(cellRangeAddress2);
				if (cellRangeAddress2 != cellRangeAddress)
				{
					flag = true;
				}
			}
			if (flag)
			{
				int count = list.Count;
				if (count == 0)
				{
					return false;
				}
				CellRangeAddress[] array = new CellRangeAddress[count];
				array = list.ToArray();
				header.CellRanges = array;
			}
			for (int j = 0; j < rules.Count; j++)
			{
				CFRuleRecord cFRuleRecord = rules[j];
				Ptg[] parsedExpression = cFRuleRecord.ParsedExpression1;
				if (parsedExpression != null && shifter.AdjustFormula(parsedExpression, currentExternSheetIx))
				{
					cFRuleRecord.ParsedExpression1 = parsedExpression;
				}
				parsedExpression = cFRuleRecord.ParsedExpression2;
				if (parsedExpression != null && shifter.AdjustFormula(parsedExpression, currentExternSheetIx))
				{
					cFRuleRecord.ParsedExpression2 = parsedExpression;
				}
			}
			return true;
		}

		private static CellRangeAddress ShiftRange(FormulaShifter shifter, CellRangeAddress cra, int currentExternSheetIx)
		{
			AreaPtg areaPtg = new AreaPtg(cra.FirstRow, cra.LastRow, cra.FirstColumn, cra.LastColumn, firstRowRelative: false, lastRowRelative: false, firstColRelative: false, lastColRelative: false);
			Ptg[] array = new Ptg[1] { areaPtg };
			if (!shifter.AdjustFormula(array, currentExternSheetIx))
			{
				return cra;
			}
			Ptg ptg = array[0];
			if (ptg is AreaPtg)
			{
				AreaPtg areaPtg2 = (AreaPtg)ptg;
				return new CellRangeAddress(areaPtg2.FirstRow, areaPtg2.LastRow, areaPtg2.FirstColumn, areaPtg2.LastColumn);
			}
			if (ptg is AreaErrPtg)
			{
				return null;
			}
			throw new InvalidCastException("Unexpected shifted ptg class (" + ptg.GetType().Name + ")");
		}

		public void AddRule(CFRuleRecord r)
		{
			if (rules.Count >= 3)
			{
				Console.WriteLine("Excel versions before 2007 cannot cope with any more than " + 3 + " - this file will cause problems with old Excel versions");
			}
			rules.Add(r);
			header.NumberOfConditionalFormats = rules.Count;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[CF]\n");
			if (header != null)
			{
				stringBuilder.Append(header.ToString());
			}
			for (int i = 0; i < rules.Count; i++)
			{
				CFRuleRecord cFRuleRecord = rules[i];
				if (cFRuleRecord != null)
				{
					stringBuilder.Append(cFRuleRecord.ToString());
				}
			}
			stringBuilder.Append("[/CF]\n");
			return stringBuilder.ToString();
		}
	}
	public class ColumnInfoRecordsAggregate : RecordAggregate
	{
		private class CIRComparator : IComparer
		{
			public static IComparer instance = new CIRComparator();

			private CIRComparator()
			{
			}

			public int Compare(object a, object b)
			{
				return CompareColInfos((ColumnInfoRecord)a, (ColumnInfoRecord)b);
			}

			public static int CompareColInfos(ColumnInfoRecord a, ColumnInfoRecord b)
			{
				return a.FirstColumn - b.FirstColumn;
			}
		}

		private ArrayList records;

		public override short Sid => -1012;

		public int NumColumns => records.Count;

		public override int RecordSize
		{
			get
			{
				int num = 0;
				IEnumerator enumerator = records.GetEnumerator();
				while (enumerator.MoveNext())
				{
					num += ((ColumnInfoRecord)enumerator.Current).RecordSize;
				}
				return num;
			}
		}

		public int MaxOutlineLevel
		{
			get
			{
				int num = 0;
				int count = records.Count;
				for (int i = 0; i < count; i++)
				{
					ColumnInfoRecord colInfo = GetColInfo(i);
					num = Math.Max(colInfo.OutlineLevel, num);
				}
				return num;
			}
		}

		public ColumnInfoRecordsAggregate()
		{
			records = new ArrayList();
		}

		public ColumnInfoRecordsAggregate(RecordStream rs)
			: this()
		{
			bool flag = true;
			ColumnInfoRecord columnInfoRecord = null;
			while (rs.PeekNextClass() == typeof(ColumnInfoRecord))
			{
				ColumnInfoRecord columnInfoRecord2 = (ColumnInfoRecord)rs.GetNext();
				records.Add(columnInfoRecord2);
				if (columnInfoRecord != null && CIRComparator.CompareColInfos(columnInfoRecord, columnInfoRecord2) > 0)
				{
					flag = false;
				}
				columnInfoRecord = columnInfoRecord2;
			}
			if (records.Count < 1)
			{
				throw new InvalidOperationException("No column info records found");
			}
			if (!flag)
			{
				records.Sort(CIRComparator.instance);
			}
		}

		public IEnumerator GetEnumerator()
		{
			return records.GetEnumerator();
		}

		public object Clone()
		{
			ColumnInfoRecordsAggregate columnInfoRecordsAggregate = new ColumnInfoRecordsAggregate();
			for (int i = 0; i < records.Count; i++)
			{
				ColumnInfoRecord columnInfoRecord = (ColumnInfoRecord)records[i];
				columnInfoRecord = (ColumnInfoRecord)columnInfoRecord.Clone();
				columnInfoRecordsAggregate.records.Add(columnInfoRecord);
			}
			return columnInfoRecordsAggregate;
		}

		public void InsertColumn(ColumnInfoRecord col)
		{
			records.Add(col);
			records.Sort(CIRComparator.instance);
		}

		public void InsertColumn(int idx, ColumnInfoRecord col)
		{
			records.Insert(idx, col);
		}

		public override int Serialize(int offset, byte[] data)
		{
			IEnumerator enumerator = records.GetEnumerator();
			int num = offset;
			while (enumerator.MoveNext())
			{
				num += ((Record)enumerator.Current).Serialize(num, data);
			}
			return num - offset;
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			int count = records.Count;
			if (count < 1)
			{
				return;
			}
			ColumnInfoRecord columnInfoRecord = null;
			for (int i = 0; i < count; i++)
			{
				ColumnInfoRecord columnInfoRecord2 = (ColumnInfoRecord)records[i];
				rv.VisitRecord(columnInfoRecord2);
				if (columnInfoRecord != null && CIRComparator.CompareColInfos(columnInfoRecord, columnInfoRecord2) > 0)
				{
					throw new InvalidOperationException("Column info records are out of order");
				}
				columnInfoRecord = columnInfoRecord2;
			}
		}

		public int FindStartOfColumnOutlineGroup(int idx)
		{
			ColumnInfoRecord columnInfoRecord = (ColumnInfoRecord)records[idx];
			int outlineLevel = columnInfoRecord.OutlineLevel;
			while (idx != 0)
			{
				ColumnInfoRecord columnInfoRecord2 = (ColumnInfoRecord)records[idx - 1];
				if (columnInfoRecord.FirstColumn - 1 != columnInfoRecord2.LastColumn || columnInfoRecord2.OutlineLevel < outlineLevel)
				{
					break;
				}
				idx--;
				columnInfoRecord = columnInfoRecord2;
			}
			return idx;
		}

		public int FindEndOfColumnOutlineGroup(int idx)
		{
			ColumnInfoRecord columnInfoRecord = (ColumnInfoRecord)records[idx];
			int outlineLevel = columnInfoRecord.OutlineLevel;
			while (idx < records.Count - 1)
			{
				ColumnInfoRecord columnInfoRecord2 = (ColumnInfoRecord)records[idx + 1];
				if (columnInfoRecord.LastColumn + 1 != columnInfoRecord2.FirstColumn || columnInfoRecord2.OutlineLevel < outlineLevel)
				{
					break;
				}
				idx++;
				columnInfoRecord = columnInfoRecord2;
			}
			return idx;
		}

		public ColumnInfoRecord GetColInfo(int idx)
		{
			return (ColumnInfoRecord)records[idx];
		}

		public bool IsColumnGroupCollapsed(int idx)
		{
			int num = FindEndOfColumnOutlineGroup(idx);
			int num2 = num + 1;
			if (num2 >= records.Count)
			{
				return false;
			}
			ColumnInfoRecord colInfo = GetColInfo(num2);
			if (!GetColInfo(num).IsAdjacentBefore(colInfo))
			{
				return false;
			}
			return colInfo.IsCollapsed;
		}

		public bool IsColumnGroupHiddenByParent(int idx)
		{
			int num = 0;
			bool result = false;
			int num2 = FindEndOfColumnOutlineGroup(idx);
			if (num2 < records.Count)
			{
				ColumnInfoRecord colInfo = GetColInfo(num2 + 1);
				if (GetColInfo(num2).IsAdjacentBefore(colInfo))
				{
					num = colInfo.OutlineLevel;
					result = colInfo.IsHidden;
				}
			}
			int num3 = 0;
			bool result2 = false;
			int num4 = FindStartOfColumnOutlineGroup(idx);
			if (num4 > 0)
			{
				ColumnInfoRecord colInfo2 = GetColInfo(num4 - 1);
				if (colInfo2.IsAdjacentBefore(GetColInfo(num4)))
				{
					num3 = colInfo2.OutlineLevel;
					result2 = colInfo2.IsHidden;
				}
			}
			if (num > num3)
			{
				return result;
			}
			return result2;
		}

		public void CollapseColumn(int columnNumber)
		{
			int num = FindColInfoIdx(columnNumber, 0);
			if (num != -1)
			{
				int num2 = FindStartOfColumnOutlineGroup(num);
				ColumnInfoRecord colInfo = GetColInfo(num2);
				int num3 = SetGroupHidden(num2, colInfo.OutlineLevel, hidden: true);
				SetColumn(num3 + 1, null, null, null, null, true);
			}
		}

		public void ExpandColumn(int columnNumber)
		{
			int num = FindColInfoIdx(columnNumber, 0);
			if (num == -1 || !IsColumnGroupCollapsed(num))
			{
				return;
			}
			int num2 = FindStartOfColumnOutlineGroup(num);
			ColumnInfoRecord colInfo = GetColInfo(num2);
			int num3 = FindEndOfColumnOutlineGroup(num);
			GetColInfo(num3);
			if (!IsColumnGroupHiddenByParent(num))
			{
				for (int i = num2; i <= num3; i++)
				{
					if (colInfo.OutlineLevel == GetColInfo(i).OutlineLevel)
					{
						GetColInfo(i).IsHidden = false;
					}
				}
			}
			SetColumn(colInfo.LastColumn + 1, null, null, null, null, false);
		}

		private static void SetColumnInfoFields(ColumnInfoRecord ci, short? xfStyle, int? width, int? level, bool? hidden, bool? collapsed)
		{
			if (((int?)xfStyle).HasValue)
			{
				ci.XFIndex = Convert.ToInt16(xfStyle, CultureInfo.InvariantCulture);
			}
			if (width.HasValue)
			{
				ci.ColumnWidth = Convert.ToInt32(width, CultureInfo.InvariantCulture);
			}
			if (level.HasValue)
			{
				ci.OutlineLevel = (short)level.Value;
			}
			if (hidden.HasValue)
			{
				ci.IsHidden = Convert.ToBoolean(hidden, CultureInfo.InvariantCulture);
			}
			if (collapsed.HasValue)
			{
				ci.IsCollapsed = Convert.ToBoolean(collapsed, CultureInfo.InvariantCulture);
			}
		}

		private void AttemptMergeColInfoRecords(int colInfoIx)
		{
			int count = records.Count;
			if (colInfoIx < 0 || colInfoIx >= count)
			{
				throw new ArgumentException("colInfoIx " + colInfoIx + " is out of range (0.." + (count - 1) + ")");
			}
			ColumnInfoRecord colInfo = GetColInfo(colInfoIx);
			int num = colInfoIx + 1;
			if (num < count && MergeColInfoRecords(colInfo, GetColInfo(num)))
			{
				records.RemoveAt(num);
			}
			if (colInfoIx > 0 && MergeColInfoRecords(GetColInfo(colInfoIx - 1), colInfo))
			{
				records.RemoveAt(colInfoIx);
			}
		}

		private static bool MergeColInfoRecords(ColumnInfoRecord ciA, ColumnInfoRecord ciB)
		{
			if (ciA.IsAdjacentBefore(ciB) && ciA.FormatMatches(ciB))
			{
				ciA.LastColumn = ciB.LastColumn;
				return true;
			}
			return false;
		}

		private int SetGroupHidden(int pIdx, int level, bool hidden)
		{
			int i = pIdx;
			ColumnInfoRecord columnInfoRecord = GetColInfo(i);
			for (; i < records.Count; i++)
			{
				columnInfoRecord.IsHidden = hidden;
				if (i + 1 < records.Count)
				{
					ColumnInfoRecord colInfo = GetColInfo(i + 1);
					if (!columnInfoRecord.IsAdjacentBefore(colInfo) || colInfo.OutlineLevel < level)
					{
						break;
					}
					columnInfoRecord = colInfo;
				}
			}
			return columnInfoRecord.LastColumn;
		}

		public void SetColumn(int targetColumnIx, short? xfIndex, int? width, int? level, bool? hidden, bool? collapsed)
		{
			ColumnInfoRecord columnInfoRecord = null;
			int num = 0;
			for (num = 0; num < records.Count; num++)
			{
				ColumnInfoRecord columnInfoRecord2 = (ColumnInfoRecord)records[num];
				if (columnInfoRecord2.ContainsColumn(targetColumnIx))
				{
					columnInfoRecord = columnInfoRecord2;
					break;
				}
				if (columnInfoRecord2.FirstColumn > targetColumnIx)
				{
					break;
				}
			}
			if (columnInfoRecord == null)
			{
				ColumnInfoRecord columnInfoRecord3 = new ColumnInfoRecord();
				columnInfoRecord3.FirstColumn = targetColumnIx;
				columnInfoRecord3.LastColumn = targetColumnIx;
				SetColumnInfoFields(columnInfoRecord3, xfIndex, width, level, hidden, collapsed);
				InsertColumn(num, columnInfoRecord3);
				AttemptMergeColInfoRecords(num);
				return;
			}
			bool flag = columnInfoRecord.XFIndex != xfIndex;
			bool flag2 = columnInfoRecord.ColumnWidth != width;
			bool flag3 = columnInfoRecord.OutlineLevel != level;
			bool flag4 = columnInfoRecord.IsHidden != hidden;
			bool flag5 = columnInfoRecord.IsCollapsed != collapsed;
			if (!flag && !flag2 && !flag3 && !flag4 && !flag5)
			{
				return;
			}
			if (columnInfoRecord.FirstColumn == targetColumnIx && columnInfoRecord.LastColumn == targetColumnIx)
			{
				SetColumnInfoFields(columnInfoRecord, xfIndex, width, level, hidden, collapsed);
				AttemptMergeColInfoRecords(num);
			}
			else if (columnInfoRecord.FirstColumn == targetColumnIx || columnInfoRecord.LastColumn == targetColumnIx)
			{
				if (columnInfoRecord.FirstColumn == targetColumnIx)
				{
					columnInfoRecord.FirstColumn = targetColumnIx + 1;
				}
				else
				{
					columnInfoRecord.LastColumn = targetColumnIx - 1;
					num++;
				}
				ColumnInfoRecord columnInfoRecord4 = CopyColInfo(columnInfoRecord);
				columnInfoRecord4.FirstColumn = targetColumnIx;
				columnInfoRecord4.LastColumn = targetColumnIx;
				SetColumnInfoFields(columnInfoRecord4, xfIndex, width, level, hidden, collapsed);
				InsertColumn(num, columnInfoRecord4);
				AttemptMergeColInfoRecords(num);
			}
			else
			{
				ColumnInfoRecord columnInfoRecord5 = columnInfoRecord;
				ColumnInfoRecord columnInfoRecord6 = CopyColInfo(columnInfoRecord);
				ColumnInfoRecord columnInfoRecord7 = CopyColInfo(columnInfoRecord);
				int lastColumn = columnInfoRecord.LastColumn;
				columnInfoRecord5.LastColumn = targetColumnIx - 1;
				columnInfoRecord6.FirstColumn = targetColumnIx;
				columnInfoRecord6.LastColumn = targetColumnIx;
				SetColumnInfoFields(columnInfoRecord6, xfIndex, width, level, hidden, collapsed);
				InsertColumn(++num, columnInfoRecord6);
				columnInfoRecord7.FirstColumn = targetColumnIx + 1;
				columnInfoRecord7.LastColumn = lastColumn;
				InsertColumn(++num, columnInfoRecord7);
			}
		}

		private ColumnInfoRecord CopyColInfo(ColumnInfoRecord ci)
		{
			return (ColumnInfoRecord)ci.Clone();
		}

		private void SetColumnInfoFields(ColumnInfoRecord ci, short xfStyle, short width, int level, bool hidden, bool collapsed)
		{
			ci.XFIndex = xfStyle;
			ci.ColumnWidth = width;
			ci.OutlineLevel = (short)level;
			ci.IsHidden = hidden;
			ci.IsCollapsed = collapsed;
		}

		public void CollapseColInfoRecords(int columnIdx)
		{
			if (columnIdx != 0)
			{
				ColumnInfoRecord columnInfoRecord = (ColumnInfoRecord)records[columnIdx - 1];
				ColumnInfoRecord columnInfoRecord2 = (ColumnInfoRecord)records[columnIdx];
				if (columnInfoRecord.LastColumn == columnInfoRecord2.FirstColumn - 1 && columnInfoRecord.XFIndex == columnInfoRecord2.XFIndex && columnInfoRecord.Options == columnInfoRecord2.Options && columnInfoRecord.ColumnWidth == columnInfoRecord2.ColumnWidth)
				{
					columnInfoRecord.LastColumn = columnInfoRecord2.LastColumn;
					records.Remove(columnIdx);
				}
			}
		}

		public void GroupColumnRange(int fromColumnIx, int toColumnIx, bool indent)
		{
			int fromColInfoIdx = 0;
			for (int i = fromColumnIx; i <= toColumnIx; i++)
			{
				int value = 1;
				int num = FindColInfoIdx(i, fromColInfoIdx);
				if (num != -1)
				{
					value = GetColInfo(num).OutlineLevel;
					value = ((!indent) ? (value - 1) : (value + 1));
					value = Math.Max(0, value);
					value = Math.Min(7, value);
					fromColInfoIdx = Math.Max(0, num - 1);
				}
				SetColumn(i, null, null, value, null, null);
			}
		}

		public ColumnInfoRecord FindColumnInfo(int columnIndex)
		{
			int count = records.Count;
			for (int i = 0; i < count; i++)
			{
				ColumnInfoRecord colInfo = GetColInfo(i);
				if (colInfo.ContainsColumn(columnIndex))
				{
					return colInfo;
				}
			}
			return null;
		}

		private int FindColInfoIdx(int columnIx, int fromColInfoIdx)
		{
			if (columnIx < 0)
			{
				throw new ArgumentException("column parameter out of range: " + columnIx);
			}
			if (fromColInfoIdx < 0)
			{
				throw new ArgumentException("fromIdx parameter out of range: " + fromColInfoIdx);
			}
			for (int i = fromColInfoIdx; i < records.Count; i++)
			{
				ColumnInfoRecord colInfo = GetColInfo(i);
				if (colInfo.ContainsColumn(columnIx))
				{
					return i;
				}
				if (colInfo.FirstColumn > columnIx)
				{
					break;
				}
			}
			return -1;
		}

		public int GetOutlineLevel(int columnIndex)
		{
			return FindColumnInfo(columnIndex)?.OutlineLevel ?? 0;
		}
	}
	public class ConditionalFormattingTable : RecordAggregate
	{
		private IList _cfHeaders;

		public int Count => _cfHeaders.Count;

		public ConditionalFormattingTable()
		{
			_cfHeaders = new ArrayList();
		}

		public ConditionalFormattingTable(RecordStream rs)
		{
			IList list = new ArrayList();
			while (rs.PeekNextClass() == typeof(CFHeaderRecord))
			{
				list.Add(CFRecordsAggregate.CreateCFAggregate(rs));
			}
			_cfHeaders = list;
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			for (int i = 0; i < _cfHeaders.Count; i++)
			{
				CFRecordsAggregate cFRecordsAggregate = (CFRecordsAggregate)_cfHeaders[i];
				cFRecordsAggregate.VisitContainedRecords(rv);
			}
		}

		public int Add(CFRecordsAggregate cfAggregate)
		{
			_cfHeaders.Add(cfAggregate);
			return _cfHeaders.Count - 1;
		}

		public CFRecordsAggregate Get(int index)
		{
			CheckIndex(index);
			return (CFRecordsAggregate)_cfHeaders[index];
		}

		public void Remove(int index)
		{
			CheckIndex(index);
			_cfHeaders.RemoveAt(index);
		}

		private void CheckIndex(int index)
		{
			if (index < 0 || index >= _cfHeaders.Count)
			{
				throw new ArgumentException("Specified CF index " + index + " is outside the allowable range (0.." + (_cfHeaders.Count - 1) + ")");
			}
		}

		public void UpdateFormulasAfterCellShift(FormulaShifter shifter, int externSheetIndex)
		{
			for (int i = 0; i < _cfHeaders.Count; i++)
			{
				CFRecordsAggregate cFRecordsAggregate = (CFRecordsAggregate)_cfHeaders[i];
				if (!cFRecordsAggregate.UpdateFormulasAfterCellShift(shifter, externSheetIndex))
				{
					_cfHeaders.RemoveAt(i);
					i--;
				}
			}
		}
	}
	public class CustomViewSettingsRecordAggregate : RecordAggregate
	{
		private Record _begin;

		private Record _end;

		private List<RecordBase> _recs;

		private PageSettingsBlock _psBlock;

		public CustomViewSettingsRecordAggregate(RecordStream rs)
		{
			_begin = rs.GetNext();
			if (_begin.Sid != 426)
			{
				throw new InvalidOperationException("Bad begin record");
			}
			List<RecordBase> list = new List<RecordBase>();
			while (rs.PeekNextSid() != 427)
			{
				if (PageSettingsBlock.IsComponentRecord(rs.PeekNextSid()))
				{
					if (_psBlock != null)
					{
						throw new InvalidOperationException("Found more than one PageSettingsBlock in custom view Settings sub-stream");
					}
					_psBlock = new PageSettingsBlock(rs);
					list.Add(_psBlock);
				}
				else
				{
					list.Add(rs.GetNext());
				}
			}
			_recs = list;
			_end = rs.GetNext();
			if (_end.Sid != 427)
			{
				throw new InvalidOperationException("Bad custom view Settings end record");
			}
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			if (_recs.Count == 0)
			{
				return;
			}
			rv.VisitRecord(_begin);
			for (int i = 0; i < _recs.Count; i++)
			{
				RecordBase recordBase = _recs[i];
				if (recordBase is RecordAggregate)
				{
					((RecordAggregate)recordBase).VisitContainedRecords(rv);
				}
				else
				{
					rv.VisitRecord((Record)recordBase);
				}
			}
			rv.VisitRecord(_end);
		}

		public static bool IsBeginRecord(int sid)
		{
			return sid == 426;
		}

		public void Append(RecordBase r)
		{
			_recs.Add(r);
		}
	}
	public class DataValidityTable : RecordAggregate
	{
		private DVALRecord _headerRec;

		private IList _validationList;

		public DataValidityTable(RecordStream rs)
		{
			_headerRec = (DVALRecord)rs.GetNext();
			IList list = new ArrayList();
			while (rs.PeekNextClass() == typeof(DVRecord))
			{
				list.Add(rs.GetNext());
			}
			_validationList = list;
		}

		public DataValidityTable()
		{
			_headerRec = new DVALRecord();
			_validationList = new ArrayList();
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			if (_validationList.Count != 0)
			{
				rv.VisitRecord(_headerRec);
				for (int i = 0; i < _validationList.Count; i++)
				{
					rv.VisitRecord((Record)_validationList[i]);
				}
			}
		}

		public void AddDataValidation(DVRecord dvRecord)
		{
			_validationList.Add(dvRecord);
			_headerRec.DVRecNo = _validationList.Count;
		}
	}
}
