namespace NPOI.HSSF.Record.Aggregates
{
	[Serializable]
	public class FormulaRecordAggregate : RecordAggregate, CellValueRecordInterface, IComparable, ICloneable
	{
		public const short sid = -2000;

		private FormulaRecord _formulaRecord;

		private SharedValueManager _sharedValueManager;

		private StringRecord _stringRecord;

		[NonSerialized]
		private SharedFormulaRecord _sharedFormulaRecord;

		public bool IsPartOfArrayFormula
		{
			get
			{
				if (_sharedFormulaRecord != null)
				{
					return false;
				}
				CellReference expReference = _formulaRecord.Formula.ExpReference;
				ArrayRecord arrayRecord = ((expReference == null) ? null : _sharedValueManager.GetArrayRecord(expReference.Row, expReference.Col));
				return arrayRecord != null;
			}
		}

		public override int RecordSize => _formulaRecord.RecordSize + ((_stringRecord != null) ? _stringRecord.RecordSize : 0);

		public override short Sid => -2000;

		public FormulaRecord FormulaRecord
		{
			get
			{
				return _formulaRecord;
			}
			set
			{
				_formulaRecord = value;
			}
		}

		public StringRecord StringRecord
		{
			get
			{
				return _stringRecord;
			}
			set
			{
				_stringRecord = value;
			}
		}

		public short XFIndex
		{
			get
			{
				return _formulaRecord.XFIndex;
			}
			set
			{
				_formulaRecord.XFIndex = value;
			}
		}

		public int Column
		{
			get
			{
				return _formulaRecord.Column;
			}
			set
			{
				_formulaRecord.Column = value;
			}
		}

		public int Row
		{
			get
			{
				return _formulaRecord.Row;
			}
			set
			{
				_formulaRecord.Row = value;
			}
		}

		public string StringValue
		{
			get
			{
				if (_stringRecord == null)
				{
					return null;
				}
				return _stringRecord.String;
			}
		}

		public Ptg[] FormulaTokens
		{
			get
			{
				if (_sharedFormulaRecord != null)
				{
					return _sharedFormulaRecord.GetFormulaTokens(_formulaRecord);
				}
				CellReference expReference = _formulaRecord.Formula.ExpReference;
				if (expReference != null)
				{
					ArrayRecord arrayRecord = _sharedValueManager.GetArrayRecord(expReference.Row, expReference.Col);
					return arrayRecord.FormulaTokens;
				}
				return _formulaRecord.ParsedExpression;
			}
		}

		public FormulaRecordAggregate(FormulaRecord formulaRec, StringRecord stringRec, SharedValueManager svm)
		{
			if (svm == null)
			{
				throw new ArgumentException("sfm must not be null");
			}
			if (formulaRec.HasCachedResultString)
			{
				if (stringRec == null)
				{
					throw new RecordFormatException("Formula record flag is set but String record was not found");
				}
				_stringRecord = stringRec;
			}
			else
			{
				_stringRecord = null;
			}
			_formulaRecord = formulaRec;
			_sharedValueManager = svm;
			if (formulaRec.IsSharedFormula)
			{
				CellReference expReference = formulaRec.Formula.ExpReference;
				if (expReference == null)
				{
					HandleMissingSharedFormulaRecord(formulaRec);
				}
				else
				{
					_sharedFormulaRecord = svm.LinkSharedFormulaRecord(expReference, this);
				}
			}
		}

		public void NotifyFormulaChanging()
		{
			if (_sharedFormulaRecord != null)
			{
				_sharedValueManager.Unlink(_sharedFormulaRecord);
			}
		}

		public override int Serialize(int offset, byte[] data)
		{
			int num = offset;
			num += _formulaRecord.Serialize(num, data);
			if (_stringRecord != null)
			{
				num += _stringRecord.Serialize(num, data);
			}
			return num - offset;
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			rv.VisitRecord(_formulaRecord);
			Record recordForFirstCell = _sharedValueManager.GetRecordForFirstCell(this);
			if (recordForFirstCell != null)
			{
				rv.VisitRecord(recordForFirstCell);
			}
			if (_formulaRecord.HasCachedResultString && _stringRecord != null)
			{
				rv.VisitRecord(_stringRecord);
			}
		}

		private static void HandleMissingSharedFormulaRecord(FormulaRecord formula)
		{
			Ptg ptg = formula.ParsedExpression[0];
			if (ptg is ExpPtg)
			{
				throw new RecordFormatException("SharedFormulaRecord not found for FormulaRecord with (isSharedFormula=true)");
			}
			formula.IsSharedFormula = false;
		}

		public int CompareTo(object o)
		{
			return _formulaRecord.CompareTo(o);
		}

		public override bool Equals(object obj)
		{
			return _formulaRecord.Equals(obj);
		}

		public override int GetHashCode()
		{
			return _formulaRecord.GetHashCode();
		}

		public override string ToString()
		{
			return _formulaRecord.ToString();
		}

		public void SetCachedDoubleResult(double value)
		{
			_stringRecord = null;
			_formulaRecord.Value = value;
		}

		public void SetCachedStringResult(string value)
		{
			if (_stringRecord == null)
			{
				_stringRecord = new StringRecord();
			}
			_stringRecord.String = value;
			if (value.Length < 1)
			{
				_formulaRecord.SetCachedResultTypeEmptyString();
			}
			else
			{
				_formulaRecord.SetCachedResultTypeString();
			}
		}

		public void SetCachedBooleanResult(bool value)
		{
			_stringRecord = null;
			_formulaRecord.SetCachedResultBoolean(value);
		}

		public void SetCachedErrorResult(int errorCode)
		{
			_stringRecord = null;
			_formulaRecord.SetCachedResultErrorCode(errorCode);
		}

		public object Clone()
		{
			return this;
		}

		public void SetParsedExpression(Ptg[] ptgs)
		{
			NotifyFormulaChanging();
			_formulaRecord.ParsedExpression = ptgs;
		}

		public void UnlinkSharedFormula()
		{
			SharedFormulaRecord sharedFormulaRecord = _sharedFormulaRecord;
			if (sharedFormulaRecord == null)
			{
				throw new InvalidOperationException("Formula not linked to shared formula");
			}
			Ptg[] formulaTokens = sharedFormulaRecord.GetFormulaTokens(_formulaRecord);
			_formulaRecord.SetParsedExpression(formulaTokens);
			_formulaRecord.SetSharedFormula(flag: false);
			_sharedFormulaRecord = null;
		}

		public CellRangeAddress GetArrayFormulaRange()
		{
			if (_sharedFormulaRecord != null)
			{
				throw new InvalidOperationException("not an array formula cell.");
			}
			CellReference expReference = _formulaRecord.Formula.ExpReference;
			if (expReference == null)
			{
				throw new InvalidOperationException("not an array formula cell.");
			}
			ArrayRecord arrayRecord = _sharedValueManager.GetArrayRecord(expReference.Row, expReference.Col);
			if (arrayRecord == null)
			{
				throw new InvalidOperationException("ArrayRecord was not found for the locator " + expReference.FormatAsString());
			}
			CellRangeAddress8Bit range = arrayRecord.Range;
			return new CellRangeAddress(range.FirstRow, range.LastRow, range.FirstColumn, range.LastColumn);
		}

		public void SetArrayFormula(CellRangeAddress r, Ptg[] ptgs)
		{
			ArrayRecord ar = new ArrayRecord(Formula.Create(ptgs), new CellRangeAddress8Bit(r.FirstRow, r.LastRow, r.FirstColumn, r.LastColumn));
			_sharedValueManager.AddArrayRecord(ar);
		}

		public CellRangeAddress RemoveArrayFormula(int rowIndex, int columnIndex)
		{
			CellRangeAddress8Bit cellRangeAddress8Bit = _sharedValueManager.RemoveArrayFormula(rowIndex, columnIndex);
			_formulaRecord.ParsedExpression = null;
			return new CellRangeAddress(cellRangeAddress8Bit.FirstRow, cellRangeAddress8Bit.LastRow, cellRangeAddress8Bit.FirstColumn, cellRangeAddress8Bit.LastColumn);
		}
	}
	public class MergedCellsTable : RecordAggregate
	{
		private const int MAX_MERGED_REGIONS = 1027;

		private List<CellRangeAddress> _mergedRegions;

		public override int RecordSize
		{
			get
			{
				int count = _mergedRegions.Count;
				if (count < 1)
				{
					return 0;
				}
				int num = count / 1027;
				int numberOfRanges = count % 1027;
				return num * (4 + CellRangeAddressList.GetEncodedSize(1027)) + 4 + CellRangeAddressList.GetEncodedSize(numberOfRanges);
			}
		}

		public List<CellRangeAddress> MergedRegions => _mergedRegions;

		public int NumberOfMergedRegions => _mergedRegions.Count;

		public MergedCellsTable()
		{
			_mergedRegions = new List<CellRangeAddress>();
		}

		public void Read(RecordStream rs)
		{
			while (rs.PeekNextClass() == typeof(MergeCellsRecord))
			{
				MergeCellsRecord mergeCellsRecord = (MergeCellsRecord)rs.GetNext();
				int numAreas = mergeCellsRecord.NumAreas;
				for (int i = 0; i < numAreas; i++)
				{
					_mergedRegions.Add(mergeCellsRecord.GetAreaAt(i));
				}
			}
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			int count = _mergedRegions.Count;
			if (count >= 1)
			{
				int num = count / 1027;
				int num2 = count % 1027;
				CellRangeAddress[] regions = _mergedRegions.ToArray();
				for (int i = 0; i < num; i++)
				{
					int startIndex = i * 1027;
					rv.VisitRecord(new MergeCellsRecord(regions, startIndex, 1027));
				}
				if (num2 > 0)
				{
					int startIndex2 = num * 1027;
					rv.VisitRecord(new MergeCellsRecord(regions, startIndex2, num2));
				}
			}
		}

		public void AddRecords(MergeCellsRecord[] mcrs)
		{
			for (int i = 0; i < mcrs.Length; i++)
			{
				AddMergeCellsRecord(mcrs[i]);
			}
		}

		private void AddMergeCellsRecord(MergeCellsRecord mcr)
		{
			int numAreas = mcr.NumAreas;
			for (int i = 0; i < numAreas; i++)
			{
				_mergedRegions.Add(mcr.GetAreaAt(i));
			}
		}

		public CellRangeAddress Get(int index)
		{
			CheckIndex(index);
			return _mergedRegions[index];
		}

		public void Remove(int index)
		{
			CheckIndex(index);
			_mergedRegions.RemoveAt(index);
		}

		private void CheckIndex(int index)
		{
			if (index < 0 || index >= _mergedRegions.Count)
			{
				throw new ArgumentException("Specified CF index " + index + " is outside the allowable range (0.." + (_mergedRegions.Count - 1) + ")");
			}
		}

		public void AddArea(int rowFrom, int colFrom, int rowTo, int colTo)
		{
			_mergedRegions.Add(new CellRangeAddress(rowFrom, rowTo, colFrom, colTo));
		}
	}
	public class PageSettingsBlock : RecordAggregate
	{
		private class CustomRecordVisitor1 : RecordVisitor
		{
			private CustomViewSettingsRecordAggregate _cv;

			private HeaderFooterRecord _hf;

			private List<HeaderFooterRecord> _sviewHeaderFooters;

			private Dictionary<string, HeaderFooterRecord> _hfGuidMap;

			public CustomRecordVisitor1(CustomViewSettingsRecordAggregate cv, HeaderFooterRecord hf, List<HeaderFooterRecord> sviewHeaderFooter, Dictionary<string, HeaderFooterRecord> hfGuidMap)
			{
				_cv = cv;
				_hf = hf;
				_sviewHeaderFooters = sviewHeaderFooter;
				_hfGuidMap = hfGuidMap;
			}

			public void VisitRecord(Record r)
			{
				if (r.Sid == 426)
				{
					string key = HexDump.ToHex(((UserSViewBegin)r).Guid);
					HeaderFooterRecord headerFooterRecord = _hfGuidMap[key];
					if (headerFooterRecord != null)
					{
						_cv.Append(_hf);
						_sviewHeaderFooters.Remove(_hf);
					}
				}
			}
		}

		private PageBreakRecord _rowBreaksRecord;

		private PageBreakRecord _columnBreaksRecord;

		private HeaderRecord header;

		private FooterRecord footer;

		private HCenterRecord _hCenter;

		private VCenterRecord _vCenter;

		private LeftMarginRecord _leftMargin;

		private RightMarginRecord _rightMargin;

		private TopMarginRecord _topMargin;

		private BottomMarginRecord _bottomMargin;

		private PrintSetupRecord printSetup;

		private Record _bitmap;

		private HeaderFooterRecord _headerFooter;

		private List<HeaderFooterRecord> _sviewHeaderFooters = new List<HeaderFooterRecord>();

		private List<PLSAggregate> _plsRecords;

		private Record _printSize;

		private PageBreakRecord RowBreaksRecord
		{
			get
			{
				if (_rowBreaksRecord == null)
				{
					_rowBreaksRecord = new HorizontalPageBreakRecord();
				}
				return _rowBreaksRecord;
			}
		}

		private PageBreakRecord ColumnBreaksRecord
		{
			get
			{
				if (_columnBreaksRecord == null)
				{
					_columnBreaksRecord = new VerticalPageBreakRecord();
				}
				return _columnBreaksRecord;
			}
		}

		public HeaderRecord Header
		{
			get
			{
				return header;
			}
			set
			{
				header = value;
			}
		}

		public FooterRecord Footer
		{
			get
			{
				return footer;
			}
			set
			{
				footer = value;
			}
		}

		public PrintSetupRecord PrintSetup
		{
			get
			{
				return printSetup;
			}
			set
			{
				printSetup = value;
			}
		}

		public int[] RowBreaks => RowBreaksRecord.GetBreaks();

		public int NumRowBreaks => RowBreaksRecord.NumBreaks;

		public int[] ColumnBreaks => ColumnBreaksRecord.GetBreaks();

		public int NumColumnBreaks => ColumnBreaksRecord.NumBreaks;

		public VCenterRecord VCenter => _vCenter;

		public HCenterRecord HCenter => _hCenter;

		public PageSettingsBlock(RecordStream rs)
		{
			_plsRecords = new List<PLSAggregate>();
			while (ReadARecord(rs))
			{
			}
		}

		public PageSettingsBlock()
		{
			_plsRecords = new List<PLSAggregate>();
			_rowBreaksRecord = new HorizontalPageBreakRecord();
			_columnBreaksRecord = new VerticalPageBreakRecord();
			header = new HeaderRecord(string.Empty);
			footer = new FooterRecord(string.Empty);
			_hCenter = CreateHCenter();
			_vCenter = CreateVCenter();
			printSetup = CreatePrintSetup();
		}

		public static bool IsComponentRecord(int sid)
		{
			switch (sid)
			{
			case 20:
			case 21:
			case 26:
			case 27:
			case 38:
			case 39:
			case 40:
			case 41:
			case 51:
			case 77:
			case 131:
			case 132:
			case 161:
			case 233:
			case 2204:
				return true;
			default:
				return false;
			}
		}

		private bool ReadARecord(RecordStream rs)
		{
			switch (rs.PeekNextSid())
			{
			case 27:
				CheckNotPresent(_rowBreaksRecord);
				_rowBreaksRecord = (PageBreakRecord)rs.GetNext();
				break;
			case 26:
				CheckNotPresent(_columnBreaksRecord);
				_columnBreaksRecord = (PageBreakRecord)rs.GetNext();
				break;
			case 20:
				CheckNotPresent(header);
				header = (HeaderRecord)rs.GetNext();
				break;
			case 21:
				CheckNotPresent(footer);
				footer = (FooterRecord)rs.GetNext();
				break;
			case 131:
				CheckNotPresent(_hCenter);
				_hCenter = (HCenterRecord)rs.GetNext();
				break;
			case 132:
				CheckNotPresent(_vCenter);
				_vCenter = (VCenterRecord)rs.GetNext();
				break;
			case 38:
				CheckNotPresent(_leftMargin);
				_leftMargin = (LeftMarginRecord)rs.GetNext();
				break;
			case 39:
				CheckNotPresent(_rightMargin);
				_rightMargin = (RightMarginRecord)rs.GetNext();
				break;
			case 40:
				CheckNotPresent(_topMargin);
				_topMargin = (TopMarginRecord)rs.GetNext();
				break;
			case 41:
				CheckNotPresent(_bottomMargin);
				_bottomMargin = (BottomMarginRecord)rs.GetNext();
				break;
			case 77:
				_plsRecords.Add(new PLSAggregate(rs));
				break;
			case 161:
				CheckNotPresent(printSetup);
				printSetup = (PrintSetupRecord)rs.GetNext();
				break;
			case 233:
				CheckNotPresent(_bitmap);
				_bitmap = rs.GetNext();
				break;
			case 51:
				CheckNotPresent(_printSize);
				_printSize = rs.GetNext();
				break;
			case 2204:
			{
				HeaderFooterRecord headerFooterRecord = (HeaderFooterRecord)rs.GetNext();
				if (headerFooterRecord.IsCurrentSheet)
				{
					_headerFooter = headerFooterRecord;
				}
				else
				{
					_sviewHeaderFooters.Add(headerFooterRecord);
				}
				break;
			}
			default:
				return false;
			}
			return true;
		}

		private void CheckNotPresent(Record rec)
		{
			if (rec != null)
			{
				throw new RecordFormatException("Duplicate PageSettingsBlock record (sid=0x" + StringUtil.ToHexString(rec.Sid) + ")");
			}
		}

		public IEnumerator GetEnumerator()
		{
			return _plsRecords.GetEnumerator();
		}

		public void SetColumnBreak(int column, int fromRow, int toRow)
		{
			ColumnBreaksRecord.AddBreak(column, fromRow, toRow);
		}

		public void RemoveColumnBreak(int column)
		{
			ColumnBreaksRecord.RemoveBreak(column);
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			VisitIfPresent(_rowBreaksRecord, rv);
			VisitIfPresent(_columnBreaksRecord, rv);
			if (header == null)
			{
				rv.VisitRecord(new HeaderRecord(""));
			}
			else
			{
				rv.VisitRecord(header);
			}
			if (footer == null)
			{
				rv.VisitRecord(new FooterRecord(""));
			}
			else
			{
				rv.VisitRecord(footer);
			}
			VisitIfPresent(_hCenter, rv);
			VisitIfPresent(_vCenter, rv);
			VisitIfPresent(_leftMargin, rv);
			VisitIfPresent(_rightMargin, rv);
			VisitIfPresent(_topMargin, rv);
			VisitIfPresent(_bottomMargin, rv);
			foreach (PLSAggregate plsRecord in _plsRecords)
			{
				plsRecord.VisitContainedRecords(rv);
			}
			VisitIfPresent(printSetup, rv);
			VisitIfPresent(_printSize, rv);
			VisitIfPresent(_headerFooter, rv);
			VisitIfPresent(_bitmap, rv);
		}

		private static void VisitIfPresent(Record r, RecordVisitor rv)
		{
			if (r != null)
			{
				rv.VisitRecord(r);
			}
		}

		private static void VisitIfPresent(PageBreakRecord r, RecordVisitor rv)
		{
			if (r != null && !r.IsEmpty)
			{
				rv.VisitRecord(r);
			}
		}

		private static HCenterRecord CreateHCenter()
		{
			HCenterRecord hCenterRecord = new HCenterRecord();
			hCenterRecord.HCenter = false;
			return hCenterRecord;
		}

		private static VCenterRecord CreateVCenter()
		{
			VCenterRecord vCenterRecord = new VCenterRecord();
			vCenterRecord.VCenter = false;
			return vCenterRecord;
		}

		private static PrintSetupRecord CreatePrintSetup()
		{
			PrintSetupRecord printSetupRecord = new PrintSetupRecord();
			printSetupRecord.PaperSize = 1;
			printSetupRecord.Scale = 100;
			printSetupRecord.PageStart = 1;
			printSetupRecord.FitWidth = 1;
			printSetupRecord.FitHeight = 1;
			printSetupRecord.Options = 2;
			printSetupRecord.HResolution = 300;
			printSetupRecord.VResolution = 300;
			printSetupRecord.HeaderMargin = 0.5;
			printSetupRecord.FooterMargin = 0.5;
			printSetupRecord.Copies = 1;
			return printSetupRecord;
		}

		private IMargin GetMarginRec(MarginType margin)
		{
			return margin switch
			{
				MarginType.LeftMargin => _leftMargin, 
				MarginType.RightMargin => _rightMargin, 
				MarginType.TopMargin => _topMargin, 
				MarginType.BottomMargin => _bottomMargin, 
				_ => throw new InvalidOperationException("Unknown margin constant:  " + (short)margin), 
			};
		}

		public double GetMargin(MarginType margin)
		{
			return GetMarginRec(margin)?.Margin ?? (margin switch
			{
				MarginType.LeftMargin => 0.75, 
				MarginType.RightMargin => 0.75, 
				MarginType.TopMargin => 1.0, 
				MarginType.BottomMargin => 1.0, 
				_ => throw new InvalidOperationException("Unknown margin constant:  " + margin), 
			});
		}

		public void SetMargin(MarginType margin, double size)
		{
			IMargin margin2 = GetMarginRec(margin);
			if (margin2 == null)
			{
				switch (margin)
				{
				case MarginType.LeftMargin:
					_leftMargin = new LeftMarginRecord();
					margin2 = _leftMargin;
					break;
				case MarginType.RightMargin:
					_rightMargin = new RightMarginRecord();
					margin2 = _rightMargin;
					break;
				case MarginType.TopMargin:
					_topMargin = new TopMarginRecord();
					margin2 = _topMargin;
					break;
				case MarginType.BottomMargin:
					_bottomMargin = new BottomMarginRecord();
					margin2 = _bottomMargin;
					break;
				default:
					throw new InvalidOperationException("Unknown margin constant:  " + margin);
				}
			}
			margin2.Margin = size;
		}

		private static void ShiftBreaks(PageBreakRecord breaks, int start, int stop, int count)
		{
			IEnumerator breaksEnumerator = breaks.GetBreaksEnumerator();
			IList list = new ArrayList();
			while (breaksEnumerator.MoveNext())
			{
				PageBreakRecord.Break @break = (PageBreakRecord.Break)breaksEnumerator.Current;
				int main = @break.main;
				bool flag = main >= start;
				bool flag2 = main <= stop;
				if (flag && flag2)
				{
					list.Add(@break);
				}
			}
			breaksEnumerator = list.GetEnumerator();
			while (breaksEnumerator.MoveNext())
			{
				PageBreakRecord.Break break2 = (PageBreakRecord.Break)breaksEnumerator.Current;
				breaks.RemoveBreak(break2.main);
				breaks.AddBreak((short)(break2.main + count), break2.subFrom, break2.subTo);
			}
		}

