			Dictionary<string, HeaderFooterRecord> dictionary = new Dictionary<string, HeaderFooterRecord>();
			foreach (HeaderFooterRecord item in list)
			{
				string key = HexDump.ToHex(item.Guid);
				if (dictionary.ContainsKey(key))
				{
