	internal class PLSAggregate : RecordAggregate
	{
		private static ContinueRecord[] EMPTY_CONTINUE_RECORD_ARRAY = new ContinueRecord[0];

		private Record _pls;

		private ContinueRecord[] _plsContinues;

		public PLSAggregate(RecordStream rs)
		{
			_pls = rs.GetNext();
			if (rs.PeekNextSid() == 60)
			{
				List<ContinueRecord> list = new List<ContinueRecord>();
				while (rs.PeekNextSid() == 60)
				{
					list.Add((ContinueRecord)rs.GetNext());
				}
				_plsContinues = new ContinueRecord[list.Count];
				_plsContinues = list.ToArray();
			}
			else
			{
				_plsContinues = EMPTY_CONTINUE_RECORD_ARRAY;
			}
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			rv.VisitRecord(_pls);
			for (int i = 0; i < _plsContinues.Length; i++)
			{
				rv.VisitRecord(_plsContinues[i]);
			}
		}
	}
	public class PositionTrackingVisitor : RecordVisitor
	{
		private RecordVisitor _rv;

		private int _position;

		public int Position
		{
			get
			{
				return _position;
			}
			set
			{
				_position = value;
			}
		}

		public PositionTrackingVisitor(RecordVisitor rv, int initialPosition)
		{
			_rv = rv;
			_position = initialPosition;
		}

		public void VisitRecord(Record r)
		{
			_position += r.RecordSize;
			_rv.VisitRecord(r);
		}
	}
	public class RowRecordsAggregate : RecordAggregate
	{
		private int firstrow = -1;

		private int lastrow = -1;

		private SortedList _rowRecords;

		private ValueRecordsAggregate _valuesAgg;

		private List<Record> _unknownRecords;

		private SharedValueManager _sharedValueManager;

		private RowRecord[] _rowRecordValues;

		public int PhysicalNumberOfRows => _rowRecords.Count;

		public int FirstRowNum => firstrow;

		public int LastRowNum => lastrow;

		public int RowBlockCount
		{
			get
			{
				int num = _rowRecords.Count / 32;
				if (_rowRecords.Count % 32 != 0)
				{
					num++;
				}
				return num;
			}
		}

		public RowRecordsAggregate()
			: this(SharedValueManager.CreateEmpty())
		{
		}

		public CellValueRecordInterface[] GetValueRecords()
		{
			return _valuesAgg.GetValueRecords();
		}

		private RowRecordsAggregate(SharedValueManager svm)
		{
			_rowRecords = new SortedList();
			_valuesAgg = new ValueRecordsAggregate();
			_unknownRecords = new List<Record>();
			_sharedValueManager = svm;
		}

		private int VisitRowRecordsForBlock(int blockIndex, RecordVisitor rv)
		{
			int num = blockIndex * 32;
			int num2 = num + 32;
			IEnumerator enumerator = _rowRecords.Values.GetEnumerator();
			int i;
			for (i = 0; i < num; i++)
			{
				if (!enumerator.MoveNext())
				{
					break;
				}
			}
			int num3 = 0;
			while (enumerator.MoveNext() && i++ < num2)
			{
				Record record = (Record)enumerator.Current;
				num3 += record.RecordSize;
				rv.VisitRecord(record);
			}
			return num3;
		}

		public override void VisitContainedRecords(RecordVisitor rv)
		{
			PositionTrackingVisitor positionTrackingVisitor = new PositionTrackingVisitor(rv, 0);
			int rowBlockCount = RowBlockCount;
			for (int i = 0; i < rowBlockCount; i++)
			{
				int num = 0;
				int num2 = VisitRowRecordsForBlock(i, rv);
				num += num2;
				int startRowNumberForBlock = GetStartRowNumberForBlock(i);
				int endRowNumberForBlock = GetEndRowNumberForBlock(i);
				DBCellRecord dBCellRecord = new DBCellRecord();
				int num3 = num2 - 20;
				for (int j = startRowNumberForBlock; j <= endRowNumberForBlock; j++)
				{
					if (_valuesAgg.RowHasCells(j))
					{
						positionTrackingVisitor.Position = 0;
						_valuesAgg.VisitCellsForRow(j, positionTrackingVisitor);
						int position = positionTrackingVisitor.Position;
						num += position;
						dBCellRecord.AddCellOffset((short)num3);
						num3 = position;
					}
				}
				dBCellRecord.RowOffset = num;
				rv.VisitRecord(dBCellRecord);
			}
			for (int k = 0; k < _unknownRecords.Count; k++)
			{
				rv.VisitRecord(_unknownRecords[k]);
			}
		}

		public RowRecordsAggregate(RecordStream rs, SharedValueManager svm)
			: this(svm)
		{
			while (rs.HasNext())
			{
				Record next = rs.GetNext();
				switch (next.Sid)
				{
				case 520:
					InsertRow((RowRecord)next);
					continue;
				case 81:
					AddUnknownRecord(next);
					continue;
				case 215:
					continue;
				}
				if (next is UnknownRecord)
				{
					AddUnknownRecord((UnknownRecord)next);
					while (rs.PeekNextSid() == 60)
					{
						AddUnknownRecord(rs.GetNext());
					}
				}
				else if (next is MulBlankRecord)
				{
					_valuesAgg.AddMultipleBlanks((MulBlankRecord)next);
				}
				else if (!(next is CellValueRecordInterface))
				{
					if (next.Sid != 4197)
					{
						throw new InvalidOperationException("Unexpected record type (" + next.GetType().Name + ")");
					}
					AddUnknownRecord(next);
				}
				else
				{
					_valuesAgg.Construct((CellValueRecordInterface)next, rs, svm);
				}
			}
		}

		private void AddUnknownRecord(Record rec)
		{
			_unknownRecords.Add(rec);
		}

		public void InsertRow(RowRecord row)
		{
			_rowRecords[row.RowNumber] = row;
			_rowRecordValues = null;
			if (row.RowNumber < firstrow || firstrow == -1)
			{
				firstrow = row.RowNumber;
			}
			if (row.RowNumber > lastrow || lastrow == -1)
			{
				lastrow = row.RowNumber;
			}
		}

		public void RemoveRow(RowRecord row)
		{
			int rowNumber = row.RowNumber;
			_valuesAgg.RemoveAllCellsValuesForRow(rowNumber);
			int num = rowNumber;
			RowRecord rowRecord = (RowRecord)_rowRecords[num];
			_rowRecords.Remove(num);
			if (rowRecord == null)
			{
				throw new Exception("Invalid row index (" + num + ")");
			}
			if (row != rowRecord)
			{
				_rowRecords[num] = rowRecord;
				throw new Exception("Attempt to remove row that does not belong to this sheet");
			}
			_rowRecordValues = null;
		}

		public void InsertCell(CellValueRecordInterface cvRec)
		{
			_valuesAgg.InsertCell(cvRec);
		}

		public void RemoveCell(CellValueRecordInterface cvRec)
		{
			if (cvRec is FormulaRecordAggregate)
			{
				((FormulaRecordAggregate)cvRec).NotifyFormulaChanging();
			}
			_valuesAgg.RemoveCell(cvRec);
		}

		public RowRecord GetRow(int rowIndex)
		{
			if (rowIndex < 0 || rowIndex > 65535)
			{
				throw new ArgumentException("The row number must be between 0 and 65535");
			}
			return (RowRecord)_rowRecords[rowIndex];
		}

		public FormulaRecordAggregate CreateFormula(int row, int col)
		{
			FormulaRecord formulaRecord = new FormulaRecord();
			formulaRecord.Row = row;
			formulaRecord.Column = (short)col;
			return new FormulaRecordAggregate(formulaRecord, null, _sharedValueManager);
		}

		public int GetRowBlockSize(int block)
		{
			return 20 * GetRowCountForBlock(block);
		}

		public int GetRowCountForBlock(int block)
		{
			int num = block * 32;
			int num2 = num + 32 - 1;
			if (num2 >= _rowRecords.Count)
			{
				num2 = _rowRecords.Count - 1;
			}
			return num2 - num + 1;
		}

		public int GetStartRowNumberForBlock(int block)
		{
			int num = block * 32;
			if (_rowRecordValues == null)
			{
				_rowRecordValues = new RowRecord[_rowRecords.Count];
				_rowRecords.Values.CopyTo(_rowRecordValues, 0);
			}
			try
			{
				return _rowRecordValues[num].RowNumber;
			}
			catch (IndexOutOfRangeException)
			{
				throw new Exception("Did not find start row for block " + block);
			}
		}

		public int GetEndRowNumberForBlock(int block)
		{
			int num = (block + 1) * 32 - 1;
			if (num >= _rowRecords.Count)
			{
				num = _rowRecords.Count - 1;
			}
			if (_rowRecordValues == null)
			{
				_rowRecordValues = new RowRecord[_rowRecords.Count];
				_rowRecords.Values.CopyTo(_rowRecordValues, 0);
			}
			try
			{
				return _rowRecordValues[num].RowNumber;
			}
			catch (IndexOutOfRangeException)
			{
				throw new Exception("Did not find end row for block " + block);
			}
		}

		public IEnumerator GetEnumerator()
		{
			return _rowRecords.Values.GetEnumerator();
		}

		public int FindStartOfRowOutlineGroup(int row)
		{
			RowRecord row2 = GetRow(row);
			int outlineLevel = row2.OutlineLevel;
			int num = row;
			while (GetRow(num) != null)
			{
				row2 = GetRow(num);
				if (row2.OutlineLevel < outlineLevel)
				{
					return num + 1;
				}
				num--;
			}
			return num + 1;
		}

		public int FindEndOfRowOutlineGroup(int row)
		{
			int outlineLevel = GetRow(row).OutlineLevel;
			int i;
			for (i = row; i < LastRowNum && GetRow(i) != null && GetRow(i).OutlineLevel >= outlineLevel; i++)
			{
			}
			return i - 1;
		}

		public int WriteHidden(RowRecord rowRecord, int row, bool hidden)
		{
			int outlineLevel = rowRecord.OutlineLevel;
			while (rowRecord != null && GetRow(row).OutlineLevel >= outlineLevel)
			{
				rowRecord.ZeroHeight = hidden;
				row++;
				rowRecord = GetRow(row);
			}
			return row - 1;
		}

		public void CollapseRow(int rowNumber)
		{
			int num = FindStartOfRowOutlineGroup(rowNumber);
			RowRecord row = GetRow(num);
			int num2 = WriteHidden(row, num, hidden: true);
			if (GetRow(num2 + 1) != null)
			{
				GetRow(num2 + 1).Colapsed = true;
				return;
			}
			RowRecord rowRecord = CreateRow(num2 + 1);
			rowRecord.Colapsed = true;
			InsertRow(rowRecord);
		}

		public DimensionsRecord CreateDimensions()
		{
			DimensionsRecord dimensionsRecord = new DimensionsRecord();
			dimensionsRecord.FirstRow = firstrow;
			dimensionsRecord.LastRow = lastrow;
			dimensionsRecord.FirstCol = _valuesAgg.FirstCellNum;
			dimensionsRecord.LastCol = _valuesAgg.LastCellNum;
			return dimensionsRecord;
		}

		public static RowRecord CreateRow(int rowNumber)
		{
			return new RowRecord(rowNumber);
		}

		public IndexRecord CreateIndexRecord(int indexRecordOffset, int sizeOfInitialSheetRecords, int offsetDefaultColWidth)
		{
			IndexRecord indexRecord = new IndexRecord();
			indexRecord.FirstRow = firstrow;
			indexRecord.LastRowAdd1 = lastrow + 1;
			int rowBlockCount = RowBlockCount;
			int recordSizeForBlockCount = IndexRecord.GetRecordSizeForBlockCount(rowBlockCount);
			int num = indexRecordOffset + recordSizeForBlockCount + sizeOfInitialSheetRecords;
			for (int i = 0; i < rowBlockCount; i++)
			{
				num += GetRowBlockSize(i);
				num += _valuesAgg.GetRowCellBlockSize(GetStartRowNumberForBlock(i), GetEndRowNumberForBlock(i));
				indexRecord.AddDbcell(num);
				num += 8 + GetRowCountForBlock(i) * 2;
			}
			return indexRecord;
		}

		public bool IsRowGroupCollapsed(int row)
		{
			int rowIndex = FindEndOfRowOutlineGroup(row) + 1;
			if (GetRow(rowIndex) == null)
			{
				return false;
			}
			return GetRow(rowIndex).Colapsed;
		}

		public void ExpandRow(int rowNumber)
		{
			if (rowNumber == -1 || !IsRowGroupCollapsed(rowNumber))
			{
				return;
			}
			int num = FindStartOfRowOutlineGroup(rowNumber);
			RowRecord row = GetRow(num);
			int num2 = FindEndOfRowOutlineGroup(rowNumber);
			if (!IsRowGroupHiddenByParent(rowNumber))
			{
				for (int i = num; i <= num2; i++)
				{
					if (row.OutlineLevel == GetRow(i).OutlineLevel)
					{
						GetRow(i).ZeroHeight = false;
					}
					else if (!IsRowGroupCollapsed(i))
					{
						GetRow(i).ZeroHeight = false;
					}
				}
			}
			GetRow(num2 + 1).Colapsed = false;
		}

		public void UpdateFormulasAfterRowShift(FormulaShifter formulaShifter, int currentExternSheetIndex)
		{
			_valuesAgg.UpdateFormulasAfterRowShift(formulaShifter, currentExternSheetIndex);
		}

		public bool IsRowGroupHiddenByParent(int row)
		{
			int num = FindEndOfRowOutlineGroup(row);
			int num2;
			bool result;
			if (GetRow(num + 1) == null)
			{
				num2 = 0;
				result = false;
			}
			else
			{
				num2 = GetRow(num + 1).OutlineLevel;
				result = GetRow(num + 1).ZeroHeight;
			}
			int num3 = FindStartOfRowOutlineGroup(row);
			int num4;
			bool result2;
			if (num3 - 1 < 0 || GetRow(num3 - 1) == null)
			{
				num4 = 0;
				result2 = false;
			}
			else
			{
				num4 = GetRow(num3 - 1).OutlineLevel;
				result2 = GetRow(num3 - 1).ZeroHeight;
			}
			if (num2 > num4)
			{
				return result;
			}
			return result2;
		}
	}
	[Serializable]
	public class SharedValueManager
	{
		private class SharedFormulaGroup
		{
			private SharedFormulaRecord _sfr;

			private FormulaRecordAggregate[] _frAggs;

			private int _numberOfFormulas;

			private CellReference _firstCell;

			internal CellReference FirstCell => _firstCell;

			public SharedFormulaRecord SFR => _sfr;

			public SharedFormulaGroup(SharedFormulaRecord sfr, CellReference firstCell)
			{
				if (!sfr.IsInRange(firstCell.Row, firstCell.Col))
				{
					throw new ArgumentException("First formula cell " + firstCell.FormatAsString() + " is not shared formula range " + sfr.Range.ToString() + ".");
				}
				_sfr = sfr;
				_firstCell = firstCell;
				int num = sfr.LastColumn - sfr.FirstColumn + 1;
				int num2 = sfr.LastRow - sfr.FirstRow + 1;
				_frAggs = new FormulaRecordAggregate[num * num2];
				_numberOfFormulas = 0;
			}

			public void Add(FormulaRecordAggregate agg)
			{
				if (_numberOfFormulas == 0 && (_firstCell.Row != agg.Row || _firstCell.Col != agg.Column))
				{
					throw new InvalidOperationException("shared formula coding error");
				}
				if (_numberOfFormulas >= _frAggs.Length)
				{
					throw new Exception("Too many formula records for shared formula group");
				}
				_frAggs[_numberOfFormulas++] = agg;
			}

			public void UnlinkSharedFormulas()
			{
				for (int i = 0; i < _numberOfFormulas; i++)
				{
					_frAggs[i].UnlinkSharedFormula();
				}
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder(64);
				stringBuilder.Append(GetType().Name).Append(" [");
				stringBuilder.Append(_sfr.Range.ToString());
				stringBuilder.Append("]");
				return stringBuilder.ToString();
			}

			public bool IsFirstCell(int row, int column)
			{
				if (_firstCell.Row == row)
				{
					return _firstCell.Col == column;
				}
				return false;
			}
		}

		private class SharedFormulaGroupComparator : Comparer<SharedFormulaGroup>
		{
			public override int Compare(SharedFormulaGroup a, SharedFormulaGroup b)
			{
				CellRangeAddress8Bit range = a.SFR.Range;
				CellRangeAddress8Bit range2 = b.SFR.Range;
				int num = range.FirstRow - range2.FirstRow;
				if (num != 0)
				{
					return num;
				}
				num = range.FirstColumn - range2.FirstColumn;
				if (num != 0)
				{
					return num;
				}
				return 0;
			}
		}

		public static readonly SharedValueManager EMPTY = new SharedValueManager(new SharedFormulaRecord[0], new CellReference[0], new List<ArrayRecord>(), new List<TableRecord>());

		private List<ArrayRecord> _arrayRecords;

		private List<TableRecord> _tableRecords;

		private Dictionary<SharedFormulaRecord, SharedFormulaGroup> _groupsBySharedFormulaRecord;

		[NonSerialized]
		private Dictionary<int, SharedFormulaGroup> _groupsCache;

		[NonSerialized]
		private SharedFormulaGroupComparator SVGComparator = new SharedFormulaGroupComparator();

		private SharedValueManager(SharedFormulaRecord[] sharedFormulaRecords, CellReference[] firstCells, List<ArrayRecord> arrayRecords, List<TableRecord> tableRecords)
		{
			int num = sharedFormulaRecords.Length;
			if (num != firstCells.Length)
			{
				throw new ArgumentException("array sizes don't match: " + num + "!=" + firstCells.Length + ".");
			}
			_arrayRecords = new List<ArrayRecord>();
			_arrayRecords.AddRange(arrayRecords);
			_tableRecords = tableRecords;
			Dictionary<SharedFormulaRecord, SharedFormulaGroup> dictionary = new Dictionary<SharedFormulaRecord, SharedFormulaGroup>(num * 3 / 2);
			for (int i = 0; i < num; i++)
			{
				SharedFormulaRecord sharedFormulaRecord = sharedFormulaRecords[i];
				dictionary[sharedFormulaRecord] = new SharedFormulaGroup(sharedFormulaRecord, firstCells[i]);
			}
			_groupsBySharedFormulaRecord = dictionary;
		}

		public static SharedValueManager CreateEmpty()
		{
			return new SharedValueManager(new SharedFormulaRecord[0], new CellReference[0], new List<ArrayRecord>(), new List<TableRecord>());
		}

		public static SharedValueManager Create(SharedFormulaRecord[] sharedFormulaRecords, CellReference[] firstCells, List<ArrayRecord> arrayRecords, List<TableRecord> tableRecords)
		{
			if (sharedFormulaRecords.Length + firstCells.Length + arrayRecords.Count + tableRecords.Count < 1)
			{
				return EMPTY;
			}
			return new SharedValueManager(sharedFormulaRecords, firstCells, arrayRecords, tableRecords);
		}

		public SharedFormulaRecord LinkSharedFormulaRecord(CellReference firstCell, FormulaRecordAggregate agg)
		{
			SharedFormulaGroup sharedFormulaGroup = FindFormulaGroupForCell(firstCell);
			if (sharedFormulaGroup == null)
			{
				throw new RuntimeException("Failed to find a matching shared formula record");
			}
			sharedFormulaGroup.Add(agg);
			return sharedFormulaGroup.SFR;
		}

		private SharedFormulaGroup FindFormulaGroupForCell(CellReference cellRef)
		{
			if (_groupsCache == null)
			{
				_groupsCache = new Dictionary<int, SharedFormulaGroup>(_groupsBySharedFormulaRecord.Count);
				foreach (SharedFormulaGroup value in _groupsBySharedFormulaRecord.Values)
				{
					_groupsCache.Add(GetKeyForCache(value.FirstCell), value);
				}
			}
			int keyForCache = GetKeyForCache(cellRef);
			SharedFormulaGroup result = null;
			if (_groupsCache.ContainsKey(keyForCache))
			{
				result = _groupsCache[keyForCache];
			}
			return result;
		}

		private int GetKeyForCache(CellReference cellRef)
		{
			return (cellRef.Col + 1 << 16) | cellRef.Row;
		}

		public SharedValueRecordBase GetRecordForFirstCell(FormulaRecordAggregate agg)
		{
			CellReference expReference = agg.FormulaRecord.Formula.ExpReference;
			if (expReference == null)
			{
				return null;
			}
			int row = expReference.Row;
			int col = expReference.Col;
			if (agg.Row != row || agg.Column != col)
			{
				return null;
			}
			if (_groupsBySharedFormulaRecord.Count != 0)
			{
				SharedFormulaGroup sharedFormulaGroup = FindFormulaGroupForCell(expReference);
				if (sharedFormulaGroup != null)
				{
					return sharedFormulaGroup.SFR;
				}
			}
			for (int i = 0; i < _tableRecords.Count; i++)
			{
				TableRecord tableRecord = _tableRecords[i];
				if (tableRecord.IsFirstCell(row, col))
				{
					return tableRecord;
				}
			}
			foreach (ArrayRecord arrayRecord in _arrayRecords)
			{
				if (arrayRecord.IsFirstCell(row, col))
				{
					return arrayRecord;
				}
			}
			return null;
		}

		public void Unlink(SharedFormulaRecord sharedFormulaRecord)
		{
			SharedFormulaGroup sharedFormulaGroup = _groupsBySharedFormulaRecord[sharedFormulaRecord];
			_groupsBySharedFormulaRecord.Remove(sharedFormulaRecord);
			_groupsCache = null;
			if (sharedFormulaGroup == null)
			{
				throw new InvalidOperationException("Failed to find formulas for shared formula");
			}
			sharedFormulaGroup.UnlinkSharedFormulas();
		}

		public void AddArrayRecord(ArrayRecord ar)
		{
			_arrayRecords.Add(ar);
		}

		public CellRangeAddress8Bit RemoveArrayFormula(int rowIndex, int columnIndex)
		{
			foreach (ArrayRecord arrayRecord in _arrayRecords)
			{
				if (arrayRecord.IsInRange(rowIndex, columnIndex))
				{
					_arrayRecords.Remove(arrayRecord);
					return arrayRecord.Range;
				}
			}
			string text = new CellReference(rowIndex, columnIndex, pAbsRow: false, pAbsCol: false).FormatAsString();
			throw new ArgumentException("Specified cell " + text + " is not part of an array formula.");
		}

		public ArrayRecord GetArrayRecord(int firstRow, int firstColumn)
		{
			foreach (ArrayRecord arrayRecord in _arrayRecords)
			{
				if (arrayRecord.IsFirstCell(firstRow, firstColumn))
				{
					return arrayRecord;
				}
			}
			return null;
		}
	}
	public class ValueRecordsAggregate
	{
		private class MyEnumerator : IEnumerator
		{
			private short nextColumn = -1;

			private int nextRow;

			private int lastRow;

			private CellValueRecordInterface[][] records;

			public object Current => records[nextRow][nextColumn];

			public MyEnumerator(ref CellValueRecordInterface[][] _records)
			{
				records = _records;
				nextRow = 0;
				lastRow = _records.Length - 1;
			}

			public MyEnumerator(ref CellValueRecordInterface[][] _records, int firstRow, int lastRow)
			{
				records = _records;
				nextRow = firstRow;
				this.lastRow = lastRow;
			}

			public bool MoveNext()
			{
				FindNext();
				return nextRow <= lastRow;
			}

			public void Remove()
			{
				throw new InvalidOperationException("gibt's noch nicht");
			}

			private void FindNext()
			{
				nextColumn++;
				while (nextRow <= lastRow)
				{
					CellValueRecordInterface[] array = ((nextRow < records.Length) ? records[nextRow] : null);
					if (array == null)
					{
						nextColumn = 0;
					}
					else
					{
						while (nextColumn < array.Length)
						{
							if (array[nextColumn] != null)
							{
								return;
							}
							nextColumn++;
						}
						nextColumn = 0;
					}
					nextRow++;
				}
			}

			public void Reset()
			{
				nextColumn = -1;
				nextRow = 0;
			}
		}

		private const int MAX_ROW_INDEX = 65535;

		private const int INDEX_NOT_SET = -1;

		public const short sid = -1001;

		private int firstcell = -1;

		private int lastcell = -1;

		private CellValueRecordInterface[][] records;

		public int PhysicalNumberOfCells
		{
			get
			{
				int num = 0;
				for (int i = 0; i < records.Length; i++)
				{
					CellValueRecordInterface[] array = records[i];
					if (array == null)
					{
						continue;
					}
					for (short num2 = 0; num2 < array.Length; num2++)
					{
						if (array[num2] != null)
						{
							num++;
						}
					}
				}
				return num;
			}
		}

		public int FirstCellNum => firstcell;

		public int LastCellNum => lastcell;

		public ValueRecordsAggregate()
			: this(-1, -1, new CellValueRecordInterface[30][])
		{
		}

		private ValueRecordsAggregate(int firstCellIx, int lastCellIx, CellValueRecordInterface[][] pRecords)
		{
			firstcell = firstCellIx;
			lastcell = lastCellIx;
			records = pRecords;
		}

		public void InsertCell(CellValueRecordInterface cell)
		{
			int column = cell.Column;
			int row = cell.Row;
			if (row >= records.Length)
			{
				CellValueRecordInterface[][] array = records;
				int num = array.Length * 2;
				if (num < row + 1)
				{
					num = row + 1;
				}
				records = new CellValueRecordInterface[num][];
				System.Array.Copy(array, 0, records, 0, array.Length);
			}
			object obj = records[row];
			if (obj == null)
			{
				int num2 = column + 1;
				if (num2 < 10)
				{
					num2 = 10;
				}
				obj = new CellValueRecordInterface[num2];
				records[row] = (CellValueRecordInterface[])obj;
			}
			CellValueRecordInterface[] array2 = (CellValueRecordInterface[])obj;
			if (column >= array2.Length)
			{
				CellValueRecordInterface[] array3 = array2;
				int num3 = array3.Length * 2;
				if (num3 < column + 1)
				{
					num3 = column + 1;
				}
				array2 = new CellValueRecordInterface[num3];
				System.Array.Copy(array3, 0, array2, 0, array3.Length);
				records[row] = array2;
			}
			array2[column] = cell;
			if (column < firstcell || firstcell == -1)
			{
				firstcell = column;
			}
			if (column > lastcell || lastcell == -1)
			{
				lastcell = column;
			}
		}

		public void RemoveCell(CellValueRecordInterface cell)
		{
			if (cell == null)
			{
				throw new ArgumentException("cell must not be null");
			}
			int row = cell.Row;
			if (row >= records.Length)
			{
				throw new Exception("cell row is out of range");
			}
			CellValueRecordInterface[] array = records[row];
			if (array == null)
			{
				throw new Exception("cell row is already empty");
			}
			int column = cell.Column;
			if (column >= array.Length)
			{
				throw new Exception("cell column is out of range");
			}
			array[column] = null;
		}

		public void RemoveAllCellsValuesForRow(int rowIndex)
		{
			if (rowIndex < 0 || rowIndex > 65535)
			{
				throw new ArgumentException("Specified rowIndex " + rowIndex + " is outside the allowable range (0.." + 65535 + ")");
			}
			if (rowIndex < records.Length)
			{
				records[rowIndex] = null;
			}
		}

		public CellValueRecordInterface[] GetValueRecords()
		{
			ArrayList arrayList = new ArrayList();
			for (int i = 0; i < records.Length; i++)
			{
				CellValueRecordInterface[] array = records[i];
				if (array == null)
				{
					continue;
				}
				foreach (CellValueRecordInterface cellValueRecordInterface in array)
				{
					if (cellValueRecordInterface != null)
					{
						arrayList.Add(cellValueRecordInterface);
					}
				}
			}
			return (CellValueRecordInterface[])arrayList.ToArray(typeof(CellValueRecordInterface));
		}

		public void AddMultipleBlanks(MulBlankRecord mbr)
		{
			for (int i = 0; i < mbr.NumColumns; i++)
			{
				BlankRecord blankRecord = new BlankRecord();
				blankRecord.Column = i + mbr.FirstColumn;
				blankRecord.Row = mbr.Row;
				blankRecord.XFIndex = mbr.GetXFAt(i);
				InsertCell(blankRecord);
			}
		}

		private MulBlankRecord CreateMBR(CellValueRecordInterface[] cellValues, int startIx, int nBlank)
		{
			short[] array = new short[nBlank];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = ((BlankRecord)cellValues[startIx + i]).XFIndex;
			}
			int row = cellValues[startIx].Row;
			return new MulBlankRecord(row, startIx, array);
		}

		public void Construct(CellValueRecordInterface rec, RecordStream rs, SharedValueManager sfh)
		{
			if (rec is FormulaRecord)
			{
				FormulaRecord formulaRec = (FormulaRecord)rec;
				StringRecord stringRecord = null;
				Type type = rs.PeekNextClass();
				stringRecord = ((!(type == typeof(StringRecord))) ? null : ((StringRecord)rs.GetNext()));
				InsertCell(new FormulaRecordAggregate(formulaRec, stringRecord, sfh));
			}
			else
			{
				InsertCell(rec);
			}
		}

		private static void HandleMissingSharedFormulaRecord(FormulaRecord formula)
		{
		}

		public int GetRowCellBlockSize(int startRow, int endRow)
		{
			MyEnumerator myEnumerator = new MyEnumerator(ref records, startRow, endRow);
			int num = 0;
			while (myEnumerator.MoveNext())
			{
				CellValueRecordInterface cellValueRecordInterface = (CellValueRecordInterface)myEnumerator.Current;
				int row = cellValueRecordInterface.Row;
				if (row > endRow)
				{
					break;
				}
				if (row >= startRow && row <= endRow)
				{
					num += ((RecordBase)cellValueRecordInterface).RecordSize;
				}
			}
			return num;
		}

		public bool RowHasCells(int row)
		{
			if (row > records.Length - 1)
			{
				return false;
			}
			CellValueRecordInterface[] array = records[row];
			if (array == null)
			{
				return false;
			}
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] != null)
				{
					return true;
				}
			}
			return false;
		}

		public void UpdateFormulasAfterRowShift(FormulaShifter shifter, int currentExternSheetIndex)
		{
			for (int i = 0; i < records.Length; i++)
			{
				CellValueRecordInterface[] array = records[i];
				if (array == null)
				{
					continue;
				}
				foreach (CellValueRecordInterface cellValueRecordInterface in array)
				{
					if (cellValueRecordInterface is FormulaRecordAggregate)
					{
						FormulaRecordAggregate formulaRecordAggregate = (FormulaRecordAggregate)cellValueRecordInterface;
						Ptg[] formulaTokens = formulaRecordAggregate.FormulaTokens;
						_ = ((FormulaRecordAggregate)cellValueRecordInterface).FormulaRecord.ParsedExpression;
						if (shifter.AdjustFormula(formulaTokens, currentExternSheetIndex))
						{
							formulaRecordAggregate.SetParsedExpression(formulaTokens);
						}
					}
				}
			}
		}

		public void VisitCellsForRow(int rowIndex, RecordVisitor rv)
		{
			CellValueRecordInterface[] array = records[rowIndex];
			if (array == null)
			{
				throw new ArgumentException("Row [" + rowIndex + "] is empty");
			}
			for (int i = 0; i < array.Length; i++)
			{
				RecordBase recordBase = (RecordBase)array[i];
				if (recordBase != null)
				{
					int num = CountBlanks(array, i);
					if (num > 1)
					{
						rv.VisitRecord(CreateMBR(array, i, num));
						i += num - 1;
					}
					else if (recordBase is RecordAggregate)
					{
						RecordAggregate recordAggregate = (RecordAggregate)recordBase;
						recordAggregate.VisitContainedRecords(rv);
					}
					else
					{
						rv.VisitRecord((Record)recordBase);
					}
				}
			}
		}

		private static int CountBlanks(CellValueRecordInterface[] rowCellValues, int startIx)
		{
			int i;
			for (i = startIx; i < rowCellValues.Length; i++)
			{
				CellValueRecordInterface cellValueRecordInterface = rowCellValues[i];
				if (!(cellValueRecordInterface is BlankRecord))
				{
					break;
				}
			}
			return i - startIx;
		}

		public int SerializeCellRow(int row, int offset, byte[] data)
		{
			MyEnumerator myEnumerator = new MyEnumerator(ref records, row, row);
			int num = offset;
			while (myEnumerator.MoveNext())
			{
				CellValueRecordInterface cellValueRecordInterface = (CellValueRecordInterface)myEnumerator.Current;
				if (cellValueRecordInterface.Row != row)
				{
					break;
				}
				num += ((RecordBase)cellValueRecordInterface).Serialize(num, data);
			}
			return num - offset;
		}

		public IEnumerator GetEnumerator()
		{
			return new MyEnumerator(ref records);
		}
	}
}
namespace NPOI.HSSF.Record
{
	public abstract class SharedValueRecordBase : StandardRecord
	{
		private CellRangeAddress8Bit _range;

		public CellRangeAddress8Bit Range => _range;

		public virtual int FirstRow => _range.FirstRow;

		public virtual int LastRow => _range.LastRow;

		public virtual int FirstColumn => (short)_range.FirstColumn;

		public virtual int LastColumn => (short)_range.LastColumn;

		protected override int DataSize => 6 + ExtraDataSize;

		protected abstract int ExtraDataSize { get; }

		protected SharedValueRecordBase(CellRangeAddress8Bit range)
		{
			_range = range;
		}

		protected SharedValueRecordBase()
			: this(new CellRangeAddress8Bit(0, 0, 0, 0))
		{
		}

		public SharedValueRecordBase(RecordInputStream in1)
		{
			_range = new CellRangeAddress8Bit(in1);
		}

		protected abstract void SerializeExtraData(ILittleEndianOutput out1);

		public override void Serialize(ILittleEndianOutput out1)
		{
			_range.Serialize(out1);
			SerializeExtraData(out1);
		}

		public bool IsInRange(int rowIx, int colIx)
		{
			CellRangeAddress8Bit range = _range;
			if (range.FirstRow <= rowIx && range.LastRow >= rowIx && range.FirstColumn <= colIx)
			{
				return range.LastColumn >= colIx;
			}
			return false;
		}

		public bool IsFirstCell(int rowIx, int colIx)
		{
			CellRangeAddress8Bit range = Range;
			if (range.FirstRow == rowIx)
			{
				return range.FirstColumn == colIx;
			}
			return false;
		}
	}
	public class ArrayRecord : SharedValueRecordBase
	{
		public const short sid = 545;

		private const int OPT_ALWAYS_RECALCULATE = 1;

		private const int OPT_CALCULATE_ON_OPEN = 2;

		private int _options;

		private int _field3notUsed;

		private Formula _formula;

		public bool IsAlwaysRecalculate => (_options & 1) != 0;

		public bool IsCalculateOnOpen => (_options & 2) != 0;

		public Ptg[] FormulaTokens => _formula.Tokens;

		protected override int ExtraDataSize => 6 + _formula.EncodedSize;

		public override short Sid => 545;

		public ArrayRecord(RecordInputStream in1)
			: base(in1)
		{
			_options = in1.ReadUShort();
			_field3notUsed = in1.ReadInt();
			int encodedTokenLen = in1.ReadUShort();
			int totalEncodedLen = in1.Available();
			_formula = Formula.Read(encodedTokenLen, in1, totalEncodedLen);
		}

		public ArrayRecord(Formula formula, CellRangeAddress8Bit range)
			: base(range)
		{
			_options = 0;
			_field3notUsed = 0;
			_formula = formula;
		}

		protected override void SerializeExtraData(ILittleEndianOutput out1)
		{
			out1.WriteShort(_options);
			out1.WriteInt(_field3notUsed);
			_formula.Serialize(out1);
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(GetType().Name).Append(" [ARRAY]\n");
			stringBuilder.Append(" range=").Append(base.Range.ToString()).Append("\n");
			stringBuilder.Append(" options=").Append(HexDump.ShortToHex(_options)).Append("\n");
			stringBuilder.Append(" notUsed=").Append(HexDump.IntToHex(_field3notUsed)).Append("\n");
			stringBuilder.Append(" formula:").Append("\n");
			Ptg[] tokens = _formula.Tokens;
			foreach (Ptg ptg in tokens)
			{
				stringBuilder.Append(ptg.ToString()).Append(ptg.RVAType).Append("\n");
			}
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		public override object Clone()
		{
			ArrayRecord arrayRecord = new ArrayRecord(_formula.Copy(), base.Range);
			arrayRecord._options = _options;
			arrayRecord._field3notUsed = _field3notUsed;
			return arrayRecord;
		}
	}
}
