	public abstract class CellRecord : StandardRecord, CellValueRecordInterface, IComparable
	{
		private int _rowIndex;

		private int _columnIndex;

		private int _formatIndex;

		public int Row
		{
			get
			{
				return _rowIndex;
			}
			set
