			}
		}

		public int Column
		{
			get
			{
				return _columnIndex;
			}
			set
			{
				_columnIndex = value;
			}
		}

		public short XFIndex
		{
			get
			{
				return (short)_formatIndex;
			}
			set
			{
				_formatIndex = value;
			}
		}

		protected abstract string RecordName { get; }

		protected abstract int ValueDataSize { get; }

		protected override int DataSize => 6 + ValueDataSize;

		protected CellRecord()
		{
		}

		protected CellRecord(RecordInputStream in1)
		{
			_rowIndex = in1.ReadUShort();
			_columnIndex = in1.ReadUShort();
			_formatIndex = in1.ReadUShort();
		}

		public int CompareTo(object obj)
		{
			CellValueRecordInterface cellValueRecordInterface = (CellValueRecordInterface)obj;
			if (Row == cellValueRecordInterface.Row && Column == cellValueRecordInterface.Column)
			{
				return 0;
			}
			if (Row < cellValueRecordInterface.Row)
			{
				return -1;
			}
			if (Row > cellValueRecordInterface.Row)
			{
				return 1;
			}
			if (Column < cellValueRecordInterface.Column)
			{
				return -1;
			}
			if (Column > cellValueRecordInterface.Column)
			{
				return 1;
			}
			return -1;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			string recordName = RecordName;
			stringBuilder.Append("[").Append(recordName).Append("]\n");
			stringBuilder.Append("    .row    = ").Append(HexDump.ShortToHex(Row)).Append("\n");
			stringBuilder.Append("    .col    = ").Append(HexDump.ShortToHex(Column)).Append("\n");
			stringBuilder.Append("    .xfindex= ").Append(HexDump.ShortToHex(XFIndex)).Append("\n");
			AppendValueText(stringBuilder);
			stringBuilder.Append("\n");
			stringBuilder.Append("[/").Append(recordName).Append("]\n");
			return stringBuilder.ToString();
		}

		protected abstract void AppendValueText(StringBuilder sb);

		protected abstract void SerializeValue(ILittleEndianOutput out1);

		public override void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteShort(Row);
			out1.WriteShort(Column);
			out1.WriteShort(XFIndex);
			SerializeValue(out1);
		}

		protected void CopyBaseFields(CellRecord rec)
		{
			rec._rowIndex = _rowIndex;
			rec._columnIndex = _columnIndex;
			rec._formatIndex = _formatIndex;
		}

		public override bool Equals(object obj)
		{
			if (!(obj is CellValueRecordInterface))
			{
				return false;
			}
			CellValueRecordInterface cellValueRecordInterface = (CellValueRecordInterface)obj;
			if (Row == cellValueRecordInterface.Row && Column == cellValueRecordInterface.Column)
			{
				return true;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return Row ^ Column;
		}
	}
	public class BoolErrRecord : CellRecord
	{
		public const short sid = 517;

		private int _value;

		private bool _isError;

		public bool BooleanValue => _value != 0;

		public byte ErrorValue => (byte)_value;

		public bool IsBoolean => !_isError;

		public bool IsError => _isError;

		protected override string RecordName => "BOOLERR";

		protected override int ValueDataSize => 2;

		public override short Sid => 517;

		public BoolErrRecord()
		{
		}

		public BoolErrRecord(RecordInputStream in1)
			: base(in1)
		{
			switch (in1.Remaining)
			{
			case 2:
				_value = in1.ReadByte();
				break;
			case 3:
				_value = in1.ReadUShort();
				break;
			default:
				throw new RecordFormatException("Unexpected size (" + in1.Remaining + ") for BOOLERR record.");
			}
			int num = in1.ReadUByte();
			switch (num)
			{
			case 0:
				_isError = false;
				break;
			case 1:
				_isError = true;
				break;
			default:
				throw new RecordFormatException("Unexpected isError flag (" + num + ") for BOOLERR record.");
			}
		}

		public void SetValue(bool value)
		{
			_value = (value ? 1 : 0);
			_isError = false;
		}

		public void SetValue(byte value)
		{
			switch (value)
			{
			case 0:
			case 7:
			case 15:
			case 23:
			case 29:
			case 36:
			case 42:
				_value = value;
				_isError = true;
				break;
			default:
				throw new ArgumentException("Error Value can only be 0,7,15,23,29,36 or 42. It cannot be " + value);
			}
		}

		protected override void AppendValueText(StringBuilder buffer)
		{
			if (IsBoolean)
			{
				buffer.Append("    .boolValue   = ").Append(BooleanValue).Append("\n");
			}
			else
			{
				buffer.Append("    .errCode     = ").Append(ErrorValue).Append("\n");
			}
		}

		protected override void SerializeValue(ILittleEndianOutput out1)
		{
			out1.WriteByte(_value);
			out1.WriteByte(_isError ? 1 : 0);
		}

		public override object Clone()
		{
			BoolErrRecord boolErrRecord = new BoolErrRecord();
			CopyBaseFields(boolErrRecord);
			boolErrRecord._value = _value;
			boolErrRecord._isError = _isError;
			return boolErrRecord;
		}
	}
