	public class NPOIFSMiniStore : BlockStore
	{
		private NPOIFSFileSystem _filesystem;

		private NPOIFSStream _mini_stream;

		private List<BATBlock> _sbat_blocks;

		private HeaderBlock _header;

		private RootProperty _root;

		public NPOIFSMiniStore(NPOIFSFileSystem filesystem, RootProperty root, List<BATBlock> sbats, HeaderBlock header)
		{
			_filesystem = filesystem;
			_sbat_blocks = sbats;
			_header = header;
			_root = root;
			_mini_stream = new NPOIFSStream(filesystem, root.StartBlock);
		}

		public override ByteBuffer GetBlockAt(int offset)
		{
			int num = offset * 64;
			int num2 = num / _filesystem.GetBigBlockSize();
			int num3 = num % _filesystem.GetBigBlockSize();
			NPOIFSStream.StreamBlockByteBufferIterator streamBlockByteBufferIterator = _mini_stream.GetBlockIterator() as NPOIFSStream.StreamBlockByteBufferIterator;
			for (int i = 0; i < num2; i++)
			{
				streamBlockByteBufferIterator.Next();
			}
			ByteBuffer byteBuffer = streamBlockByteBufferIterator.Next();
			if (byteBuffer == null)
			{
				throw new IndexOutOfRangeException("Big block " + num2 + " outside stream");
			}
			byteBuffer.Position += num3;
			ByteBuffer byteBuffer2 = byteBuffer.Slice();
			byteBuffer2.Limit = 64;
			return byteBuffer2;
		}

		public override ByteBuffer CreateBlockIfNeeded(int offset)
		{
			bool flag = false;
			if (_mini_stream.GetStartBlock() == -2)
			{
				flag = true;
			}
			if (!flag)
			{
				try
				{
					return GetBlockAt(offset);
				}
				catch (IndexOutOfRangeException)
				{
				}
			}
			int freeBlock = _filesystem.GetFreeBlock();
			_filesystem.CreateBlockIfNeeded(freeBlock);
			if (flag)
			{
				_filesystem.PropertyTable.Root.StartBlock = freeBlock;
				_mini_stream = new NPOIFSStream(_filesystem, freeBlock);
			}
			else
			{
				ChainLoopDetector chainLoopDetector = _filesystem.GetChainLoopDetector();
				int offset2 = _mini_stream.GetStartBlock();
				while (true)
				{
					chainLoopDetector.Claim(offset2);
					int nextBlock = _filesystem.GetNextBlock(offset2);
					if (nextBlock == -2)
					{
						break;
					}
					offset2 = nextBlock;
				}
				_filesystem.SetNextBlock(offset2, freeBlock);
			}
			_filesystem.SetNextBlock(freeBlock, -2);
			return CreateBlockIfNeeded(offset);
		}

		public override BATBlockAndIndex GetBATBlockAndIndex(int offset)
		{
			return BATBlock.GetSBATBlockAndIndex(offset, _header, _sbat_blocks);
		}

		public override int GetNextBlock(int offset)
		{
			BATBlockAndIndex bATBlockAndIndex = GetBATBlockAndIndex(offset);
			return bATBlockAndIndex.Block.GetValueAt(bATBlockAndIndex.Index);
		}

		public override void SetNextBlock(int offset, int nextBlock)
		{
			BATBlockAndIndex bATBlockAndIndex = GetBATBlockAndIndex(offset);
			bATBlockAndIndex.Block.SetValueAt(bATBlockAndIndex.Index, nextBlock);
		}

		public override int GetFreeBlock()
		{
			int bATEntriesPerBlock = _filesystem.GetBigBlockSizeDetails().GetBATEntriesPerBlock();
			int num = 0;
			for (int i = 0; i < _sbat_blocks.Count; i++)
			{
				BATBlock bATBlock = _sbat_blocks[i];
				if (bATBlock.HasFreeSectors)
				{
					for (int j = 0; j < bATEntriesPerBlock; j++)
					{
						int valueAt = bATBlock.GetValueAt(j);
						if (valueAt == -1)
						{
							return num + j;
						}
					}
				}
				num += bATEntriesPerBlock;
			}
			BATBlock bATBlock2 = BATBlock.CreateEmptyBATBlock(_filesystem.GetBigBlockSizeDetails(), isXBAT: false);
			int num2 = (bATBlock2.OurBlockIndex = _filesystem.GetFreeBlock());
			if (_header.SBATCount == 0)
			{
				_header.SBATStart = num2;
				_header.SBATBlockCount = 1;
			}
			else
			{
				ChainLoopDetector chainLoopDetector = _filesystem.GetChainLoopDetector();
				int offset = _header.SBATStart;
				while (true)
				{
					chainLoopDetector.Claim(offset);
					int nextBlock = _filesystem.GetNextBlock(offset);
					if (nextBlock == -2)
					{
						break;
					}
					offset = nextBlock;
				}
				_filesystem.SetNextBlock(offset, num2);
				_header.SBATBlockCount = _header.SBATCount + 1;
			}
			_filesystem.SetNextBlock(num2, -2);
			_sbat_blocks.Add(bATBlock2);
			return num;
		}

		public override ChainLoopDetector GetChainLoopDetector()
		{
			return new ChainLoopDetector(_root.Size, this);
		}

		public override int GetBlockStoreBlockSize()
		{
			return 64;
		}

		public void SyncWithDataSource()
		{
			foreach (BATBlock sbat_block in _sbat_blocks)
			{
				ByteBuffer blockAt = _filesystem.GetBlockAt(sbat_block.OurBlockIndex);
				BlockAllocationTableWriter.WriteBlock(sbat_block, blockAt);
			}
		}
	}
	public class NPOIFSStream : IEnumerable<ByteBuffer>, IEnumerable
	{
		public class StreamBlockByteBuffer : MemoryStream
		{
			private byte[] oneByte = new byte[1];

			private ByteBuffer buffer;

			private ChainLoopDetector loopDetector;

			private int prevBlock;

			private int nextBlock;

			private NPOIFSStream pStream;

			protected internal StreamBlockByteBuffer(NPOIFSStream pStream)
			{
				this.pStream = pStream;
				loopDetector = pStream.blockStore.GetChainLoopDetector();
				prevBlock = -2;
				nextBlock = pStream.startBlock;
			}

			protected void CreateBlockIfNeeded()
			{
				if (buffer != null && buffer.HasRemaining())
				{
					return;
				}
				int freeBlock = nextBlock;
				if (freeBlock == -2)
				{
					freeBlock = pStream.blockStore.GetFreeBlock();
					loopDetector.Claim(freeBlock);
					nextBlock = -2;
					if (prevBlock != -2)
					{
						pStream.blockStore.SetNextBlock(prevBlock, freeBlock);
					}
					pStream.blockStore.SetNextBlock(freeBlock, -2);
					if (pStream.startBlock == -2)
					{
						pStream.startBlock = freeBlock;
					}
				}
				else
				{
					loopDetector.Claim(freeBlock);
					nextBlock = pStream.blockStore.GetNextBlock(freeBlock);
				}
				buffer = pStream.blockStore.CreateBlockIfNeeded(freeBlock);
				prevBlock = freeBlock;
			}

			public void Write(int b)
			{
				oneByte[0] = (byte)((uint)b & 0xFFu);
				base.Write(oneByte, 0, oneByte.Length);
			}

			public override void Write(byte[] b, int off, int len)
			{
				if (off < 0 || off > b.Length || len < 0 || off + len > b.Length || off + len < 0)
				{
					throw new IndexOutOfRangeException();
				}
				if (len != 0)
				{
					do
					{
						CreateBlockIfNeeded();
						int num = Math.Min(buffer.Remaining(), len);
						buffer.Write(b, off, num);
						off += num;
						len -= num;
					}
					while (len > 0);
				}
			}

			public override void Close()
			{
				NPOIFSStream nPOIFSStream = new NPOIFSStream(pStream.blockStore, nextBlock);
				nPOIFSStream.Free(loopDetector);
				pStream.blockStore.SetNextBlock(prevBlock, -2);
				base.Close();
			}
		}

		public class StreamBlockByteBufferIterator : IEnumerator<ByteBuffer>, IDisposable, IEnumerator
		{
			private ChainLoopDetector loopDetector;

			private int nextBlock;

			private ByteBuffer current;

			private NPOIFSStream pStream;

			public ByteBuffer Current => current;

			object IEnumerator.Current => current;

			public StreamBlockByteBufferIterator(NPOIFSStream pStream, int firstBlock)
			{
				this.pStream = pStream;
				nextBlock = firstBlock;
				try
				{
					loopDetector = pStream.blockStore.GetChainLoopDetector();
				}
				catch (IOException ex)
				{
					throw new Exception(ex.Message);
				}
			}

			public bool HasNext()
			{
				if (nextBlock == -2)
				{
					return false;
				}
				return true;
			}

			public ByteBuffer Next()
			{
				if (nextBlock == -2)
				{
					throw new IndexOutOfRangeException("Can't read past the end of the stream");
				}
				try
				{
					loopDetector.Claim(nextBlock);
					ByteBuffer blockAt = pStream.blockStore.GetBlockAt(nextBlock);
					nextBlock = pStream.blockStore.GetNextBlock(nextBlock);
					return blockAt;
				}
				catch (IOException ex)
				{
					throw new RuntimeException(ex.Message);
				}
			}

			public void Remove()
			{
				throw new NotImplementedException("Unsupported Operations!");
			}

			void IEnumerator.Reset()
			{
				throw new NotImplementedException();
			}

			bool IEnumerator.MoveNext()
			{
				if (nextBlock == -2)
				{
					return false;
				}
				try
				{
					loopDetector.Claim(nextBlock);
					current = pStream.blockStore.GetBlockAt(nextBlock);
					nextBlock = pStream.blockStore.GetNextBlock(nextBlock);
					return true;
				}
				catch (IOException)
				{
					return false;
				}
			}

			public void Dispose()
			{
			}
		}

		private BlockStore blockStore;

		private int startBlock;

		private MemoryStream outStream;

		public NPOIFSStream(BlockStore blockStore, int startBlock)
		{
			this.blockStore = blockStore;
			this.startBlock = startBlock;
		}

		public NPOIFSStream(BlockStore blockStore)
		{
			this.blockStore = blockStore;
			startBlock = -2;
		}

		public int GetStartBlock()
		{
			return startBlock;
		}

		public IEnumerator<ByteBuffer> GetEnumerator()
		{
			return GetBlockIterator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetBlockIterator();
		}

		public IEnumerator<ByteBuffer> GetBlockIterator()
		{
			if (startBlock == -2)
			{
				throw new InvalidOperationException("Can't read from a new stream before it has been written to");
			}
			return new StreamBlockByteBufferIterator(this, startBlock);
		}

		public void UpdateContents(byte[] contents)
		{
			Stream outputStream = GetOutputStream();
			outputStream.Write(contents, 0, contents.Length);
			outputStream.Close();
		}

		public Stream GetOutputStream()
		{
			if (outStream == null)
			{
				outStream = new StreamBlockByteBuffer(this);
			}
			return outStream;
		}

		public void Free()
		{
			ChainLoopDetector chainLoopDetector = blockStore.GetChainLoopDetector();
			Free(chainLoopDetector);
		}

		internal void Free(ChainLoopDetector loopDetector)
		{
			int nextBlock = startBlock;
			while (nextBlock != -2)
			{
				int offset = nextBlock;
				loopDetector.Claim(offset);
				nextBlock = blockStore.GetNextBlock(offset);
				blockStore.SetNextBlock(offset, -1);
			}
			startBlock = -2;
		}
	}
	public class ODocumentInputStream : DocumentInputStream
	{
		private long _current_offset;

		private long _marked_offset;

		private int _document_size;

		private bool _closed;

		private POIFSDocument _document;

		private DataInputBlock _currentBlock;

		public override long Length => _document_size;

		public override long Position
		{
			get
			{
				if (_closed)
				{
					throw new InvalidOperationException("cannot perform requested operation on a closed stream");
				}
				return _current_offset;
			}
			set
			{
				_current_offset = (int)value;
			}
		}

		public ODocumentInputStream(DocumentEntry document)
		{
			if (!(document is DocumentNode))
			{
				throw new IOException("Cannot open internal document storage");
			}
			DocumentNode documentNode = (DocumentNode)document;
			if (documentNode.Document == null)
			{
				throw new IOException("Cannot open internal document storage");
			}
			_current_offset = 0L;
			_marked_offset = 0L;
			_document_size = document.Size;
			_closed = false;
			_document = documentNode.Document;
			_currentBlock = GetDataInputBlock(0L);
		}

		public ODocumentInputStream(POIFSDocument document)
		{
			_current_offset = 0L;
			_marked_offset = 0L;
			_document_size = document.Size;
			_closed = false;
			_document = document;
			_currentBlock = GetDataInputBlock(0L);
		}

		public override int Available()
		{
			if (_closed)
			{
				throw new InvalidOperationException("cannot perform requested operation on a closed stream");
			}
			return _document_size - (int)_current_offset;
		}

		public override void Close()
		{
			_closed = true;
		}

		public override void Mark(int ignoredReadlimit)
		{
			_marked_offset = _current_offset;
		}

		private DataInputBlock GetDataInputBlock(long offset)
		{
			return _document.GetDataInputBlock((int)offset);
		}

		public override int Read()
		{
			dieIfClosed();
			if (atEOD())
			{
				return DocumentInputStream.EOF;
			}
			int result = _currentBlock.ReadUByte();
			_current_offset++;
			if (_currentBlock.Available() < 1)
			{
				_currentBlock = GetDataInputBlock(_current_offset);
			}
			return result;
		}

		public override int Read(byte[] b, int off, int len)
		{
			dieIfClosed();
			if (b == null)
			{
				throw new ArgumentException("buffer must not be null");
			}
			if (off < 0 || len < 0 || b.Length < off + len)
			{
				throw new IndexOutOfRangeException("can't read past buffer boundaries");
			}
			if (len == 0)
			{
				return 0;
			}
			if (atEOD())
			{
				return DocumentInputStream.EOF;
			}
			int num = Math.Min(Available(), len);
			ReadFully(b, off, num);
			return num;
		}

		public override void Reset()
		{
			_current_offset = _marked_offset;
			_currentBlock = GetDataInputBlock(_current_offset);
		}

		public override long Skip(long n)
		{
			dieIfClosed();
			if (n < 0)
			{
				return 0L;
			}
			long num = _current_offset + (int)n;
			if (num < _current_offset)
			{
				num = _document_size;
			}
			else if (num > _document_size)
			{
				num = _document_size;
			}
			long result = num - _current_offset;
			_current_offset = num;
			_currentBlock = GetDataInputBlock(_current_offset);
			return result;
		}

		private void dieIfClosed()
		{
			if (_closed)
			{
				throw new IOException("cannot perform requested operation on a closed stream");
			}
		}

		private bool atEOD()
		{
			return _current_offset == _document_size;
		}

		private void CheckAvaliable(int requestedSize)
		{
			if (_closed)
			{
				throw new InvalidOperationException("cannot perform requested operation on a closed stream");
			}
			if (requestedSize > _document_size - _current_offset)
			{
				throw new Exception("Buffer underrun - requested " + requestedSize + " bytes but " + (_document_size - _current_offset) + " was available");
			}
		}

		public override int ReadByte()
		{
			return ReadUByte();
		}

		public override double ReadDouble()
		{
			return BitConverter.Int64BitsToDouble(ReadLong());
		}

		public override short ReadShort()
		{
			return (short)ReadUShort();
		}

		public override void ReadFully(byte[] buf, int off, int len)
		{
			CheckAvaliable(len);
			int num = _currentBlock.Available();
			if (num > len)
			{
				_currentBlock.ReadFully(buf, off, len);
				_current_offset += len;
				return;
			}
			int num2 = len;
			int num3 = off;
			while (num2 > 0)
			{
				bool flag = num2 >= num;
				int num4 = ((!flag) ? num2 : num);
				_currentBlock.ReadFully(buf, num3, num4);
				num2 -= num4;
				num3 += num4;
				_current_offset += num4;
				if (!flag)
				{
					continue;
				}
				if (_current_offset == _document_size)
				{
					if (num2 > 0)
					{
						throw new InvalidOperationException("reached end of document stream unexpectedly");
					}
					_currentBlock = null;
					break;
				}
				_currentBlock = GetDataInputBlock(_current_offset);
				num = _currentBlock.Available();
			}
		}

		public override long ReadLong()
		{
			CheckAvaliable(DocumentInputStream.SIZE_LONG);
			int num = _currentBlock.Available();
			long result;
			if (num > DocumentInputStream.SIZE_LONG)
			{
				result = _currentBlock.ReadLongLE();
			}
			else
			{
				DataInputBlock dataInputBlock = GetDataInputBlock(_current_offset + num);
				result = ((num != DocumentInputStream.SIZE_LONG) ? dataInputBlock.ReadLongLE(_currentBlock, num) : _currentBlock.ReadLongLE());
				_currentBlock = dataInputBlock;
			}
			_current_offset += DocumentInputStream.SIZE_LONG;
			return result;
		}

		public override int ReadInt()
		{
			CheckAvaliable(DocumentInputStream.SIZE_INT);
			int num = _currentBlock.Available();
			int result;
			if (num > DocumentInputStream.SIZE_INT)
			{
				result = _currentBlock.ReadIntLE();
			}
			else
			{
				DataInputBlock dataInputBlock = GetDataInputBlock(_current_offset + num);
				result = ((num != DocumentInputStream.SIZE_INT) ? dataInputBlock.ReadIntLE(_currentBlock, num) : _currentBlock.ReadIntLE());
				_currentBlock = dataInputBlock;
			}
			_current_offset += DocumentInputStream.SIZE_INT;
			return result;
		}

		public override int ReadUShort()
		{
			CheckAvaliable(DocumentInputStream.SIZE_SHORT);
			int num = _currentBlock.Available();
			int result;
			if (num > DocumentInputStream.SIZE_SHORT)
			{
				result = _currentBlock.ReadUshortLE();
			}
			else
			{
				DataInputBlock dataInputBlock = GetDataInputBlock(_current_offset + num);
				result = ((num != DocumentInputStream.SIZE_SHORT) ? dataInputBlock.ReadUshortLE(_currentBlock) : _currentBlock.ReadUshortLE());
				_currentBlock = dataInputBlock;
			}
			_current_offset += DocumentInputStream.SIZE_SHORT;
			return result;
		}

		public override int ReadUByte()
		{
			CheckAvaliable(1);
			int result = _currentBlock.ReadUByte();
			_current_offset++;
			if (_currentBlock.Available() < 1)
			{
				_currentBlock = GetDataInputBlock(_current_offset);
			}
			return result;
		}

		public override long Seek(long offset, SeekOrigin origin)
		{
			switch (origin)
			{
			case SeekOrigin.Current:
				if (_current_offset + offset >= Length || _current_offset + offset < 0)
				{
					throw new ArgumentException("invalid offset");
				}
				_current_offset += (int)offset;
				break;
			case SeekOrigin.Begin:
				if (offset >= Length || offset < 0)
				{
					throw new ArgumentException("invalid offset");
				}
				_current_offset = offset;
				break;
			case SeekOrigin.End:
				if (Length + offset >= Length || Length + offset < 0)
				{
					throw new ArgumentException("invalid offset");
				}
				_current_offset = Length + offset;
				break;
			}
			return _current_offset;
		}
	}
