namespace NPOI.POIFS.NIO
{
	public abstract class DataSource
	{
		public abstract long Size { get; }

		public abstract ByteBuffer Read(int length, long position);

		public abstract void Write(ByteBuffer src, long position);

		public abstract void Close();

		public abstract void CopyTo(Stream stream);
	}
	public class ByteArrayBackedDataSource : DataSource
	{
		private byte[] buffer;

		private long size;

		public override long Size => size;

		public ByteArrayBackedDataSource(byte[] data, int size)
		{
			buffer = data;
			this.size = size;
		}

		public ByteArrayBackedDataSource(byte[] data)
			: this(data, data.Length)
		{
		}

		public override ByteBuffer Read(int length, long position)
		{
			if (position >= size)
			{
				throw new IndexOutOfRangeException("Unable to read " + length + " bytes from " + position + " in stream of length " + size);
			}
			int length2 = (int)Math.Min(length, size - position);
			return ByteBuffer.CreateBuffer(buffer, (int)position, length2);
		}

		public override void Write(ByteBuffer src, long position)
		{
			long num = position + src.Length;
			if (num > buffer.Length)
			{
				Extend(num);
			}
			src.Read(buffer, (int)position, src.Length);
			if (num > size)
			{
				size = num;
			}
		}

		private void Extend(long length)
		{
			long num = length - buffer.Length;
			if ((double)num < (double)buffer.Length * 0.25)
			{
				num = (long)((double)buffer.Length * 0.25);
			}
			if (num < 4096)
			{
				num = 4096L;
			}
			byte[] destinationArray = new byte[(int)(num + buffer.Length)];
			System.Array.Copy(buffer, 0, destinationArray, 0, (int)size);
			buffer = destinationArray;
		}

		public override void CopyTo(Stream stream)
		{
			stream.Write(buffer, 0, (int)size);
		}

		public override void Close()
		{
			buffer = null;
			size = -1L;
		}
	}
	public class FileBackedDataSource : DataSource
	{
		private MemoryStream fileStream;

		private FileInfo fileinfo;

		private bool writable;

		public bool IsWriteable => writable;

		public Stream Stream => fileStream;

		public override long Size
		{
			get
			{
				if (fileStream != null)
				{
					return fileStream.Length;
				}
				return fileinfo.Length;
			}
		}

		public FileBackedDataSource(FileInfo file)
			: this(file, readOnly: false)
		{
		}

		public FileBackedDataSource(FileInfo file, bool readOnly)
		{
			if (!file.Exists)
			{
				throw new FileNotFoundException(file.FullName);
			}
			fileinfo = file;
			FileStream fileStream = new FileStream(file.FullName, FileMode.Open, FileAccess.Read);
			byte[] array = new byte[fileStream.Length];
			fileStream.Read(array, 0, (int)fileStream.Length);
			MemoryStream memoryStream = new MemoryStream(array, 0, array.Length);
			this.fileStream = memoryStream;
			writable = !readOnly;
			fileStream.Position = 0L;
		}

		public FileBackedDataSource(FileStream stream, bool readOnly)
		{
			stream.Position = 0L;
			byte[] array = new byte[stream.Length];
			stream.Read(array, 0, (int)stream.Length);
			MemoryStream memoryStream = new MemoryStream(array, 0, array.Length);
			fileStream = memoryStream;
			writable = !readOnly;
			stream.Position = 0L;
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		private void Dispose(bool disposing)
		{
			if (disposing && fileStream != null)
			{
				fileStream.Dispose();
				fileStream = null;
			}
		}

		~FileBackedDataSource()
		{
			Dispose(disposing: false);
		}

		public override ByteBuffer Read(int length, long position)
		{
			if (position >= Size)
			{
				throw new ArgumentException("Position " + position + " past the end of the file");
			}
			int num = -1;
			ByteBuffer byteBuffer;
			if (writable)
			{
				byteBuffer = ByteBuffer.CreateBuffer(length);
				num = 0;
			}
			else
			{
				fileStream.Position = position;
				byteBuffer = ByteBuffer.CreateBuffer(length);
				num = IOUtils.ReadFully(fileStream, byteBuffer.Buffer);
			}
			if (num == -1)
			{
				throw new ArgumentException("Position " + position + " past the end of the file");
			}
			byteBuffer.Position = 0;
			return byteBuffer;
		}

		public override void Write(ByteBuffer src, long position)
		{
			fileStream.Write(src.Buffer, (int)position, src.Length);
		}

		public override void CopyTo(Stream stream)
		{
			byte[] array = fileStream.ToArray();
			stream.Write(array, 0, array.Length);
		}

		public override void Close()
		{
			if (fileStream != null)
			{
				fileStream.Close();
			}
		}
	}
