namespace NPOI.POIFS.Properties
{
	public abstract class PropertyTableBase : BATManaged
	{
		protected HeaderBlock _header_block;

		protected List<Property> _properties;

		public RootProperty Root => (RootProperty)_properties[0];

		public virtual int StartBlock
		{
			get
			{
				return _header_block.PropertyStart;
			}
			set
			{
				_header_block.PropertyStart = value;
			}
		}

		public virtual int CountBlocks
		{
			get
			{
				throw new NotImplementedException();
			}
		}

		public PropertyTableBase(HeaderBlock header_block)
		{
			_header_block = header_block;
			_properties = new List<Property>();
			AddProperty(new RootProperty());
		}

		public PropertyTableBase(HeaderBlock header_block, List<Property> properties)
		{
			_header_block = header_block;
			_properties = properties;
			PopulatePropertyTree((DirectoryProperty)_properties[0]);
		}

		public void AddProperty(Property property)
		{
			_properties.Add(property);
		}

		public void RemoveProperty(Property property)
		{
			_properties.Remove(property);
		}

		protected void PopulatePropertyTree(DirectoryProperty root)
		{
			try
			{
				int childIndex = root.ChildIndex;
				if (!Property.IsValidIndex(childIndex))
				{
					return;
				}
				Stack<Property> stack = new Stack<Property>();
				stack.Push(_properties[childIndex]);
				while (stack.Count != 0)
				{
					Property property = stack.Pop();
					if (property != null)
					{
						root.AddChild(property);
						if (property.IsDirectory)
						{
							PopulatePropertyTree((DirectoryProperty)property);
						}
						childIndex = property.PreviousChildIndex;
						if (Property.IsValidIndex(childIndex))
						{
							stack.Push(_properties[childIndex]);
						}
						childIndex = property.NextChildIndex;
						if (Property.IsValidIndex(childIndex))
						{
							stack.Push(_properties[childIndex]);
						}
					}
				}
			}
			catch (IOException ex)
			{
				throw ex;
			}
		}
	}
	public class NPropertyTable : PropertyTableBase
	{
		private POIFSBigBlockSize _bigBigBlockSize;

		public override int CountBlocks
		{
			get
			{
				int num = _properties.Count * 128;
				return (int)Math.Ceiling(1.0 * (double)num / (double)_bigBigBlockSize.GetBigBlockSize());
			}
		}

		public NPropertyTable(HeaderBlock headerBlock)
			: base(headerBlock)
		{
			_bigBigBlockSize = headerBlock.BigBlockSize;
		}

		public NPropertyTable(HeaderBlock headerBlock, NPOIFSFileSystem fileSystem)
			: base(headerBlock, BuildProperties(new NPOIFSStream(fileSystem, headerBlock.PropertyStart).GetEnumerator(), headerBlock.BigBlockSize))
		{
			_bigBigBlockSize = headerBlock.BigBlockSize;
		}

		private static List<Property> BuildProperties(IEnumerator<ByteBuffer> dataSource, POIFSBigBlockSize bigBlockSize)
		{
			List<Property> list = new List<Property>();
			while (dataSource.MoveNext())
			{
				ByteBuffer current = dataSource.Current;
				byte[] array;
				if (current.HasBuffer && current.Offset == 0 && current.Buffer.Length == bigBlockSize.GetBigBlockSize())
				{
					array = current.Buffer;
				}
				else
				{
					array = new byte[bigBlockSize.GetBigBlockSize()];
					int length = array.Length;
					if (current.Remaining() < bigBlockSize.GetBigBlockSize())
					{
						length = current.Remaining();
					}
					current.Read(array, 0, length);
				}
				PropertyFactory.ConvertToProperties(array, list);
			}
			return list;
		}

		public void PreWrite()
		{
			List<Property> list = new List<Property>();
			int num = 0;
			foreach (Property property in _properties)
			{
				if (property != null)
				{
					property.Index = num++;
					list.Add(property);
				}
			}
			foreach (Property item in list)
			{
				item.PreWrite();
			}
		}

		public void Write(NPOIFSStream stream)
		{
			Stream outputStream = stream.GetOutputStream();
			try
			{
				new MemoryStream();
				foreach (Property property in _properties)
				{
					property?.WriteData(outputStream);
				}
				outputStream.Close();
				if (StartBlock != stream.GetStartBlock())
				{
					StartBlock = stream.GetStartBlock();
				}
			}
			catch (IOException ex)
			{
				throw ex;
			}
		}
	}
