	public class CellDateFormatter : CellFormatter
	{
		private class DatePartHandler : CellFormatPart.IPartHandler
		{
			private CellDateFormatter _formatter;

			private int mStart = -1;

			private int mLen;

			private int hStart = -1;

			private int hLen;

			public DatePartHandler(CellDateFormatter formatter)
			{
				_formatter = formatter;
			}

			public string HandlePart(System.Text.RegularExpressions.Match m, string part, CellFormatType type, StringBuilder desc)
			{
				int length = desc.Length;
				switch (part[0])
				{
				case 'S':
				case 's':
					if (mStart >= 0)
					{
						for (int i = 0; i < mLen; i++)
						{
							desc[mStart + i] = 'm';
						}
						mStart = -1;
					}
					return part.ToLower();
				case 'H':
				case 'h':
					mStart = -1;
					hStart = length;
					hLen = part.Length;
					return part.ToLower();
				case 'D':
				case 'd':
					mStart = -1;
					return part.ToLower();
				case 'M':
				case 'm':
					mStart = length;
					mLen = part.Length;
					if (hStart >= 0)
					{
						return part.ToLower();
					}
					return part.ToUpper();
				case 'Y':
				case 'y':
					mStart = -1;
					if (part.Length == 3)
					{
						part = "yyyy";
					}
					return part.ToLower();
				case '0':
				{
					mStart = -1;
					int length2 = part.Length;
					_formatter.sFmt = "%0" + (length2 + 2) + "." + length2 + "f";
					_formatter.millisecondPartLength = length2;
					return part.Replace('0', 'f');
				}
				case 'A':
				case 'P':
				case 'a':
				case 'p':
					if (part.Length > 1)
					{
						mStart = -1;
						_formatter.ShowAmPm = true;
						_formatter.ShowM = char.ToLower(part[1]) == 'm';
						_formatter.amPmUpper = _formatter.ShowM || char.IsUpper(part[0]);
						if (_formatter.ShowM)
						{
							return "tt";
						}
						return "t";
					}
					return null;
				default:
					return null;
				}
			}

			public void Finish(StringBuilder toAppendTo)
			{
				if (hStart >= 0 && !_formatter.ShowAmPm)
				{
					for (int i = 0; i < hLen; i++)
					{
						toAppendTo[hStart + i] = 'H';
					}
				}
			}
		}

		private bool amPmUpper;

		private bool ShowM;

		private bool ShowAmPm;

		private FormatBase dateFmt;

		private string sFmt;

		private int millisecondPartLength;

		private static readonly TimeSpan EXCEL_EPOCH_TIME;

		private static readonly DateTime EXCEL_EPOCH_DATE;

		private static readonly CellFormatter SIMPLE_DATE;

		static CellDateFormatter()
		{
			SIMPLE_DATE = new CellDateFormatter("mm/d/y");
			DateTime dateTime = (EXCEL_EPOCH_DATE = new DateTime(1904, 1, 1));
			EXCEL_EPOCH_TIME = dateTime.TimeOfDay;
		}

		public CellDateFormatter(string format)
			: base(format)
		{
			DatePartHandler datePartHandler = new DatePartHandler(this);
			StringBuilder stringBuilder = CellFormatPart.ParseFormat(format, CellFormatType.DATE, datePartHandler);
			datePartHandler.Finish(stringBuilder);
			dateFmt = new SimpleDateFormat(stringBuilder.ToString());
			string pattern = Regex.Replace(stringBuilder.ToString(), "((y)(?!y))(?<!yy)", "yy");
			dateFmt = new SimpleDateFormat(pattern);
		}

		public override void FormatValue(StringBuilder toAppendTo, object value)
		{
			if (value == null)
			{
				value = 0.0;
			}
			if (Number.IsNumber(value))
			{
				double.TryParse(value.ToString(), out var result);
				if (result == 0.0)
				{
					value = EXCEL_EPOCH_DATE;
				}
				else
				{
					TimeSpan eXCEL_EPOCH_TIME = EXCEL_EPOCH_TIME;
					value = new DateTime((long)((double)eXCEL_EPOCH_TIME.Ticks + result));
				}
			}
			DateTime dateTime = (DateTime)value;
			if (millisecondPartLength > 0)
			{
				double num = (double)dateTime.Millisecond / 1000.0 * Math.Pow(10.0, millisecondPartLength);
				num -= Math.Truncate(num);
				if (num >= 0.5)
				{
					dateTime = dateTime.AddMilliseconds((1.0 - num) / Math.Pow(10.0, millisecondPartLength) * 1000.0);
				}
			}
			dateFmt.Format(dateTime, toAppendTo, CultureInfo.CurrentCulture);
		}

		public override void SimpleValue(StringBuilder toAppendTo, object value)
		{
			SIMPLE_DATE.FormatValue(toAppendTo, value);
		}
	}
	public class CellFormatPart
	{
		private class CaseInsensitiveComparator : IEqualityComparer<string>
		{
			public bool Equals(string x, string y)
			{
				return x.Equals(y, StringComparison.InvariantCultureIgnoreCase);
			}

			public int GetHashCode(string obj)
			{
				return obj.GetHashCode();
			}
		}

		public interface IPartHandler
		{
			string HandlePart(System.Text.RegularExpressions.Match m, string part, CellFormatType type, StringBuilder desc);
		}

		private Color color;

		private CellFormatCondition condition;

		private CellFormatter format;

		private CellFormatType type;

		private static Dictionary<string, Color> NAMED_COLORS;

		public static IEqualityComparer<string> CASE_INSENSITIVE_ORDER;

		public static Regex COLOR_PAT;

		public static Regex CONDITION_PAT;

		public static Regex SPECIFICATION_PAT;

		public static Regex FORMAT_PAT;

		public static int COLOR_GROUP;

		public static int CONDITION_OPERATOR_GROUP;

		public static int CONDITION_VALUE_GROUP;

		public static int SPECIFICATION_GROUP;

		internal CellFormatType CellFormatType => type;

		internal bool HasCondition => condition != null;

		static CellFormatPart()
		{
			CASE_INSENSITIVE_ORDER = new CaseInsensitiveComparator();
			NAMED_COLORS = new Dictionary<string, Color>(CASE_INSENSITIVE_ORDER);
			Hashtable indexHash = HSSFColor.GetIndexHash();
			foreach (object value2 in indexHash.Values)
			{
				HSSFColor hSSFColor = (HSSFColor)value2;
				Type type = hSSFColor.GetType();
				string name = type.Name;
				if (name.Equals(name.ToUpper()))
				{
					byte[] rGB = hSSFColor.RGB;
					Color value = Color.FromArgb(rGB[0], rGB[1], rGB[2]);
					if (!NAMED_COLORS.ContainsKey(name))
					{
						NAMED_COLORS.Add(name, value);
					}
					if (name.IndexOf('_') > 0 && !NAMED_COLORS.ContainsKey(name.Replace('_', ' ')))
					{
						NAMED_COLORS.Add(name.Replace('_', ' '), value);
					}
					if (name.IndexOf("_PERCENT") > 0 && !NAMED_COLORS.ContainsKey(name.Replace("_PERCENT", "%").Replace('_', ' ')))
					{
						NAMED_COLORS.Add(name.Replace("_PERCENT", "%").Replace('_', ' '), value);
					}
				}
			}
			string text = "([<>=]=?|!=|<>)    # The operator\n  \\s*([0-9]+(?:\\.[0-9]*)?)\\s*  # The constant to test against\n";
			string text2 = "\\[(black|blue|cyan|green|magenta|red|white|yellow|color [0-9]+)\\]";
			string text3 = "\\\\.                 # Quoted single character\n|\"([^\\\\\"]|\\\\.)*\"         # Quoted string of characters (handles escaped quotes like \\\") \n|_.                             # Space as wide as a given character\n|\\*.                           # Repeating fill character\n|@                              # Text: cell text\n|([0?\\#](?:[0?\\#,]*))         # Number: digit + other digits and commas\n|e[-+]                          # Number: Scientific: Exponent\n|m{1,5}                         # Date: month or minute spec\n|d{1,4}                         # Date: day/date spec\n|y{2,4}                         # Date: year spec\n|h{1,2}                         # Date: hour spec\n|s{1,2}                         # Date: second spec\n|am?/pm?                        # Date: am/pm spec\n|\\[h{1,2}\\]                   # Elapsed time: hour spec\n|\\[m{1,2}\\]                   # Elapsed time: minute spec\n|\\[s{1,2}\\]                   # Elapsed time: second spec\n|[^;]                           # A character\n";
			string pattern = "(?:" + text2 + ")?                  # Text color\n(?:\\[" + text + "\\])?                # Condition\n((?:" + text3 + ")+)                        # Format spec\n";
			RegexOptions options = RegexOptions.IgnoreCase | RegexOptions.Compiled | RegexOptions.IgnorePatternWhitespace;
			COLOR_PAT = new Regex(text2, options);
			CONDITION_PAT = new Regex(text, options);
			SPECIFICATION_PAT = new Regex(text3, options);
			FORMAT_PAT = new Regex(pattern, options);
			COLOR_GROUP = FindGroup(FORMAT_PAT, "[Blue]@", "Blue");
			CONDITION_OPERATOR_GROUP = FindGroup(FORMAT_PAT, "[>=1]@", ">=");
			CONDITION_VALUE_GROUP = FindGroup(FORMAT_PAT, "[>=1]@", "1");
			SPECIFICATION_GROUP = FindGroup(FORMAT_PAT, "[Blue][>1]\\a ?", "\\a ?");
		}

		public CellFormatPart(string desc)
		{
			System.Text.RegularExpressions.Match match = FORMAT_PAT.Match(desc);
			if (!match.Success)
			{
				throw new ArgumentException("Unrecognized format: \"" + desc + "\"");
			}
			color = GetColor(match);
			condition = GetCondition(match);
			type = GetCellFormatType(match);
			format = GetFormatter(match);
		}

		public bool Applies(object valueObject)
		{
			if (condition == null || !valueObject.GetType().IsPrimitive)
			{
				if (valueObject == null)
				{
					throw new NullReferenceException("valueObject");
				}
				return true;
			}
			double value = (double)valueObject;
			return condition.Pass(value);
		}

		private static int FindGroup(Regex pat, string str, string marker)
		{
			System.Text.RegularExpressions.Match match = pat.Match(str);
			if (!match.Success)
			{
				throw new ArgumentException("Pattern \"" + pat.ToString() + "\" doesn't match \"" + str + "\"");
			}
			for (int i = 1; i <= match.Groups.Count; i++)
			{
				string value = match.Groups[i].Value;
				if (value != null && value.Equals(marker))
				{
					return i;
				}
			}
			throw new ArgumentException("\"" + marker + "\" not found in \"" + pat.ToString() + "\"");
		}

		private static Color GetColor(System.Text.RegularExpressions.Match m)
		{
			string text = m.Groups[COLOR_GROUP].Value.ToUpper();
			if (text == null || text.Length == 0)
			{
				return Color.Empty;
			}
			Color result = Color.Empty;
			if (NAMED_COLORS.ContainsKey(text))
			{
				result = NAMED_COLORS[text];
			}
			return result;
		}

		private CellFormatCondition GetCondition(System.Text.RegularExpressions.Match m)
		{
			string value = m.Groups[CONDITION_OPERATOR_GROUP].Value;
			if (value == null || value.Length == 0)
			{
				return null;
			}
			return CellFormatCondition.GetInstance(m.Groups[CONDITION_OPERATOR_GROUP].Value, m.Groups[CONDITION_VALUE_GROUP].Value);
		}

		private CellFormatType GetCellFormatType(System.Text.RegularExpressions.Match matcher)
		{
			string value = matcher.Groups[SPECIFICATION_GROUP].Value;
			return formatType(value);
		}

		private CellFormatter GetFormatter(System.Text.RegularExpressions.Match matcher)
		{
			string value = matcher.Groups[SPECIFICATION_GROUP].Value;
			return type.Formatter(value);
		}

		private CellFormatType formatType(string fdesc)
		{
			fdesc = fdesc.Trim();
			if (fdesc.Equals("") || fdesc.Equals("General", StringComparison.InvariantCultureIgnoreCase))
			{
				return CellFormatType.GENERAL;
			}
			MatchCollection matchCollection = SPECIFICATION_PAT.Matches(fdesc);
			bool flag = false;
			bool flag2 = false;
			foreach (System.Text.RegularExpressions.Match item in matchCollection)
			{
				string value = item.Groups[0].Value;
				if (value.Length > 0)
				{
					switch (value[0])
					{
					case '@':
						return CellFormatType.TEXT;
					case 'D':
					case 'Y':
					case 'd':
					case 'y':
						return CellFormatType.DATE;
					case 'H':
					case 'M':
					case 'S':
					case 'h':
					case 'm':
					case 's':
						flag = true;
						break;
					case '0':
						flag2 = true;
						break;
					case '[':
						return CellFormatType.ELAPSED;
					case '#':
					case '?':
						return CellFormatType.NUMBER;
					}
				}
			}
			if (flag)
			{
				return CellFormatType.DATE;
			}
			if (flag2)
			{
				return CellFormatType.NUMBER;
			}
			return CellFormatType.TEXT;
		}

		private static string QuoteSpecial(string repl, CellFormatType type)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char c in repl)
			{
				if (c == '\'' && type.IsSpecial('\''))
				{
					stringBuilder.Append('\0');
					continue;
				}
				bool flag = type.IsSpecial(c);
				if (flag)
				{
					stringBuilder.Append("'");
				}
				stringBuilder.Append(c);
				if (flag)
				{
					stringBuilder.Append("'");
				}
			}
			return stringBuilder.ToString();
		}

		public CellFormatResult Apply(object value)
		{
			bool flag = Applies(value);
			string text;
			Color empty;
			if (flag)
			{
				text = format.Format(value);
				empty = color;
			}
			else
			{
				text = format.SimpleFormat(value);
				empty = Color.Empty;
			}
			return new CellFormatResult(flag, text, empty);
		}

		public CellFormatResult Apply(Label label, object value)
		{
			CellFormatResult cellFormatResult = Apply(value);
			((Control)label).Text = cellFormatResult.Text;
			if (cellFormatResult.TextColor != Color.Empty)
			{
				((Control)label).ForeColor = cellFormatResult.TextColor;
			}
			return cellFormatResult;
		}

		public static StringBuilder ParseFormat(string fdesc, CellFormatType type, IPartHandler partHandler)
		{
			MatchCollection matchCollection = SPECIFICATION_PAT.Matches(fdesc);
			StringBuilder stringBuilder = new StringBuilder();
			System.Text.RegularExpressions.Match match = null;
			foreach (System.Text.RegularExpressions.Match item in matchCollection)
			{
				string text = Group(item, 0);
				if (text.Length > 0)
				{
					string text2 = partHandler.HandlePart(item, text, type, stringBuilder);
					if (text2 == null)
					{
						text2 = text[0] switch
						{
							'"' => QuoteSpecial(text.Substring(1, text.Length - 2), type), 
							'\\' => QuoteSpecial(text.Substring(1), type), 
							'_' => " ", 
							'*' => ExpandChar(text), 
							_ => text, 
						};
					}
					stringBuilder.Append(text.Replace(item.Captures[0].Value, text2));
					if (item.NextMatch().Index - (item.Index + text.Length) > 0)
					{
						stringBuilder.Append(fdesc.Substring(item.Index + text.Length, item.NextMatch().Index - (item.Index + text.Length)));
					}
					match = item;
				}
			}
			if (match != null)
			{
				stringBuilder.Append(fdesc.Substring(match.Index + match.Groups[0].Value.Length));
			}
			if (type.IsSpecial('\''))
			{
				int startIndex = 0;
				while ((startIndex = stringBuilder.ToString().IndexOf("''", startIndex)) >= 0)
				{
					stringBuilder.Remove(startIndex, 2);
				}
				startIndex = 0;
				while ((startIndex = stringBuilder.ToString().IndexOf("\0", startIndex)) >= 0)
				{
					stringBuilder.Remove(startIndex, 1);
					stringBuilder.Insert(startIndex, "''");
				}
			}
			return stringBuilder;
		}

		public static string QuoteReplacement(string s)
		{
			if (s.IndexOf('\\') == -1 && s.IndexOf('$') == -1)
			{
				return s;
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char c in s)
			{
				if (c == '\\' || c == '$')
				{
					stringBuilder.Append('\\');
				}
				stringBuilder.Append(c);
			}
			return stringBuilder.ToString();
		}

		internal static string ExpandChar(string part)
		{
			char c = part[1];
			return string.Concat(c, c, c);
		}

		public static string Group(System.Text.RegularExpressions.Match m, int g)
		{
			string value = m.Groups[g].Value;
			if (value != null)
			{
				return value;
			}
			return "";
		}

		public override string ToString()
		{
			return format.ToString();
		}
	}
	public class CellElapsedFormatter : CellFormatter
	{
		private class TimeSpec
		{
			internal char type;

			internal int pos;

			internal int len;

			internal double factor;

			internal double modBy;

			public TimeSpec(char type, int pos, int len, double factor)
			{
				this.type = type;
				this.pos = pos;
				this.len = len;
				this.factor = factor;
				modBy = 0.0;
			}

			public long ValueFor(double elapsed)
			{
				double num = ((modBy != 0.0) ? (elapsed / factor % modBy) : (elapsed / factor));
				if (type == '0')
				{
					return (long)Math.Round(num);
				}
				return (long)num;
			}
		}

		private class ElapsedPartHandler : CellFormatPart.IPartHandler
		{
			private CellElapsedFormatter _formatter;

			public ElapsedPartHandler(CellElapsedFormatter formatter)
			{
				_formatter = formatter;
			}

			public string HandlePart(System.Text.RegularExpressions.Match m, string part, CellFormatType type, StringBuilder desc)
			{
				int length = desc.Length;
				switch (part[0])
				{
				case '[':
					if (part.Length >= 3)
					{
						if (_formatter.topmost != null)
						{
							throw new ArgumentException("Duplicate '[' times in format");
						}
						part = part.ToLower();
						int num = part.Length - 2;
						_formatter.topmost = _formatter.AssignSpec(part[1], length, num);
						return part.Substring(1, num);
					}
					break;
				case '0':
				case 'h':
				case 'm':
				case 's':
					part = part.ToLower();
					_formatter.AssignSpec(part[0], length, part.Length);
					return part;
				case '\n':
					return "%n";
				case '"':
					part = part.Substring(1, part.Length - 2);
					break;
				case '\\':
					part = part.Substring(1);
					break;
				case '*':
					if (part.Length > 1)
					{
						part = CellFormatPart.ExpandChar(part);
					}
					break;
				case '_':
					return null;
				}
				return part;
			}
		}

		private const double HOUR__FACTOR = 1.0 / 24.0;

		private const double MIN__FACTOR = 0.0006944444444444444;

		private const double SEC__FACTOR = 1.1574074074074073E-05;

		private List<TimeSpec> specs;

		private TimeSpec topmost;

		private string printfFmt;

		private static readonly Regex PERCENTS = new Regex("%");

		public CellElapsedFormatter(string pattern)
			: base(pattern)
		{
			specs = new List<TimeSpec>();
			StringBuilder stringBuilder = CellFormatPart.ParseFormat(pattern, CellFormatType.ELAPSED, new ElapsedPartHandler(this));
			for (int num = specs.Count - 1; num >= 0; num--)
			{
				TimeSpec timeSpec = specs[num];
				stringBuilder.Remove(timeSpec.pos, timeSpec.len);
				stringBuilder.Insert(timeSpec.pos, "D" + timeSpec.len);
				if (timeSpec.type != topmost.type)
				{
					timeSpec.modBy = modFor(timeSpec.type, timeSpec.len);
				}
			}
			printfFmt = stringBuilder.ToString();
		}

		private TimeSpec AssignSpec(char type, int pos, int len)
		{
			TimeSpec timeSpec = new TimeSpec(type, pos, len, factorFor(type, len));
			specs.Add(timeSpec);
			return timeSpec;
		}

		private static double factorFor(char type, int len)
		{
			return type switch
			{
				'h' => 1.0 / 24.0, 
				'm' => 0.0006944444444444444, 
				's' => 1.1574074074074073E-05, 
				'0' => 1.1574074074074073E-05 / Math.Pow(10.0, len), 
				_ => throw new ArgumentException("Uknown elapsed time spec: " + type), 
			};
		}

		private static double modFor(char type, int len)
		{
			return type switch
			{
				'h' => 24.0, 
				'm' => 60.0, 
				's' => 60.0, 
				'0' => Math.Pow(10.0, len), 
				_ => throw new ArgumentException("Uknown elapsed time spec: " + type), 
			};
		}

		public override void FormatValue(StringBuilder toAppendTo, object value)
		{
			double num = (double)value;
			if (num < 0.0)
			{
				toAppendTo.Append('-');
				num = 0.0 - num;
			}
			long[] array = new long[specs.Count];
			for (int i = 0; i < specs.Count; i++)
			{
				array[i] = specs[i].ValueFor(num);
			}
			string[] array2 = printfFmt.Split(":. []".ToCharArray());
			string empty = string.Empty;
			int num2 = 0;
			int num3 = 0;
			Regex regex = new Regex("D\\d+");
			string[] array3 = array2;
			foreach (string text in array3)
			{
				num2 += text.Length;
				if (num2 < printfFmt.Length)
				{
					empty = printfFmt[num2].ToString();
					num2++;
				}
				else
				{
					empty = string.Empty;
				}
				if (regex.IsMatch(text))
				{
					toAppendTo.Append(array[num3].ToString(text)).Append(empty);
					num3++;
				}
				else
				{
					toAppendTo.Append(text).Append(empty);
				}
			}
		}

		public override void SimpleValue(StringBuilder toAppendTo, object value)
		{
			FormatValue(toAppendTo, value);
		}
	}
	public class CellFormat
	{
		public class GeneralCellFormat : CellFormat
		{
			public GeneralCellFormat()
				: base("General")
			{
			}

			public override CellFormatResult Apply(object value)
			{
				string text = new CellGeneralFormatter().Format(value);
				return new CellFormatResult(applies: true, text, Color.Empty);
			}
		}

		private const string INVALID_VALUE_FOR_FORMAT = "###############################################################################################################################################################################################################################################################";

		private const string QUOTE = "\"";

		private string format;

		private CellFormatPart posNumFmt;

		private CellFormatPart zeroNumFmt;

		private CellFormatPart negNumFmt;

		private CellFormatPart textFmt;

		private int formatPartCount;

		private static readonly Regex ONE_PART = new Regex(CellFormatPart.FORMAT_PAT.ToString() + "(;|$)", RegexOptions.IgnoreCase | RegexOptions.IgnorePatternWhitespace);

		private static readonly CellFormatPart DEFAULT_TEXT_FORMAT = new CellFormatPart("@");

		private static readonly CellFormat GENERAL_FORMAT = new GeneralCellFormat();

		private static Dictionary<string, CellFormat> formatCache = new Dictionary<string, CellFormat>();

		public static CellFormat GetInstance(string format)
		{
			CellFormat cellFormat = null;
			if (formatCache.ContainsKey(format))
			{
				cellFormat = formatCache[format];
			}
			if (cellFormat == null)
			{
				cellFormat = ((!format.Equals("General") && !format.Equals("@")) ? new CellFormat(format) : GENERAL_FORMAT);
				formatCache.Add(format, cellFormat);
			}
			return cellFormat;
		}

		private CellFormat(string format)
		{
			this.format = format;
			MatchCollection matchCollection = ONE_PART.Matches(format);
			List<CellFormatPart> list = new List<CellFormatPart>();
			foreach (System.Text.RegularExpressions.Match item in matchCollection)
			{
				try
				{
					string text = item.Groups[0].Value;
					if (text.EndsWith(";"))
					{
						text = text.Substring(0, text.Length - 1);
					}
					list.Add(new CellFormatPart(text));
				}
				catch (Exception)
				{
					list.Add(null);
				}
			}
			formatPartCount = list.Count;
			switch (formatPartCount)
			{
			case 1:
				posNumFmt = list[0];
				negNumFmt = null;
				zeroNumFmt = null;
				textFmt = DEFAULT_TEXT_FORMAT;
				break;
			case 2:
				posNumFmt = list[0];
				negNumFmt = list[1];
				zeroNumFmt = null;
				textFmt = DEFAULT_TEXT_FORMAT;
				break;
			case 3:
				posNumFmt = list[0];
				negNumFmt = list[1];
				zeroNumFmt = list[2];
				textFmt = DEFAULT_TEXT_FORMAT;
				break;
			default:
				posNumFmt = list[0];
				negNumFmt = list[1];
				zeroNumFmt = list[2];
				textFmt = list[3];
				break;
			}
		}

		public virtual CellFormatResult Apply(object value)
		{
			if (Number.IsNumber(value))
			{
				double.TryParse(value.ToString(), out var result);
				if (result < 0.0 && ((formatPartCount == 2 && !posNumFmt.HasCondition && !negNumFmt.HasCondition) || (formatPartCount == 3 && !negNumFmt.HasCondition) || (formatPartCount == 4 && !negNumFmt.HasCondition)))
				{
					return negNumFmt.Apply(0.0 - result);
				}
				return GetApplicableFormatPart(result).Apply(result);
			}
			if (value is DateTime)
			{
				double excelDate = DateUtil.GetExcelDate((DateTime)value);
				if (DateUtil.IsValidExcelDate(excelDate))
				{
					return GetApplicableFormatPart(excelDate).Apply(value);
				}
				throw new ArgumentException("value not a valid Excel date");
			}
			return textFmt.Apply(value);
		}

		private CellFormatResult Apply(DateTime date, double numericValue)
		{
			return GetApplicableFormatPart(numericValue).Apply(date);
		}

		public CellFormatResult Apply(ICell c)
		{
			switch (UltimateType(c))
			{
			case CellType.Blank:
				return Apply("");
			case CellType.Boolean:
				return Apply(c.BooleanCellValue);
			case CellType.Numeric:
			{
				double numericCellValue = c.NumericCellValue;
				if (GetApplicableFormatPart(numericCellValue).CellFormatType == CellFormatType.DATE)
				{
					if (DateUtil.IsValidExcelDate(numericCellValue))
					{
						return Apply(c.DateCellValue, numericCellValue);
					}
					return Apply("###############################################################################################################################################################################################################################################################");
				}
				return Apply(numericCellValue);
			}
			case CellType.String:
				return Apply(c.StringCellValue);
			default:
				return Apply("?");
			}
		}

		public CellFormatResult Apply(Label label, object value)
		{
			CellFormatResult cellFormatResult = Apply(value);
			((Control)label).Text = cellFormatResult.Text;
			if (cellFormatResult.TextColor != Color.Empty)
			{
				((Control)label).ForeColor = cellFormatResult.TextColor;
			}
			return cellFormatResult;
		}

		private CellFormatResult Apply(Label label, DateTime date, double numericValue)
		{
			CellFormatResult cellFormatResult = Apply(date, numericValue);
			((Control)label).Text = cellFormatResult.Text;
			if (cellFormatResult.TextColor != Color.Empty)
			{
				((Control)label).ForeColor = cellFormatResult.TextColor;
			}
			return cellFormatResult;
		}

		public CellFormatResult Apply(Label label, ICell c)
		{
			switch (UltimateType(c))
			{
			case CellType.Blank:
				return Apply(label, "");
			case CellType.Boolean:
				return Apply(label, c.BooleanCellValue);
			case CellType.Numeric:
			{
				double numericCellValue = c.NumericCellValue;
				if (GetApplicableFormatPart(numericCellValue).CellFormatType == CellFormatType.DATE)
				{
					if (DateUtil.IsValidExcelDate(numericCellValue))
					{
						return Apply(label, c.DateCellValue, numericCellValue);
					}
					return Apply(label, "###############################################################################################################################################################################################################################################################");
				}
				return Apply(label, numericCellValue);
			}
			case CellType.String:
				return Apply(label, c.StringCellValue);
			default:
				return Apply(label, "?");
			}
		}

		private CellFormatPart GetApplicableFormatPart(object value)
		{
			if (Number.IsNumber(value))
			{
				double.TryParse(value.ToString(), out var result);
				if (formatPartCount == 1)
				{
					if (!posNumFmt.HasCondition || (posNumFmt.HasCondition && posNumFmt.Applies(result)))
					{
						return posNumFmt;
					}
					return new CellFormatPart("General");
				}
				if (formatPartCount == 2)
				{
					if ((!posNumFmt.HasCondition && result >= 0.0) || (posNumFmt.HasCondition && posNumFmt.Applies(result)))
					{
						return posNumFmt;
					}
					if (!negNumFmt.HasCondition || (negNumFmt.HasCondition && negNumFmt.Applies(result)))
					{
						return negNumFmt;
					}
					return new CellFormatPart("\"###############################################################################################################################################################################################################################################################\"");
				}
				if ((!posNumFmt.HasCondition && result > 0.0) || (posNumFmt.HasCondition && posNumFmt.Applies(result)))
				{
					return posNumFmt;
				}
				if ((!negNumFmt.HasCondition && result < 0.0) || (negNumFmt.HasCondition && negNumFmt.Applies(result)))
				{
					return negNumFmt;
				}
				return zeroNumFmt;
			}
			throw new ArgumentException("value must be a Number");
		}

		public static CellType UltimateType(ICell cell)
		{
			CellType cellType = cell.CellType;
			if (cellType == CellType.Formula)
			{
				return cell.CachedFormulaResultType;
			}
			return cellType;
		}

		public override bool Equals(object obj)
		{
			if (this == obj)
			{
				return true;
			}
			if (obj is CellFormat)
			{
				CellFormat cellFormat = (CellFormat)obj;
				return format.Equals(cellFormat.format);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return format.GetHashCode();
		}

		public override string ToString()
		{
			return format;
		}
	}
	public abstract class CellFormatCondition
	{
		private class LT_CellFormatCondition : CellFormatCondition
		{
			private double _c;

			public LT_CellFormatCondition(double c)
			{
				_c = c;
			}

			public override bool Pass(double value)
			{
				return value < _c;
			}
		}

		private class LE_CellFormatCondition : CellFormatCondition
		{
			private double _c;

			public LE_CellFormatCondition(double c)
			{
				_c = c;
			}

			public override bool Pass(double value)
			{
				return value <= _c;
			}
		}

		private class GT_CellFormatCondition : CellFormatCondition
		{
			private double _c;

			public GT_CellFormatCondition(double c)
			{
				_c = c;
			}

			public override bool Pass(double value)
			{
				return value > _c;
			}
		}

		private class GE_CellFormatCondition : CellFormatCondition
		{
			private double _c;

			public GE_CellFormatCondition(double c)
			{
				_c = c;
			}

			public override bool Pass(double value)
			{
				return value >= _c;
			}
		}

		private class EQ_CellFormatCondition : CellFormatCondition
		{
			private double _c;

			public EQ_CellFormatCondition(double c)
			{
				_c = c;
			}

			public override bool Pass(double value)
			{
				return value == _c;
			}
		}

		private class NE_CellFormatCondition : CellFormatCondition
		{
			private double _c;

			public NE_CellFormatCondition(double c)
			{
				_c = c;
			}

			public override bool Pass(double value)
			{
				return value != _c;
			}
		}

		private const int LT = 0;

		private const int LE = 1;

		private const int GT = 2;

		private const int GE = 3;

		private const int EQ = 4;

		private const int NE = 5;

		private static Dictionary<string, int> TESTS;

		static CellFormatCondition()
		{
			TESTS = new Dictionary<string, int>();
			TESTS.Add("<", 0);
			TESTS.Add("<=", 1);
			TESTS.Add(">", 2);
			TESTS.Add(">=", 3);
			TESTS.Add("=", 4);
			TESTS.Add("==", 4);
			TESTS.Add("!=", 5);
			TESTS.Add("<>", 5);
		}

		public static CellFormatCondition GetInstance(string opString, string constStr)
		{
			if (!TESTS.ContainsKey(opString))
			{
				throw new ArgumentException("Unknown test: " + opString);
			}
			int num = TESTS[opString];
			double c = double.Parse(constStr, CultureInfo.InvariantCulture);
			return num switch
			{
				0 => new LT_CellFormatCondition(c), 
				1 => new LE_CellFormatCondition(c), 
				2 => new GT_CellFormatCondition(c), 
				3 => new GE_CellFormatCondition(c), 
				4 => new EQ_CellFormatCondition(c), 
				5 => new NE_CellFormatCondition(c), 
				_ => throw new ArgumentException("Cannot create for test number " + num + "(\"" + opString + "\")"), 
			};
		}

		public abstract bool Pass(double value);
	}
