namespace NPOI.SS.Formula.Functions
{
	public class EDate : FreeRefFunction
	{
		public static FreeRefFunction Instance = new EDate();

		internal EDate()
		{
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length != 2)
			{
				return ErrorEval.VALUE_INVALID;
			}
			try
			{
				double value = GetValue(args[0]);
				int months = (int)GetValue(args[1]);
				DateTime date = DateUtil.GetJavaDate(value).AddMonths(months);
				double excelDate = DateUtil.GetExcelDate(date);
				NumericFunction.CheckValue(excelDate);
				return new NumberEval(excelDate);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		private double GetValue(ValueEval arg)
		{
			if (arg is NumberEval)
			{
				return ((NumberEval)arg).NumberValue;
			}
			if (arg is BlankEval)
			{
				return 0.0;
			}
			if (arg is RefEval)
			{
				RefEval refEval = (RefEval)arg;
				if (refEval.NumberOfSheets > 1)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
				ValueEval innerValueEval = refEval.GetInnerValueEval(refEval.FirstSheetIndex);
				if (innerValueEval is NumberEval)
				{
					return ((NumberEval)innerValueEval).NumberValue;
				}
				if (innerValueEval is BlankEval)
				{
					return 0.0;
				}
			}
			throw new EvaluationException(ErrorEval.VALUE_INVALID);
		}
	}
}
namespace NPOI.SS.Formula.Constant
{
	public class ConstantValueParser
	{
		private const int TYPE_EMPTY = 0;

		private const int TYPE_NUMBER = 1;

		private const int TYPE_STRING = 2;

		private const int TYPE_BOOLEAN = 4;

		private const int TYPE_ERROR_CODE = 16;

		private const int TRUE_ENCODING = 1;

		private const int FALSE_ENCODING = 0;

		private const object EMPTY_REPRESENTATION = null;

		private ConstantValueParser()
		{
		}

		public static object[] Parse(ILittleEndianInput in1, int nValues)
		{
			object[] array = new object[nValues];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = ReadAConstantValue(in1);
			}
			return array;
		}

		private static object ReadAConstantValue(ILittleEndianInput in1)
		{
			byte b = (byte)in1.ReadByte();
			switch (b)
			{
			case 0:
				in1.ReadLong();
				return null;
			case 1:
				return in1.ReadDouble();
			case 2:
				return StringUtil.ReadUnicodeString(in1);
			case 4:
				return ReadBoolean(in1);
			case 16:
			{
				int errorCode = in1.ReadUShort();
				in1.ReadUShort();
				in1.ReadInt();
				return ErrorConstant.ValueOf(errorCode);
			}
			default:
				throw new Exception("Unknown grbit value (" + b + ")");
			}
		}

		private static object ReadBoolean(ILittleEndianInput in1)
		{
			byte b = (byte)in1.ReadLong();
			return b switch
			{
				0 => false, 
				1 => true, 
				_ => throw new Exception("unexpected bool encoding (" + b + ")"), 
			};
		}

		public static int GetEncodedSize(System.Array values)
		{
			int num = values.Length;
			for (int i = 0; i < values.Length; i++)
			{
				num += GetEncodedSize(values.GetValue(i));
			}
			return num;
		}

		private static int GetEncodedSize(object obj)
		{
			if (obj == null)
			{
				return 8;
			}
			Type type = obj.GetType();
			if (type == typeof(bool) || type == typeof(double) || type == typeof(ErrorConstant))
			{
				return 8;
			}
			string value = (string)obj;
			return StringUtil.GetEncodedSize(value);
		}

		public static void Encode(ILittleEndianOutput out1, System.Array values)
		{
			for (int i = 0; i < values.Length; i++)
			{
				EncodeSingleValue(out1, values.GetValue(i));
			}
		}

		private static void EncodeSingleValue(ILittleEndianOutput out1, object value)
		{
			if (value == null)
			{
				out1.WriteByte(0);
				out1.WriteLong(0L);
				return;
			}
			if (value is bool flag)
			{
				out1.WriteByte(4);
				long v = (flag ? 1 : 0);
				out1.WriteLong(v);
				return;
			}
			if (value is double v2)
			{
				out1.WriteByte(1);
				out1.WriteDouble(v2);
				return;
			}
			if (value is string)
			{
				string value2 = (string)value;
				out1.WriteByte(2);
				StringUtil.WriteUnicodeString(out1, value2);
				return;
			}
			if (value is ErrorConstant)
			{
				ErrorConstant errorConstant = (ErrorConstant)value;
				out1.WriteByte(16);
				long v3 = errorConstant.ErrorCode;
				out1.WriteLong(v3);
				return;
			}
			throw new Exception("Unexpected value type (" + value.GetType().Name + "'");
		}
	}
	public class ErrorConstant
	{
		private static readonly ErrorConstant NULL = new ErrorConstant(0);

		private static readonly ErrorConstant DIV_0 = new ErrorConstant(7);

		private static readonly ErrorConstant VALUE = new ErrorConstant(15);

		private static readonly ErrorConstant REF = new ErrorConstant(23);

		private static readonly ErrorConstant NAME = new ErrorConstant(29);

		private static readonly ErrorConstant NUM = new ErrorConstant(36);

		private static readonly ErrorConstant NA = new ErrorConstant(42);

		private int _errorCode;

		public int ErrorCode => _errorCode;

		public string Text
		{
			get
			{
				if (HSSFErrorConstants.IsValidCode(_errorCode))
				{
					return HSSFErrorConstants.GetText(_errorCode);
				}
				return "unknown error code (" + _errorCode + ")";
			}
		}

		private ErrorConstant(int errorCode)
		{
			_errorCode = errorCode;
		}

		public static ErrorConstant ValueOf(int errorCode)
		{
			switch (errorCode)
			{
			case 0:
				return NULL;
			case 7:
				return DIV_0;
			case 15:
				return VALUE;
			case 23:
				return REF;
			case 29:
				return NAME;
			case 36:
				return NUM;
			case 42:
				return NA;
			default:
				Console.Error.WriteLine("Warning - Unexpected error code (" + errorCode + ")");
				return new ErrorConstant(errorCode);
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(64);
			stringBuilder.Append(GetType().Name).Append(" [");
			stringBuilder.Append(Text);
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}
	}
