	public class Biff8DecryptingStream : BiffHeaderInput, ILittleEndianInput
	{
		private ILittleEndianInput _le;

		private Biff8RC4 _rc4;

		public Biff8DecryptingStream(Stream in1, int InitialOffSet, Biff8EncryptionKey key)
		{
			_rc4 = new Biff8RC4(InitialOffSet, key);
			if (in1 is ILittleEndianInput)
			{
				_le = (ILittleEndianInput)in1;
			}
			else
			{
				_le = new LittleEndianInputStream(in1);
			}
		}

		public int Available()
		{
			return _le.Available();
		}

		public int ReadRecordSID()
		{
			int num = _le.ReadUShort();
			_rc4.SkipTwoBytes();
			_rc4.StartRecord(num);
			return num;
		}

		public int ReadDataSize()
		{
			int result = _le.ReadUShort();
			_rc4.SkipTwoBytes();
			return result;
		}

		public double ReadDouble()
		{
			long value = ReadLong();
			double num = BitConverter.Int64BitsToDouble(value);
			if (double.IsNaN(num))
			{
				throw new Exception("Did not expect to read NaN");
			}
			return num;
		}

		public void ReadFully(byte[] buf)
		{
			ReadFully(buf, 0, buf.Length);
		}

		public void ReadFully(byte[] buf, int off, int len)
		{
			_le.ReadFully(buf, off, len);
			_rc4.Xor(buf, off, len);
		}

		public int ReadUByte()
		{
			return _rc4.XorByte(_le.ReadUByte());
		}

		public int ReadByte()
		{
			return _rc4.XorByte(_le.ReadUByte());
		}

		public int ReadUShort()
		{
			return _rc4.Xorshort(_le.ReadUShort());
		}

		public short ReadShort()
		{
			return (short)_rc4.Xorshort(_le.ReadUShort());
		}

		public int ReadInt()
		{
			return _rc4.XorInt(_le.ReadInt());
		}

		public long ReadLong()
		{
			return _rc4.XorLong(_le.ReadLong());
		}
	}
	public class Biff8EncryptionKey
	{
		private const int KEY_DIGEST_LENGTH = 5;

		private const int PASSWORD_HASH_NUMBER_OF_BYTES_USED = 5;

		private byte[] _keyDigest;

		[ThreadStatic]
		private static string _userPasswordTLS;

		public static string CurrentUserPassword
		{
			get
			{
				return _userPasswordTLS;
			}
			set
			{
				_userPasswordTLS = value;
			}
		}

		public static Biff8EncryptionKey Create(byte[] docId)
		{
			return new Biff8EncryptionKey(CreateKeyDigest("VelvetSweatshop", docId));
		}

		public static Biff8EncryptionKey Create(string password, byte[] docIdData)
		{
			return new Biff8EncryptionKey(CreateKeyDigest(password, docIdData));
		}

		internal Biff8EncryptionKey(byte[] keyDigest)
		{
			if (keyDigest.Length != 5)
			{
				throw new ArgumentException("Expected 5 byte key digest, but got " + HexDump.ToHex(keyDigest));
			}
			_keyDigest = keyDigest;
		}

		internal static byte[] CreateKeyDigest(string password, byte[] docIdData)
		{
			Check16Bytes(docIdData, "docId");
			int num = Math.Min(password.Length, 16);
			byte[] array = new byte[num * 2];
			for (int i = 0; i < num; i++)
			{
				char c = password[i];
				array[i * 2] = (byte)(c & 0xFFu);
				array[i * 2 + 1] = (byte)(((uint)c << 8) & 0xFFu);
			}
			using MD5 mD = new MD5CryptoServiceProvider();
			byte[] sourceArray = mD.ComputeHash(array);
			mD.Initialize();
			byte[] array2 = new byte[80 + docIdData.Length * 16];
			int num2 = 0;
			for (int j = 0; j < 16; j++)
			{
				System.Array.Copy(sourceArray, 0, array2, num2, 5);
				num2 += 5;
				System.Array.Copy(docIdData, 0, array2, num2, docIdData.Length);
				num2 += docIdData.Length;
			}
			byte[] sourceArray2 = mD.ComputeHash(array2);
			byte[] array3 = new byte[5];
			System.Array.Copy(sourceArray2, 0, array3, 0, 5);
			mD.Clear();
			return array3;
		}

		public bool Validate(byte[] saltData, byte[] saltHash)
		{
			Check16Bytes(saltData, "saltData");
			Check16Bytes(saltHash, "saltHash");
			RC4 rC = CreateRC4(0);
			byte[] array = new byte[saltData.Length];
			System.Array.Copy(saltData, array, saltData.Length);
			rC.Encrypt(array);
			byte[] array2 = new byte[saltHash.Length];
			System.Array.Copy(saltHash, array2, saltHash.Length);
			rC.Encrypt(array2);
			using MD5 mD = new MD5CryptoServiceProvider();
			byte[] b = mD.ComputeHash(array);
			return Arrays.Equals(array2, b);
		}

		private static byte[] xor(byte[] a, byte[] b)
		{
			byte[] array = new byte[a.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = (byte)(a[i] ^ b[i]);
			}
			return array;
		}

		private static void Check16Bytes(byte[] data, string argName)
		{
			if (data.Length != 16)
			{
				throw new ArgumentException("Expected 16 byte " + argName + ", but got " + HexDump.ToHex(data));
			}
		}

		internal RC4 CreateRC4(int keyBlockNo)
		{
			using MD5 mD = new MD5CryptoServiceProvider();
			using MemoryStream memoryStream = new MemoryStream(4);
			new LittleEndianOutputStream(memoryStream).WriteInt(keyBlockNo);
			byte[] array = memoryStream.ToArray();
			byte[] array2 = new byte[array.Length + _keyDigest.Length];
			System.Array.Copy(_keyDigest, 0, array2, 0, _keyDigest.Length);
			System.Array.Copy(array, 0, array2, _keyDigest.Length, array.Length);
			byte[] key = mD.ComputeHash(array2);
			return new RC4(key);
		}
	}
	public class Biff8RC4
	{
		private const int RC4_REKEYING_INTERVAL = 1024;

		private RC4 _rc4;

		private int _streamPos;

		private int _nextRC4BlockStart;

		private int _currentKeyIndex;

		private bool _shouldSkipEncryptionOnCurrentRecord;

		private Biff8EncryptionKey _key;

		public Biff8RC4(int InitialOffset, Biff8EncryptionKey key)
		{
			if (InitialOffset >= 1024)
			{
				throw new Exception("InitialOffset (" + InitialOffset + ")>" + 1024 + " not supported yet");
			}
			_key = key;
			_streamPos = 0;
			RekeyForNextBlock();
			_streamPos = InitialOffset;
			for (int num = InitialOffset; num > 0; num--)
			{
				_rc4.Output();
			}
			_shouldSkipEncryptionOnCurrentRecord = false;
		}

		private void RekeyForNextBlock()
		{
			_currentKeyIndex = _streamPos / 1024;
			_rc4 = _key.CreateRC4(_currentKeyIndex);
			_nextRC4BlockStart = (_currentKeyIndex + 1) * 1024;
		}

		private int GetNextRC4Byte()
		{
			if (_streamPos >= _nextRC4BlockStart)
			{
				RekeyForNextBlock();
			}
			byte b = _rc4.Output();
			_streamPos++;
			if (_shouldSkipEncryptionOnCurrentRecord)
			{
				return 0;
			}
			return b & 0xFF;
		}

		public void StartRecord(int currentSid)
		{
			_shouldSkipEncryptionOnCurrentRecord = IsNeverEncryptedRecord(currentSid);
		}

		private static bool IsNeverEncryptedRecord(int sid)
		{
			if (sid == 47 || sid == 225 || sid == 2057)
			{
				return true;
			}
			return false;
		}

		public void SkipTwoBytes()
		{
			GetNextRC4Byte();
			GetNextRC4Byte();
		}

		public void Xor(byte[] buf, int pOffSet, int pLen)
		{
			int num = _nextRC4BlockStart - _streamPos;
			if (pLen <= num)
			{
				_rc4.Encrypt(buf, pOffSet, pLen);
				_streamPos += pLen;
				return;
			}
			int num2 = pOffSet;
			int num3 = pLen;
			if (num3 > num)
			{
				if (num > 0)
				{
					_rc4.Encrypt(buf, num2, num);
					_streamPos += num;
					num2 += num;
					num3 -= num;
				}
				RekeyForNextBlock();
			}
			while (num3 > 1024)
			{
				_rc4.Encrypt(buf, num2, 1024);
				_streamPos += 1024;
				num2 += 1024;
				num3 -= 1024;
				RekeyForNextBlock();
			}
			_rc4.Encrypt(buf, num2, num3);
			_streamPos += num3;
		}

		public int XorByte(int rawVal)
		{
			int nextRC4Byte = GetNextRC4Byte();
			return (byte)(rawVal ^ nextRC4Byte);
		}

		public int Xorshort(int rawVal)
		{
			int nextRC4Byte = GetNextRC4Byte();
			int nextRC4Byte2 = GetNextRC4Byte();
			int num = (nextRC4Byte2 << 8) + nextRC4Byte;
			return rawVal ^ num;
		}

		public int XorInt(int rawVal)
		{
			int nextRC4Byte = GetNextRC4Byte();
			int nextRC4Byte2 = GetNextRC4Byte();
			int nextRC4Byte3 = GetNextRC4Byte();
			int nextRC4Byte4 = GetNextRC4Byte();
			int num = (nextRC4Byte4 << 24) + (nextRC4Byte3 << 16) + (nextRC4Byte2 << 8) + nextRC4Byte;
			return rawVal ^ num;
		}

		public long XorLong(long rawVal)
		{
			int nextRC4Byte = GetNextRC4Byte();
			int nextRC4Byte2 = GetNextRC4Byte();
			int nextRC4Byte3 = GetNextRC4Byte();
			int nextRC4Byte4 = GetNextRC4Byte();
			int nextRC4Byte5 = GetNextRC4Byte();
			int nextRC4Byte6 = GetNextRC4Byte();
			int nextRC4Byte7 = GetNextRC4Byte();
			int nextRC4Byte8 = GetNextRC4Byte();
			long num = ((long)nextRC4Byte8 << 56) + ((long)nextRC4Byte7 << 48) + ((long)nextRC4Byte6 << 40) + ((long)nextRC4Byte5 << 32) + ((long)nextRC4Byte4 << 24) + (nextRC4Byte3 << 16) + (nextRC4Byte2 << 8) + nextRC4Byte;
			return rawVal ^ num;
		}
	}
	internal class RC4
	{
		private int _i;

		private int _j;

		private byte[] _s = new byte[256];

		public RC4(byte[] key)
		{
			int num = key.Length;
			for (int i = 0; i < 256; i++)
			{
				_s[i] = (byte)i;
			}
			int j = 0;
			int num2 = 0;
			for (; j < 256; j++)
			{
				num2 = (num2 + key[j % num] + _s[j]) & 0xFF;
				byte b = _s[j];
				_s[j] = _s[num2];
				_s[num2] = b;
			}
			_i = 0;
			_j = 0;
		}

		public byte Output()
		{
			_i = (_i + 1) & 0xFF;
			_j = (_j + _s[_i]) & 0xFF;
			byte b = _s[_i];
			_s[_i] = _s[_j];
			_s[_j] = b;
			return _s[(_s[_i] + _s[_j]) & 0xFF];
		}

		public void Encrypt(byte[] in1)
		{
			for (int i = 0; i < in1.Length; i++)
			{
				in1[i] ^= Output();
			}
		}

		public void Encrypt(byte[] in1, int OffSet, int len)
		{
			int num = OffSet + len;
			for (int i = OffSet; i < num; i++)
			{
				in1[i] ^= Output();
			}
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(GetType().Name).Append(" [");
			stringBuilder.Append("i=").Append(_i);
			stringBuilder.Append(" j=").Append(_j);
			stringBuilder.Append("]");
			stringBuilder.Append("\n");
			stringBuilder.Append(HexDump.Dump(_s, 0L, 0));
			return stringBuilder.ToString();
		}
	}
