				List<EscherRecord> list = base.EscherRecords;
				int escherRecordSize = GetEscherRecordSize(list);
				byte[] data = new byte[escherRecordSize];
				List<int> list2 = new List<int>();
				int num2 = 0;
				foreach (EscherRecord item in list)
				{
					num2 += item.Serialize(num2, data, new RecordSizeListener(list2, item));
				}
				list2.Insert(0, 0);
				for (int i = 1; i < list2.Count; i++)
				{
					if (i == list2.Count - 1 && list2[i] < num2)
					{
						num += 4;
					}
					if (list2[i] - list2[i - 1] > 8224)
					{
						num += (list2[i] - list2[i - 1]) / 8224 * 4;
					}
				}
				int num3 = escherRecordSize + shapeToObj.Count * 4;
				if (escherRecordSize != 0 && list2.Count == 1)
				{
					num += 4;
				}
				int num4 = 0;
				foreach (Record value in shapeToObj.Values)
				{
					num4 += value.RecordSize;
				}
				int num5 = 0;
				foreach (NoteRecord value2 in tailRec.Values)
				{
					num5 += value2.RecordSize;
				}
				return num3 + num4 + num5 + num;
			}
		}

