	public class ExtSSTRecord : ContinuableRecord
	{
		public const short DEFAULT_BUCKET_SIZE = 8;

		public const int MAX_BUCKETS = 128;

		public const short sid = 255;

		private short field_1_strings_per_bucket = 8;

		private InfoSubRecord[] _sstInfos;

		public short NumStringsPerBucket
		{
			get
			{
				return field_1_strings_per_bucket;
			}
			set
			{
				field_1_strings_per_bucket = value;
			}
		}

		internal int DataSize => 2 + 8 * _sstInfos.Length;

		internal InfoSubRecord[] InfoSubRecords => _sstInfos;

		public override short Sid => 255;

		public ExtSSTRecord()
		{
			_sstInfos = new InfoSubRecord[0];
		}

		public ExtSSTRecord(RecordInputStream in1)
		{
			field_1_strings_per_bucket = in1.ReadShort();
			int capacity = in1.Remaining / 8;
			List<InfoSubRecord> list = new List<InfoSubRecord>(capacity);
			while (in1.Available() > 0)
			{
				InfoSubRecord item = new InfoSubRecord(in1);
				list.Add(item);
				if (in1.Available() == 0 && in1.HasNextRecord && in1.GetNextSid() == 60)
				{
					in1.NextRecord();
				}
			}
			_sstInfos = list.ToArray();
		}

		public IEnumerator GetEnumerator()
		{
			return _sstInfos.GetEnumerator();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[EXTSST]\n");
			stringBuilder.Append("    .dsst           = ").Append(StringUtil.ToHexString(NumStringsPerBucket)).Append("\n");
			stringBuilder.Append("    .numInfoRecords = ").Append(_sstInfos.Length).Append("\n");
			for (int i = 0; i < _sstInfos.Length; i++)
			{
				stringBuilder.Append("    .inforecord     = ").Append(i).Append("\n");
				stringBuilder.Append("    .streampos      = ").Append(StringUtil.ToHexString(_sstInfos[i].StreamPos)).Append("\n");
				stringBuilder.Append("    .sstoffset      = ").Append(StringUtil.ToHexString(_sstInfos[i].BucketSSTOffset)).Append("\n");
			}
			stringBuilder.Append("[/EXTSST]\n");
			return stringBuilder.ToString();
		}

		protected override void Serialize(ContinuableRecordOutput out1)
		{
			out1.WriteShort(field_1_strings_per_bucket);
			for (int i = 0; i < _sstInfos.Length; i++)
			{
				_sstInfos[i].Serialize(out1);
			}
		}

		public static int GetNumberOfInfoRecsForStrings(int numStrings)
		{
			int num = numStrings / 8;
			if (numStrings % 8 != 0)
			{
				num++;
			}
			if (num > 128)
			{
				num = 128;
			}
			return num;
		}

		public static int GetRecordSizeForStrings(int numStrings)
		{
			return 6 + GetNumberOfInfoRecsForStrings(numStrings) * 8;
		}

		public void SetBucketOffsets(int[] bucketAbsoluteOffsets, int[] bucketRelativeOffsets)
		{
			_sstInfos = new InfoSubRecord[bucketAbsoluteOffsets.Length];
			for (int i = 0; i < bucketAbsoluteOffsets.Length; i++)
			{
				_sstInfos[i] = new InfoSubRecord(bucketAbsoluteOffsets[i], bucketRelativeOffsets[i]);
			}
		}
	}
	public class FilePassRecord : StandardRecord
	{
		public const short sid = 47;

		private const int ENCRYPTION_XOR = 0;

		private const int ENCRYPTION_OTHER = 1;

		private const int ENCRYPTION_OTHER_RC4 = 1;

		private const int ENCRYPTION_OTHER_CAPI_2 = 2;

		private const int ENCRYPTION_OTHER_CAPI_3 = 3;

		private int _encryptionType;

		private int _encryptionInfo;

		private int _minorVersionNo;

		private byte[] _docId;

		private byte[] _saltData;

		private byte[] _saltHash;

		protected override int DataSize => 54;

		public byte[] DocId
		{
			get
			{
				return _docId;
			}
			set
			{
			}
		}

		public byte[] SaltData => _saltData;

		public byte[] SaltHash => _saltHash;

		public override short Sid => 47;

		public FilePassRecord()
		{
		}

		public FilePassRecord(RecordInputStream in1)
		{
			_encryptionType = in1.ReadUShort();
			switch (_encryptionType)
			{
			case 0:
				throw new RecordFormatException("HSSF does not currently support XOR obfuscation");
			default:
				throw new RecordFormatException("Unknown encryption type " + _encryptionType);
			case 1:
				_encryptionInfo = in1.ReadUShort();
				switch (_encryptionInfo)
				{
				case 2:
				case 3:
					throw new RecordFormatException("HSSF does not currently support CryptoAPI encryption");
				default:
					throw new RecordFormatException("Unknown encryption info " + _encryptionInfo);
				case 1:
					_minorVersionNo = in1.ReadUShort();
					if (_minorVersionNo != 1)
					{
						throw new RecordFormatException("Unexpected VersionInfo number for RC4Header " + _minorVersionNo);
					}
					_docId = Read(in1, 16);
					_saltData = Read(in1, 16);
					_saltHash = Read(in1, 16);
					break;
				}
				break;
			}
		}

		private static byte[] Read(RecordInputStream in1, int size)
		{
			byte[] array = new byte[size];
			in1.ReadFully(array);
			return array;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[FILEPASS]\n");
			stringBuilder.Append("    .type = ").Append(HexDump.ShortToHex(_encryptionType)).Append("\n");
			stringBuilder.Append("    .info = ").Append(HexDump.ShortToHex(_encryptionInfo)).Append("\n");
			stringBuilder.Append("    .ver  = ").Append(HexDump.ShortToHex(_minorVersionNo)).Append("\n");
			stringBuilder.Append("    .docId= ").Append(HexDump.ToHex(_docId)).Append("\n");
			stringBuilder.Append("    .salt = ").Append(HexDump.ToHex(_saltData)).Append("\n");
			stringBuilder.Append("    .hash = ").Append(HexDump.ToHex(_saltHash)).Append("\n");
			stringBuilder.Append("[/FILEPASS]\n");
			return stringBuilder.ToString();
		}

		public override void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteShort(_encryptionType);
			out1.WriteShort(_encryptionInfo);
			out1.WriteShort(_minorVersionNo);
			out1.Write(_docId);
			out1.Write(_saltData);
			out1.Write(_saltHash);
		}

		public override object Clone()
		{
			return this;
		}
	}
	public class FileSharingRecord : StandardRecord
	{
		public const short sid = 91;

		private short field_1_Readonly;

		private short field_2_password;

		private byte field_3_username_unicode_options;

		private string field_3_username_value;

		public short ReadOnly
		{
			get
			{
				return field_1_Readonly;
			}
			set
			{
				field_1_Readonly = value;
			}
		}

		public short Password
		{
			get
			{
				return field_2_password;
			}
			set
			{
				field_2_password = value;
			}
		}

		public string Username
		{
			get
			{
				return field_3_username_value;
			}
			set
			{
				field_3_username_value = value;
			}
		}

		protected override int DataSize
		{
			get
			{
				int length = field_3_username_value.Length;
				if (length < 1)
				{
					return 6;
				}
				return 7 + length;
			}
		}

		public override short Sid => 91;

		public FileSharingRecord()
		{
		}

		public FileSharingRecord(RecordInputStream in1)
		{
			field_1_Readonly = in1.ReadShort();
			field_2_password = in1.ReadShort();
			int num = in1.ReadShort();
			if (num > 0)
			{
				field_3_username_unicode_options = (byte)in1.ReadByte();
				field_3_username_value = in1.ReadCompressedUnicode(num);
				if (field_3_username_value == null)
				{
					field_3_username_value = "";
				}
			}
			else
			{
				field_3_username_value = "";
			}
		}

		public static short HashPassword(string password)
		{
			byte[] bytes = Encoding.UTF8.GetBytes(password);
			int num = 0;
			if (bytes.Length > 0)
			{
				int num2 = bytes.Length;
				while (num2-- > 0)
				{
					num = ((num >> 14) & 1) | ((num << 1) & 0x7FFF);
					num ^= bytes[num2];
				}
				num = ((num >> 14) & 1) | ((num << 1) & 0x7FFF);
				num ^= bytes.Length;
				num ^= 0xCE4B;
			}
			return (short)num;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[FILESHARING]\n");
			stringBuilder.Append("    .Readonly       = ").Append((ReadOnly == 1) ? "true" : "false").Append("\n");
			stringBuilder.Append("    .password       = ").Append(StringUtil.ToHexString(Password)).Append("\n");
			stringBuilder.Append("    .username       = ").Append(Username).Append("\n");
			stringBuilder.Append("[/FILESHARING]\n");
			return stringBuilder.ToString();
		}

		public override void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteShort(ReadOnly);
			out1.WriteShort(Password);
			out1.WriteShort(field_3_username_value.Length);
			if (field_3_username_value.Length > 0)
			{
				out1.WriteByte(field_3_username_unicode_options);
				StringUtil.PutCompressedUnicode(Username, out1);
			}
		}

		public override object Clone()
		{
			FileSharingRecord fileSharingRecord = new FileSharingRecord();
			fileSharingRecord.ReadOnly = field_1_Readonly;
			fileSharingRecord.Password = field_2_password;
			fileSharingRecord.Username = field_3_username_value;
			return fileSharingRecord;
		}
	}
