			string value;
			string value2;
			if (Sid == 27)
			{
				text = "HORIZONTALPAGEBREAK";
				value = "row";
				value2 = "col";
			}
			else
			{
				text = "VERTICALPAGEBREAK";
				value = "column";
				value2 = "row";
			}
			stringBuilder.Append("[" + text + "]").Append("\n");
			stringBuilder.Append("     .Sid        =").Append(Sid).Append("\n");
