					.Append("\n");
				stringBuilder.Append("     .").Append(value2).Append("To      =")
					.Append(@break.subTo)
					.Append("\n");
			}
			stringBuilder.Append("[" + text + "]").Append("\n");
			return stringBuilder.ToString();
