			}
			field_2_first_row = in1.ReadInt();
			field_3_last_row_add1 = in1.ReadInt();
			field_4_zero = in1.ReadInt();
			int num = in1.Remaining / 4;
			field_5_dbcells = new IntList(num);
			for (int i = 0; i < num; i++)
			{
