		public static void SetCapacity(int capacity)
		{
			NUM_RECORDS = capacity;
		}

		public static List<Record> CreateRecords(Stream in1)
		{
			List<Record> list = new List<Record>(NUM_RECORDS);
			RecordFactoryInputStream recordFactoryInputStream = new RecordFactoryInputStream(in1, shouldIncludeContinueRecords: true);
			Record item;
			while ((item = recordFactoryInputStream.NextRecord()) != null)
			{
				list.Add(item);
			}
			return list;
		}

		[Obsolete]
		private static void AddAll(List<Record> destList, Record[] srcRecs)
		{
			for (int i = 0; i < srcRecs.Length; i++)
			{
				destList.Add(srcRecs[i]);
			}
		}

		public static Record[] CreateRecord(RecordInputStream in1)
		{
			Record record = CreateSingleRecord(in1);
			if (record is DBCellRecord)
			{
				return new Record[1];
			}
			if (record is RKRecord)
			{
				return new Record[1] { ConvertToNumberRecord((RKRecord)record) };
			}
			if (record is MulRKRecord)
			{
				return ConvertRKRecords((MulRKRecord)record);
			}
			return new Record[1] { record };
		}

		public static BlankRecord[] ConvertBlankRecords(MulBlankRecord mbk)
		{
			BlankRecord[] array = new BlankRecord[mbk.NumColumns];
			for (int i = 0; i < mbk.NumColumns; i++)
			{
				BlankRecord blankRecord = new BlankRecord();
				blankRecord.Column = i + mbk.FirstColumn;
				blankRecord.Row = mbk.Row;
				blankRecord.XFIndex = mbk.GetXFAt(i);
				array[i] = blankRecord;
			}
			return array;
		}

		public static Record CreateSingleRecord(RecordInputStream in1)
		{
			if (_recordCreatorsById.ContainsKey(in1.Sid))
			{
				I_RecordCreator i_RecordCreator = _recordCreatorsById[in1.Sid];
				return i_RecordCreator.Create(in1);
			}
			return new UnknownRecord(in1);
		}

		public static NumberRecord ConvertToNumberRecord(RKRecord rk)
		{
			NumberRecord numberRecord = new NumberRecord();
			numberRecord.Column = rk.Column;
			numberRecord.Row = rk.Row;
			numberRecord.XFIndex = rk.XFIndex;
			numberRecord.Value = rk.RKNumber;
			return numberRecord;
		}

		public static NumberRecord[] ConvertRKRecords(MulRKRecord mrk)
		{
			NumberRecord[] array = new NumberRecord[mrk.NumColumns];
			for (int i = 0; i < mrk.NumColumns; i++)
			{
				NumberRecord numberRecord = new NumberRecord();
				numberRecord.Column = (short)(i + mrk.FirstColumn);
				numberRecord.Row = mrk.Row;
				numberRecord.XFIndex = mrk.GetXFAt(i);
				numberRecord.Value = mrk.GetRKNumberAt(i);
				array[i] = numberRecord;
			}
			return array;
		}

		public static short[] GetAllKnownRecordSIDs()
		{
			if (_allKnownRecordSIDs == null)
			{
				short[] array = new short[_recordCreatorsById.Count];
				int num = 0;
				foreach (KeyValuePair<short, I_RecordCreator> item in _recordCreatorsById)
				{
					array[num++] = item.Key;
				}
				System.Array.Sort(array);
				_allKnownRecordSIDs = array;
			}
			return (short[])_allKnownRecordSIDs.Clone();
		}

		private static Dictionary<short, I_RecordCreator> RecordsToMap(Type[] records)
		{
			Dictionary<short, I_RecordCreator> dictionary = new Dictionary<short, I_RecordCreator>();
			Hashtable hashtable = new Hashtable(records.Length * 3 / 2);
			foreach (Type type in records)
			{
				if (!typeof(Record).IsAssignableFrom(type))
				{
					throw new Exception("Invalid record sub-class (" + type.Name + ")");
				}
				if (type.IsAbstract)
				{
					throw new Exception("Invalid record class (" + type.Name + ") - must not be abstract");
				}
				if (hashtable.Contains(type))
				{
					throw new Exception("duplicate record class (" + type.Name + ")");
				}
				hashtable.Add(type, type);
				short num = 0;
				try
				{
					num = (short)type.GetField("sid").GetValue(null);
				}
				catch (Exception ex)
				{
					throw new RecordFormatException("Unable to determine record types", ex);
				}
				if (dictionary.ContainsKey(num))
				{
					Type recordClass = dictionary[num].GetRecordClass();
					throw new RuntimeException("duplicate record sid 0x" + num.ToString("X", CultureInfo.CurrentCulture) + " for classes (" + type.Name + ") and (" + recordClass.Name + ")");
				}
				dictionary[num] = GetRecordCreator(type);
			}
			return dictionary;
		}

		[Obsolete]
		private static void CheckZeros(Stream in1, int avail)
		{
			int num = 0;
			while (true)
			{
				int num2 = in1.ReadByte();
				if (num2 < 0)
				{
					break;
				}
				if (num2 != 0)
				{
					Console.Error.WriteLine(HexDump.ByteToHex(num2));
				}
				num++;
			}
			if (avail != num)
			{
				Console.Error.WriteLine("avail!=count (" + avail + "!=" + num + ").");
			}
		}

		private static I_RecordCreator GetRecordCreator(Type recClass)
		{
			try
			{
				ConstructorInfo constructor = recClass.GetConstructor(CONSTRUCTOR_ARGS);
				if (constructor != null)
				{
					return new ReflectionConstructorRecordCreator(constructor);
				}
			}
			catch (Exception)
			{
			}
			try
			{
				MethodInfo method = recClass.GetMethod("Create", CONSTRUCTOR_ARGS);
				return new ReflectionMethodRecordCreator(method);
			}
			catch (Exception)
			{
				throw new RuntimeException("Failed to find constructor or create method for (" + recClass.Name + ").");
			}
		}
	}
	public class RecordFactoryInputStream
	{
		private class StreamEncryptionInfo
		{
			private int _InitialRecordsSize;

			private FilePassRecord _filePassRec;

			private Record _lastRecord;

			private bool _hasBOFRecord;

			public bool HasEncryption => _filePassRec != null;

			public Record LastRecord => _lastRecord;

			public bool HasBOFRecord => _hasBOFRecord;

			public StreamEncryptionInfo(RecordInputStream rs, List<Record> outputRecs)
			{
				rs.NextRecord();
				int num = 4 + rs.Remaining;
				Record record = RecordFactory.CreateSingleRecord(rs);
				outputRecs.Add(record);
				FilePassRecord filePassRec = null;
				if (record is BOFRecord)
				{
					_hasBOFRecord = true;
					if (rs.HasNextRecord)
					{
						rs.NextRecord();
						record = RecordFactory.CreateSingleRecord(rs);
						num += record.RecordSize;
						outputRecs.Add(record);
						if (record is WriteProtectRecord && rs.HasNextRecord)
						{
							rs.NextRecord();
							record = RecordFactory.CreateSingleRecord(rs);
							num += record.RecordSize;
							outputRecs.Add(record);
						}
						if (record is FilePassRecord)
						{
							filePassRec = (FilePassRecord)record;
							outputRecs.RemoveAt(outputRecs.Count - 1);
							record = outputRecs[0];
						}
						else if (record is EOFRecord)
						{
							throw new InvalidOperationException("Nothing between BOF and EOF");
						}
					}
				}
				else
				{
					_hasBOFRecord = false;
				}
				_InitialRecordsSize = num;
				_filePassRec = filePassRec;
				_lastRecord = record;
			}

			public RecordInputStream CreateDecryptingStream(Stream original)
			{
				FilePassRecord filePassRec = _filePassRec;
				string currentUserPassword = Biff8EncryptionKey.CurrentUserPassword;
				Biff8EncryptionKey biff8EncryptionKey = ((currentUserPassword != null) ? Biff8EncryptionKey.Create(currentUserPassword, filePassRec.DocId) : Biff8EncryptionKey.Create(filePassRec.DocId));
				if (!biff8EncryptionKey.Validate(filePassRec.SaltData, filePassRec.SaltHash))
				{
					throw new EncryptedDocumentException(((currentUserPassword == null) ? "Default" : "Supplied") + " password is invalid for docId/saltData/saltHash");
				}
				return new RecordInputStream(original, biff8EncryptionKey, _InitialRecordsSize);
			}
		}

		private RecordInputStream _recStream;

		private bool _shouldIncludeContinueRecords;

		private Record[] _unreadRecordBuffer;

		private int _unreadRecordIndex = -1;

		private Record _lastRecord;

		private DrawingRecord _lastDrawingRecord = new DrawingRecord();

		private int _bofDepth;

		private bool _lastRecordWasEOFLevelZero;

		public RecordFactoryInputStream(Stream in1, bool shouldIncludeContinueRecords)
		{
			RecordInputStream recordInputStream = new RecordInputStream(in1);
			List<Record> list = new List<Record>();
			StreamEncryptionInfo streamEncryptionInfo = new StreamEncryptionInfo(recordInputStream, list);
			if (streamEncryptionInfo.HasEncryption)
			{
				recordInputStream = streamEncryptionInfo.CreateDecryptingStream(in1);
			}
			if (list.Count != 0)
			{
				_unreadRecordBuffer = new Record[list.Count];
				_unreadRecordBuffer = list.ToArray();
				_unreadRecordIndex = 0;
			}
			_recStream = recordInputStream;
			_shouldIncludeContinueRecords = shouldIncludeContinueRecords;
			_lastRecord = streamEncryptionInfo.LastRecord;
			_bofDepth = (streamEncryptionInfo.HasBOFRecord ? 1 : 0);
			_lastRecordWasEOFLevelZero = false;
		}

		public Record NextRecord()
		{
			Record nextUnreadRecord = GetNextUnreadRecord();
			if (nextUnreadRecord != null)
			{
				return nextUnreadRecord;
			}
			do
			{
				if (!_recStream.HasNextRecord)
				{
					return null;
				}
				_recStream.NextRecord();
				if (_lastRecordWasEOFLevelZero && _recStream.Sid != 2057)
				{
					return null;
				}
				nextUnreadRecord = ReadNextRecord();
			}
			while (nextUnreadRecord == null);
			return nextUnreadRecord;
		}

		private Record GetNextUnreadRecord()
		{
			if (_unreadRecordBuffer != null)
			{
				int unreadRecordIndex = _unreadRecordIndex;
				if (unreadRecordIndex < _unreadRecordBuffer.Length)
				{
					Record result = _unreadRecordBuffer[unreadRecordIndex];
					_unreadRecordIndex = unreadRecordIndex + 1;
					return result;
				}
				_unreadRecordIndex = -1;
				_unreadRecordBuffer = null;
			}
			return null;
		}

		private Record ReadNextRecord()
		{
			Record record = RecordFactory.CreateSingleRecord(_recStream);
			_lastRecordWasEOFLevelZero = false;
			if (record is BOFRecord)
			{
				_bofDepth++;
				return record;
			}
			if (record is EOFRecord)
			{
				_bofDepth--;
				if (_bofDepth < 1)
				{
					_lastRecordWasEOFLevelZero = true;
				}
				return record;
			}
			if (record is DBCellRecord)
			{
				return null;
			}
			if (record is RKRecord)
			{
				return RecordFactory.ConvertToNumberRecord((RKRecord)record);
			}
			if (record is MulRKRecord)
			{
				Record[] array = (_unreadRecordBuffer = RecordFactory.ConvertRKRecords((MulRKRecord)record));
				_unreadRecordIndex = 1;
				return array[0];
			}
			if (record.Sid == 235 && _lastRecord is DrawingGroupRecord)
			{
				DrawingGroupRecord drawingGroupRecord = (DrawingGroupRecord)_lastRecord;
				drawingGroupRecord.Join((AbstractEscherHolderRecord)record);
				return null;
			}
			if (record.Sid == 60)
			{
				ContinueRecord continueRecord = (ContinueRecord)record;
				if (_lastRecord is ObjRecord || _lastRecord is TextObjectRecord)
				{
					_lastDrawingRecord.ProcessContinueRecord(continueRecord.Data);
					if (_shouldIncludeContinueRecords)
					{
						return record;
					}
					return null;
				}
				if (_lastRecord is DrawingGroupRecord)
				{
					((DrawingGroupRecord)_lastRecord).ProcessContinueRecord(continueRecord.Data);
					return null;
				}
				if (_lastRecord is DrawingRecord)
				{
					return continueRecord;
				}
				if (_lastRecord is CrtMlFrtRecord)
				{
					return record;
				}
				if (_lastRecord is UnknownRecord)
				{
					return record;
				}
				if (_lastRecord is EOFRecord)
				{
					return record;
				}
				throw new RecordFormatException("Unhandled Continue Record");
			}
			_lastRecord = record;
			if (record is DrawingRecord)
			{
				_lastDrawingRecord = (DrawingRecord)record;
			}
			return record;
		}
	}
	[Serializable]
	public class LeftoverDataException : Exception
	{
		public LeftoverDataException(int sid, int remainingByteCount)
			: base("Initialisation of record 0x" + StringUtil.ToHexString(sid).ToUpper() + " left " + remainingByteCount + " bytes remaining still to be read.")
		{
		}
	}
	internal class SimpleHeaderInput : BiffHeaderInput
	{
		private ILittleEndianInput _lei;

		internal static ILittleEndianInput GetLEI(Stream in1)
		{
			if (in1 is ILittleEndianInput)
			{
				return (ILittleEndianInput)in1;
			}
			return new LittleEndianInputStream(in1);
		}

		public SimpleHeaderInput(Stream in1)
		{
			_lei = GetLEI(in1);
		}

		public int Available()
		{
			return _lei.Available();
		}

		public int ReadDataSize()
		{
			return _lei.ReadUShort();
		}

		public int ReadRecordSID()
		{
			return _lei.ReadUShort();
		}
	}
	public class RecordInputStream : Stream, ILittleEndianInput
	{
		public const short MAX_RECORD_DATA_SIZE = 8224;

		private const int INVALID_SID_VALUE = -1;

		private const int DATA_LEN_NEEDS_TO_BE_READ = -1;

		protected int _currentSid;

		protected int _currentDataLength = -1;

		protected int _nextSid = -1;

		private int _currentDataOffset;

		private long pos;

		private BiffHeaderInput _bhi;

		private ILittleEndianInput _dataInput;

		public short Sid => (short)_currentSid;

		public override long Position
		{
			get
			{
				return pos;
			}
			set
			{
				throw new NotImplementedException();
			}
		}

		public long CurrentLength => _currentDataLength;

		public int RecordOffset => _currentDataOffset;

		public bool HasNextRecord
		{
			get
			{
				if (_currentDataLength != -1 && _currentDataLength != _currentDataOffset)
				{
					throw new LeftoverDataException(_currentSid, Remaining);
				}
				if (_currentDataLength != -1)
				{
					_nextSid = ReadNextSid();
				}
				return _nextSid != -1;
			}
		}

		public int Remaining
		{
			get
			{
				if (_currentDataLength == -1)
				{
					return 0;
				}
				return _currentDataLength - _currentDataOffset;
			}
		}

		public bool IsContinueNext
		{
			get
			{
				if (_currentDataLength != -1 && _currentDataOffset != _currentDataLength)
				{
					throw new InvalidOperationException("Should never be called before end of current record");
				}
				if (!HasNextRecord)
				{
					return false;
				}
				return _nextSid == 60;
			}
		}

		public override long Length => _currentDataLength;

		public override bool CanRead => true;

		public override bool CanSeek => false;

		public override bool CanWrite => false;

		public RecordInputStream(Stream in1)
			: this(in1, null, 0)
		{
		}

		public RecordInputStream(Stream in1, Biff8EncryptionKey key, int initialOffset)
		{
			if (key == null)
			{
				_dataInput = SimpleHeaderInput.GetLEI(in1);
				_bhi = new SimpleHeaderInput(in1);
			}
			else
			{
				_dataInput = (ILittleEndianInput)(_bhi = new Biff8DecryptingStream(in1, initialOffset, key));
			}
			_nextSid = ReadNextSid();
		}

		public int Available()
		{
			return Remaining;
		}

		public int Read()
		{
			CheckRecordPosition(1);
			_currentDataOffset++;
			pos++;
			return _dataInput.ReadByte();
		}

		private int ReadNextSid()
		{
			int num = _bhi.Available();
			if (num < 4)
			{
				_ = 0;
				return -1;
			}
			int num2 = _bhi.ReadRecordSID();
			if (num2 == -1)
			{
				throw new RecordFormatException("Found invalid sid (" + num2 + ")");
			}
			_currentDataLength = -1;
			return num2;
		}

		public override long Seek(long offset, SeekOrigin origin)
		{
			throw new NotSupportedException();
		}

		public void NextRecord()
		{
			if (_nextSid == -1)
			{
				throw new InvalidDataException("EOF - next record not available");
			}
			if (_currentDataLength != -1)
			{
				throw new InvalidDataException("Cannot call nextRecord() without checking hasNextRecord() first");
			}
			_currentSid = _nextSid;
			_currentDataOffset = 0;
			_currentDataLength = _bhi.ReadDataSize();
			pos += 2L;
			if (_currentDataLength > 8224)
			{
				throw new RecordFormatException("The content of an excel record cannot exceed " + (short)8224 + " bytes");
			}
		}

		protected void CheckRecordPosition(int requiredByteCount)
		{
			int remaining = Remaining;
			if (remaining < requiredByteCount)
			{
				if (remaining != 0 || !IsContinueNext)
				{
					throw new RecordFormatException("Not enough data (" + remaining + ") to read requested (" + requiredByteCount + ") bytes");
				}
				NextRecord();
			}
		}

		public override int ReadByte()
		{
			CheckRecordPosition(1);
			_currentDataOffset++;
			pos++;
			return _dataInput.ReadByte();
		}

		public short ReadShort()
		{
			CheckRecordPosition(2);
			_currentDataOffset += 2;
			pos += 2L;
			return _dataInput.ReadShort();
		}

		public int ReadInt()
		{
			CheckRecordPosition(4);
			_currentDataOffset += 4;
			pos += 4L;
			return _dataInput.ReadInt();
		}

		public long ReadLong()
		{
			CheckRecordPosition(8);
			_currentDataOffset += 8;
			pos += 8L;
			return _dataInput.ReadLong();
		}

		public int ReadUByte()
		{
			int num = ReadByte();
			if (num < 0)
			{
				num += 256;
			}
			return num;
		}

		public int ReadUShort()
		{
			CheckRecordPosition(2);
			_currentDataOffset += 2;
			pos += 2L;
			return _dataInput.ReadUShort();
		}

		public double ReadDouble()
		{
			CheckRecordPosition(8);
			_currentDataOffset += 8;
			long value = _dataInput.ReadLong();
			double result = BitConverter.Int64BitsToDouble(value);
			pos += 8L;
			return result;
		}

		public void ReadFully(byte[] buf)
		{
			ReadFully(buf, 0, buf.Length);
		}

		public void ReadFully(byte[] buf, int off, int len)
		{
			int num = len;
			if (buf == null)
			{
				throw new ArgumentNullException();
			}
			if (off < 0 || len < 0 || len > buf.Length - off)
			{
				throw new IndexOutOfRangeException();
			}
			while (len > 0)
			{
				int num2 = Math.Min(Available(), len);
				if (num2 == 0)
				{
					if (!HasNextRecord)
					{
						throw new RecordFormatException("Can't read the remaining " + len + " bytes of the requested " + num + " bytes. No further record exists.");
					}
					NextRecord();
					num2 = Math.Min(Available(), len);
				}
				CheckRecordPosition(num2);
				_dataInput.ReadFully(buf, off, num2);
				_currentDataOffset += num2;
				off += num2;
				len -= num2;
				pos += num2;
			}
		}

		public string ReadUnicodeLEString(int requestedLength)
		{
			return ReadStringCommon(requestedLength, pIsCompressedEncoding: false);
		}

		public string ReadCompressedUnicode(int requestedLength)
		{
			return ReadStringCommon(requestedLength, pIsCompressedEncoding: true);
		}

		private string ReadStringCommon(int requestedLength, bool pIsCompressedEncoding)
		{
			if (requestedLength < 0 || requestedLength > 1048576)
			{
				throw new ArgumentException("Bad requested string length (" + requestedLength + ")");
			}
			char[] array = new char[requestedLength];
			bool flag = pIsCompressedEncoding;
			int i = 0;
			while (true)
			{
				int num = (flag ? Remaining : (Remaining / 2));
				if (requestedLength - i <= num)
				{
					for (; i < requestedLength; i++)
					{
						char c = ((!flag) ? ((char)ReadShort()) : ((char)ReadUByte()));
						array[i] = c;
					}
					return new string(array);
				}
				while (num > 0)
				{
					char c2 = ((!flag) ? ((char)ReadShort()) : ((char)ReadUByte()));
					array[i] = c2;
					i++;
					num--;
				}
				if (!IsContinueNext)
				{
					throw new RecordFormatException("Expected to find a ContinueRecord in order to read remaining " + (requestedLength - i) + " of " + requestedLength + " chars");
				}
				if (Remaining != 0)
				{
					break;
				}
				NextRecord();
				byte b = (byte)ReadByte();
				flag = b == 0;
			}
			throw new RecordFormatException("Odd number of bytes(" + Remaining + ") left behind");
		}

		public string ReadString()
		{
			int requestedLength = ReadUShort();
			byte b = (byte)ReadByte();
			return ReadStringCommon(requestedLength, b == 0);
		}

		public byte[] ReadRemainder()
		{
			int remaining = Remaining;
			if (remaining == 0)
			{
				return new byte[0];
			}
			byte[] array = new byte[remaining];
			ReadFully(array);
			return array;
		}

		public byte[] ReadAllContinuedRemainder()
		{
			using MemoryStream memoryStream = new MemoryStream(16448);
			while (true)
			{
				byte[] array = ReadRemainder();
				memoryStream.Write(array, 0, array.Length);
				if (!IsContinueNext)
				{
					break;
				}
				NextRecord();
			}
			return memoryStream.ToArray();
		}

		public override void SetLength(long value)
		{
			_currentDataLength = (int)value;
		}

		public override void Flush()
		{
			throw new NotSupportedException();
		}

		public override void Write(byte[] buffer, int offset, int count)
		{
			throw new NotSupportedException();
		}

		public override int Read(byte[] b, int off, int len)
		{
			int num = Math.Min(len, Remaining);
			if (num == 0)
			{
				return 0;
			}
			ReadFully(b, off, num);
			return num;
		}

		public int GetNextSid()
		{
			return _nextSid;
		}
	}
	public class RefModeRecord : StandardRecord
	{
		public const short sid = 15;

		public const short USE_A1_MODE = 1;

		public const short USE_R1C1_MODE = 0;

		private short field_1_mode;

		public short Mode
		{
			get
			{
				return field_1_mode;
			}
			set
			{
				field_1_mode = value;
			}
		}

		public override short Sid => 15;

		protected override int DataSize => 2;

		public RefModeRecord()
		{
		}

		public RefModeRecord(RecordInputStream in1)
		{
			field_1_mode = in1.ReadShort();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[REFMODE]\n");
			stringBuilder.Append("    .mode           = ").Append(StringUtil.ToHexString(Mode)).Append("\n");
			stringBuilder.Append("[/REFMODE]\n");
			return stringBuilder.ToString();
		}

		public override object Clone()
		{
			RefModeRecord refModeRecord = new RefModeRecord();
			refModeRecord.field_1_mode = field_1_mode;
			return refModeRecord;
		}

		public override void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteShort(Mode);
		}
	}
	public class RefreshAllRecord : StandardRecord
	{
		public const short sid = 439;

		private static BitField refreshFlag = BitFieldFactory.GetInstance(1);

		private int _options;

		public bool RefreshAll
		{
			get
			{
				return refreshFlag.IsSet(_options);
			}
			set
			{
				_options = refreshFlag.SetBoolean(_options, value);
