			stringBuilder.Append("    .numstrings     = ").Append(StringUtil.ToHexString(NumStrings)).Append("\n");
			stringBuilder.Append("    .uniquestrings  = ").Append(StringUtil.ToHexString(NumUniqueStrings)).Append("\n");
