namespace NPOI.POIFS.EventFileSystem
{
	public class POIFSReader
	{
		private POIFSReaderRegistry registry;

		private bool registryClosed;

		public event POIFSReaderEventHandler StreamReaded;

		protected virtual void OnStreamReaded(POIFSReaderEventArgs e)
		{
			if (this.StreamReaded != null)
			{
				this.StreamReaded(this, e);
			}
		}

		public POIFSReader()
		{
			registry = new POIFSReaderRegistry();
			registryClosed = false;
		}

		public List<DocumentDescriptor> Read(Stream stream)
		{
			registryClosed = true;
			HeaderBlock headerBlock = new HeaderBlock(stream);
			RawDataBlockList rawDataBlockList = new RawDataBlockList(stream, headerBlock.BigBlockSize);
			new BlockAllocationTableReader(headerBlock.BigBlockSize, headerBlock.BATCount, headerBlock.BATArray, headerBlock.XBATCount, headerBlock.XBATIndex, rawDataBlockList);
			PropertyTable propertyTable = new PropertyTable(headerBlock, rawDataBlockList);
			return ProcessProperties(SmallBlockTableReader.GetSmallDocumentBlocks(headerBlock.BigBlockSize, rawDataBlockList, propertyTable.Root, headerBlock.SBATStart), rawDataBlockList, propertyTable.Root.Children, new POIFSDocumentPath());
		}

		public void RegisterListener(POIFSReaderListener listener)
		{
			if (listener == null)
			{
				throw new NullReferenceException();
			}
			if (registryClosed)
			{
				throw new InvalidOperationException();
			}
			registry.RegisterListener(listener);
		}

		public void RegisterListener(POIFSReaderListener listener, string name)
		{
			RegisterListener(listener, null, name);
		}

		public void RegisterListener(POIFSReaderListener listener, POIFSDocumentPath path, string name)
		{
			if (listener == null || name == null || name.Length == 0)
			{
				throw new NullReferenceException();
			}
			if (registryClosed)
			{
				throw new InvalidOperationException();
			}
			registry.RegisterListener(listener, (path == null) ? new POIFSDocumentPath() : path, name);
		}

		private List<DocumentDescriptor> ProcessProperties(BlockList small_blocks, BlockList big_blocks, IEnumerator properties, POIFSDocumentPath path)
		{
			List<DocumentDescriptor> result = new List<DocumentDescriptor>();
			while (properties.MoveNext())
			{
				NPOI.POIFS.Properties.Property property = (NPOI.POIFS.Properties.Property)properties.Current;
				string name = property.Name;
				if (property.IsDirectory)
				{
					POIFSDocumentPath path2 = new POIFSDocumentPath(path, new string[1] { name });
					ProcessProperties(small_blocks, big_blocks, ((DirectoryProperty)property).Children, path2);
					continue;
				}
				int startBlock = property.StartBlock;
				IEnumerator listeners = registry.GetListeners(path, name);
				POIFSDocument pOIFSDocument = null;
				if (listeners.MoveNext())
				{
					listeners.Reset();
					int size = property.Size;
					pOIFSDocument = ((!property.ShouldUseSmallBlocks) ? new POIFSDocument(name, big_blocks.FetchBlocks(startBlock, -1), size) : new POIFSDocument(name, small_blocks.FetchBlocks(startBlock, -1), size));
					while (listeners.MoveNext())
					{
						POIFSReaderListener pOIFSReaderListener = (POIFSReaderListener)listeners.Current;
						pOIFSReaderListener.ProcessPOIFSReaderEvent(new POIFSReaderEvent(new DocumentInputStream(pOIFSDocument), path, name));
					}
				}
				else if (property.ShouldUseSmallBlocks)
				{
					small_blocks.FetchBlocks(startBlock, -1);
				}
				else
				{
					big_blocks.FetchBlocks(startBlock, -1);
				}
			}
			return result;
		}
	}
	public class POIFSReaderEvent
	{
		private DocumentInputStream stream;

		private POIFSDocumentPath path;

		private string documentName;

		public DocumentInputStream Stream => stream;

		public POIFSDocumentPath Path => path;

		public string Name => documentName;

		public POIFSReaderEvent(DocumentInputStream stream, POIFSDocumentPath path, string documentName)
		{
			this.stream = stream;
			this.path = path;
			this.documentName = documentName;
		}
	}
	public class POIFSReaderEventArgs : EventArgs
	{
		private POIFSDocumentPath path;

		private POIFSDocument document;

		private string name;

		public virtual POIFSDocumentPath Path => path;

		public virtual POIFSDocument Document => document;

		public virtual DocumentInputStream Stream => new DocumentInputStream(document);

		public virtual string Name => name;

		public POIFSReaderEventArgs(string name, POIFSDocumentPath path, POIFSDocument document)
		{
			this.name = name;
			this.path = path;
			this.document = document;
		}
	}
	public delegate void POIFSReaderEventHandler(object sender, POIFSReaderEventArgs e);
	public interface POIFSReaderListener
	{
		void ProcessPOIFSReaderEvent(POIFSReaderEvent evt);
	}
	public class POIFSReaderRegistry
	{
		private ArrayList omnivorousListeners;

		private Hashtable selectiveListeners;

		private Hashtable chosenDocumentDescriptors;

		public POIFSReaderRegistry()
		{
			omnivorousListeners = new ArrayList();
			selectiveListeners = new Hashtable();
			chosenDocumentDescriptors = new Hashtable();
		}

		public void RegisterListener(POIFSReaderListener listener, POIFSDocumentPath path, string documentName)
		{
			if (omnivorousListeners.Contains(listener))
			{
				return;
			}
			ArrayList arrayList = (ArrayList)selectiveListeners[listener];
			if (arrayList == null)
			{
				arrayList = new ArrayList();
				selectiveListeners[listener] = arrayList;
			}
			DocumentDescriptor documentDescriptor = new DocumentDescriptor(path, documentName);
			if (arrayList.Add(documentDescriptor) >= 0)
			{
				ArrayList arrayList2 = (ArrayList)chosenDocumentDescriptors[documentDescriptor];
				if (arrayList2 == null)
				{
					arrayList2 = new ArrayList();
					chosenDocumentDescriptors[documentDescriptor] = arrayList2;
				}
				arrayList2.Add(listener);
			}
		}

		public void RegisterListener(POIFSReaderListener listener)
		{
			if (!omnivorousListeners.Contains(listener))
			{
				RemoveSelectiveListener(listener);
				omnivorousListeners.Add(listener);
			}
		}

		public IEnumerator GetListeners(POIFSDocumentPath path, string name)
		{
			ArrayList arrayList = new ArrayList(omnivorousListeners);
			ArrayList arrayList2 = (ArrayList)chosenDocumentDescriptors[new DocumentDescriptor(path, name)];
			if (arrayList2 != null)
			{
				arrayList.AddRange(arrayList2);
			}
			return arrayList.GetEnumerator();
		}

		private void RemoveSelectiveListener(POIFSReaderListener listener)
		{
			ArrayList arrayList = (ArrayList)selectiveListeners[listener];
			if (arrayList != null)
			{
				selectiveListeners.Remove(listener);
				IEnumerator enumerator = arrayList.GetEnumerator();
				while (enumerator.MoveNext())
				{
					DropDocument(listener, (DocumentDescriptor)enumerator.Current);
				}
			}
		}

		private void DropDocument(POIFSReaderListener listener, DocumentDescriptor descriptor)
		{
			ArrayList arrayList = (ArrayList)chosenDocumentDescriptors[descriptor];
			arrayList.Remove(listener);
			if (arrayList.Count == 0)
			{
				chosenDocumentDescriptors.Remove(descriptor);
			}
		}
	}
