	{
		private class OrderedSheet : IComparable<OrderedSheet>
		{
			private string _sheetName;

			private int _index;

			public OrderedSheet(string sheetName, int index)
			{
				_sheetName = sheetName;
				_index = index;
			}

			public string GetSheetName()
			{
				return _sheetName;
