namespace NPOI.SS.UserModel
{
	public class FractionFormat : FormatBase
	{
		private class SimpleFractionException : Exception
		{
			public SimpleFractionException(string message)
				: base(message)
			{
			}
		}

		private static Regex DENOM_FORMAT_PATTERN = new Regex("(?:(#+)|(\\d+))");

		private static int MAX_DENOM_POW = 4;

		private int exactDenom;

		private int maxDenom;

		private string wholePartFormatString;

		public FractionFormat(string wholePartFormatString, string denomFormatString)
		{
			this.wholePartFormatString = wholePartFormatString;
			System.Text.RegularExpressions.Match match = DENOM_FORMAT_PATTERN.Match(denomFormatString);
			int num = -1;
			int num2 = -1;
			if (match.Success)
			{
				if (match.Groups[2] != null && match.Groups[2].Success)
				{
					try
					{
						num = int.Parse(match.Groups[2].Value);
						if (num == 0)
						{
							num = -1;
						}
					}
					catch (FormatException)
					{
					}
				}
				else if (match.Groups[1] != null && match.Groups[1].Success)
				{
					int length = match.Groups[1].Value.Length;
					num2 = (int)Math.Pow(10.0, (length > MAX_DENOM_POW) ? MAX_DENOM_POW : length);
				}
				else
				{
					num = 100;
				}
			}
			if (num <= 0 && num2 <= 0)
			{
				num = 100;
			}
			exactDenom = num;
			maxDenom = num2;
		}

		public string Format(string num)
		{
			double result = 0.0;
			double.TryParse(num, out result);
			bool flag = result < 0.0;
			double num2 = Math.Abs(result);
			double num3 = Math.Floor(num2);
			double num4 = num2 - num3;
			if (num3 + num4 == 0.0)
			{
				return "0";
			}
			if (num2 < (double)(1 / Math.Max(exactDenom, maxDenom)))
			{
				return "0";
			}
			if (num3 + (double)(int)num4 == num3 + num4)
			{
				StringBuilder stringBuilder = new StringBuilder();
				if (flag)
				{
					stringBuilder.Append("-");
				}
				stringBuilder.Append((int)num3);
				return stringBuilder.ToString();
			}
			SimpleFraction simpleFraction = null;
			try
			{
				simpleFraction = ((exactDenom <= 0) ? SimpleFraction.BuildFractionMaxDenominator(num4, maxDenom) : SimpleFraction.BuildFractionExactDenominator(num4, exactDenom));
			}
			catch (SimpleFractionException)
			{
				return result.ToString();
			}
			StringBuilder stringBuilder2 = new StringBuilder();
			if (flag)
			{
				stringBuilder2.Append("-");
			}
			if ("".Equals(wholePartFormatString))
			{
				int value = simpleFraction.Denominator * (int)num3 + simpleFraction.Numerator;
				stringBuilder2.Append(value).Append("/").Append(simpleFraction.Denominator);
				return stringBuilder2.ToString();
			}
			if (simpleFraction.Numerator == 0)
			{
				stringBuilder2.Append((int)num3);
				return stringBuilder2.ToString();
			}
			if (simpleFraction.Numerator == simpleFraction.Denominator)
			{
				stringBuilder2.Append((int)num3 + 1);
				return stringBuilder2.ToString();
			}
			if (num3 > 0.0)
			{
				stringBuilder2.Append((int)num3).Append(" ");
			}
			stringBuilder2.Append(simpleFraction.Numerator).Append("/").Append(simpleFraction.Denominator);
			return stringBuilder2.ToString();
		}

		public override StringBuilder Format(object obj, StringBuilder toAppendTo, int pos)
		{
			return toAppendTo.Append(Format(obj.ToString()));
		}

		public override string Format(object obj, CultureInfo culture)
		{
			return Format(obj.ToString());
		}

		public override object ParseObject(string source, int pos)
		{
			throw new NotImplementedException("Reverse parsing not supported");
		}

		public override StringBuilder Format(object obj, StringBuilder toAppendTo, CultureInfo culture)
		{
			return toAppendTo.Append(Format(obj, culture));
		}
	}
}
namespace NPOI.SS.Format
{
	public class SimpleFraction
	{
		private int denominator;

		private int numerator;

		public int Denominator => denominator;

		public int Numerator => numerator;

		public static SimpleFraction BuildFractionExactDenominator(double val, int exactDenom)
		{
			int num = (int)Math.Round(val * (double)exactDenom, MidpointRounding.AwayFromZero);
			return new SimpleFraction(num, exactDenom);
		}

		public static SimpleFraction BuildFractionMaxDenominator(double value, int maxDenominator)
		{
			return BuildFractionMaxDenominator(value, 0.0, maxDenominator, 100);
		}

		private static SimpleFraction BuildFractionMaxDenominator(double value, double epsilon, int maxDenominator, int maxIterations)
		{
			long num = long.MaxValue;
			double num2 = value;
			long num3 = (long)Math.Floor(num2);
			if (num3 > num)
			{
				throw new ArgumentException("Overflow trying to convert " + value + " to fraction (" + num3 + "/" + 1L + ")");
			}
			if (Math.Abs((double)num3 - value) < epsilon)
			{
				return new SimpleFraction((int)num3, 1);
			}
			long num4 = 1L;
			long num5 = 0L;
			long num6 = num3;
			long num7 = 1L;
			int num8 = 0;
			bool flag = false;
			long num11;
			long num12;
			do
			{
				num8++;
				double num9 = 1.0 / (num2 - (double)num3);
				long num10 = (long)Math.Floor(num9);
				num11 = num10 * num6 + num4;
				num12 = num10 * num7 + num5;
				if (epsilon == 0.0 && maxDenominator > 0 && Math.Abs(num12) > maxDenominator && Math.Abs(num7) < maxDenominator)
				{
					return new SimpleFraction((int)num6, (int)num7);
				}
				if (num11 > num || num12 > num)
				{
					throw new RuntimeException("Overflow trying to convert " + value + " to fraction (" + num11 + "/" + num12 + ")");
				}
				double num13 = (double)num11 / (double)num12;
				if (num8 < maxIterations && Math.Abs(num13 - value) > epsilon && num12 < maxDenominator)
				{
					num4 = num6;
					num6 = num11;
					num5 = num7;
					num7 = num12;
					num3 = num10;
					num2 = num9;
				}
				else
				{
					flag = true;
				}
			}
			while (!flag);
			if (num8 >= maxIterations)
			{
				throw new RuntimeException("Unable to convert " + value + " to fraction after " + maxIterations + " iterations");
			}
			if (num12 < maxDenominator)
			{
				return new SimpleFraction((int)num11, (int)num12);
			}
			return new SimpleFraction((int)num6, (int)num7);
		}

		public SimpleFraction(int numerator, int denominator)
		{
			this.numerator = numerator;
			this.denominator = denominator;
		}
	}
}
