			int num2 = array[1] & 0xFF;
			int num3 = array[2] & 0xFF;
			int num4 = array[3] & 0xFF;
			int num5 = array[4] & 0xFF;
			int num6 = array[5] & 0xFF;
			int num7 = array[6] & 0xFF;
			int num8 = array[7] & 0xFF;
