						}
					}
				}
				else
				{
					for (int k = 0; k < array2[i]._data.Length; k++)
					{
						array2[i]._data[k] = _default_value;
					}
				}
				num += 512;
			}
			return array2;
		}

		public static void Read(DocumentBlock[] blocks, byte[] buffer, int offset)
		{
			int num = offset / 512;
			int num2 = offset % 512;
			int num3 = (offset + buffer.Length - 1) / 512;
			if (num == num3)
			{
				System.Array.Copy(blocks[num]._data, num2, buffer, 0, buffer.Length);
				return;
			}
			int num4 = 0;
			System.Array.Copy(blocks[num]._data, num2, buffer, num4, 512 - num2);
			num4 += 512 - num2;
			for (int i = num + 1; i < num3; i++)
			{
				System.Array.Copy(blocks[i]._data, 0, buffer, num4, 512);
				num4 += 512;
			}
			System.Array.Copy(blocks[num3]._data, 0, buffer, num4, buffer.Length - num4);
		}

		public static DataInputBlock GetDataInputBlock(DocumentBlock[] blocks, int offset)
		{
