			}
			POIFSBigBlockSize pOIFSBigBlockSize = blocks[0].bigBlockSize;
			int headerValue = pOIFSBigBlockSize.GetHeaderValue();
			int num = pOIFSBigBlockSize.GetBigBlockSize();
			int num2 = num - 1;
			int num3 = offset >> headerValue;
			int startOffset = offset & num2;
			return new DataInputBlock(blocks[num3]._data, startOffset);
		}

		public override void WriteData(Stream stream)
		{
