	internal class EvaluationCycleDetector
	{
		private class CellEvaluationFrame
		{
			private HSSFWorkbook _workbook;

			private HSSFSheet _sheet;

			private int _srcRowNum;

			private int _srcColNum;

			public CellEvaluationFrame(HSSFWorkbook workbook, HSSFSheet sheet, int srcRowNum, int srcColNum)
			{
				if (workbook == null)
				{
					throw new ArgumentException("workbook must not be null");
				}
				if (sheet == null)
				{
					throw new ArgumentException("sheet must not be null");
				}
				_workbook = workbook;
				_sheet = sheet;
				_srcRowNum = srcRowNum;
				_srcColNum = srcColNum;
			}

			public override bool Equals(object obj)
			{
				CellEvaluationFrame cellEvaluationFrame = (CellEvaluationFrame)obj;
				if (_workbook != cellEvaluationFrame._workbook)
				{
					return false;
				}
				if (_sheet != cellEvaluationFrame._sheet)
				{
					return false;
				}
				if (_srcRowNum != cellEvaluationFrame._srcRowNum)
				{
					return false;
				}
				if (_srcColNum != cellEvaluationFrame._srcColNum)
				{
					return false;
				}
				return true;
			}

			public override int GetHashCode()
			{
				return _workbook.GetHashCode() ^ _sheet.GetHashCode() ^ _srcRowNum ^ _srcColNum;
			}

			public string FormatAsString()
			{
				return "R=" + _srcRowNum + " C=" + _srcColNum + " ShIx=" + _workbook.GetSheetIndex(_sheet);
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder(64);
				stringBuilder.Append(GetType().Name).Append(" [");
				stringBuilder.Append(FormatAsString());
				stringBuilder.Append("]");
				return stringBuilder.ToString();
			}
		}

		private IList _evaluationFrames;

		public EvaluationCycleDetector()
		{
			_evaluationFrames = new ArrayList();
		}

		public bool StartEvaluate(HSSFWorkbook workbook, HSSFSheet sheet, int srcRowNum, int srcColNum)
		{
			CellEvaluationFrame value = new CellEvaluationFrame(workbook, sheet, srcRowNum, srcColNum);
			if (_evaluationFrames.Contains(value))
			{
				return false;
			}
			_evaluationFrames.Add(value);
			return true;
		}

		public void EndEvaluate(HSSFWorkbook workbook, HSSFSheet sheet, int srcRowNum, int srcColNum)
		{
			int count = _evaluationFrames.Count;
			if (count < 1)
			{
				throw new InvalidOperationException("Call to endEvaluate without matching call to startEvaluate");
			}
			count--;
			CellEvaluationFrame cellEvaluationFrame = (CellEvaluationFrame)_evaluationFrames[count];
			CellEvaluationFrame cellEvaluationFrame2 = new CellEvaluationFrame(workbook, sheet, srcRowNum, srcColNum);
			if (!cellEvaluationFrame2.Equals(cellEvaluationFrame))
			{
				throw new Exception("Wrong cell specified. Corresponding startEvaluate() call was for cell {" + cellEvaluationFrame.FormatAsString() + "} this endEvaluate() call Is for cell {" + cellEvaluationFrame2.FormatAsString() + "}");
			}
			_evaluationFrames.Remove(count);
		}
	}
	internal class EvaluationCycleDetectorManager
	{
		[ThreadStatic]
		private static EvaluationCycleDetector ecd = new EvaluationCycleDetector();

		public static EvaluationCycleDetector GetTracker()
		{
			return ecd;
		}

		private EvaluationCycleDetectorManager()
		{
		}
	}
	public class FontDetails
	{
		private string fontName;

		private int height;

		private Hashtable charWidths = new Hashtable();

		public FontDetails(string fontName, int height)
		{
			this.fontName = fontName;
			this.height = height;
		}

		public string GetFontName()
		{
			return fontName;
		}

		public int GetHeight()
		{
			return height;
		}

		public void AddChar(char c, int width)
		{
			charWidths[c] = width;
		}

		public int GetCharWidth(char c)
		{
			object obj = charWidths[c];
			if (obj == null)
			{
				if ('W' != c)
				{
					return GetCharWidth('W');
				}
				return 0;
			}
			return (int)obj;
		}

		public void AddChars(char[] Chars, int[] widths)
		{
			for (int i = 0; i < Chars.Length; i++)
			{
				if (Chars[i] != ' ')
				{
					charWidths[Chars[i]] = widths[i];
				}
			}
		}

		public static string BuildFontHeightProperty(string fontName)
		{
			return "font." + fontName + ".height";
		}

		public static string BuildFontWidthsProperty(string fontName)
		{
			return "font." + fontName + ".widths";
		}

		public static string BuildFontCharsProperty(string fontName)
		{
			return "font." + fontName + ".characters";
		}

		public static FontDetails Create(string fontName, Properties fontMetricsProps)
		{
			string text = fontMetricsProps[BuildFontHeightProperty(fontName)];
			string text2 = fontMetricsProps[BuildFontWidthsProperty(fontName)];
			string text3 = fontMetricsProps[BuildFontCharsProperty(fontName)];
			if (text == null || text2 == null || text3 == null)
			{
				throw new ArgumentException("The supplied FontMetrics doesn't know about the font '" + fontName + "', so we can't use it. Please Add it to your font metrics file (see StaticFontMetrics.GetFontDetails");
			}
			int num = int.Parse(text, CultureInfo.InvariantCulture);
			FontDetails fontDetails = new FontDetails(fontName, num);
			string[] array = Split(text3, ",", -1);
			string[] array2 = Split(text2, ",", -1);
			if (array.Length != array2.Length)
			{
				throw new Exception("Number of Chars does not number of widths for font " + fontName);
			}
			for (int i = 0; i < array2.Length; i++)
			{
				if (array[i].Trim().Length != 0)
				{
					fontDetails.AddChar(array[i].Trim()[0], int.Parse(array2[i], CultureInfo.InvariantCulture));
				}
			}
			return fontDetails;
		}

		public int GetStringWidth(string str)
		{
			int num = 0;
			for (int i = 0; i < str.Length; i++)
			{
				num += GetCharWidth(str[i]);
			}
			return num;
		}

		private static string[] Split(string text, string separator, int max)
		{
			return text.Split(separator.ToCharArray());
		}
	}
}
