		private string Trim(string value)
		{
			int num = value.Length;
			int i = 0;
			char[] array;
			for (array = value.ToCharArray(); i < num && array[i] <= ' '; i++)
			{
			}
			while (i < num && array[num - 1] <= ' ')
			{
				num--;
			}
			if (i <= 0 && num >= value.Length)
			{
				return value;
			}
			return value.Substring(i, num - i);
		}

