	public class HSSFOptimiser
	{
		public static void OptimiseFonts(HSSFWorkbook workbook)
		{
			short[] array = new short[workbook.Workbook.NumberOfFontRecords + 1];
			bool[] array2 = new bool[array.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = (short)i;
				array2[i] = false;
			}
			FontRecord[] array3 = new FontRecord[array.Length];
			for (int j = 0; j < array.Length; j++)
			{
				if (j != 4)
				{
					array3[j] = workbook.Workbook.GetFontRecordAt(j);
				}
			}
			for (int k = 5; k < array.Length; k++)
			{
				int num = -1;
				for (int l = 0; l < k; l++)
				{
					if (num != -1)
					{
						break;
					}
					if (l != 4)
					{
						FontRecord fontRecordAt = workbook.Workbook.GetFontRecordAt(l);
						if (fontRecordAt.SameProperties(array3[k]))
						{
							num = l;
						}
					}
				}
				if (num != -1)
				{
					array[k] = (short)num;
					array2[k] = true;
				}
			}
			for (int m = 5; m < array.Length; m++)
			{
				short num2 = array[m];
				short num3 = num2;
				for (int n = 0; n < num2; n++)
				{
					if (array2[n])
					{
						num3--;
					}
				}
				array[m] = num3;
			}
			for (int num4 = 5; num4 < array.Length; num4++)
			{
				if (array2[num4])
				{
					workbook.Workbook.RemoveFontRecord(array3[num4]);
				}
			}
			workbook.ResetFontCache();
			for (int num5 = 0; num5 < workbook.Workbook.NumExFormats; num5++)
			{
				ExtendedFormatRecord exFormatAt = workbook.Workbook.GetExFormatAt(num5);
				exFormatAt.FontIndex = array[exFormatAt.FontIndex];
			}
			ArrayList arrayList = new ArrayList();
			for (int num6 = 0; num6 < workbook.NumberOfSheets; num6++)
			{
				ISheet sheetAt = workbook.GetSheetAt(num6);
				foreach (IRow item in sheetAt)
				{
					foreach (ICell item2 in item)
					{
						if (item2.CellType != CellType.String)
						{
							continue;
						}
						HSSFRichTextString hSSFRichTextString = (HSSFRichTextString)item2.RichStringCellValue;
						NPOI.HSSF.Record.UnicodeString rawUnicodeString = hSSFRichTextString.RawUnicodeString;
						if (arrayList.Contains(rawUnicodeString))
						{
							continue;
						}
						for (short num7 = 5; num7 < array.Length; num7++)
						{
							if (num7 != array[num7])
							{
								rawUnicodeString.SwapFontUse(num7, array[num7]);
							}
						}
						arrayList.Add(rawUnicodeString);
					}
				}
			}
		}

		public static void OptimiseCellStyles(HSSFWorkbook workbook)
		{
			short[] array = new short[workbook.Workbook.NumExFormats];
			bool[] array2 = new bool[array.Length];
			bool[] array3 = new bool[array.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array2[i] = false;
				array[i] = (short)i;
				array3[i] = false;
			}
			ExtendedFormatRecord[] array4 = new ExtendedFormatRecord[array.Length];
			for (int j = 0; j < array.Length; j++)
			{
				array4[j] = workbook.Workbook.GetExFormatAt(j);
			}
			for (int k = 21; k < array.Length; k++)
			{
				int num = -1;
				for (int l = 0; l < k; l++)
				{
					if (num != -1)
					{
						break;
					}
					ExtendedFormatRecord exFormatAt = workbook.Workbook.GetExFormatAt(l);
					if (exFormatAt.Equals(array4[k]))
					{
						num = l;
					}
				}
				if (num != -1)
				{
					array[k] = (short)num;
					array3[k] = true;
				}
				if (num != -1)
				{
					array2[num] = true;
				}
			}
			for (int m = 0; m < workbook.NumberOfSheets; m++)
			{
				HSSFSheet hSSFSheet = (HSSFSheet)workbook.GetSheetAt(m);
				foreach (IRow item in hSSFSheet)
				{
					foreach (ICell item2 in item)
					{
						HSSFCell hSSFCell = (HSSFCell)item2;
						short xFIndex = hSSFCell.CellValueRecord.XFIndex;
						array2[xFIndex] = true;
					}
				}
			}
			for (int n = 21; n < array2.Length; n++)
			{
				if (!array2[n])
				{
					array3[n] = true;
					array[n] = 0;
				}
			}
			for (int num2 = 21; num2 < array.Length; num2++)
			{
				short num3 = array[num2];
				short num4 = num3;
				for (int num5 = 0; num5 < num3; num5++)
				{
					if (array3[num5])
					{
						num4--;
					}
				}
				array[num2] = num4;
			}
			int num6 = array.Length;
			int num7 = 0;
			for (int num8 = 21; num8 < num6; num8++)
			{
				if (array3[num8 + num7])
				{
					workbook.Workbook.RemoveExFormatRecord(num8);
					num8--;
					num6--;
					num7++;
				}
			}
			for (int num9 = 0; num9 < workbook.NumberOfSheets; num9++)
			{
				HSSFSheet hSSFSheet2 = (HSSFSheet)workbook.GetSheetAt(num9);
				foreach (IRow item3 in hSSFSheet2)
				{
					foreach (ICell item4 in item3)
					{
						short xFIndex2 = ((HSSFCell)item4).CellValueRecord.XFIndex;
						ICellStyle cellStyleAt = workbook.GetCellStyleAt(array[xFIndex2]);
						item4.CellStyle = cellStyleAt;
					}
				}
			}
		}
	}
	public class HSSFPalette
	{
		private class CustomColor : HSSFColor
		{
			private short byteOffset;

			private byte red;

			private byte green;

			private byte blue;

			public override short Indexed => byteOffset;

			public CustomColor(short byteOffset, byte[] colors)
				: this(byteOffset, colors[0], colors[1], colors[2])
			{
			}

			public CustomColor(short byteOffset, byte red, byte green, byte blue)
			{
				this.byteOffset = byteOffset;
				this.red = red;
				this.green = green;
				this.blue = blue;
			}

			public override byte[] GetTriplet()
			{
				return new byte[3]
				{
					(byte)(red & 0xFFu),
					(byte)(green & 0xFFu),
					(byte)(blue & 0xFFu)
				};
			}

			public override string GetHexString()
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append(GetGnumericPart(red));
				stringBuilder.Append(':');
				stringBuilder.Append(GetGnumericPart(green));
				stringBuilder.Append(':');
				stringBuilder.Append(GetGnumericPart(blue));
				return stringBuilder.ToString();
			}

			private string GetGnumericPart(byte color)
			{
				string text;
				if (color == 0)
				{
					text = "0";
				}
				else
				{
					int num = color & 0xFF;
					num = (num << 8) | num;
					text = StringUtil.ToHexString(num).ToUpper();
					while (text.Length < 4)
					{
						text = "0" + text;
					}
				}
				return text;
			}
		}

		private PaletteRecord palette;

		public HSSFPalette(PaletteRecord palette)
		{
			this.palette = palette;
		}

		public HSSFColor GetColor(short index)
		{
			if (index == 64)
			{
				return HSSFColor.Automatic.GetInstance();
			}
			byte[] color = palette.GetColor(index);
			if (color != null)
			{
				return new CustomColor(index, color);
			}
			return null;
		}

		public HSSFColor FindColor(byte red, byte green, byte blue)
		{
			byte[] color = palette.GetColor(8);
			short num = 8;
			while (color != null)
			{
				if (color[0] == red && color[1] == green && color[2] == blue)
				{
					return new CustomColor(num, color);
				}
				color = palette.GetColor(++num);
			}
			return null;
		}

		public HSSFColor FindSimilarColor(byte red, byte green, byte blue)
		{
			HSSFColor result = null;
			int num = int.MaxValue;
			byte[] color = palette.GetColor(8);
			short num2 = 8;
			while (color != null)
			{
				int num3 = Math.Abs(red - color[0]) + Math.Abs(green - color[1]) + Math.Abs(blue - color[2]);
				if (num3 < num)
				{
					num = num3;
					result = GetColor(num2);
				}
				color = palette.GetColor(++num2);
			}
			return result;
		}

		public void SetColorAtIndex(short index, byte red, byte green, byte blue)
		{
			palette.SetColor(index, red, green, blue);
		}

		public HSSFColor AddColor(byte red, byte green, byte blue)
		{
			byte[] color = palette.GetColor(8);
			short num = 8;
			while (num < 64)
			{
				if (color == null)
				{
					SetColorAtIndex(num, red, green, blue);
					return GetColor(num);
				}
				color = palette.GetColor(++num);
			}
			throw new Exception("Could not Find free color index");
		}
	}
