		private void NotifyRowShifting(HSSFRow row)
		{
			string msg = "Row[rownum=" + row.RowNum + "] contains cell(s) included in a multi-cell array formula. You cannot change part of an array.";
			foreach (ICell cell in row.Cells)
			{
