	internal class OperationEvaluatorFactory
	{
		private static Type[] OPERATION_CONSTRUCTOR_CLASS_ARRAY = new Type[1] { typeof(Ptg) };

		private static Hashtable _constructorsByPtgClass = InitialiseConstructorsMap();

		private OperationEvaluatorFactory()
		{
		}

		private static Hashtable InitialiseConstructorsMap()
		{
			Hashtable hashtable = new Hashtable(32);
			Add(hashtable, typeof(AddPtg), typeof(AddEval));
			Add(hashtable, typeof(DividePtg), typeof(DivideEval));
			Add(hashtable, typeof(EqualPtg), typeof(EqualEval));
			Add(hashtable, typeof(MultiplyPtg), typeof(MultiplyEval));
			Add(hashtable, typeof(ConcatPtg), typeof(ConcatEval));
			Add(hashtable, typeof(GreaterEqualPtg), typeof(GreaterEqualEval));
			Add(hashtable, typeof(GreaterThanPtg), typeof(GreaterThanEval));
			Add(hashtable, typeof(LessEqualPtg), typeof(LessEqualEval));
			Add(hashtable, typeof(LessThanPtg), typeof(LessThanEval));
			Add(hashtable, typeof(NotEqualPtg), typeof(NotEqualEval));
			Add(hashtable, typeof(PercentPtg), typeof(PercentEval));
			Add(hashtable, typeof(PowerPtg), typeof(PowerEval));
			Add(hashtable, typeof(SubtractPtg), typeof(SubtractEval));
			Add(hashtable, typeof(UnaryMinusPtg), typeof(UnaryMinusEval));
			Add(hashtable, typeof(UnaryPlusPtg), typeof(UnaryPlusEval));
			return hashtable;
		}

		private static void Add(Hashtable m, Type ptgClass, Type evalClass)
		{
			if (!typeof(Ptg).IsAssignableFrom(ptgClass))
			{
				throw new ArgumentException("Expected Ptg subclass");
			}
			if (!typeof(OperationEval).IsAssignableFrom(evalClass))
			{
				throw new ArgumentException("Expected OperationEval subclass");
			}
			if (!evalClass.IsPublic)
			{
				throw new Exception("Eval class must be public");
			}
			if (evalClass.IsAbstract)
			{
				throw new Exception("Eval class must not be abstract");
			}
			ConstructorInfo constructor;
			try
			{
				constructor = evalClass.GetConstructor(OPERATION_CONSTRUCTOR_CLASS_ARRAY);
			}
			catch (Exception)
			{
				throw;
			}
			if (!constructor.IsPublic)
			{
				throw new Exception("Eval constructor must be public");
			}
			m[ptgClass] = constructor;
		}

		public static OperationEval Create(OperationPtg ptg)
		{
			if (ptg == null)
			{
				throw new ArgumentException("ptg must not be null");
			}
			Type type = ptg.GetType();
			ConstructorInfo constructorInfo = (ConstructorInfo)_constructorsByPtgClass[type];
			if (constructorInfo == null)
			{
				if (type == typeof(ExpPtg))
				{
					throw new Exception("ExpPtg currently not supported");
				}
				throw new Exception("Unexpected operation ptg class (" + type.Name + ")");
			}
			object[] parameters = new object[1] { ptg };
			object obj;
			try
			{
				obj = constructorInfo.Invoke(parameters);
			}
			catch (Exception)
			{
				throw;
			}
			return (OperationEval)obj;
		}
	}
	internal class StaticFontMetrics
	{
		private const string FONT_METRICS_PROPERTIES_FILE_NAME = "font_metrics.properties";

		private static Properties fontMetricsProps;

		private static Hashtable fontDetailsMap = new Hashtable();

		public static FontDetails GetFontDetails(Font font)
		{
			if (fontMetricsProps == null)
			{
				Stream stream = null;
				try
				{
					fontMetricsProps = new Properties();
					string text = null;
					try
					{
						text = ConfigurationManager.AppSettings["font.metrics.filename"];
					}
					catch (Exception)
					{
					}
					if (text != null)
					{
						if (!File.Exists(text))
						{
							throw new FileNotFoundException("font_metrics.properties not found at path " + Path.GetFullPath(text));
						}
						stream = typeof(StaticFontMetrics).Assembly.GetManifestResourceStream("font_metrics.properties");
					}
					else
					{
						stream = typeof(StaticFontMetrics).Assembly.GetManifestResourceStream("font_metrics.properties");
						if (stream == null)
						{
							throw new FileNotFoundException("font_metrics.properties not found in classpath");
						}
					}
					fontMetricsProps.Load(stream);
				}
				catch (IOException ex2)
				{
					throw new Exception("Could not Load font metrics: " + ex2.Message);
				}
				finally
				{
					if (stream != null)
					{
						try
						{
							stream.Close();
						}
						catch (IOException)
						{
						}
					}
				}
			}
			string text2 = font.FontFamily.Name;
			string text3 = "";
			if (font.Bold)
			{
				text3 += "bold";
			}
			if (font.Italic)
			{
				text3 += "italic";
			}
			if (fontMetricsProps[FontDetails.BuildFontHeightProperty(text2)] == null && fontMetricsProps[FontDetails.BuildFontHeightProperty(text2 + "." + text3)] != null)
			{
				text2 = text2 + "." + text3;
			}
			if (fontDetailsMap[text2] == null)
			{
				FontDetails fontDetails = FontDetails.Create(text2, fontMetricsProps);
				fontDetailsMap[text2] = fontDetails;
				return fontDetails;
			}
			return (FontDetails)fontDetailsMap[text2];
		}
	}
}
namespace NPOI.HSSF.Util
{
	public class GUID
	{
		private const int TEXT_FORMAT_LENGTH = 36;

		public const int ENCODED_SIZE = 16;

		private int _d1;

		private int _d2;

		private int _d3;

		private long _d4;

		public int D1 => _d1;

		public int D2 => _d2;

		public int D3 => _d3;

		public long D4
		{
			get
			{
				byte[] array;
				using (MemoryStream memoryStream = new MemoryStream(8))
				{
					BinaryWriter binaryWriter = new BinaryWriter(memoryStream);
					binaryWriter.Write(_d4);
					array = memoryStream.ToArray();
					binaryWriter.Close();
				}
				System.Array.Reverse((System.Array)array);
				return new LittleEndianByteArrayInputStream(array).ReadLong();
			}
		}

		public GUID(ILittleEndianInput in1)
			: this(in1.ReadInt(), in1.ReadUShort(), in1.ReadUShort(), in1.ReadLong())
		{
		}

		public GUID(int d1, int d2, int d3, long d4)
		{
			_d1 = d1;
			_d2 = d2;
			_d3 = d3;
			_d4 = d4;
		}

		public void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteInt(_d1);
			out1.WriteShort(_d2);
			out1.WriteShort(_d3);
			out1.WriteLong(_d4);
		}

		public override bool Equals(object obj)
		{
			if (!(obj is GUID))
			{
				return false;
			}
			GUID gUID = (GUID)obj;
			if (_d1 == gUID._d1 && _d2 == gUID._d2 && _d3 == gUID._d3)
			{
				return _d4 == gUID._d4;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return _d1 ^ _d2 ^ _d3 ^ _d4.GetHashCode();
		}

		public string FormatAsString()
		{
			StringBuilder stringBuilder = new StringBuilder(36);
			int length = "0x".Length;
			stringBuilder.Append(HexDump.IntToHex(_d1), length, 8);
			stringBuilder.Append("-");
			stringBuilder.Append(HexDump.ShortToHex(_d2), length, 4);
			stringBuilder.Append("-");
			stringBuilder.Append(HexDump.ShortToHex(_d3), length, 4);
			stringBuilder.Append("-");
			char[] value = HexDump.LongToHex(D4);
			stringBuilder.Append(value, length, 4);
			stringBuilder.Append("-");
			stringBuilder.Append(value, length + 4, 12);
			return stringBuilder.ToString();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(64);
			stringBuilder.Append(GetType().Name).Append(" [");
			stringBuilder.Append(FormatAsString());
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		public static GUID Parse(string rep)
		{
			char[] array = rep.ToCharArray();
			if (array.Length != 36)
			{
				throw new RecordFormatException("supplied text is the wrong length for a GUID");
			}
			int d = (ParseShort(array, 0) << 16) + ParseShort(array, 4);
			int d2 = ParseShort(array, 9);
			int d3 = ParseShort(array, 14);
			for (int num = 23; num > 19; num--)
			{
				array[num] = array[num - 1];
			}
			long d4 = ParseLELong(array, 20);
			return new GUID(d, d2, d3, d4);
		}

		private static long ParseLELong(char[] cc, int startIndex)
		{
			long num = 0L;
			for (int num2 = startIndex + 14; num2 >= startIndex; num2 -= 2)
			{
				num <<= 4;
				num += ParseHexChar(cc[num2]);
				num <<= 4;
				num += ParseHexChar(cc[num2 + 1]);
			}
			return num;
		}

		private static int ParseShort(char[] cc, int startIndex)
		{
			int num = 0;
			for (int i = 0; i < 4; i++)
			{
				num <<= 4;
				num += ParseHexChar(cc[startIndex + i]);
			}
			return num;
		}

		private static int ParseHexChar(char c)
		{
			if (c >= '0' && c <= '9')
			{
				return c - 48;
			}
			if (c >= 'A' && c <= 'F')
			{
				return c - 65 + 10;
			}
			if (c >= 'a' && c <= 'f')
			{
				return c - 97 + 10;
			}
			throw new RecordFormatException("Bad hex char '" + c + "'");
		}
	}
	public class HSSFCellRangeAddress
	{
		public class AddrStructure
		{
			private short _first_row;

			private short _first_col;

			private short _last_row;

			private short _last_col;

			public short FirstColumn
			{
				get
				{
					return _first_col;
				}
				set
				{
					_first_col = value;
				}
			}

			public short FirstRow
			{
				get
				{
					return _first_row;
				}
				set
				{
					_first_row = value;
				}
			}

			public short LastColumn
			{
				get
				{
					return _last_col;
				}
				set
				{
					_last_col = value;
				}
			}

			public short LastRow
			{
				get
				{
					return _last_row;
				}
				set
				{
					_last_row = value;
				}
			}

			public AddrStructure(short first_row, short last_row, short first_col, short last_col)
			{
				_first_row = first_row;
				_last_row = last_row;
				_first_col = first_col;
				_last_col = last_col;
			}
		}

		private static POILogger logger = POILogFactory.GetLogger(typeof(HSSFCellRangeAddress));

		private short field_Addr_number;

		private ArrayList field_regions_list;

		public short AddRStructureNumber => field_Addr_number;

		public int Size => 2 + field_Addr_number * 8;

		public HSSFCellRangeAddress()
		{
		}

		public HSSFCellRangeAddress(RecordInputStream in1)
		{
			FillFields(in1);
		}

		public void FillFields(RecordInputStream in1)
		{
			field_Addr_number = in1.ReadShort();
			field_regions_list = new ArrayList(field_Addr_number);
			for (int i = 0; i < field_Addr_number; i++)
			{
				short num = in1.ReadShort();
				short num2 = in1.ReadShort();
				short first_col = num;
				short last_col = num2;
				if (in1.Remaining >= 4)
				{
					first_col = in1.ReadShort();
					last_col = in1.ReadShort();
				}
				else
				{
					logger.Log(5, "Ran out of data reading cell references for DVRecord");
					i = field_Addr_number;
				}
				AddrStructure value = new AddrStructure(num, num2, first_col, last_col);
				field_regions_list.Add(value);
			}
		}

		public int AddAddRStructure(short first_row, short first_col, short last_row, short last_col)
		{
			if (field_regions_list == null)
			{
				field_Addr_number = 0;
				field_regions_list = new ArrayList(10);
			}
			AddrStructure value = new AddrStructure(first_row, last_row, first_col, last_col);
			field_regions_list.Add(value);
			field_Addr_number++;
			return field_Addr_number;
		}

		public void RemoveAddRStructureAt(int index)
		{
			field_regions_list.Remove(index);
			field_Addr_number--;
		}

		public AddrStructure GetAddRStructureAt(int index)
		{
			return (AddrStructure)field_regions_list[index];
		}

		public int Serialize(int offSet, byte[] data)
		{
			int num = 2;
			LittleEndian.PutShort(data, offSet, AddRStructureNumber);
			for (int i = 0; i < AddRStructureNumber; i++)
			{
				AddrStructure addRStructureAt = GetAddRStructureAt(i);
				LittleEndian.PutShort(data, offSet + num, addRStructureAt.FirstRow);
				num += 2;
				LittleEndian.PutShort(data, offSet + num, addRStructureAt.LastRow);
				num += 2;
				LittleEndian.PutShort(data, offSet + num, addRStructureAt.FirstColumn);
				num += 2;
				LittleEndian.PutShort(data, offSet + num, addRStructureAt.LastColumn);
				num += 2;
			}
			return Size;
		}
	}
	public class RangeAddress
	{
		private const int WRONG_POS = -1;

		private const int MAX_HEIGHT = 66666;

		private string m_sheetName;

		private string m_cellFrom;

		private string m_cellTo;

		public string Address
		{
			get
			{
				string text = "";
				if (m_sheetName != null)
				{
					text = text + m_sheetName + "!";
				}
				if (m_cellFrom != null)
				{
					text += m_cellFrom;
					if (m_cellTo != null)
					{
						text = text + ":" + m_cellTo;
					}
				}
				return text;
			}
		}

		public string SheetName => m_sheetName;

		public string Range
		{
			get
			{
				string text = "";
				if (m_cellFrom != null)
				{
					text += m_cellFrom;
					if (m_cellTo != null)
					{
						text = text + ":" + m_cellTo;
					}
				}
				return text;
			}
		}

		public string FromCell => m_cellFrom;

		public string ToCell => m_cellTo;

		public int Width
		{
			get
			{
				if (m_cellFrom != null && m_cellTo != null)
				{
					int xPosition = GetXPosition(m_cellTo);
					int xPosition2 = GetXPosition(m_cellFrom);
					if (xPosition == -1 || xPosition2 == -1)
					{
						return 0;
					}
					return xPosition - xPosition2 + 1;
				}
				return 0;
			}
		}

		public int Height
		{
			get
			{
				if (m_cellFrom != null && m_cellTo != null)
				{
					int yPosition = GetYPosition(m_cellTo);
					int yPosition2 = GetYPosition(m_cellFrom);
					if (yPosition == -1 || yPosition2 == -1)
					{
						return 0;
					}
					return yPosition - yPosition2 + 1;
				}
				return 0;
			}
		}

		public bool HasSheetName
		{
			get
			{
				if (m_sheetName == null)
				{
					return false;
				}
				return true;
			}
		}

		public bool HasRange
		{
			get
