	internal class MRound : FreeRefFunction
	{
		public static FreeRefFunction Instance = new MRound();

		private MRound()
		{
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length != 2)
			{
				return ErrorEval.VALUE_INVALID;
			}
			try
			{
				double num = OperandResolver.CoerceValueToDouble(OperandResolver.GetSingleValue(args[0], ec.RowIndex, ec.ColumnIndex));
				double num2 = OperandResolver.CoerceValueToDouble(OperandResolver.GetSingleValue(args[1], ec.RowIndex, ec.ColumnIndex));
				double num3;
				if (num2 == 0.0)
				{
					num3 = 0.0;
				}
				else
				{
					if (num * num2 < 0.0)
					{
						throw new EvaluationException(ErrorEval.NUM_ERROR);
					}
					num3 = num2 * Math.Round(num / num2, MidpointRounding.AwayFromZero);
				}
				NumericFunction.CheckValue(num3);
				return new NumberEval(num3);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}
	}
	public class ParityFunction : FreeRefFunction
	{
		public static readonly FreeRefFunction IS_EVEN = new ParityFunction(0);

		public static readonly FreeRefFunction IS_ODD = new ParityFunction(1);

		private int _desiredParity;

		private ParityFunction(int desiredParity)
		{
			_desiredParity = desiredParity;
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length != 1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			int num;
			try
			{
				num = EvaluateArgParity(args[0], ec.RowIndex, ec.ColumnIndex);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return BoolEval.ValueOf(num == _desiredParity);
		}

		private static int EvaluateArgParity(ValueEval arg, int srcCellRow, int srcCellCol)
		{
			ValueEval singleValue = OperandResolver.GetSingleValue(arg, srcCellRow, srcCellCol);
			double num = OperandResolver.CoerceValueToDouble(singleValue);
			if (num < 0.0)
			{
				num = 0.0 - num;
			}
			long num2 = (long)Math.Floor(num);
			return (int)(num2 & 1);
		}
	}
	internal class RandBetween : FreeRefFunction
	{
		public static FreeRefFunction Instance = new RandBetween();

		private RandBetween()
		{
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length != 2)
			{
				return ErrorEval.VALUE_INVALID;
			}
			double num;
			double num2;
			try
			{
				num = OperandResolver.CoerceValueToDouble(OperandResolver.GetSingleValue(args[0], ec.RowIndex, ec.ColumnIndex));
				num2 = OperandResolver.CoerceValueToDouble(OperandResolver.GetSingleValue(args[1], ec.RowIndex, ec.ColumnIndex));
				if (num > num2)
				{
					return ErrorEval.NUM_ERROR;
				}
			}
			catch (EvaluationException)
			{
				return ErrorEval.VALUE_INVALID;
			}
			num = Math.Ceiling(num);
			num2 = Math.Floor(num2);
			if (num > num2)
			{
				num2 = num;
			}
			Random random = new Random();
			return new NumberEval(num + (double)(int)(random.NextDouble() * (num2 - num + 1.0)));
		}
	}
	internal class YearFrac : FreeRefFunction
	{
		public static FreeRefFunction instance = new YearFrac();

		private YearFrac()
		{
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			int rowIndex = ec.RowIndex;
			int columnIndex = ec.ColumnIndex;
			double value;
			try
			{
				int basis = 0;
				switch (args.Length)
				{
				case 3:
					basis = EvaluateIntArg(args[2], rowIndex, columnIndex);
					break;
				default:
					return ErrorEval.VALUE_INVALID;
				case 2:
					break;
				}
				double pStartDateVal = EvaluateDateArg(args[0], rowIndex, columnIndex);
				double pEndDateVal = EvaluateDateArg(args[1], rowIndex, columnIndex);
				value = YearFracCalculator.Calculate(pStartDateVal, pEndDateVal, basis);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(value);
		}

		private static double EvaluateDateArg(ValueEval arg, int srcCellRow, int srcCellCol)
		{
			ValueEval singleValue = OperandResolver.GetSingleValue(arg, srcCellRow, (short)srcCellCol);
			if (singleValue is StringEval)
			{
				string stringValue = ((StringEval)singleValue).StringValue;
				double num = OperandResolver.ParseDouble(stringValue);
				if (!double.IsNaN(num))
				{
					return num;
				}
				DateTime date = DateParser.ParseDate(stringValue);
				return DateUtil.GetExcelDate(date, use1904windowing: false);
			}
			return OperandResolver.CoerceValueToDouble(singleValue);
		}

		private static int EvaluateIntArg(ValueEval arg, int srcCellRow, int srcCellCol)
		{
			ValueEval singleValue = OperandResolver.GetSingleValue(arg, srcCellRow, srcCellCol);
			return OperandResolver.CoerceValueToInt(singleValue);
		}
	}
	public class YearFracCalculator
	{
		private class SimpleDate
		{
			public const int JANUARY = 1;

			public const int FEBRUARY = 2;

			public int year;

			public int month;

			public int day;

			public long ticks;

			public SimpleDate(DateTime date)
			{
				year = date.Year;
				month = date.Month;
				day = date.Day;
				ticks = date.Ticks;
			}
		}

		private const int MS_PER_HOUR = 3600000;

		private const int MS_PER_DAY = 86400000;

		private const int DAYS_PER_NORMAL_YEAR = 365;

		private const int DAYS_PER_LEAP_YEAR = 366;

		private const int LONG_MONTH_LEN = 31;

		private const int SHORT_MONTH_LEN = 30;

		private const int SHORT_FEB_LEN = 28;

		private const int LONG_FEB_LEN = 29;

		public static double Calculate(double pStartDateVal, double pEndDateVal, int basis)
		{
			if (basis < 0 || basis >= 5)
			{
				throw new EvaluationException(ErrorEval.NUM_ERROR);
			}
			int num = (int)Math.Floor(pStartDateVal);
			int num2 = (int)Math.Floor(pEndDateVal);
			if (num == num2)
			{
				return 0.0;
			}
			if (num > num2)
			{
				int num3 = num;
				num = num2;
				num2 = num3;
			}
			return basis switch
			{
				0 => Basis0(num, num2), 
				1 => Basis1(num, num2), 
				2 => Basis2(num, num2), 
				3 => Basis3(num, num2), 
				4 => Basis4(num, num2), 
				_ => throw new InvalidOperationException("cannot happen"), 
			};
		}

		public static double Basis0(int startDateVal, int endDateVal)
		{
			SimpleDate simpleDate = CreateDate(startDateVal);
			SimpleDate simpleDate2 = CreateDate(endDateVal);
			int num = simpleDate.day;
			int num2 = simpleDate2.day;
			if (num == 31 && num2 == 31)
			{
				num = 30;
				num2 = 30;
			}
			else if (num == 31)
			{
				num = 30;
			}
			else if (num == 30 && num2 == 31)
			{
				num2 = 30;
			}
			else if (simpleDate.month == 2 && IsLastDayOfMonth(simpleDate))
			{
				num = 30;
				if (simpleDate2.month == 2 && IsLastDayOfMonth(simpleDate2))
				{
					num2 = 30;
				}
			}
			return CalculateAdjusted(simpleDate, simpleDate2, num, num2);
		}

		public static double Basis1(int startDateVal, int endDateVal)
		{
			SimpleDate simpleDate = CreateDate(startDateVal);
			SimpleDate simpleDate2 = CreateDate(endDateVal);
			double num = (IsGreaterThanOneYear(simpleDate, simpleDate2) ? AverageYearLength(simpleDate.year, simpleDate2.year) : ((!ShouldCountFeb29(simpleDate, simpleDate2)) ? 365.0 : 366.0));
			return DateDiff(simpleDate.ticks, simpleDate2.ticks) / num;
		}

		public static double Basis2(int startDateVal, int endDateVal)
		{
			return (double)(endDateVal - startDateVal) / 360.0;
		}

		public static double Basis3(double startDateVal, double endDateVal)
		{
			return (endDateVal - startDateVal) / 365.0;
		}

		public static double Basis4(int startDateVal, int endDateVal)
		{
			SimpleDate simpleDate = CreateDate(startDateVal);
			SimpleDate simpleDate2 = CreateDate(endDateVal);
			int num = simpleDate.day;
			int num2 = simpleDate2.day;
			if (num == 31)
			{
				num = 30;
			}
			if (num2 == 31)
			{
				num2 = 30;
			}
			return CalculateAdjusted(simpleDate, simpleDate2, num, num2);
		}

		private static double CalculateAdjusted(SimpleDate startDate, SimpleDate endDate, int date1day, int date2day)
		{
			double num = (endDate.year - startDate.year) * 360 + (endDate.month - startDate.month) * 30 + (date2day - date1day);
			return num / 360.0;
		}

		private static bool IsLastDayOfMonth(SimpleDate date)
		{
			if (date.day < 28)
			{
				return false;
			}
			return date.day == GetLastDayOfMonth(date);
		}

		private static int GetLastDayOfMonth(SimpleDate date)
		{
			switch (date.month)
			{
			case 1:
			case 3:
			case 5:
			case 7:
			case 8:
			case 10:
			case 12:
				return 31;
			case 4:
			case 6:
			case 9:
			case 11:
				return 30;
			default:
				if (IsLeapYear(date.year))
				{
					return 29;
				}
				return 28;
			}
		}

		private static bool ShouldCountFeb29(SimpleDate start, SimpleDate end)
		{
			bool flag = IsLeapYear(start.year);
			if (flag && start.year == end.year)
			{
				return true;
			}
			bool flag2 = IsLeapYear(end.year);
			if (!flag && !flag2)
			{
				return false;
			}
			if (flag)
			{
				switch (start.month)
				{
				case 1:
				case 2:
					return true;
				default:
					return false;
				}
			}
			if (flag2)
			{
				return end.month switch
				{
					1 => false, 
					2 => end.day == 29, 
					_ => true, 
				};
			}
			return false;
		}

		private static double DateDiff(long startDateTicks, long endDateTicks)
		{
			return new TimeSpan(endDateTicks - startDateTicks).TotalDays;
		}

		private static double AverageYearLength(int startYear, int endYear)
		{
			int num = 0;
			for (int i = startYear; i <= endYear; i++)
			{
				num += 365;
				if (IsLeapYear(i))
				{
					num++;
				}
			}
			double num2 = endYear - startYear + 1;
			return (double)num / num2;
		}

		private static bool IsLeapYear(int i)
		{
			if (i % 4 != 0)
			{
				return false;
			}
			if (i % 400 == 0)
			{
				return true;
			}
			if (i % 100 == 0)
			{
				return false;
			}
			return true;
		}

		private static bool IsGreaterThanOneYear(SimpleDate start, SimpleDate end)
		{
			if (start.year == end.year)
			{
				return false;
			}
			if (start.year + 1 != end.year)
			{
				return true;
			}
			if (start.month > end.month)
			{
				return false;
			}
			if (start.month < end.month)
			{
				return true;
			}
			return start.day < end.day;
		}

		private static SimpleDate CreateDate(int dayCount)
		{
			DateTime calendar = DateTime.Now;
			DateUtil.SetCalendar(ref calendar, dayCount, 0, use1904windowing: false, roundSeconds: false);
			return new SimpleDate(calendar);
		}
	}
}
namespace NPOI.SS.Formula
{
	public interface ICacheEntry
	{
		ValueEval GetValue();
	}
	public abstract class CellCacheEntry : ICacheEntry
	{
		public static CellCacheEntry[] EMPTY_ARRAY = new CellCacheEntry[0];

		private FormulaCellCacheEntrySet _consumingCells;

		private ValueEval _value;

		protected CellCacheEntry()
		{
			_consumingCells = new FormulaCellCacheEntrySet();
		}

		protected void ClearValue()
		{
			_value = null;
		}

		public bool UpdateValue(ValueEval value)
		{
			if (value == null)
			{
				throw new ArgumentException("Did not expect To Update To null");
			}
			bool result = !AreValuesEqual(_value, value);
			_value = value;
			return result;
		}

		public ValueEval GetValue()
		{
			return _value;
		}

		private static bool AreValuesEqual(ValueEval a, ValueEval b)
		{
			if (a == null)
			{
				return false;
			}
			Type type = a.GetType();
			if (type != b.GetType())
			{
				return false;
			}
			if (a == BlankEval.instance)
			{
				return b == a;
			}
			if (type == typeof(NumberEval))
			{
				return ((NumberEval)a).NumberValue == ((NumberEval)b).NumberValue;
			}
			if (type == typeof(StringEval))
			{
				return ((StringEval)a).StringValue.Equals(((StringEval)b).StringValue);
			}
			if (type == typeof(BoolEval))
			{
				return ((BoolEval)a).BooleanValue == ((BoolEval)b).BooleanValue;
			}
			if (type == typeof(ErrorEval))
			{
				return ((ErrorEval)a).ErrorCode == ((ErrorEval)b).ErrorCode;
			}
			throw new InvalidOperationException("Unexpected value class (" + type.Name + ")");
		}

		public void AddConsumingCell(FormulaCellCacheEntry cellLoc)
		{
			_consumingCells.Add(cellLoc);
		}

		public FormulaCellCacheEntry[] GetConsumingCells()
		{
			return _consumingCells.ToArray();
		}

		public void ClearConsumingCell(FormulaCellCacheEntry cce)
		{
			if (!_consumingCells.Remove(cce))
			{
				throw new InvalidOperationException("Specified formula cell is not consumed by this cell");
			}
		}

		public void RecurseClearCachedFormulaResults(IEvaluationListener listener)
		{
			if (listener == null)
			{
				RecurseClearCachedFormulaResults();
				return;
			}
			listener.OnClearCachedValue(this);
			RecurseClearCachedFormulaResults(listener, 1);
		}

		protected void RecurseClearCachedFormulaResults()
		{
			FormulaCellCacheEntry[] consumingCells = GetConsumingCells();
			foreach (FormulaCellCacheEntry formulaCellCacheEntry in consumingCells)
			{
				formulaCellCacheEntry.ClearFormulaEntry();
				formulaCellCacheEntry.RecurseClearCachedFormulaResults();
			}
		}

		protected void RecurseClearCachedFormulaResults(IEvaluationListener listener, int depth)
		{
			FormulaCellCacheEntry[] consumingCells = GetConsumingCells();
			listener.SortDependentCachedValues(consumingCells);
			foreach (FormulaCellCacheEntry formulaCellCacheEntry in consumingCells)
			{
				listener.OnClearDependentCachedValue(formulaCellCacheEntry, depth);
				formulaCellCacheEntry.ClearFormulaEntry();
				formulaCellCacheEntry.RecurseClearCachedFormulaResults(listener, depth + 1);
			}
		}
	}
	internal class CellEvaluationFrame
	{
		private FormulaCellCacheEntry _cce;

		private ArrayList _sensitiveInputCells;

		private FormulaUsedBlankCellSet _usedBlankCellGroup;

		public CellEvaluationFrame(FormulaCellCacheEntry cce)
		{
			_cce = cce;
			_sensitiveInputCells = new ArrayList();
		}

		public CellCacheEntry GetCCE()
		{
			return _cce;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(64);
			stringBuilder.Append(GetType().Name).Append(" [");
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		public void AddSensitiveInputCell(CellCacheEntry inputCell)
		{
			_sensitiveInputCells.Add(inputCell);
		}

		private CellCacheEntry[] GetSensitiveInputCells()
		{
			int count = _sensitiveInputCells.Count;
			if (count < 1)
			{
				return CellCacheEntry.EMPTY_ARRAY;
			}
			CellCacheEntry[] array = new CellCacheEntry[count];
			return (CellCacheEntry[])_sensitiveInputCells.ToArray(typeof(CellCacheEntry));
		}

		public void AddUsedBlankCell(int bookIndex, int sheetIndex, int rowIndex, int columnIndex)
		{
			if (_usedBlankCellGroup == null)
			{
				_usedBlankCellGroup = new FormulaUsedBlankCellSet();
			}
			_usedBlankCellGroup.AddCell(bookIndex, sheetIndex, rowIndex, columnIndex);
		}

		public void UpdateFormulaResult(ValueEval result)
		{
			_cce.UpdateFormulaResult(result, GetSensitiveInputCells(), _usedBlankCellGroup);
		}
	}
	[Serializable]
	public class WorkbookNotFoundException : Exception
	{
		public WorkbookNotFoundException(string msg)
			: base(msg)
		{
		}
	}
	public class CollaboratingWorkbooksEnvironment
	{
		public static readonly CollaboratingWorkbooksEnvironment EMPTY = new CollaboratingWorkbooksEnvironment();

		private Dictionary<string, WorkbookEvaluator> _evaluatorsByName;

		private WorkbookEvaluator[] _evaluators;

		private bool _unhooked;

		private CollaboratingWorkbooksEnvironment()
		{
			_evaluatorsByName = new Dictionary<string, WorkbookEvaluator>();
			_evaluators = new WorkbookEvaluator[0];
		}

		public static void Setup(string[] workbookNames, WorkbookEvaluator[] evaluators)
		{
			int num = workbookNames.Length;
			if (evaluators.Length != num)
			{
				throw new ArgumentException("Number of workbook names is " + num + " but number of evaluators is " + evaluators.Length);
			}
			if (num < 1)
			{
				throw new ArgumentException("Must provide at least one collaborating worbook");
			}
			CollaboratingWorkbooksEnvironment env = new CollaboratingWorkbooksEnvironment(workbookNames, evaluators, num);
			HookNewEnvironment(evaluators, env);
		}

		public static void Setup(Dictionary<string, WorkbookEvaluator> evaluatorsByName)
		{
			if (evaluatorsByName.Count < 1)
			{
				throw new ArgumentException("Must provide at least one collaborating worbook");
			}
			List<WorkbookEvaluator> list = new List<WorkbookEvaluator>(evaluatorsByName.Count);
			list.AddRange(evaluatorsByName.Values);
			WorkbookEvaluator[] evaluators = list.ToArray();
			new CollaboratingWorkbooksEnvironment(evaluatorsByName, evaluators);
		}

		public static void SetupFormulaEvaluator(Dictionary<string, IFormulaEvaluator> evaluators)
		{
			Dictionary<string, WorkbookEvaluator> dictionary = new Dictionary<string, WorkbookEvaluator>(evaluators.Count);
			foreach (string key in evaluators.Keys)
			{
				IFormulaEvaluator formulaEvaluator = evaluators[key];
				if (formulaEvaluator is IWorkbookEvaluatorProvider)
				{
					dictionary.Add(key, ((IWorkbookEvaluatorProvider)formulaEvaluator).GetWorkbookEvaluator());
					continue;
				}
				throw new ArgumentException(string.Concat("Formula Evaluator ", formulaEvaluator, " provides no WorkbookEvaluator access"));
			}
			Setup(dictionary);
		}

		private CollaboratingWorkbooksEnvironment(string[] workbookNames, WorkbookEvaluator[] evaluators, int nItems)
			: this(toUniqueMap(workbookNames, evaluators, nItems), evaluators)
		{
		}

		private static Dictionary<string, WorkbookEvaluator> toUniqueMap(string[] workbookNames, WorkbookEvaluator[] evaluators, int nItems)
		{
			Dictionary<string, WorkbookEvaluator> dictionary = new Dictionary<string, WorkbookEvaluator>(nItems * 3 / 2);
			for (int i = 0; i < nItems; i++)
			{
				string text = workbookNames[i];
				WorkbookEvaluator value = evaluators[i];
				if (dictionary.ContainsKey(text))
				{
					throw new ArgumentException("Duplicate workbook name '" + text + "'");
				}
				dictionary.Add(text, value);
			}
			return dictionary;
		}

		private CollaboratingWorkbooksEnvironment(Dictionary<string, WorkbookEvaluator> evaluatorsByName, WorkbookEvaluator[] evaluators)
		{
			Dictionary<WorkbookEvaluator, string> dictionary = new Dictionary<WorkbookEvaluator, string>(evaluators.Length);
			foreach (string key2 in evaluatorsByName.Keys)
			{
				WorkbookEvaluator key = evaluatorsByName[key2];
				if (dictionary.ContainsKey(key))
				{
					string message = "Attempted to register same workbook under names '" + dictionary[key] + "' and '" + key2 + "'";
					throw new ArgumentException(message);
				}
				dictionary.Add(key, key2);
			}
			UnhookOldEnvironments(evaluators);
			HookNewEnvironment(evaluators, this);
			_unhooked = false;
			_evaluators = evaluators;
			_evaluatorsByName = evaluatorsByName;
		}

		private static void HookNewEnvironment(WorkbookEvaluator[] evaluators, CollaboratingWorkbooksEnvironment env)
		{
			int num = evaluators.Length;
			IEvaluationListener evaluationListener = evaluators[0].GetEvaluationListener();
			for (int i = 0; i < num; i++)
			{
				if (evaluationListener != evaluators[i].GetEvaluationListener())
				{
					throw new Exception("Workbook evaluators must all have the same evaluation listener");
				}
			}
			EvaluationCache cache = new EvaluationCache(evaluationListener);
			for (int j = 0; j < num; j++)
			{
				evaluators[j].AttachToEnvironment(env, cache, j);
			}
		}

		private void UnhookOldEnvironments(WorkbookEvaluator[] evaluators)
		{
			ArrayList arrayList = new ArrayList();
			for (int i = 0; i < evaluators.Length; i++)
			{
				arrayList.Add(evaluators[i].GetEnvironment());
			}
			CollaboratingWorkbooksEnvironment[] array = new CollaboratingWorkbooksEnvironment[arrayList.Count];
			array = (CollaboratingWorkbooksEnvironment[])arrayList.ToArray(typeof(CollaboratingWorkbooksEnvironment));
			for (int j = 0; j < array.Length; j++)
			{
				array[j].Unhook();
			}
		}

		private void Unhook()
		{
			if (_evaluators.Length >= 1)
			{
				for (int i = 0; i < _evaluators.Length; i++)
				{
					_evaluators[i].DetachFromEnvironment();
				}
				_unhooked = true;
			}
		}

		public WorkbookEvaluator GetWorkbookEvaluator(string workbookName)
		{
			if (_unhooked)
			{
				throw new InvalidOperationException("This environment Has been unhooked");
			}
			if (_evaluatorsByName.ContainsKey(workbookName))
			{
				return _evaluatorsByName[workbookName];
			}
			StringBuilder stringBuilder = new StringBuilder(256);
			stringBuilder.Append("Could not resolve external workbook name '").Append(workbookName).Append("'.");
			if (_evaluators.Length < 1)
			{
				stringBuilder.Append(" Workbook environment has not been set up.");
			}
			else
			{
				stringBuilder.Append(" The following workbook names are valid: (");
				IEnumerator enumerator = _evaluatorsByName.Keys.GetEnumerator();
				int num = 0;
				while (enumerator.MoveNext())
				{
					if (num++ > 0)
					{
						stringBuilder.Append(", ");
					}
					stringBuilder.Append("'").Append(enumerator.Current).Append("'");
				}
				stringBuilder.Append(")");
			}
			throw new WorkbookNotFoundException(stringBuilder.ToString());
		}
	}
	public class EvaluationCache
	{
		public class EntryOperation : IEntryOperation
		{
			private BookSheetKey bsk;

			private int rowIndex;

			private int columnIndex;

			private IEvaluationListener evaluationListener;

			public EntryOperation(BookSheetKey bsk, int rowIndex, int columnIndex, IEvaluationListener evaluationListener)
			{
				this.bsk = bsk;
				this.evaluationListener = evaluationListener;
				this.rowIndex = rowIndex;
				this.columnIndex = columnIndex;
			}

			public void ProcessEntry(FormulaCellCacheEntry entry)
			{
				entry.NotifyUpdatedBlankCell(bsk, rowIndex, columnIndex, evaluationListener);
			}
		}

		private PlainCellCache _plainCellCache;

		private FormulaCellCache _formulaCellCache;

		private IEvaluationListener _evaluationListener;

		public EvaluationCache(IEvaluationListener evaluationListener)
		{
			_evaluationListener = evaluationListener;
			_plainCellCache = new PlainCellCache();
			_formulaCellCache = new FormulaCellCache();
		}

		public void NotifyUpdateCell(int bookIndex, int sheetIndex, IEvaluationCell cell)
		{
			FormulaCellCacheEntry formulaCellCacheEntry = _formulaCellCache.Get(cell);
			int rowIndex = cell.RowIndex;
			int columnIndex = cell.ColumnIndex;
			Loc key = new Loc(bookIndex, sheetIndex, cell.RowIndex, cell.ColumnIndex);
			PlainValueCellCacheEntry plainValueCellCacheEntry = _plainCellCache.Get(key);
			if (cell.CellType == CellType.Formula)
			{
				if (formulaCellCacheEntry == null)
				{
					formulaCellCacheEntry = new FormulaCellCacheEntry();
					if (plainValueCellCacheEntry == null)
					{
						if (_evaluationListener != null)
						{
							_evaluationListener.OnChangeFromBlankValue(sheetIndex, rowIndex, columnIndex, cell, formulaCellCacheEntry);
						}
						UpdateAnyBlankReferencingFormulas(bookIndex, sheetIndex, rowIndex, columnIndex);
					}
					_formulaCellCache.Put(cell, formulaCellCacheEntry);
				}
				else
				{
					formulaCellCacheEntry.RecurseClearCachedFormulaResults(_evaluationListener);
					formulaCellCacheEntry.ClearFormulaEntry();
				}
				if (plainValueCellCacheEntry != null)
				{
					plainValueCellCacheEntry.RecurseClearCachedFormulaResults(_evaluationListener);
					_plainCellCache.Remove(key);
				}
				return;
			}
			ValueEval valueFromNonFormulaCell = WorkbookEvaluator.GetValueFromNonFormulaCell(cell);
			if (plainValueCellCacheEntry == null)
			{
				if (valueFromNonFormulaCell != BlankEval.instance)
				{
					plainValueCellCacheEntry = new PlainValueCellCacheEntry(valueFromNonFormulaCell);
					if (formulaCellCacheEntry == null)
					{
						if (_evaluationListener != null)
						{
							_evaluationListener.OnChangeFromBlankValue(sheetIndex, rowIndex, columnIndex, cell, plainValueCellCacheEntry);
						}
						UpdateAnyBlankReferencingFormulas(bookIndex, sheetIndex, rowIndex, columnIndex);
					}
					_plainCellCache.Put(key, plainValueCellCacheEntry);
				}
			}
			else
			{
				if (plainValueCellCacheEntry.UpdateValue(valueFromNonFormulaCell))
				{
					plainValueCellCacheEntry.RecurseClearCachedFormulaResults(_evaluationListener);
				}
				if (valueFromNonFormulaCell == BlankEval.instance)
				{
					_plainCellCache.Remove(key);
				}
			}
			if (formulaCellCacheEntry != null)
			{
				_formulaCellCache.Remove(cell);
				formulaCellCacheEntry.SetSensitiveInputCells(null);
				formulaCellCacheEntry.RecurseClearCachedFormulaResults(_evaluationListener);
			}
		}

		private void UpdateAnyBlankReferencingFormulas(int bookIndex, int sheetIndex, int rowIndex, int columnIndex)
		{
			BookSheetKey bsk = new BookSheetKey(bookIndex, sheetIndex);
			_formulaCellCache.ApplyOperation(new EntryOperation(bsk, rowIndex, columnIndex, _evaluationListener));
		}

		public PlainValueCellCacheEntry GetPlainValueEntry(int bookIndex, int sheetIndex, int rowIndex, int columnIndex, ValueEval value)
		{
			Loc key = new Loc(bookIndex, sheetIndex, rowIndex, columnIndex);
			PlainValueCellCacheEntry plainValueCellCacheEntry = _plainCellCache.Get(key);
			if (plainValueCellCacheEntry == null)
			{
				plainValueCellCacheEntry = new PlainValueCellCacheEntry(value);
				_plainCellCache.Put(key, plainValueCellCacheEntry);
				if (_evaluationListener != null)
				{
					_evaluationListener.OnReadPlainValue(sheetIndex, rowIndex, columnIndex, plainValueCellCacheEntry);
				}
			}
			else
			{
				if (!AreValuesEqual(plainValueCellCacheEntry.GetValue(), value))
				{
					throw new InvalidOperationException("value changed");
				}
				if (_evaluationListener != null)
				{
					_evaluationListener.OnCacheHit(sheetIndex, rowIndex, columnIndex, value);
				}
			}
			return plainValueCellCacheEntry;
		}

		private bool AreValuesEqual(ValueEval a, ValueEval b)
		{
			if (a == null)
			{
				return false;
			}
			Type type = a.GetType();
			if (type != b.GetType())
			{
				return false;
			}
			if (a == BlankEval.instance)
			{
				return b == a;
			}
			if (type == typeof(NumberEval))
			{
				return ((NumberEval)a).NumberValue == ((NumberEval)b).NumberValue;
			}
			if (type == typeof(StringEval))
			{
				return ((StringEval)a).StringValue.Equals(((StringEval)b).StringValue);
			}
			if (type == typeof(BoolEval))
			{
				return ((BoolEval)a).BooleanValue == ((BoolEval)b).BooleanValue;
			}
			if (type == typeof(ErrorEval))
			{
				return ((ErrorEval)a).ErrorCode == ((ErrorEval)b).ErrorCode;
			}
			throw new InvalidOperationException("Unexpected value class (" + type.Name + ")");
		}

		public FormulaCellCacheEntry GetOrCreateFormulaCellEntry(IEvaluationCell cell)
		{
			FormulaCellCacheEntry formulaCellCacheEntry = _formulaCellCache.Get(cell);
			if (formulaCellCacheEntry == null)
			{
				formulaCellCacheEntry = new FormulaCellCacheEntry();
				_formulaCellCache.Put(cell, formulaCellCacheEntry);
			}
			return formulaCellCacheEntry;
		}

		public void Clear()
		{
			if (_evaluationListener != null)
			{
				_evaluationListener.OnClearWholeCache();
			}
			_plainCellCache.Clear();
			_formulaCellCache.Clear();
		}

		public void NotifyDeleteCell(int bookIndex, int sheetIndex, IEvaluationCell cell)
		{
			if (cell.CellType == CellType.Formula)
			{
				FormulaCellCacheEntry formulaCellCacheEntry = _formulaCellCache.Remove(cell);
				if (formulaCellCacheEntry != null)
				{
					formulaCellCacheEntry.SetSensitiveInputCells(null);
					formulaCellCacheEntry.RecurseClearCachedFormulaResults(_evaluationListener);
				}
			}
			else
			{
				Loc key = new Loc(bookIndex, sheetIndex, cell.RowIndex, cell.ColumnIndex);
				_plainCellCache.Get(key)?.RecurseClearCachedFormulaResults(_evaluationListener);
			}
		}
	}
	public interface IEntryOperation
	{
		void ProcessEntry(FormulaCellCacheEntry entry);
	}
	public class EvaluationTracker
	{
		private IList _evaluationFrames;

		private IList _currentlyEvaluatingCells;

		private EvaluationCache _cache;

		public EvaluationTracker(EvaluationCache cache)
		{
			_cache = cache;
			_evaluationFrames = new ArrayList();
			_currentlyEvaluatingCells = new ArrayList();
		}

		public bool StartEvaluate(FormulaCellCacheEntry cce)
		{
			if (cce == null)
			{
				throw new ArgumentException("cellLoc must not be null");
			}
			if (_currentlyEvaluatingCells.Contains(cce))
			{
				return false;
			}
			_currentlyEvaluatingCells.Add(cce);
			_evaluationFrames.Add(new CellEvaluationFrame(cce));
			return true;
		}

		public void UpdateCacheResult(ValueEval result)
		{
			int count = _evaluationFrames.Count;
			if (count < 1)
			{
				throw new InvalidOperationException("Call To endEvaluate without matching call To startEvaluate");
			}
			CellEvaluationFrame cellEvaluationFrame = (CellEvaluationFrame)_evaluationFrames[count - 1];
			cellEvaluationFrame.UpdateFormulaResult(result);
		}

		public void EndEvaluate(CellCacheEntry cce)
		{
			int count = _evaluationFrames.Count;
			if (count < 1)
			{
				throw new InvalidOperationException("Call To endEvaluate without matching call To startEvaluate");
			}
			count--;
			CellEvaluationFrame cellEvaluationFrame = (CellEvaluationFrame)_evaluationFrames[count];
			if (cce != cellEvaluationFrame.GetCCE())
			{
				throw new InvalidOperationException("Wrong cell specified. ");
			}
			_evaluationFrames.RemoveAt(count);
			_currentlyEvaluatingCells.Remove(cce);
		}

		public void AcceptFormulaDependency(CellCacheEntry cce)
		{
			int num = _evaluationFrames.Count - 1;
			if (num >= 0)
			{
				CellEvaluationFrame cellEvaluationFrame = (CellEvaluationFrame)_evaluationFrames[num];
				cellEvaluationFrame.AddSensitiveInputCell(cce);
			}
		}

		public void AcceptPlainValueDependency(int bookIndex, int sheetIndex, int rowIndex, int columnIndex, ValueEval value)
		{
			int num = _evaluationFrames.Count - 1;
			if (num >= 0)
			{
				CellEvaluationFrame cellEvaluationFrame = (CellEvaluationFrame)_evaluationFrames[num];
				if (value == BlankEval.instance)
				{
					cellEvaluationFrame.AddUsedBlankCell(bookIndex, sheetIndex, rowIndex, columnIndex);
					return;
				}
				PlainValueCellCacheEntry plainValueEntry = _cache.GetPlainValueEntry(bookIndex, sheetIndex, rowIndex, columnIndex, value);
				cellEvaluationFrame.AddSensitiveInputCell(plainValueEntry);
			}
		}
	}
