		public static void RegisterFunction(string name, NPOI.SS.Formula.Functions.Function func)
		{
			FunctionMetadata functionByName = FunctionMetadataRegistry.GetFunctionByName(name);
			if (functionByName == null)
			{
				if (AnalysisToolPak.IsATPFunction(name))
				{
					throw new ArgumentException(name + " is a function from the Excel Analysis Toolpack. Use AnalysisToolpack.RegisterFunction(String name, FreeRefFunction func) instead.");
				}
				throw new ArgumentException("Unknown function: " + name);
			}
			int index = functionByName.Index;
			if (functions[index] is NotImplementedFunction)
			{
				functions[index] = func;
				return;
			}
			throw new ArgumentException("POI already implememts " + name + ". You cannot override POI's implementations of Excel functions");
		}

		public static ReadOnlyCollection<string> GetSupportedFunctionNames()
		{
			List<string> list = new List<string>();
			for (int i = 0; i < functions.Length; i++)
			{
				NPOI.SS.Formula.Functions.Function function = functions[i];
				FunctionMetadata functionByIndex = FunctionMetadataRegistry.GetFunctionByIndex(i);
				if (function != null && !(function is NotImplementedFunction))
				{
					list.Add(functionByIndex.Name);
				}
			}
			list.Add("INDIRECT");
			return list.AsReadOnly();
		}

		public static ReadOnlyCollection<string> GetNotSupportedFunctionNames()
		{
			List<string> list = new List<string>();
			for (int i = 0; i < functions.Length; i++)
			{
				NPOI.SS.Formula.Functions.Function function = functions[i];
				if (function != null && function is NotImplementedFunction)
				{
					FunctionMetadata functionByIndex = FunctionMetadataRegistry.GetFunctionByIndex(i);
					list.Add(functionByIndex.Name);
				}
			}
			list.Remove("INDIRECT");
			return list.AsReadOnly();
		}
	}
	public class IntersectionEval : Fixed2ArgFunction
	{
		public static NPOI.SS.Formula.Functions.Function instance = new IntersectionEval();

		private IntersectionEval()
		{
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			try
			{
				AreaEval aeA = EvaluateRef(arg0);
				AreaEval aeB = EvaluateRef(arg1);
				AreaEval areaEval = ResolveRange(aeA, aeB);
				if (areaEval == null)
				{
					return ErrorEval.NULL_INTERSECTION;
				}
				return areaEval;
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		private static AreaEval ResolveRange(AreaEval aeA, AreaEval aeB)
		{
			int firstRow = aeA.FirstRow;
			int firstColumn = aeA.FirstColumn;
			int lastColumn = aeB.LastColumn;
			if (firstColumn > lastColumn)
			{
				return null;
			}
			int firstColumn2 = aeB.FirstColumn;
			if (firstColumn2 > aeA.LastColumn)
			{
				return null;
			}
			int lastRow = aeB.LastRow;
			if (firstRow > lastRow)
			{
				return null;
			}
			int firstRow2 = aeB.FirstRow;
			int lastRow2 = aeA.LastRow;
			if (firstRow2 > lastRow2)
			{
				return null;
			}
			int num = Math.Max(firstRow, firstRow2);
			int num2 = Math.Min(lastRow2, lastRow);
			int num3 = Math.Max(firstColumn, firstColumn2);
			int num4 = Math.Min(aeA.LastColumn, lastColumn);
			return aeA.Offset(num - firstRow, num2 - firstRow, num3 - firstColumn, num4 - firstColumn);
		}

		private AreaEval EvaluateRef(ValueEval arg)
		{
			if (arg is AreaEval)
			{
				return (AreaEval)arg;
			}
			if (arg is RefEval)
			{
				return ((RefEval)arg).Offset(0, 0, 0, 0);
			}
			if (arg is ErrorEval)
			{
				throw new EvaluationException((ErrorEval)arg);
			}
			throw new ArgumentException("Unexpected ref arg class (" + arg.GetType().Name + ")");
		}
	}
