	public abstract class TwoOperandNumericOperation : Fixed2ArgFunction
	{
		public static NPOI.SS.Formula.Functions.Function AddEval = new AddEval();

		public static NPOI.SS.Formula.Functions.Function DivideEval = new DivideEval();

		public static NPOI.SS.Formula.Functions.Function MultiplyEval = new MultiplyEval();

		public static NPOI.SS.Formula.Functions.Function PowerEval = new PowerEval();

		public static NPOI.SS.Formula.Functions.Function SubtractEval = new SubtractEval();

		protected double SingleOperandEvaluate(ValueEval arg, int srcCellRow, int srcCellCol)
		{
			ValueEval singleValue = OperandResolver.GetSingleValue(arg, srcCellRow, srcCellCol);
			return OperandResolver.CoerceValueToDouble(singleValue);
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			double num;
			try
			{
				double d = SingleOperandEvaluate(arg0, srcRowIndex, srcColumnIndex);
				double d2 = SingleOperandEvaluate(arg1, srcRowIndex, srcColumnIndex);
				num = Evaluate(d, d2);
				if (num == 0.0 && !(this is SubtractEval))
				{
					return NumberEval.ZERO;
				}
				if (double.IsNaN(num) || double.IsInfinity(num))
				{
					return ErrorEval.NUM_ERROR;
				}
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(num);
		}

		public abstract double Evaluate(double d0, double d1);
	}
	public class AddEval : TwoOperandNumericOperation
	{
		public override double Evaluate(double d0, double d1)
		{
			return d0 + d1;
		}
	}
	public class DivideEval : TwoOperandNumericOperation
	{
		public override double Evaluate(double d0, double d1)
		{
			if (d1 == 0.0)
			{
				throw new EvaluationException(ErrorEval.DIV_ZERO);
			}
			return d0 / d1;
		}
	}
	public class MultiplyEval : TwoOperandNumericOperation
	{
		public override double Evaluate(double d0, double d1)
		{
			return d0 * d1;
		}
	}
	public class PowerEval : TwoOperandNumericOperation
	{
		public override double Evaluate(double d0, double d1)
		{
			return Math.Pow(d0, d1);
		}
	}
	public class SubtractEval : TwoOperandNumericOperation
	{
		public override double Evaluate(double d0, double d1)
		{
			return d0 - d1;
		}
	}
	public class UnaryMinusEval : Fixed1ArgFunction
	{
		public static NPOI.SS.Formula.Functions.Function instance = new UnaryMinusEval();

		private UnaryMinusEval()
		{
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0)
		{
			double num;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(arg0, srcRowIndex, srcColumnIndex);
				num = OperandResolver.CoerceValueToDouble(singleValue);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			if (num == 0.0)
			{
				return NumberEval.ZERO;
			}
			return new NumberEval(0.0 - num);
		}
	}
	public class UnaryPlusEval : Fixed1ArgFunction
	{
		public static NPOI.SS.Formula.Functions.Function instance = new UnaryPlusEval();

		private UnaryPlusEval()
		{
		}

		public override ValueEval Evaluate(int srcCellRow, int srcCellCol, ValueEval arg0)
		{
			double value;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(arg0, srcCellRow, srcCellCol);
				if (singleValue is BlankEval)
				{
					return NumberEval.ZERO;
				}
				if (singleValue is StringEval)
				{
					return singleValue;
				}
				value = OperandResolver.CoerceValueToDouble(singleValue);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(value);
		}
	}
