		public CellCacheEntry[] GetCacheEntries()
		{
			FormulaCellCacheEntry[] array = new FormulaCellCacheEntry[_formulaEntriesByCell.Count];
			_formulaEntriesByCell.Values.CopyTo(array, 0);
			return array;
