	public class FormulaCellCacheEntry : CellCacheEntry
	{
		public new static FormulaCellCacheEntry[] EMPTY_ARRAY = new FormulaCellCacheEntry[0];

		private CellCacheEntry[] _sensitiveInputCells;

		private FormulaUsedBlankCellSet _usedBlankCellGroup;

		public bool IsInputSensitive
		{
			get
			{
				if (_sensitiveInputCells != null && _sensitiveInputCells.Length > 0)
				{
					return true;
				}
				if (_usedBlankCellGroup != null)
				{
					return !_usedBlankCellGroup.IsEmpty;
				}
				return false;
			}
		}

		public void SetSensitiveInputCells(CellCacheEntry[] sensitiveInputCells)
		{
			ChangeConsumingCells((sensitiveInputCells == null) ? CellCacheEntry.EMPTY_ARRAY : sensitiveInputCells);
			_sensitiveInputCells = sensitiveInputCells;
		}

		public void ClearFormulaEntry()
		{
			CellCacheEntry[] sensitiveInputCells = _sensitiveInputCells;
			if (sensitiveInputCells != null)
			{
				for (int num = sensitiveInputCells.Length - 1; num >= 0; num--)
				{
					sensitiveInputCells[num].ClearConsumingCell(this);
				}
			}
			_sensitiveInputCells = null;
			ClearValue();
		}

		private void ChangeConsumingCells(CellCacheEntry[] usedCells)
		{
			CellCacheEntry[] sensitiveInputCells = _sensitiveInputCells;
			int num = usedCells.Length;
			for (int i = 0; i < num; i++)
			{
				usedCells[i].AddConsumingCell(this);
			}
			if (sensitiveInputCells == null)
			{
				return;
			}
			int num2 = sensitiveInputCells.Length;
			if (num2 < 1)
			{
				return;
			}
			ArrayList arrayList;
			if (num < 1)
			{
				arrayList = new ArrayList();
			}
			else
			{
				arrayList = new ArrayList(num * 3 / 2);
				for (int j = 0; j < num; j++)
				{
					arrayList.Add(usedCells[j]);
				}
			}
			for (int k = 0; k < num2; k++)
			{
				CellCacheEntry cellCacheEntry = sensitiveInputCells[k];
				if (!arrayList.Contains(cellCacheEntry))
				{
					cellCacheEntry.ClearConsumingCell(this);
				}
			}
		}

		public void UpdateFormulaResult(ValueEval result, CellCacheEntry[] sensitiveInputCells, FormulaUsedBlankCellSet usedBlankAreas)
		{
			UpdateValue(result);
			SetSensitiveInputCells(sensitiveInputCells);
			_usedBlankCellGroup = usedBlankAreas;
		}

		public void NotifyUpdatedBlankCell(BookSheetKey bsk, int rowIndex, int columnIndex, IEvaluationListener evaluationListener)
		{
			if (_usedBlankCellGroup != null && _usedBlankCellGroup.ContainsCell(bsk, rowIndex, columnIndex))
			{
				ClearFormulaEntry();
				RecurseClearCachedFormulaResults(evaluationListener);
			}
		}
	}
	internal class FormulaCellCacheEntrySet
	{
		private int _size;

		private FormulaCellCacheEntry[] _arr;

		public FormulaCellCacheEntrySet()
		{
			_arr = FormulaCellCacheEntry.EMPTY_ARRAY;
		}

		public FormulaCellCacheEntry[] ToArray()
		{
			int size = _size;
			if (size < 1)
			{
				return FormulaCellCacheEntry.EMPTY_ARRAY;
			}
			FormulaCellCacheEntry[] array = new FormulaCellCacheEntry[size];
			int num = 0;
			for (int i = 0; i < _arr.Length; i++)
			{
				FormulaCellCacheEntry formulaCellCacheEntry = _arr[i];
				if (formulaCellCacheEntry != null)
				{
					array[num++] = formulaCellCacheEntry;
				}
			}
			if (num != size)
			{
				throw new InvalidOperationException("size mismatch");
			}
			return array;
		}

		public void Add(CellCacheEntry cce)
		{
			if (_size * 3 >= _arr.Length * 2)
			{
				FormulaCellCacheEntry[] arr = _arr;
				FormulaCellCacheEntry[] arr2 = new FormulaCellCacheEntry[4 + _arr.Length * 3 / 2];
				for (int i = 0; i < arr.Length; i++)
				{
					FormulaCellCacheEntry formulaCellCacheEntry = _arr[i];
					if (formulaCellCacheEntry != null)
					{
						AddInternal(arr2, formulaCellCacheEntry);
					}
				}
				_arr = arr2;
			}
			if (AddInternal(_arr, cce))
			{
				_size++;
			}
		}

		private static bool AddInternal(CellCacheEntry[] arr, CellCacheEntry cce)
		{
			int num = cce.GetHashCode() % arr.Length;
			for (int i = num; i < arr.Length; i++)
			{
				CellCacheEntry cellCacheEntry = arr[i];
				if (cellCacheEntry == cce)
				{
					return false;
				}
				if (cellCacheEntry == null)
				{
					arr[i] = cce;
					return true;
				}
			}
			for (int j = 0; j < num; j++)
			{
				CellCacheEntry cellCacheEntry2 = arr[j];
				if (cellCacheEntry2 == cce)
				{
					return false;
				}
				if (cellCacheEntry2 == null)
				{
					arr[j] = cce;
					return true;
				}
			}
			throw new InvalidOperationException("No empty space found");
		}

		public bool Remove(CellCacheEntry cce)
		{
			FormulaCellCacheEntry[] arr = _arr;
			if (_size * 3 < _arr.Length && _arr.Length > 8)
			{
				bool result = false;
				FormulaCellCacheEntry[] arr2 = _arr;
				FormulaCellCacheEntry[] arr3 = new FormulaCellCacheEntry[_arr.Length / 2];
				for (int i = 0; i < arr2.Length; i++)
				{
					FormulaCellCacheEntry formulaCellCacheEntry = _arr[i];
					if (formulaCellCacheEntry != null)
					{
						if (formulaCellCacheEntry == cce)
						{
							result = true;
							_size--;
						}
						else
						{
							AddInternal(arr3, formulaCellCacheEntry);
						}
					}
				}
				_arr = arr3;
				return result;
			}
			int num = cce.GetHashCode() % arr.Length;
			for (int j = num; j < arr.Length; j++)
			{
				FormulaCellCacheEntry formulaCellCacheEntry2 = arr[j];
				if (formulaCellCacheEntry2 == cce)
				{
					arr[j] = null;
					_size--;
					return true;
				}
			}
			for (int k = 0; k < num; k++)
			{
				FormulaCellCacheEntry formulaCellCacheEntry3 = arr[k];
				if (formulaCellCacheEntry3 == cce)
				{
					arr[k] = null;
					_size--;
					return true;
				}
			}
			return false;
		}
	}
