	public class Countif : Fixed2ArgFunction
	{
		internal class CmpOp
		{
			public const int NONE = 0;

			public const int EQ = 1;

			public const int NE = 2;

			public const int LE = 3;

			public const int LT = 4;

			public const int GT = 5;

			public const int GE = 6;

			public static readonly CmpOp OP_NONE = op("", 0);

			public static readonly CmpOp OP_EQ = op("=", 1);

			public static readonly CmpOp OP_NE = op("<>", 2);

			public static readonly CmpOp OP_LE = op("<=", 3);

			public static readonly CmpOp OP_LT = op("<", 4);

			public static readonly CmpOp OP_GT = op(">", 5);

			public static readonly CmpOp OP_GE = op(">=", 6);

			private string _representation;

			private int _code;

			public int Length => _representation.Length;

			public int Code => _code;

			public string Representation => _representation;

			private static CmpOp op(string rep, int code)
			{
				return new CmpOp(rep, code);
			}

			private CmpOp(string representation, int code)
			{
				_representation = representation;
				_code = code;
			}

			public static CmpOp GetOperator(string value)
			{
				int length = value.Length;
				if (length < 1)
				{
					return OP_NONE;
				}
				switch (value[0])
				{
				case '=':
					return OP_EQ;
				case '>':
					if (length > 1)
					{
						char c = value[1];
						if (c == '=')
						{
							return OP_GE;
						}
					}
					return OP_GT;
				case '<':
					if (length > 1)
					{
						switch (value[1])
						{
						case '=':
							return OP_LE;
						case '>':
							return OP_NE;
						}
					}
					return OP_LT;
				default:
					return OP_NONE;
				}
			}

			public bool Evaluate(bool cmpResult)
			{
				switch (_code)
				{
				case 0:
				case 1:
					return cmpResult;
				case 2:
					return !cmpResult;
				default:
					throw new Exception("Cannot call bool Evaluate on non-equality operator '" + _representation + "'");
				}
			}

			public bool Evaluate(int cmpResult)
			{
				switch (_code)
				{
				case 0:
				case 1:
					return cmpResult == 0;
				case 2:
					return cmpResult != 0;
				case 4:
					return cmpResult < 0;
				case 3:
					return cmpResult <= 0;
				case 5:
					return cmpResult > 0;
				case 6:
					return cmpResult >= 0;
				default:
					throw new Exception("Cannot call bool Evaluate on non-equality operator '" + _representation + "'");
				}
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder(64);
				stringBuilder.Append(GetType().Name);
				stringBuilder.Append(" [").Append(_representation).Append("]");
				return stringBuilder.ToString();
			}
		}

		internal abstract class MatcherBase : IMatchPredicate
		{
			private CmpOp _operator;

			protected int Code => _operator.Code;

			protected abstract string ValueText { get; }

			protected MatcherBase(CmpOp operator1)
			{
				_operator = operator1;
			}

			protected bool Evaluate(int cmpResult)
			{
				return _operator.Evaluate(cmpResult);
			}

			protected bool Evaluate(bool cmpResult)
			{
				return _operator.Evaluate(cmpResult);
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder(64);
				stringBuilder.Append(GetType().Name).Append(" [");
				stringBuilder.Append(_operator.Representation);
				stringBuilder.Append(ValueText);
				stringBuilder.Append("]");
				return stringBuilder.ToString();
			}

			public abstract bool Matches(ValueEval x);
		}

		private class ErrorMatcher : MatcherBase
		{
			private int _value;

			protected override string ValueText => ErrorConstants.GetText(_value);

			public ErrorMatcher(int errorCode, CmpOp operator1)
				: base(operator1)
			{
				_value = errorCode;
			}

			public override bool Matches(ValueEval x)
			{
				if (x is ErrorEval)
				{
					int errorCode = ((ErrorEval)x).ErrorCode;
					return Evaluate(errorCode - _value);
				}
				return false;
			}
		}

		private class NumberMatcher : MatcherBase
		{
			private double _value;

			protected override string ValueText => _value.ToString(CultureInfo.InvariantCulture);

			public NumberMatcher(double value, CmpOp optr)
				: base(optr)
			{
				_value = value;
			}

			public override bool Matches(ValueEval x)
			{
				if (x is StringEval)
				{
					switch (base.Code)
					{
					case 2:
						return true;
					default:
						return false;
					case 0:
					case 1:
					{
						StringEval stringEval = (StringEval)x;
						double num = OperandResolver.ParseDouble(stringEval.StringValue);
						if (double.IsNaN(num))
						{
							return false;
						}
						return _value == num;
					}
					}
				}
				if (x is NumberEval)
				{
					NumberEval numberEval = (NumberEval)x;
					return Evaluate(numberEval.NumberValue.CompareTo(_value));
				}
				if (x is BlankEval)
				{
					int code = base.Code;
					if (code == 2)
					{
						return true;
					}
					return false;
				}
				return false;
			}
		}

		private class BooleanMatcher : MatcherBase
		{
			private int _value;

			protected override string ValueText
			{
				get
				{
					if (_value != 1)
					{
						return "FALSE";
					}
					return "TRUE";
				}
			}

			public BooleanMatcher(bool value, CmpOp optr)
				: base(optr)
			{
				_value = BoolToInt(value);
			}

			private static int BoolToInt(bool value)
			{
				if (!value)
				{
					return 0;
				}
				return 1;
			}

			public override bool Matches(ValueEval x)
			{
				if (x is StringEval)
				{
					return false;
				}
				if (x is BoolEval)
				{
					BoolEval boolEval = (BoolEval)x;
					int num = BoolToInt(boolEval.BooleanValue);
					return Evaluate(num - _value);
				}
				if (x is BlankEval)
				{
					int code = base.Code;
					if (code == 2)
					{
						return true;
					}
					return false;
				}
				if (x is NumberEval)
				{
					int code2 = base.Code;
					if (code2 == 2)
					{
						return true;
					}
					return false;
				}
				return false;
			}
		}

		internal class StringMatcher : MatcherBase
		{
			private string _value;

			private CmpOp _operator;

			private Regex _pattern;

			protected override string ValueText
			{
				get
				{
					if (_pattern == null)
					{
						return _value;
					}
					return _pattern.ToString();
				}
			}

			public StringMatcher(string value, CmpOp optr)
				: base(optr)
			{
				_value = value;
				_operator = optr;
				switch (optr.Code)
				{
				case 0:
				case 1:
				case 2:
					_pattern = GetWildCardPattern(value);
					break;
				default:
					_pattern = null;
					break;
				}
			}

			public override bool Matches(ValueEval x)
			{
				if (x is BlankEval)
				{
					switch (_operator.Code)
					{
					case 0:
					case 1:
						return _value.Length == 0;
					case 2:
						return _value.Length != 0;
					default:
						return false;
					}
				}
				if (!(x is StringEval))
				{
					return false;
				}
				string stringValue = ((StringEval)x).StringValue;
				if (stringValue.Length < 1 && _value.Length < 1)
				{
					return _operator.Code switch
					{
						0 => true, 
						1 => false, 
						2 => true, 
						_ => false, 
					};
				}
				if (_pattern != null)
				{
					return Evaluate(_pattern.IsMatch(stringValue));
				}
				return Evaluate(string.Compare(stringValue, _value, StringComparison.CurrentCultureIgnoreCase));
			}

			internal static Regex GetWildCardPattern(string value)
			{
				int length = value.Length;
				StringBuilder stringBuilder = new StringBuilder(length);
				stringBuilder.Append("^");
				bool flag = false;
				for (int i = 0; i < length; i++)
				{
					char c = value[i];
					switch (c)
					{
					case '?':
						flag = true;
						stringBuilder.Append('.');
						break;
					case '*':
						flag = true;
						stringBuilder.Append(".*");
						break;
					case '~':
						if (i + 1 < length)
						{
							c = value[i + 1];
							char c2 = c;
							if (c2 == '*' || c2 == '?')
							{
								flag = true;
								stringBuilder.Append('[').Append(c).Append(']');
								i++;
								break;
							}
						}
						stringBuilder.Append('~');
						break;
					case '$':
					case '(':
					case ')':
					case '.':
					case '[':
					case ']':
					case '^':
						stringBuilder.Append("\\").Append(c);
						break;
					default:
						stringBuilder.Append(c);
						break;
					}
				}
				stringBuilder.Append("$");
				if (flag)
				{
					return new Regex(stringBuilder.ToString(), RegexOptions.IgnoreCase);
				}
				return null;
			}
		}

		private double CountMatchingCellsInArea(ValueEval rangeArg, IMatchPredicate criteriaPredicate)
		{
			if (rangeArg is RefEval)
			{
				return CountUtils.CountMatchingCellsInRef((RefEval)rangeArg, criteriaPredicate);
			}
			if (rangeArg is ThreeDEval)
			{
				return CountUtils.CountMatchingCellsInArea((ThreeDEval)rangeArg, criteriaPredicate);
			}
			throw new ArgumentException("Bad range arg type (" + rangeArg.GetType().Name + ")");
		}

		private static ValueEval EvaluateCriteriaArg(ValueEval arg, int srcRowIndex, int srcColumnIndex)
		{
			try
			{
				return OperandResolver.GetSingleValue(arg, srcRowIndex, (short)srcColumnIndex);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		private static IMatchPredicate CreateGeneralMatchPredicate(StringEval stringEval)
		{
			string stringValue = stringEval.StringValue;
			CmpOp @operator = CmpOp.GetOperator(stringValue);
			stringValue = stringValue.Substring(@operator.Length);
			bool? flag = ParseBoolean(stringValue);
			if (flag.HasValue)
			{
				return new BooleanMatcher(flag.Value, @operator);
			}
			double num = OperandResolver.ParseDouble(stringValue);
			if (!double.IsNaN(num))
			{
				return new NumberMatcher(num, @operator);
			}
			ErrorEval errorEval = ParseError(stringValue);
			if (errorEval != null)
			{
				return new ErrorMatcher(errorEval.ErrorCode, @operator);
			}
			return new StringMatcher(stringValue, @operator);
		}

		public static IMatchPredicate CreateCriteriaPredicate(ValueEval arg, int srcRowIndex, int srcColumnIndex)
		{
			ValueEval valueEval = EvaluateCriteriaArg(arg, srcRowIndex, srcColumnIndex);
			if (valueEval is NumberEval)
			{
				return new NumberMatcher(((NumberEval)valueEval).NumberValue, CmpOp.OP_NONE);
			}
			if (valueEval is BoolEval)
			{
				return new BooleanMatcher(((BoolEval)valueEval).BooleanValue, CmpOp.OP_NONE);
			}
			if (valueEval is StringEval)
			{
				return CreateGeneralMatchPredicate((StringEval)valueEval);
			}
			if (valueEval is ErrorEval)
			{
				return new ErrorMatcher(((ErrorEval)valueEval).ErrorCode, CmpOp.OP_NONE);
			}
			if (valueEval == BlankEval.instance)
			{
				return null;
			}
			throw new Exception("Unexpected type for criteria (" + valueEval.GetType().Name + ")");
		}

		private static ErrorEval ParseError(string value)
		{
			if (value.Length < 4 || value[0] != '#')
			{
				return null;
			}
			if (value.Equals("#NULL!"))
			{
				return ErrorEval.NULL_INTERSECTION;
			}
			if (value.Equals("#DIV/0!"))
			{
				return ErrorEval.DIV_ZERO;
			}
			if (value.Equals("#VALUE!"))
			{
				return ErrorEval.VALUE_INVALID;
			}
			if (value.Equals("#REF!"))
			{
				return ErrorEval.REF_INVALID;
			}
			if (value.Equals("#NAME?"))
			{
				return ErrorEval.NAME_INVALID;
			}
			if (value.Equals("#NUM!"))
			{
				return ErrorEval.NUM_ERROR;
			}
			if (value.Equals("#N/A"))
			{
				return ErrorEval.NA;
			}
			return null;
		}

		public static bool? ParseBoolean(string strRep)
		{
			if (strRep.Length < 1)
			{
				return null;
			}
			switch (strRep[0])
			{
			case 'T':
			case 't':
				if ("TRUE".Equals(strRep, StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
				break;
			case 'F':
			case 'f':
				if ("FALSE".Equals(strRep, StringComparison.OrdinalIgnoreCase))
				{
					return false;
				}
				break;
			}
			return null;
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			IMatchPredicate matchPredicate = CreateCriteriaPredicate(arg1, srcRowIndex, srcColumnIndex);
			if (matchPredicate == null)
			{
				return NumberEval.ZERO;
			}
			double value = CountMatchingCellsInArea(arg0, matchPredicate);
			return new NumberEval(value);
		}
	}
	internal class CountUtils
	{
		private CountUtils()
		{
		}

		public static int CountMatchingCellsInRef(RefEval refEval, IMatchPredicate criteriaPredicate)
		{
			int num = 0;
			for (int i = refEval.FirstSheetIndex; i <= refEval.LastSheetIndex; i++)
			{
				ValueEval innerValueEval = refEval.GetInnerValueEval(i);
				if (criteriaPredicate.Matches(innerValueEval))
				{
					num++;
				}
			}
			return num;
		}

		public static int CountArg(ValueEval eval, IMatchPredicate criteriaPredicate)
		{
			if (eval == null)
			{
				throw new ArgumentException("eval must not be null");
			}
			if (eval is ThreeDEval)
			{
				return CountMatchingCellsInArea((ThreeDEval)eval, criteriaPredicate);
			}
			if (eval is TwoDEval)
			{
				throw new ArgumentException("Count requires 3D Evals, 2D ones aren't supported");
			}
			if (eval is RefEval)
			{
				return CountMatchingCellsInRef((RefEval)eval, criteriaPredicate);
			}
			if (!criteriaPredicate.Matches(eval))
			{
				return 0;
			}
			return 1;
		}

		public static int CountMatchingCellsInArea(ThreeDEval areaEval, IMatchPredicate criteriaPredicate)
		{
			int num = 0;
			for (int i = areaEval.FirstSheetIndex; i <= areaEval.LastSheetIndex; i++)
			{
				int height = areaEval.Height;
				int width = areaEval.Width;
				for (int j = 0; j < height; j++)
				{
					for (int k = 0; k < width; k++)
					{
						ValueEval value = areaEval.GetValue(i, j, k);
						if (criteriaPredicate is I_MatchAreaPredicate)
						{
							I_MatchAreaPredicate i_MatchAreaPredicate = (I_MatchAreaPredicate)criteriaPredicate;
							if (!i_MatchAreaPredicate.Matches(areaEval, j, k))
							{
								continue;
							}
						}
						if (criteriaPredicate.Matches(value))
						{
							num++;
						}
					}
				}
			}
			return num;
		}
	}
	public abstract class Fixed3ArgFunction : Function3Arg, Function
	{
		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			if (args.Length != 3)
			{
				return ErrorEval.VALUE_INVALID;
			}
			return Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2]);
		}

		public abstract ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2);
	}
	public class DateFunc : Fixed3ArgFunction
	{
		public static Function instance = new DateFunc();

		private DateFunc()
		{
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			double num3;
			try
			{
				double d = NumericFunction.SingleOperandEvaluate(arg0, srcRowIndex, srcColumnIndex);
				double num = NumericFunction.SingleOperandEvaluate(arg1, srcRowIndex, srcColumnIndex);
				double num2 = NumericFunction.SingleOperandEvaluate(arg2, srcRowIndex, srcColumnIndex);
				num3 = Evaluate(GetYear(d), (int)num, (int)num2);
				NumericFunction.CheckValue(num3);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(num3);
		}

		public double Evaluate(int year, int month, int pDay)
		{
			if (year < 0)
			{
				throw new EvaluationException(ErrorEval.VALUE_INVALID);
			}
			while (month <= 0)
			{
				year--;
				month += 12;
			}
			if (year == 1900 && month == 2 && pDay == 29)
			{
				return 60.0;
			}
			int num = pDay;
			if (year == 1900 && ((month == 1 && num >= 60) || (month == 2 && num >= 30)))
			{
				num--;
			}
			bool use1904windowing = false;
			return DateUtil.GetExcelDate(year, month, num, 0, 0, 0, use1904windowing);
		}

		private int GetYear(double d)
		{
			int num = (int)d;
			if (num < 0)
			{
				return -1;
			}
			if (num >= 1900)
			{
				return num;
			}
			return 1900 + num;
		}
	}
	public class Days360 : Var2or3ArgFunction
	{
		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			double value;
			try
			{
				double d = NumericFunction.SingleOperandEvaluate(arg0, srcRowIndex, srcColumnIndex);
				double d2 = NumericFunction.SingleOperandEvaluate(arg1, srcRowIndex, srcColumnIndex);
				value = Evaluate(d, d2);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(value);
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			double value;
			try
			{
				double d = NumericFunction.SingleOperandEvaluate(arg0, srcRowIndex, srcColumnIndex);
				double d2 = NumericFunction.SingleOperandEvaluate(arg1, srcRowIndex, srcColumnIndex);
				ValueEval singleValue = OperandResolver.GetSingleValue(arg2, srcRowIndex, srcColumnIndex);
				OperandResolver.CoerceValueToBoolean(singleValue, stringsAreBlanks: false);
				value = Evaluate(d, d2);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(value);
		}

		private double Evaluate(double d0, double d1)
		{
			DateTime startingDate = GetStartingDate(d0);
			DateTime endingDateAccordingToStartingDate = GetEndingDateAccordingToStartingDate(d1, startingDate);
			long num = startingDate.Month * 30 + startingDate.Day;
			long num2 = (endingDateAccordingToStartingDate.Year - startingDate.Year) * 360 + endingDateAccordingToStartingDate.Month * 30 + endingDateAccordingToStartingDate.Day;
			return num2 - num;
		}

		private DateTime GetDate(double date)
		{
			return DateUtil.GetJavaDate(date);
		}

		private DateTime GetStartingDate(double date)
		{
			DateTime dateTime = GetDate(date);
			if (IsLastDayOfMonth(dateTime))
			{
				dateTime = new DateTime(dateTime.Year, dateTime.Month, 30, dateTime.Hour, dateTime.Minute, dateTime.Second);
			}
			return dateTime;
		}

		private DateTime GetEndingDateAccordingToStartingDate(double date, DateTime startingDate)
		{
			DateTime dateTime = DateUtil.GetJavaDate(date, use1904windowing: false);
			if (IsLastDayOfMonth(dateTime) && startingDate.Day < 30)
			{
				dateTime = GetFirstDayOfNextMonth(dateTime);
			}
			return dateTime;
		}

		private bool IsLastDayOfMonth(DateTime date)
		{
			return date.AddDays(1.0).Month != date.Month;
		}

		private DateTime GetFirstDayOfNextMonth(DateTime date)
		{
			return (date.Month >= 12) ? new DateTime(date.Year + 1, 1, 1, date.Hour, date.Minute, date.Second) : new DateTime(date.Year, date.Month + 1, 1, date.Hour, date.Minute, date.Second);
		}
	}
