	public abstract class FinanceFunction : Function3Arg, Function4Arg, Function
	{
		private static ValueEval DEFAULT_ARG3 = NumberEval.ZERO;

		private static ValueEval DEFAULT_ARG4 = BoolEval.FALSE;

		public static readonly Function FV = new Fv();

		public static readonly Function NPER = new Nper();

		public static readonly Function PMT = new Pmt();

		public static readonly Function PV = new Pv();

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			return Evaluate(srcRowIndex, srcColumnIndex, arg0, arg1, arg2, DEFAULT_ARG3);
		}

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2, ValueEval arg3)
		{
			return Evaluate(srcRowIndex, srcColumnIndex, arg0, arg1, arg2, arg3, DEFAULT_ARG4);
		}

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2, ValueEval arg3, ValueEval arg4)
		{
			double num2;
			try
			{
				double rate = NumericFunction.SingleOperandEvaluate(arg0, srcRowIndex, srcColumnIndex);
				double arg5 = NumericFunction.SingleOperandEvaluate(arg1, srcRowIndex, srcColumnIndex);
				double arg6 = NumericFunction.SingleOperandEvaluate(arg2, srcRowIndex, srcColumnIndex);
				double arg7 = NumericFunction.SingleOperandEvaluate(arg3, srcRowIndex, srcColumnIndex);
				double num = NumericFunction.SingleOperandEvaluate(arg4, srcRowIndex, srcColumnIndex);
				num2 = Evaluate(rate, arg5, arg6, arg7, num != 0.0);
				NumericFunction.CheckValue(num2);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return new NumberEval(num2);
		}

		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			return args.Length switch
			{
				3 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2], DEFAULT_ARG3, DEFAULT_ARG4), 
				4 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2], args[3], DEFAULT_ARG4), 
				5 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2], args[3], args[4]), 
				_ => ErrorEval.VALUE_INVALID, 
			};
		}

		public double Evaluate(double[] ds)
		{
			double arg = 0.0;
			double num = 0.0;
			switch (ds.Length)
			{
			case 5:
				num = ds[4];
				break;
			case 4:
				arg = ds[3];
				break;
			default:
				throw new ArgumentException("Wrong number of arguments");
			case 3:
				break;
			}
			return Evaluate(ds[0], ds[1], ds[2], arg, num != 0.0);
		}

		public abstract double Evaluate(double rate, double arg1, double arg2, double arg3, bool type);
	}
	public class FinanceLib
	{
		private FinanceLib()
		{
		}

		public static double fv(double r, double n, double y, double p, bool t)
		{
			double num = 0.0;
			if (r == 0.0)
			{
				return -1.0 * (p + n * y);
			}
			double num2 = r + 1.0;
			return (1.0 - Math.Pow(num2, n)) * (t ? num2 : 1.0) * y / r - p * Math.Pow(num2, n);
		}

		public static double pv(double r, double n, double y, double f, bool t)
		{
			double num = 0.0;
			if (r == 0.0)
			{
				return -1.0 * (n * y + f);
			}
			double num2 = r + 1.0;
			return ((1.0 - Math.Pow(num2, n)) / r * (t ? num2 : 1.0) * y - f) / Math.Pow(num2, n);
		}

		public static double npv(double r, double[] cfs)
		{
			double num = 0.0;
			double num2 = r + 1.0;
			double num3 = num2;
			int i = 0;
			for (int num4 = cfs.Length; i < num4; i++)
			{
				num += cfs[i] / num3;
				num3 *= num2;
			}
			return num;
		}

		public static double pmt(double r, double n, double p, double f, bool t)
		{
			double num = 0.0;
			if (r == 0.0)
			{
				return -1.0 * (f + p) / n;
			}
			double num2 = r + 1.0;
			return (f + p * Math.Pow(num2, n)) * r / ((t ? num2 : 1.0) * (1.0 - Math.Pow(num2, n)));
		}

		public static double nper(double r, double y, double p, double f, bool t)
		{
			double num = 0.0;
			if (r == 0.0)
			{
				return -1.0 * (f + p) / y;
			}
			double num2 = r + 1.0;
			double num3 = (t ? num2 : 1.0) * y / r;
			double num4 = ((num3 - f < 0.0) ? Math.Log(f - num3) : Math.Log(num3 - f));
			double num5 = ((num3 - f < 0.0) ? Math.Log(0.0 - p - num3) : Math.Log(p + num3));
			double num6 = Math.Log(num2);
			return (num4 - num5) / num6;
		}
	}
