	public class Index : Function2Arg, Function3Arg, Function4Arg, Function
	{
		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			TwoDEval twoDEval = ConvertFirstArg(arg0);
			int pColumnIx = 0;
			try
			{
				int num = ResolveIndexArg(arg1, srcRowIndex, srcColumnIndex);
				if (!twoDEval.IsColumn)
				{
					if (!twoDEval.IsRow)
					{
						return ErrorEval.REF_INVALID;
					}
					pColumnIx = num;
					num = 0;
				}
				return GetValueFromArea(twoDEval, num, pColumnIx);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			TwoDEval ae = ConvertFirstArg(arg0);
			try
			{
				int pColumnIx = ResolveIndexArg(arg2, srcRowIndex, srcColumnIndex);
				int pRowIx = ResolveIndexArg(arg1, srcRowIndex, srcColumnIndex);
				return GetValueFromArea(ae, pRowIx, pColumnIx);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		public ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2, ValueEval arg3)
		{
			throw new Exception("Incomplete code - don't know how to support the 'area_num' parameter yet)");
		}

		private static TwoDEval ConvertFirstArg(ValueEval arg0)
		{
			if (arg0 is RefEval)
			{
				return ((RefEval)arg0).Offset(0, 0, 0, 0);
			}
			if (arg0 is TwoDEval)
			{
				return (TwoDEval)arg0;
			}
			throw new Exception("Incomplete code - cannot handle first arg of type (" + arg0.GetType().Name + ")");
		}

		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			return args.Length switch
			{
				2 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1]), 
				3 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2]), 
				4 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2], args[3]), 
				_ => ErrorEval.VALUE_INVALID, 
			};
		}

		private static ValueEval GetValueFromArea(TwoDEval ae, int pRowIx, int pColumnIx)
		{
			TwoDEval twoDEval = ae;
			if (pRowIx != 0)
			{
				if (pRowIx > ae.Height)
				{
					throw new EvaluationException(ErrorEval.REF_INVALID);
				}
				twoDEval = twoDEval.GetRow(pRowIx - 1);
			}
			if (pColumnIx != 0)
			{
				if (pColumnIx > ae.Width)
				{
					throw new EvaluationException(ErrorEval.REF_INVALID);
				}
				twoDEval = twoDEval.GetColumn(pColumnIx - 1);
			}
			return twoDEval;
		}

		[Obsolete]
		private static ValueEval GetValueFromArea(AreaEval ae, int pRowIx, int pColumnIx, bool colArgWasPassed, int srcRowIx, int srcColIx)
		{
			bool flag = pRowIx == 0;
			bool flag2 = pColumnIx == 0;
			int num;
			int num2;
			if (ae.IsRow)
			{
				if (ae.IsColumn)
				{
					num = ((!flag) ? (pRowIx - 1) : 0);
					num2 = ((!flag2) ? (pColumnIx - 1) : 0);
				}
				else if (colArgWasPassed)
				{
					num = ((!flag) ? (pRowIx - 1) : 0);
					num2 = pColumnIx - 1;
				}
				else
				{
					num = 0;
					num2 = pRowIx - 1;
					flag2 = flag;
				}
			}
			else if (ae.IsColumn)
			{
				num = ((!flag) ? (pRowIx - 1) : (srcRowIx - ae.FirstRow));
				num2 = ((!flag2) ? ((!flag2) ? (pColumnIx - 1) : 0) : 0);
			}
			else
			{
				if (!colArgWasPassed)
				{
					throw new EvaluationException((pRowIx < 0) ? ErrorEval.VALUE_INVALID : ErrorEval.REF_INVALID);
				}
				num = ((!flag) ? (pRowIx - 1) : (srcRowIx - ae.FirstRow));
				num2 = ((!flag2) ? (pColumnIx - 1) : (srcColIx - ae.FirstColumn));
			}
			int width = ae.Width;
			int height = ae.Height;
			if ((!flag && num >= height) || (!flag2 && num2 >= width))
			{
				throw new EvaluationException(ErrorEval.REF_INVALID);
			}
			if (num < 0 || num2 < 0 || num >= height || num2 >= width)
			{
				throw new EvaluationException(ErrorEval.VALUE_INVALID);
			}
			return ae.GetRelativeValue(num, num2);
		}

		private static int ResolveIndexArg(ValueEval arg, int srcCellRow, int srcCellCol)
		{
			ValueEval singleValue = OperandResolver.GetSingleValue(arg, srcCellRow, srcCellCol);
			if (singleValue == MissingArgEval.instance)
			{
				return 0;
			}
			if (singleValue == BlankEval.instance)
			{
				return 0;
			}
			int num = OperandResolver.CoerceValueToInt(singleValue);
			if (num < 0)
			{
				throw new EvaluationException(ErrorEval.VALUE_INVALID);
			}
			return num;
		}
	}
	public class Indirect : FreeRefFunction
	{
		public static FreeRefFunction instance = new Indirect();

		private Indirect()
		{
		}

		public ValueEval Evaluate(ValueEval[] args, OperationEvaluationContext ec)
		{
			if (args.Length < 1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			string text;
			bool isA1style;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(args[0], ec.RowIndex, ec.ColumnIndex);
				text = OperandResolver.CoerceValueToString(singleValue);
				switch (args.Length)
				{
				case 1:
					isA1style = true;
					break;
				case 2:
					isA1style = EvaluateBooleanArg(args[1], ec);
					break;
				default:
					return ErrorEval.VALUE_INVALID;
				}
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return EvaluateIndirect(ec, text, isA1style);
		}

		private static bool EvaluateBooleanArg(ValueEval arg, OperationEvaluationContext ec)
		{
			ValueEval singleValue = OperandResolver.GetSingleValue(arg, ec.RowIndex, ec.ColumnIndex);
			if (singleValue == BlankEval.instance || singleValue == MissingArgEval.instance)
			{
				return false;
			}
			return OperandResolver.CoerceValueToBoolean(singleValue, stringsAreBlanks: false).Value;
		}

		private static ValueEval EvaluateIndirect(OperationEvaluationContext ec, string text, bool isA1style)
		{
			int num = text.LastIndexOf('!');
			string workbookName;
			string sheetName;
			string text2;
			if (num < 0)
			{
				workbookName = null;
				sheetName = null;
				text2 = text;
			}
			else
			{
				string[] array = ParseWorkbookAndSheetName(text.Substring(0, num));
				if (array == null)
				{
					return ErrorEval.REF_INVALID;
				}
				workbookName = array[0];
				sheetName = array[1];
				text2 = text.Substring(num + 1);
			}
			int num2 = text2.IndexOf(':');
			string refStrPart;
			string refStrPart2;
			if (num2 < 0)
			{
				refStrPart = text2.Trim();
				refStrPart2 = null;
			}
			else
			{
				refStrPart = text2.Substring(0, num2).Trim();
				refStrPart2 = text2.Substring(num2 + 1).Trim();
			}
			return ec.GetDynamicReference(workbookName, sheetName, refStrPart, refStrPart2, isA1style);
		}

		private static string[] ParseWorkbookAndSheetName(string text)
		{
			int num = text.Length - 1;
			if (num < 0)
			{
				return null;
			}
			if (CanTrim(text))
			{
				return null;
			}
			char c = text[0];
			if (char.IsWhiteSpace(c))
			{
				return null;
			}
			switch (c)
			{
			case '\'':
			{
				if (text[num] != '\'')
				{
					return null;
				}
				c = text[1];
				if (char.IsWhiteSpace(c))
				{
					return null;
				}
				string text4;
				int num4;
				if (c == '[')
				{
					int num3 = text.ToString().LastIndexOf(']');
					if (num3 < 0)
					{
						return null;
					}
					text4 = UnescapeString(text.Substring(2, num3 - 2));
					if (text4 == null || CanTrim(text4))
					{
						return null;
					}
					num4 = num3 + 1;
				}
				else
				{
					text4 = null;
					num4 = 1;
				}
				string text5 = UnescapeString(text.Substring(num4, num - num4));
				if (text5 == null)
				{
					return null;
				}
				return new string[2] { text4, text5 };
			}
			case '[':
			{
				int num2 = text.ToString().LastIndexOf(']');
				if (num2 < 0)
				{
					return null;
				}
				string text2 = text.Substring(1, num2 - 1);
				if (CanTrim(text2))
				{
					return null;
				}
				string text3 = text.Substring(num2 + 1);
				if (CanTrim(text3))
				{
					return null;
				}
				return new string[2]
				{
					text2.ToString(),
					text3.ToString()
				};
			}
			default:
				return new string[2]
				{
					null,
					text.ToString()
				};
			}
		}

		private static string UnescapeString(string text)
		{
			int length = text.Length;
			StringBuilder stringBuilder = new StringBuilder(length);
			for (int i = 0; i < length; i++)
			{
				char c = text[i];
				if (c == '\'')
				{
					i++;
					if (i >= length)
					{
						return null;
					}
					c = text[i];
					if (c != '\'')
					{
						return null;
					}
				}
				stringBuilder.Append(c);
			}
			return stringBuilder.ToString();
		}

		private static bool CanTrim(string text)
		{
			int num = text.Length - 1;
			if (num < 0)
			{
				return false;
			}
			if (char.IsWhiteSpace(text[0]))
			{
				return true;
			}
			if (char.IsWhiteSpace(text[num]))
			{
				return true;
			}
			return false;
		}
	}
