	public class StatsLib
	{
		private StatsLib()
		{
		}

		public static double avedev(double[] v)
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			int i = 0;
			for (int num4 = v.Length; i < num4; i++)
			{
				num3 += v[i];
			}
			num2 = num3 / (double)v.Length;
			num3 = 0.0;
			int j = 0;
			for (int num5 = v.Length; j < num5; j++)
			{
				num3 += Math.Abs(v[j] - num2);
			}
			return num3 / (double)v.Length;
		}

		public static double stdev(double[] v)
		{
			double result = double.NaN;
			if (v != null && v.Length > 1)
			{
				result = Math.Sqrt(devsq(v) / (double)(v.Length - 1));
			}
			return result;
		}

		public static double var(double[] v)
		{
			double result = double.NaN;
			if (v != null && v.Length > 1)
			{
				result = devsq(v) / (double)(v.Length - 1);
			}
			return result;
		}

		public static double varp(double[] v)
		{
			double result = double.NaN;
			if (v != null && v.Length > 1)
			{
				result = devsq(v) / (double)v.Length;
			}
			return result;
		}

		public static double mode(double[] v)
		{
			double result = double.NaN;
			if (v != null && v.Length > 1)
			{
				int[] array = new int[v.Length];
				Arrays.Fill(array, 1);
				int i = 0;
				for (int num = v.Length; i < num; i++)
				{
					int j = i + 1;
					for (int num2 = v.Length; j < num2; j++)
					{
						if (v[i] == v[j])
						{
							array[i]++;
						}
					}
				}
				double num3 = 0.0;
				int num4 = 0;
				int k = 0;
				for (int num5 = array.Length; k < num5; k++)
				{
					if (array[k] > num4)
					{
						num3 = v[k];
						num4 = array[k];
					}
				}
				result = ((num4 > 1) ? num3 : double.NaN);
			}
			return result;
		}

		public static double median(double[] v)
		{
			double result = double.NaN;
			if (v != null && v.Length >= 1)
			{
				int num = v.Length;
				System.Array.Sort(v);
				result = ((num % 2 == 0) ? ((v[num / 2] + v[num / 2 - 1]) / 2.0) : v[num / 2]);
			}
			return result;
		}

		public static double devsq(double[] v)
		{
			double result = double.NaN;
			if (v != null && v.Length >= 1)
			{
				double num = 0.0;
				double num2 = 0.0;
				int num3 = v.Length;
				for (int i = 0; i < num3; i++)
				{
					num2 += v[i];
				}
				num = num2 / (double)num3;
				num2 = 0.0;
				for (int j = 0; j < num3; j++)
				{
					num2 += (v[j] - num) * (v[j] - num);
				}
				result = ((num3 == 1) ? 0.0 : num2);
			}
			return result;
		}

		public static double kthLargest(double[] v, int k)
		{
			double result = double.NaN;
			k--;
			if (v != null && v.Length > k && k >= 0)
			{
				System.Array.Sort(v);
				result = v[v.Length - k - 1];
			}
			return result;
		}

		public static double kthSmallest(double[] v, int k)
		{
			double result = double.NaN;
			k--;
			if (v != null && v.Length > k && k >= 0)
			{
				System.Array.Sort(v);
				result = v[k];
			}
			return result;
		}
	}
	public class Subtotal : Function
	{
		private static Function FindFunction(int functionCode)
		{
			switch (functionCode)
			{
			case 1:
				return AggregateFunction.SubtotalInstance(AggregateFunction.AVERAGE);
			case 2:
				return Count.SubtotalInstance();
			case 3:
				return Counta.SubtotalInstance();
			case 4:
				return AggregateFunction.SubtotalInstance(AggregateFunction.MAX);
			case 5:
				return AggregateFunction.SubtotalInstance(AggregateFunction.MIN);
			case 6:
				return AggregateFunction.SubtotalInstance(AggregateFunction.PRODUCT);
			case 7:
				return AggregateFunction.SubtotalInstance(AggregateFunction.STDEV);
			case 8:
				throw new NotImplementedFunctionException("STDEVP");
			case 9:
				return AggregateFunction.SubtotalInstance(AggregateFunction.SUM);
			case 10:
				throw new NotImplementedFunctionException("VAR");
			case 11:
				throw new NotImplementedFunctionException("VARP");
			case 101:
			case 102:
			case 103:
			case 104:
			case 105:
			case 106:
			case 107:
			case 108:
			case 109:
			case 110:
			case 111:
				throw new NotImplementedException("SUBTOTAL - with 'exclude hidden values' option");
			default:
				throw EvaluationException.InvalidValue();
			}
		}

		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			int num = args.Length - 1;
			if (num < 1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			Function function;
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(args[0], srcRowIndex, srcColumnIndex);
				int functionCode = OperandResolver.CoerceValueToInt(singleValue);
				function = FindFunction(functionCode);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			ValueEval[] array = new ValueEval[num];
			System.Array.Copy(args, 1, array, 0, num);
			return function.Evaluate(array, srcRowIndex, srcColumnIndex);
		}
	}
	public class Sumif : Var2or3ArgFunction
	{
		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			AreaEval areaEval;
			try
			{
				areaEval = ConvertRangeArg(arg0);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return Eval(srcRowIndex, srcColumnIndex, arg1, areaEval, areaEval);
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			AreaEval aeRange;
			AreaEval aeSum;
			try
			{
				aeRange = ConvertRangeArg(arg0);
				aeSum = CreateSumRange(arg2, aeRange);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			return Eval(srcRowIndex, srcColumnIndex, arg1, aeRange, aeSum);
		}

		private static ValueEval Eval(int srcRowIndex, int srcColumnIndex, ValueEval arg1, AreaEval aeRange, AreaEval aeSum)
		{
			IMatchPredicate mp = Countif.CreateCriteriaPredicate(arg1, srcRowIndex, srcColumnIndex);
			double value = SumMatchingCells(aeRange, mp, aeSum);
			return new NumberEval(value);
		}

		private static double SumMatchingCells(AreaEval aeRange, IMatchPredicate mp, AreaEval aeSum)
		{
			int height = aeRange.Height;
			int width = aeRange.Width;
			double num = 0.0;
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					num += Accumulate(aeRange, mp, aeSum, i, j);
				}
			}
			return num;
		}

		private static double Accumulate(AreaEval aeRange, IMatchPredicate mp, AreaEval aeSum, int relRowIndex, int relColIndex)
		{
			if (!mp.Matches(aeRange.GetRelativeValue(relRowIndex, relColIndex)))
			{
				return 0.0;
			}
			ValueEval relativeValue = aeSum.GetRelativeValue(relRowIndex, relColIndex);
			if (relativeValue is NumberEval)
			{
				return ((NumberEval)relativeValue).NumberValue;
			}
			return 0.0;
		}

		private static AreaEval CreateSumRange(ValueEval eval, AreaEval aeRange)
		{
			if (eval is AreaEval)
			{
				return ((AreaEval)eval).Offset(0, aeRange.Height - 1, 0, aeRange.Width - 1);
			}
			if (eval is RefEval)
			{
				return ((RefEval)eval).Offset(0, aeRange.Height - 1, 0, aeRange.Width - 1);
			}
			throw new EvaluationException(ErrorEval.VALUE_INVALID);
		}

		private static AreaEval ConvertRangeArg(ValueEval eval)
		{
			if (eval is AreaEval)
			{
				return (AreaEval)eval;
			}
			if (eval is RefEval)
			{
				return ((RefEval)eval).Offset(0, 0, 0, 0);
			}
			throw new EvaluationException(ErrorEval.VALUE_INVALID);
		}
	}
	public class Sumproduct : Function
	{
		public ValueEval Evaluate(ValueEval[] args, int srcCellRow, int srcCellCol)
		{
			int num = args.Length;
			if (num < 1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			ValueEval valueEval = args[0];
			try
			{
				if (valueEval is NumericValueEval)
				{
					return EvaluateSingleProduct(args);
				}
				if (valueEval is RefEval)
				{
					return EvaluateSingleProduct(args);
				}
				if (valueEval is TwoDEval)
				{
					TwoDEval twoDEval = (TwoDEval)valueEval;
					if (twoDEval.IsRow && twoDEval.IsColumn)
					{
						return EvaluateSingleProduct(args);
					}
					return EvaluateAreaSumProduct(args);
				}
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			throw new RuntimeException("Invalid arg type for SUMPRODUCT: (" + valueEval.GetType().Name + ")");
		}

		private ValueEval EvaluateSingleProduct(ValueEval[] evalArgs)
		{
			int num = evalArgs.Length;
			double num2 = 1.0;
			for (int i = 0; i < num; i++)
			{
				double scalarValue = GetScalarValue(evalArgs[i]);
				num2 *= scalarValue;
			}
			return new NumberEval(num2);
		}

		private static double GetScalarValue(ValueEval arg)
		{
			ValueEval valueEval;
			if (arg is RefEval)
			{
				RefEval refEval = (RefEval)arg;
				if (refEval.NumberOfSheets > 1)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
				valueEval = refEval.GetInnerValueEval(refEval.FirstSheetIndex);
			}
			else
			{
				valueEval = arg;
			}
			if (valueEval == null)
			{
				throw new ArgumentException("parameter may not be null");
			}
			if (valueEval is AreaEval)
			{
				AreaEval areaEval = (AreaEval)valueEval;
				if (!areaEval.IsColumn || !areaEval.IsRow)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
				valueEval = areaEval.GetRelativeValue(0, 0);
			}
			if (valueEval == null)
			{
				throw new ArgumentException("Unexpected value eval class (" + valueEval.GetType().Name + ")");
			}
			return GetProductTerm(valueEval, IsScalarProduct: true);
		}

		private ValueEval EvaluateAreaSumProduct(ValueEval[] evalArgs)
		{
			int num = evalArgs.Length;
			AreaEval[] array = new AreaEval[num];
			try
			{
				System.Array.Copy(evalArgs, 0, array, 0, num);
			}
			catch (Exception)
			{
				return ErrorEval.VALUE_INVALID;
			}
			AreaEval areaEval = array[0];
			int num2 = areaEval.LastRow - areaEval.FirstRow + 1;
			int num3 = areaEval.LastColumn - areaEval.FirstColumn + 1;
			if (!AreasAllSameSize(array, num2, num3))
			{
				for (int i = 1; i < array.Length; i++)
				{
					ThrowFirstError(array[i]);
				}
				return ErrorEval.VALUE_INVALID;
			}
			double num4 = 0.0;
			for (int j = 0; j < num2; j++)
			{
				for (int k = 0; k < num3; k++)
				{
					double num5 = 1.0;
					for (int l = 0; l < num; l++)
					{
						double productTerm = GetProductTerm(array[l].GetRelativeValue(j, k), IsScalarProduct: false);
						num5 *= productTerm;
					}
					num4 += num5;
				}
			}
			return new NumberEval(num4);
		}

		private static void ThrowFirstError(TwoDEval areaEval)
		{
			int height = areaEval.Height;
			int width = areaEval.Width;
			for (int i = 0; i < height; i++)
			{
				for (int j = 0; j < width; j++)
				{
					ValueEval value = areaEval.GetValue(i, j);
					if (value is ErrorEval)
					{
						throw new EvaluationException((ErrorEval)value);
					}
				}
			}
		}

		private static bool AreasAllSameSize(TwoDEval[] args, int height, int width)
		{
			foreach (TwoDEval twoDEval in args)
			{
				if (twoDEval.Height != height)
				{
					return false;
				}
				if (twoDEval.Width != width)
				{
					return false;
				}
			}
			return true;
		}

		private static double GetProductTerm(ValueEval ve, bool IsScalarProduct)
		{
			if (ve is BlankEval || ve == null)
			{
				if (IsScalarProduct)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
				return 0.0;
			}
			if (ve is ErrorEval)
			{
				throw new EvaluationException((ErrorEval)ve);
			}
			if (ve is StringEval)
			{
				if (IsScalarProduct)
				{
					throw new EvaluationException(ErrorEval.VALUE_INVALID);
				}
				return 0.0;
			}
			if (ve is NumericValueEval)
			{
				NumericValueEval numericValueEval = (NumericValueEval)ve;
				return numericValueEval.NumberValue;
			}
			throw new RuntimeException("Unexpected value eval class (" + ve.GetType().Name + ")");
		}
	}
	public abstract class XYNumericFunction : Fixed2ArgFunction
	{
		private abstract class ValueArray : ValueVector
		{
			private int _size;

			public int Size => _size;

			protected ValueArray(int size)
			{
				_size = size;
			}

			public ValueEval GetItem(int index)
			{
				if (index < 0 || index > _size)
				{
					throw new ArgumentException("Specified index " + index + " is outside range (0.." + (_size - 1) + ")");
				}
				return GetItemInternal(index);
			}

			protected abstract ValueEval GetItemInternal(int index);
		}

		private class SingleCellValueArray : ValueArray
		{
			private ValueEval _value;

			public SingleCellValueArray(ValueEval value)
				: base(1)
			{
				_value = value;
			}

			protected override ValueEval GetItemInternal(int index)
			{
				return _value;
			}
		}

		private class RefValueArray : ValueArray
		{
			private RefEval _ref;

			private int _width;

			public RefValueArray(RefEval ref1)
				: base(ref1.NumberOfSheets)
			{
				_ref = ref1;
				_width = ref1.NumberOfSheets;
			}

			protected override ValueEval GetItemInternal(int index)
			{
				int sheetIndex = index % _width + _ref.FirstSheetIndex;
				return _ref.GetInnerValueEval(sheetIndex);
			}
		}

		private class AreaValueArray : ValueArray
		{
			private TwoDEval _ae;

			private int _width;

			public AreaValueArray(TwoDEval ae)
				: base(ae.Width * ae.Height)
			{
				_ae = ae;
				_width = ae.Width;
			}

			protected override ValueEval GetItemInternal(int index)
