	{
		public override ValueEval EvaluateFunc(ValueEval[] args, int srcCellRow, int srcCellCol)
		{
			if (args.Length != 4)
			{
				return ErrorEval.VALUE_INVALID;
			}
			string text = TextFunction.EvaluateStringArg(args[0], srcCellRow, srcCellCol);
			int num = TextFunction.EvaluateIntArg(args[1], srcCellRow, srcCellCol);
			int num2 = TextFunction.EvaluateIntArg(args[2], srcCellRow, srcCellCol);
			string value = TextFunction.EvaluateStringArg(args[3], srcCellRow, srcCellCol);
			if (num < 1 || num2 < 0)
			{
				return ErrorEval.VALUE_INVALID;
			}
			StringBuilder stringBuilder = new StringBuilder(text);
			if (num <= text.Length && num2 != 0)
			{
				stringBuilder.Remove(num - 1, Math.Min(num2, text.Length - num + 1));
			}
			if (num > stringBuilder.Length)
			{
				stringBuilder.Append(value);
			}
			else
			{
				stringBuilder.Insert(num - 1, value);
			}
			return new StringEval(stringBuilder.ToString());
		}
	}
	public class SearchFind : Var2or3ArgFunction
	{
		private bool _isCaseSensitive;

		public SearchFind(bool isCaseSensitive)
		{
			_isCaseSensitive = isCaseSensitive;
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1)
		{
			try
			{
				string needle = TextFunction.EvaluateStringArg(arg0, srcRowIndex, srcColumnIndex);
				string haystack = TextFunction.EvaluateStringArg(arg1, srcRowIndex, srcColumnIndex);
				return Eval(haystack, needle, 0);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			try
			{
				string needle = TextFunction.EvaluateStringArg(arg0, srcRowIndex, srcColumnIndex);
				string haystack = TextFunction.EvaluateStringArg(arg1, srcRowIndex, srcColumnIndex);
				int num = TextFunction.EvaluateIntArg(arg2, srcRowIndex, srcColumnIndex) - 1;
				if (num < 0)
				{
					return ErrorEval.VALUE_INVALID;
				}
				return Eval(haystack, needle, num);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		private ValueEval Eval(string haystack, string needle, int startIndex)
		{
			int num = ((!_isCaseSensitive) ? haystack.IndexOf(needle, startIndex, StringComparison.CurrentCultureIgnoreCase) : haystack.IndexOf(needle, startIndex, StringComparison.CurrentCulture));
			if (num == -1)
			{
				return ErrorEval.VALUE_INVALID;
			}
			return new NumberEval(num + 1);
		}
	}
	public class Substitute : TextFunction
	{
		public override ValueEval EvaluateFunc(ValueEval[] args, int srcCellRow, int srcCellCol)
		{
			if (args.Length < 3 || args.Length > 4)
			{
				return ErrorEval.VALUE_INVALID;
			}
			string oldStr = TextFunction.EvaluateStringArg(args[0], srcCellRow, srcCellCol);
			string searchStr = TextFunction.EvaluateStringArg(args[1], srcCellRow, srcCellCol);
			string newStr = TextFunction.EvaluateStringArg(args[2], srcCellRow, srcCellCol);
			string value;
			switch (args.Length)
			{
			case 4:
			{
				int num = TextFunction.EvaluateIntArg(args[3], srcCellRow, srcCellCol);
				if (num < 1)
				{
					return ErrorEval.VALUE_INVALID;
				}
				value = ReplaceOneOccurrence(oldStr, searchStr, newStr, num);
				break;
			}
			case 3:
				value = ReplaceAllOccurrences(oldStr, searchStr, newStr);
				break;
			default:
				throw new InvalidOperationException("Cannot happen");
			}
			return new StringEval(value);
		}

		private static string ReplaceAllOccurrences(string oldStr, string searchStr, string newStr)
		{
			StringBuilder stringBuilder = new StringBuilder();
			int num = 0;
			int num2 = -1;
			while (true)
			{
				num2 = oldStr.IndexOf(searchStr, num, StringComparison.CurrentCulture);
				if (num2 < 0)
				{
					break;
				}
				stringBuilder.Append(oldStr.Substring(num, num2 - num));
				stringBuilder.Append(newStr);
				num = num2 + searchStr.Length;
			}
			stringBuilder.Append(oldStr.Substring(num));
			return stringBuilder.ToString();
		}

		private static string ReplaceOneOccurrence(string oldStr, string searchStr, string newStr, int instanceNumber)
		{
			if (searchStr.Length < 1)
			{
				return oldStr;
			}
			int startIndex = 0;
			int num = -1;
			int num2 = 0;
			while (true)
			{
				num = oldStr.IndexOf(searchStr, startIndex, StringComparison.CurrentCulture);
				if (num < 0)
				{
					return oldStr;
				}
				num2++;
				if (num2 == instanceNumber)
				{
					break;
				}
				startIndex = num + searchStr.Length;
			}
			StringBuilder stringBuilder = new StringBuilder(oldStr.Length + newStr.Length);
			stringBuilder.Append(oldStr.Substring(0, num));
			stringBuilder.Append(newStr);
			stringBuilder.Append(oldStr.Substring(num + searchStr.Length));
			return stringBuilder.ToString();
		}
	}
