	public class Value : Fixed1ArgFunction
	{
		private const int MIN_DISTANCE_BETWEEN_THOUSANDS_SEPARATOR = 4;

		private const double ZERO = 0.0;

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0)
		{
			ValueEval singleValue;
			try
			{
				singleValue = OperandResolver.GetSingleValue(arg0, srcRowIndex, srcColumnIndex);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
			string strText = OperandResolver.CoerceValueToString(singleValue);
			double num = ConvertTextToNumber(strText);
			if (double.IsNaN(num))
			{
				return ErrorEval.VALUE_INVALID;
			}
			return new NumberEval(num);
		}

		private static double ConvertTextToNumber(string strText)
		{
			bool flag = false;
			bool flag2 = false;
			bool flag3 = false;
			bool flag4 = false;
			int length = strText.Length;
			int i;
			for (i = 0; i < length; i++)
			{
				char c = strText[i];
				if (char.IsDigit(c) || c == '.')
				{
					break;
				}
				switch (c)
				{
				case '$':
					if (flag)
					{
						return double.NaN;
					}
					flag = true;
					break;
				case '+':
					if (flag3 || flag2)
					{
						return double.NaN;
					}
					flag2 = true;
					break;
				case '-':
					if (flag3 || flag2)
					{
						return double.NaN;
					}
					flag3 = true;
					break;
				default:
					return double.NaN;
				case ' ':
					break;
				}
			}
			if (i >= length)
			{
				if (flag || flag3 || flag2)
				{
					return double.NaN;
				}
				return 0.0;
			}
			bool flag5 = false;
			int num = -32768;
			StringBuilder stringBuilder = new StringBuilder(length);
			for (; i < length; i++)
			{
				char c2 = strText[i];
				if (char.IsDigit(c2))
				{
					stringBuilder.Append(c2);
					continue;
				}
				switch (c2)
				{
				case ' ':
				{
					string text = strText.Substring(i).Trim();
					if (text.Equals("%"))
					{
						flag4 = true;
					}
					else if (text.Length > 0)
					{
						return double.NaN;
					}
					break;
				}
				case '.':
					if (flag5)
					{
						return double.NaN;
					}
					if (i - num < 4)
					{
						return double.NaN;
					}
					flag5 = true;
					stringBuilder.Append('.');
					break;
				case ',':
				{
					if (flag5)
					{
						return double.NaN;
					}
					int num2 = i - num;
					if (num2 < 4)
					{
						return double.NaN;
					}
					num = i;
					break;
				}
				case 'E':
				case 'e':
					if (i - num < 4)
					{
						return double.NaN;
					}
					stringBuilder.Append(strText.Substring(i));
					i = length;
					break;
				case '%':
					flag4 = true;
					break;
				default:
					return double.NaN;
				}
			}
			if (!flag5 && i - num < 4)
			{
				return double.NaN;
			}
			double num3;
			try
			{
				num3 = double.Parse(stringBuilder.ToString(), CultureInfo.InvariantCulture);
			}
			catch (FormatException)
			{
				return double.NaN;
			}
			double num4 = (flag3 ? (0.0 - num3) : num3);
			if (!flag4)
			{
				return num4;
			}
			return num4 / 100.0;
		}
	}
	public abstract class Var3or4ArgFunction : Function3Arg, Function4Arg, Function
	{
		public ValueEval Evaluate(ValueEval[] args, int srcRowIndex, int srcColumnIndex)
		{
			return args.Length switch
			{
				3 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2]), 
				4 => Evaluate(srcRowIndex, srcColumnIndex, args[0], args[1], args[2], args[3]), 
				_ => ErrorEval.VALUE_INVALID, 
			};
		}

		public abstract ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2);

		public abstract ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2, ValueEval arg3);
	}
	public class Vlookup : Var3or4ArgFunction
	{
		private static ValueEval DEFAULT_ARG3 = BoolEval.TRUE;

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval arg0, ValueEval arg1, ValueEval arg2)
		{
			return Evaluate(srcRowIndex, srcColumnIndex, arg0, arg1, arg2, DEFAULT_ARG3);
		}

		public override ValueEval Evaluate(int srcRowIndex, int srcColumnIndex, ValueEval lookup_value, ValueEval table_array, ValueEval col_index, ValueEval range_lookup)
		{
			try
			{
				ValueEval singleValue = OperandResolver.GetSingleValue(lookup_value, srcRowIndex, srcColumnIndex);
				TwoDEval tableArray = LookupUtils.ResolveTableArrayArg(table_array);
				bool isRangeLookup = LookupUtils.ResolveRangeLookupArg(range_lookup, srcRowIndex, srcColumnIndex);
				int index = LookupUtils.LookupIndexOfValue(singleValue, LookupUtils.CreateColumnVector(tableArray, 0), isRangeLookup);
				int colIndex = LookupUtils.ResolveRowOrColIndexArg(col_index, srcRowIndex, srcColumnIndex);
				ValueVector valueVector = CreateResultColumnVector(tableArray, colIndex);
				return valueVector.GetItem(index);
			}
			catch (EvaluationException ex)
			{
				return ex.GetErrorEval();
			}
		}

		private ValueVector CreateResultColumnVector(TwoDEval tableArray, int colIndex)
		{
			if (colIndex >= tableArray.Width)
			{
				throw EvaluationException.InvalidRef();
			}
			return LookupUtils.CreateColumnVector(tableArray, colIndex);
		}
	}
