		public ValueEval GetNameXEval(NameXPtg nameXPtg)
		{
			ExternalSheet externalSheet = _workbook.GetExternalSheet(nameXPtg.SheetRefIndex);
			if (externalSheet == null || externalSheet.WorkbookName == null)
			{
				return GetLocalNameXEval(nameXPtg);
			}
			string workbookName = externalSheet.WorkbookName;
			ExternalName externalName = _workbook.GetExternalName(nameXPtg.SheetRefIndex, nameXPtg.NameIndex);
			return GetExternalNameXEval(externalName, workbookName);
		}

		public ValueEval GetNameXEval(NameXPxg nameXPxg)
		{
			ExternalSheet externalSheet = _workbook.GetExternalSheet(nameXPxg.SheetName, null, nameXPxg.ExternalWorkbookNumber);
			if (externalSheet == null || externalSheet.WorkbookName == null)
			{
				return GetLocalNameXEval(nameXPxg);
			}
			string workbookName = externalSheet.WorkbookName;
			ExternalName externalName = _workbook.GetExternalName(nameXPxg.NameName, nameXPxg.SheetName, nameXPxg.ExternalWorkbookNumber);
			return GetExternalNameXEval(externalName, workbookName);
		}

		private ValueEval GetLocalNameXEval(NameXPxg nameXPxg)
		{
			int sheetIndex = -1;
			if (nameXPxg.SheetName != null)
			{
				sheetIndex = _workbook.GetSheetIndex(nameXPxg.SheetName);
			}
			string nameName = nameXPxg.NameName;
			IEvaluationName name = _workbook.GetName(nameName, sheetIndex);
			if (name != null)
			{
				return new ExternalNameEval(name);
			}
			return new FunctionNameEval(nameName);
		}

		private ValueEval GetLocalNameXEval(NameXPtg nameXPtg)
		{
			string text = _workbook.ResolveNameXText(nameXPtg);
			int num = text.IndexOf('!');
			IEvaluationName evaluationName = null;
			if (num > -1)
			{
				string sheetName = text.Substring(0, num);
				string name = text.Substring(num + 1);
				evaluationName = _workbook.GetName(name, _workbook.GetSheetIndex(sheetName));
			}
			else
			{
				evaluationName = _workbook.GetName(text, -1);
			}
			if (evaluationName != null)
			{
				return new ExternalNameEval(evaluationName);
			}
			return new FunctionNameEval(text);
		}

		private ValueEval GetExternalNameXEval(ExternalName externName, string workbookName)
		{
			try
			{
				WorkbookEvaluator otherWorkbookEvaluator = _bookEvaluator.GetOtherWorkbookEvaluator(workbookName);
				IEvaluationName name = otherWorkbookEvaluator.GetName(externName.Name, externName.Ix - 1);
				if (name != null && name.HasFormula)
				{
					if (name.NameDefinition.Length > 1)
					{
						throw new Exception("Complex name formulas not supported yet");
					}
					OperationEvaluationContext operationEvaluationContext = new OperationEvaluationContext(otherWorkbookEvaluator, otherWorkbookEvaluator.Workbook, -1, -1, -1, _tracker);
					Ptg ptg = name.NameDefinition[0];
					if (ptg is Ref3DPtg)
					{
						Ref3DPtg rptg = (Ref3DPtg)ptg;
						return operationEvaluationContext.GetRef3DEval(rptg);
					}
					if (ptg is Ref3DPxg)
					{
						Ref3DPxg rptg2 = (Ref3DPxg)ptg;
						return operationEvaluationContext.GetRef3DEval(rptg2);
					}
					if (ptg is Area3DPtg)
					{
						Area3DPtg aptg = (Area3DPtg)ptg;
						return operationEvaluationContext.GetArea3DEval(aptg);
					}
					if (ptg is Area3DPxg)
					{
						Area3DPxg aptg2 = (Area3DPxg)ptg;
						return operationEvaluationContext.GetArea3DEval(aptg2);
					}
				}
				return ErrorEval.REF_INVALID;
			}
			catch (WorkbookNotFoundException)
			{
				return ErrorEval.REF_INVALID;
			}
		}
	}
	internal class OperationEvaluatorFactory
	{
		private static Type[] OPERATION_CONSTRUCTOR_CLASS_ARRAY = new Type[1] { typeof(Ptg) };

		private static Hashtable _instancesByPtgClass = InitialiseInstancesMap();

		private OperationEvaluatorFactory()
		{
		}

		private static Hashtable InitialiseInstancesMap()
		{
			Hashtable hashtable = new Hashtable(32);
			Add(hashtable, EqualPtg.instance, RelationalOperationEval.EqualEval);
			Add(hashtable, GreaterEqualPtg.instance, RelationalOperationEval.GreaterEqualEval);
			Add(hashtable, GreaterThanPtg.instance, RelationalOperationEval.GreaterThanEval);
			Add(hashtable, LessEqualPtg.instance, RelationalOperationEval.LessEqualEval);
			Add(hashtable, LessThanPtg.instance, RelationalOperationEval.LessThanEval);
			Add(hashtable, NotEqualPtg.instance, RelationalOperationEval.NotEqualEval);
			Add(hashtable, ConcatPtg.instance, ConcatEval.instance);
			Add(hashtable, AddPtg.instance, TwoOperandNumericOperation.AddEval);
			Add(hashtable, DividePtg.instance, TwoOperandNumericOperation.DivideEval);
			Add(hashtable, MultiplyPtg.instance, TwoOperandNumericOperation.MultiplyEval);
			Add(hashtable, PercentPtg.instance, PercentEval.instance);
			Add(hashtable, PowerPtg.instance, TwoOperandNumericOperation.PowerEval);
			Add(hashtable, SubtractPtg.instance, TwoOperandNumericOperation.SubtractEval);
			Add(hashtable, UnaryMinusPtg.instance, UnaryMinusEval.instance);
			Add(hashtable, UnaryPlusPtg.instance, UnaryPlusEval.instance);
			Add(hashtable, RangePtg.instance, RangeEval.instance);
			Add(hashtable, IntersectionPtg.instance, IntersectionEval.instance);
			return hashtable;
		}

		private static void Add(Hashtable m, OperationPtg ptgKey, NPOI.SS.Formula.Functions.Function instance)
		{
			ConstructorInfo[] constructors = ptgKey.GetType().GetConstructors();
			if (constructors.Length > 1 || (constructors.Length > 0 && !constructors[0].IsPrivate))
			{
				throw new Exception("Failed to verify instance (" + ptgKey.GetType().Name + ") is a singleton.");
			}
			m[ptgKey] = instance;
		}

		public static ValueEval Evaluate(OperationPtg ptg, ValueEval[] args, OperationEvaluationContext ec)
		{
			if (ptg == null)
			{
				throw new ArgumentException("ptg must not be null");
			}
			if (_instancesByPtgClass[ptg] is NPOI.SS.Formula.Functions.Function function)
			{
				return function.Evaluate(args, ec.RowIndex, (short)ec.ColumnIndex);
			}
			if (ptg is AbstractFunctionPtg)
			{
				AbstractFunctionPtg abstractFunctionPtg = (AbstractFunctionPtg)ptg;
				int functionIndex = abstractFunctionPtg.FunctionIndex;
				return functionIndex switch
				{
					148 => Indirect.instance.Evaluate(args, ec), 
					255 => UserDefinedFunction.instance.Evaluate(args, ec), 
					_ => FunctionEval.GetBasicFunction(functionIndex).Evaluate(args, ec.RowIndex, ec.ColumnIndex), 
				};
			}
			throw new Exception("Unexpected operation ptg class (" + ptg.GetType().Name + ")");
		}
	}
	internal class ParseNode
	{
		private class TokenCollector
		{
			private Ptg[] _ptgs;

			private int _offset;

			public TokenCollector(int tokenCount)
			{
				_ptgs = new Ptg[tokenCount];
				_offset = 0;
			}

			public int sumTokenSizes(int fromIx, int ToIx)
			{
				int num = 0;
				for (int i = fromIx; i < ToIx; i++)
				{
					num += _ptgs[i].Size;
				}
				return num;
			}

			public int CreatePlaceholder()
			{
				return _offset++;
			}

			public void Add(Ptg token)
			{
				if (token == null)
				{
					throw new ArgumentException("token must not be null");
				}
				_ptgs[_offset] = token;
				_offset++;
			}

			public void SetPlaceholder(int index, Ptg token)
			{
				if (_ptgs[index] != null)
				{
					throw new InvalidOperationException("Invalid placeholder index (" + index + ")");
				}
				_ptgs[index] = token;
			}

			public Ptg[] GetResult()
			{
				return _ptgs;
			}
		}

		public static ParseNode[] EMPTY_ARRAY = new ParseNode[0];

		private Ptg _token;

		private ParseNode[] _children;

		private bool _isIf;

		private int _tokenCount;

		private int TokenCount => _tokenCount;

		public int EncodedSize
		{
			get
			{
				int num = ((_token is ArrayPtg) ? 8 : _token.Size);
				for (int i = 0; i < _children.Length; i++)
				{
					num += _children[i].EncodedSize;
				}
				return num;
			}
		}

		public ParseNode(Ptg token, ParseNode[] children)
		{
			_token = token;
			_children = children;
			_isIf = IsIf(token);
			int num = 1;
			for (int i = 0; i < children.Length; i++)
			{
				num += children[i].TokenCount;
			}
			if (_isIf)
			{
				num += children.Length;
			}
			_tokenCount = num;
		}

		public ParseNode(Ptg token)
			: this(token, EMPTY_ARRAY)
		{
		}

		public ParseNode(Ptg token, ParseNode child0)
			: this(token, new ParseNode[1] { child0 })
		{
		}

		public ParseNode(Ptg token, ParseNode child0, ParseNode child1)
			: this(token, new ParseNode[2] { child0, child1 })
		{
		}

		public static Ptg[] ToTokenArray(ParseNode rootNode)
		{
			TokenCollector tokenCollector = new TokenCollector(rootNode.TokenCount);
			rootNode.CollectPtgs(tokenCollector);
			return tokenCollector.GetResult();
		}

		private void CollectPtgs(TokenCollector temp)
		{
			if (IsIf(_token))
			{
				CollectIfPtgs(temp);
				return;
			}
			bool flag = _token is MemFuncPtg || _token is MemAreaPtg;
			if (flag)
			{
				temp.Add(_token);
			}
			for (int i = 0; i < GetChildren().Length; i++)
			{
				GetChildren()[i].CollectPtgs(temp);
			}
			if (!flag)
			{
				temp.Add(_token);
			}
		}

		private void CollectIfPtgs(TokenCollector temp)
		{
			GetChildren()[0].CollectPtgs(temp);
			int num = temp.CreatePlaceholder();
			GetChildren()[1].CollectPtgs(temp);
			int num2 = temp.CreatePlaceholder();
			int num3 = temp.sumTokenSizes(num + 1, num2);
			AttrPtg token = AttrPtg.CreateIf(num3 + 4);
			if (GetChildren().Length > 2)
			{
				GetChildren()[2].CollectPtgs(temp);
				int num4 = temp.CreatePlaceholder();
				int num5 = temp.sumTokenSizes(num2 + 1, num4);
				AttrPtg token2 = AttrPtg.CreateSkip(num5 + 4 + 4 - 1);
				AttrPtg token3 = AttrPtg.CreateSkip(3);
				temp.SetPlaceholder(num, token);
				temp.SetPlaceholder(num2, token2);
				temp.SetPlaceholder(num4, token3);
			}
			else
			{
				AttrPtg token4 = AttrPtg.CreateSkip(3);
				temp.SetPlaceholder(num, token);
				temp.SetPlaceholder(num2, token4);
			}
			temp.Add(GetToken());
		}

		private static bool IsIf(Ptg token)
		{
			if (token is FuncVarPtg)
			{
				FuncVarPtg funcVarPtg = (FuncVarPtg)token;
				if ("IF".Equals(funcVarPtg.Name))
				{
					return true;
				}
			}
			return false;
		}

		public Ptg GetToken()
		{
			return _token;
		}

		public ParseNode[] GetChildren()
		{
			return _children;
		}
	}
	public class Loc
	{
		private long _bookSheetColumn;

		private int _rowIndex;

		public int RowIndex => _rowIndex;

		public int ColumnIndex => (int)(_bookSheetColumn & 0xFFFF);

		public int SheetIndex => (int)((_bookSheetColumn >> 32) & 0xFFFF);

		public int BookIndex => (int)((_bookSheetColumn >> 48) & 0xFFFF);

		public Loc(int bookIndex, int sheetIndex, int rowIndex, int columnIndex)
		{
			_bookSheetColumn = ToBookSheetColumn(bookIndex, sheetIndex, columnIndex);
			_rowIndex = rowIndex;
		}

		public static long ToBookSheetColumn(int bookIndex, int sheetIndex, int columnIndex)
		{
			return (long)((((ulong)bookIndex & 0xFFFFuL) << 48) + (((ulong)sheetIndex & 0xFFFFuL) << 32) + ((ulong)columnIndex & 0xFFFFuL));
		}

		public Loc(int bookSheetColumn, int rowIndex)
		{
			_bookSheetColumn = bookSheetColumn;
			_rowIndex = rowIndex;
		}

		public override int GetHashCode()
		{
			return (int)(_bookSheetColumn ^ Operator.UnsignedRightShift(_bookSheetColumn, 32)) + 17 * _rowIndex;
		}

		public override bool Equals(object obj)
		{
			Loc loc = (Loc)obj;
			if (_bookSheetColumn == loc._bookSheetColumn)
			{
				return _rowIndex == loc._rowIndex;
			}
			return false;
		}
	}
	public class PlainCellCache
	{
		private Hashtable _plainValueEntriesByLoc;

		public PlainCellCache()
		{
			_plainValueEntriesByLoc = new Hashtable();
		}

		public void Put(Loc key, PlainValueCellCacheEntry cce)
		{
			_plainValueEntriesByLoc[key] = cce;
		}

		public void Clear()
		{
			_plainValueEntriesByLoc.Clear();
		}

		public PlainValueCellCacheEntry Get(Loc key)
		{
			return (PlainValueCellCacheEntry)_plainValueEntriesByLoc[key];
		}

		public void Remove(Loc key)
		{
			_plainValueEntriesByLoc.Remove(key);
		}
	}
