	public class ArrayPtg : Ptg
	{
		public class Initial : Ptg
		{
			private int _reserved0;

			private int _reserved1;

			private int _reserved2;

			public override byte DefaultOperandClass
			{
				get
				{
					throw Invalid();
				}
			}

			public override int Size => 8;

			public override bool IsBaseToken => false;

			public Initial(ILittleEndianInput in1)
			{
				_reserved0 = in1.ReadInt();
				_reserved1 = in1.ReadUShort();
				_reserved2 = in1.ReadUByte();
			}

			private static Exception Invalid()
			{
				throw new InvalidOperationException("This object is a partially initialised tArray, and cannot be used as a Ptg");
			}

			public override string ToFormulaString()
			{
				throw Invalid();
			}

			public override void Write(ILittleEndianOutput out1)
			{
				throw Invalid();
			}

			public ArrayPtg FinishReading(ILittleEndianInput in1)
			{
				int num = in1.ReadUByte();
				short num2 = in1.ReadShort();
				num++;
				num2++;
				int nValues = num2 * num;
				object[] arrayValues = ConstantValueParser.Parse(in1, nValues);
				ArrayPtg arrayPtg = new ArrayPtg(_reserved0, _reserved1, _reserved2, num, num2, arrayValues);
				arrayPtg.PtgClass = base.PtgClass;
				return arrayPtg;
			}
		}

		public const byte sid = 32;

		private const int RESERVED_FIELD_LEN = 7;

		public const int PLAIN_TOKEN_SIZE = 8;

		private int _reserved0Int;

		private int _reserved1Short;

		private int _reserved2Byte;

		private int _nColumns;

		private int _nRows;

		private object[] _arrayValues;

		public override bool IsBaseToken => false;

		public int RowCount => _nRows;

		public int ColumnCount => _nColumns;

		public override int Size
		{
			get
			{
				int num = 11;
				return num + ConstantValueParser.GetEncodedSize(_arrayValues);
			}
		}

		public override byte DefaultOperandClass => 64;

		private ArrayPtg(int reserved0, int reserved1, int reserved2, int nColumns, int nRows, object[] arrayValues)
		{
			_reserved0Int = reserved0;
			_reserved1Short = reserved1;
			_reserved2Byte = reserved2;
			_nColumns = nColumns;
			_nRows = nRows;
			_arrayValues = arrayValues;
		}

		public ArrayPtg(object[][] values2d)
		{
			int num = values2d[0].Length;
			int num2 = values2d.Length;
			_nColumns = (short)num;
			_nRows = (short)num2;
			object[] array = new object[_nColumns * _nRows];
			for (int i = 0; i < num2; i++)
			{
				object[] array2 = values2d[i];
				for (int j = 0; j < num; j++)
				{
					array[GetValueIndex(j, i)] = array2[j];
				}
			}
			_arrayValues = array;
			_reserved0Int = 0;
			_reserved1Short = 0;
			_reserved2Byte = 0;
		}

		public object[][] GetTokenArrayValues()
		{
			if (_arrayValues == null)
			{
				throw new InvalidOperationException("array values not read yet");
			}
			object[][] array = new object[_nRows][];
			for (int i = 0; i < _nRows; i++)
			{
				array[i] = new object[_nColumns];
				for (int j = 0; j < _nColumns; j++)
				{
					array[i][j] = _arrayValues[GetValueIndex(j, i)];
				}
			}
			return array;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder("[ArrayPtg]\n");
			stringBuilder.Append("columns = ").Append(ColumnCount).Append("\n");
			stringBuilder.Append("rows = ").Append(RowCount).Append("\n");
			for (int i = 0; i < ColumnCount; i++)
			{
				for (int j = 0; j < RowCount; j++)
				{
					object value = _arrayValues.GetValue(GetValueIndex(i, j));
					stringBuilder.Append("[").Append(i).Append("][")
						.Append(j)
						.Append("] = ")
						.Append(value)
						.Append("\n");
				}
			}
			return stringBuilder.ToString();
		}

		public int GetValueIndex(int colIx, int rowIx)
		{
			if (colIx < 0 || colIx >= _nColumns)
			{
				throw new ArgumentException("Specified colIx (" + colIx + ") is outside the allowed range (0.." + (_nColumns - 1) + ")");
			}
			if (rowIx < 0 || rowIx >= _nRows)
			{
				throw new ArgumentException("Specified rowIx (" + rowIx + ") is outside the allowed range (0.." + (_nRows - 1) + ")");
			}
			return rowIx * _nColumns + colIx;
		}

		public override void Write(ILittleEndianOutput out1)
		{
			out1.WriteByte(32 + base.PtgClass);
			out1.WriteInt(_reserved0Int);
			out1.WriteShort(_reserved1Short);
			out1.WriteByte(_reserved2Byte);
		}

		public int WriteTokenValueBytes(ILittleEndianOutput out1)
		{
			out1.WriteByte(_nColumns - 1);
			out1.WriteShort(_nRows - 1);
			ConstantValueParser.Encode(out1, _arrayValues);
			return 3 + ConstantValueParser.GetEncodedSize(_arrayValues);
		}

		public override string ToFormulaString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("{");
			for (int i = 0; i < RowCount; i++)
			{
				if (i > 0)
				{
					stringBuilder.Append(";");
				}
				for (int j = 0; j < ColumnCount; j++)
				{
					if (j > 0)
					{
						stringBuilder.Append(",");
					}
					object value = _arrayValues.GetValue(GetValueIndex(j, i));
					stringBuilder.Append(GetConstantText(value));
				}
			}
			stringBuilder.Append("}");
			return stringBuilder.ToString();
		}

		private static string GetConstantText(object o)
		{
			if (o == null)
			{
				return "";
			}
			if (o is string)
			{
				return "\"" + (string)o + "\"";
			}
			if (o is double || o is double)
			{
				return NumberToTextConverter.ToText((double)o);
			}
			if (o is bool || o is bool)
			{
				return ((bool)o).ToString().ToUpper();
			}
			if (o is ErrorConstant)
			{
				return ((ErrorConstant)o).Text;
			}
			throw new ArgumentException("Unexpected constant class (" + o.GetType().Name + ")");
		}
	}
	public abstract class ControlPtg : Ptg
	{
		public override bool IsBaseToken => true;

		public override byte DefaultOperandClass
		{
			get
			{
				throw new NotImplementedException("Control tokens are not classified");
			}
		}
	}
	public class AttrPtg : ControlPtg
	{
		public enum SpaceType
		{
			SpaceBefore,
			CrBefore,
			SpaceBeforeOpenParen,
			CrBeforeOpenParen,
			SpaceBeforeCloseParen,
			CrBeforeCloseParen,
			SpaceAfterEquality
		}

		public const byte sid = 25;

		private const int SIZE = 4;

		private byte field_1_options;

		private short field_2_data;

		private int[] _jumpTable;

		private int _chooseFuncOffset;

		private static BitField semiVolatile = BitFieldFactory.GetInstance(1);

		private static BitField optiIf = BitFieldFactory.GetInstance(2);

		private static BitField optiChoose = BitFieldFactory.GetInstance(4);

		private static BitField optiSkip = BitFieldFactory.GetInstance(8);

		private static BitField optiSum = BitFieldFactory.GetInstance(16);

		private static BitField baxcel = BitFieldFactory.GetInstance(32);

		private static BitField space = BitFieldFactory.GetInstance(64);

		public static readonly AttrPtg SUM = new AttrPtg(16, 0, null, -1);

		public bool IsSemiVolatile => semiVolatile.IsSet(field_1_options);

		public bool IsOptimizedIf
		{
			get
			{
				return optiIf.IsSet(field_1_options);
			}
			set
			{
				field_1_options = optiIf.SetByteBoolean(field_1_options, value);
			}
		}

		public bool IsOptimizedChoose => optiChoose.IsSet(field_1_options);

		public bool IsSum
		{
			get
			{
				return optiSum.IsSet(field_1_options);
			}
			set
			{
				field_1_options = optiSum.SetByteBoolean(field_1_options, value);
			}
		}

		public bool IsBaxcel => baxcel.IsSet(field_1_options);

		public bool IsSpace => space.IsSet(field_1_options);

		public bool IsSkip => optiSkip.IsSet(field_1_options);

		public short Data
		{
			get
			{
				return field_2_data;
			}
			set
			{
				field_2_data = value;
			}
		}

		public int[] JumpTable => (int[])_jumpTable.Clone();

		public int ChooseFuncOffset
		{
			get
			{
				if (_jumpTable == null)
				{
					throw new InvalidOperationException("Not tAttrChoose");
				}
				return _chooseFuncOffset;
			}
		}

		public override int Size
		{
			get
			{
				if (_jumpTable != null)
				{
					return 4 + (_jumpTable.Length + 1) * 2;
				}
				return 4;
			}
		}

		public int NumberOfOperands => 1;

		public int Type => -1;

		public AttrPtg()
		{
			_jumpTable = null;
			_chooseFuncOffset = -1;
		}

		public AttrPtg(ILittleEndianInput in1)
		{
			field_1_options = (byte)in1.ReadByte();
			field_2_data = in1.ReadShort();
			if (IsOptimizedChoose)
			{
				int num = field_2_data;
				int[] array = new int[num];
				for (int i = 0; i < array.Length; i++)
				{
					array[i] = in1.ReadUShort();
				}
				_jumpTable = array;
				_chooseFuncOffset = in1.ReadUShort();
			}
			else
			{
				_jumpTable = null;
				_chooseFuncOffset = -1;
			}
		}

		private AttrPtg(int options, int data, int[] jt, int chooseFuncOffset)
		{
			field_1_options = (byte)options;
			field_2_data = (short)data;
			_jumpTable = jt;
			_chooseFuncOffset = chooseFuncOffset;
		}

		public static AttrPtg CreateSpace(SpaceType type, int count)
		{
			int data = (int)(type & (SpaceType)255) | ((count << 8) & 0xFFFF);
			return new AttrPtg(space.Set(0), data, null, -1);
		}

		public static AttrPtg CreateIf(int dist)
		{
			return new AttrPtg(optiIf.Set(0), dist, null, -1);
		}

		public static AttrPtg CreateSkip(int dist)
		{
			return new AttrPtg(optiSkip.Set(0), dist, null, -1);
		}

		public static AttrPtg GetSumSingle()
		{
			return new AttrPtg(optiSum.Set(0), 0, null, -1);
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(64);
			stringBuilder.Append(GetType().Name).Append(" [");
			if (IsSemiVolatile)
			{
				stringBuilder.Append("volatile ");
			}
			if (IsSpace)
			{
				stringBuilder.Append("space count=").Append((field_2_data >> 8) & 0xFF);
				stringBuilder.Append(" type=").Append(field_2_data & 0xFF).Append(" ");
			}
			if (IsOptimizedIf)
			{
				stringBuilder.Append("if dist=").Append(Data);
			}
			else if (IsOptimizedChoose)
			{
				stringBuilder.Append("choose nCases=").Append(Data);
			}
			else if (IsSkip)
			{
				stringBuilder.Append("skip dist=").Append(Data);
			}
			else if (IsSum)
			{
				stringBuilder.Append("sum ");
			}
			else if (IsBaxcel)
			{
				stringBuilder.Append("assign ");
			}
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		public override void Write(ILittleEndianOutput out1)
		{
			out1.WriteByte(25 + base.PtgClass);
			out1.WriteByte(field_1_options);
			out1.WriteShort(field_2_data);
			int[] jumpTable = _jumpTable;
			if (jumpTable != null)
			{
				for (int i = 0; i < jumpTable.Length; i++)
				{
					out1.WriteShort(jumpTable[i]);
				}
				out1.WriteShort(_chooseFuncOffset);
			}
		}

		public string ToFormulaString(string[] operands)
		{
			if (space.IsSet(field_1_options))
			{
				return operands[0];
			}
			if (optiIf.IsSet(field_1_options))
			{
				return ToFormulaString() + "(" + operands[0] + ")";
			}
			if (optiSkip.IsSet(field_1_options))
			{
				return ToFormulaString() + operands[0];
			}
			return ToFormulaString() + "(" + operands[0] + ")";
		}

		public override string ToFormulaString()
		{
			if (semiVolatile.IsSet(field_1_options))
			{
				return "ATTR(semiVolatile)";
			}
			if (optiIf.IsSet(field_1_options))
			{
				return "IF";
			}
			if (optiChoose.IsSet(field_1_options))
			{
				return "CHOOSE";
			}
			if (optiSkip.IsSet(field_1_options))
			{
				return "";
			}
			if (optiSum.IsSet(field_1_options))
			{
				return "SUM";
			}
			if (baxcel.IsSet(field_1_options))
			{
				return "ATTR(baxcel)";
			}
			if (space.IsSet(field_1_options))
			{
				return "";
			}
			return "UNKNOWN ATTRIBUTE";
		}

		public override object Clone()
		{
			return new AttrPtg(jt: (_jumpTable != null) ? ((int[])_jumpTable.Clone()) : null, options: field_1_options, data: field_2_data, chooseFuncOffset: _chooseFuncOffset);
		}
	}
