namespace NPOI.SS.Util
{
	public class AreaReference
	{
		private const char SHEET_NAME_DELIMITER = '!';

		private const char CELL_DELIMITER = ':';

		private const char SPECIAL_NAME_DELIMITER = '\'';

		private CellReference _firstCell;

		private CellReference _lastCell;

		private bool _isSingleCell;

		public bool IsSingleCell => _isSingleCell;

		public CellReference FirstCell => _firstCell;

		public CellReference LastCell => _lastCell;

		public AreaReference(string reference)
		{
			if (!IsContiguous(reference))
			{
				throw new ArgumentException("References passed to the AreaReference must be contiguous, use generateContiguous(ref) if you have non-contiguous references");
			}
			string[] array = SeparateAreaRefs(reference);
			string text = array[0];
			if (array.Length == 1)
			{
				_firstCell = new CellReference(text);
				_lastCell = _firstCell;
				_isSingleCell = true;
				return;
			}
			if (array.Length != 2)
			{
				throw new ArgumentException("Bad area ref '" + reference + "'");
			}
			string text2 = array[1];
			if (IsPlainColumn(text))
			{
				if (!IsPlainColumn(text2))
				{
					throw new Exception("Bad area ref '" + reference + "'");
				}
				bool pAbsCol = CellReference.IsPartAbsolute(text);
				bool pAbsCol2 = CellReference.IsPartAbsolute(text2);
				int pCol = CellReference.ConvertColStringToIndex(text);
				int pCol2 = CellReference.ConvertColStringToIndex(text2);
				_firstCell = new CellReference(0, pCol, pAbsRow: true, pAbsCol);
				_lastCell = new CellReference(65535, pCol2, pAbsRow: true, pAbsCol2);
				_isSingleCell = false;
			}
			else
			{
				_firstCell = new CellReference(text);
				_lastCell = new CellReference(text2);
				_isSingleCell = text.Equals(text2);
			}
		}

		private bool IsPlainColumn(string refPart)
		{
			for (int num = refPart.Length - 1; num >= 0; num--)
			{
				int num2 = refPart[num];
				if ((num2 != 36 || num != 0) && (num2 < 65 || num2 > 90))
				{
					return false;
				}
			}
			return true;
		}

		public static AreaReference GetWholeRow(string start, string end)
		{
			return new AreaReference("$A" + start + ":$IV" + end);
		}

		public static AreaReference GetWholeColumn(string start, string end)
		{
			return new AreaReference(start + "$1:" + end + "$65536");
		}

		public AreaReference(CellReference topLeft, CellReference botRight)
		{
			bool flag = topLeft.Row > botRight.Row;
			bool flag2 = topLeft.Col > botRight.Col;
			if (flag || flag2)
			{
				int row;
				bool isRowAbsolute;
				int row2;
				bool isRowAbsolute2;
				if (flag)
				{
					row = botRight.Row;
					isRowAbsolute = botRight.IsRowAbsolute;
					row2 = topLeft.Row;
					isRowAbsolute2 = topLeft.IsRowAbsolute;
				}
				else
				{
					row = topLeft.Row;
					isRowAbsolute = topLeft.IsRowAbsolute;
					row2 = botRight.Row;
					isRowAbsolute2 = botRight.IsRowAbsolute;
				}
				int col;
				bool isColAbsolute;
				int col2;
				bool isColAbsolute2;
				if (flag2)
				{
					col = botRight.Col;
					isColAbsolute = botRight.IsColAbsolute;
					col2 = topLeft.Col;
					isColAbsolute2 = topLeft.IsColAbsolute;
				}
				else
				{
					col = topLeft.Col;
					isColAbsolute = topLeft.IsColAbsolute;
					col2 = botRight.Col;
					isColAbsolute2 = botRight.IsColAbsolute;
				}
				_firstCell = new CellReference(row, col, isRowAbsolute, isColAbsolute);
				_lastCell = new CellReference(row2, col2, isRowAbsolute2, isColAbsolute2);
			}
			else
			{
				_firstCell = topLeft;
				_lastCell = botRight;
			}
			_isSingleCell = false;
		}

		public static bool IsContiguous(string reference)
		{
			int num = reference.IndexOf('!');
			if (num != -1)
			{
				reference = reference.Substring(num);
			}
			if (reference.IndexOf(',') == -1)
			{
				return true;
			}
			return false;
		}

		public static bool IsWholeColumnReference(CellReference topLeft, CellReference botRight)
		{
			if (topLeft.Row == 0 && topLeft.IsRowAbsolute && (botRight.Row == -1 || botRight.Row == 65535) && botRight.IsRowAbsolute)
			{
				return true;
			}
			return false;
		}

		public bool IsWholeColumnReference()
		{
			return IsWholeColumnReference(_firstCell, _lastCell);
		}

		public static AreaReference[] GenerateContiguous(string reference)
		{
			ArrayList arrayList = new ArrayList();
			string[] array = reference.Split(new char[1] { ',' });
			string[] array2 = array;
			foreach (string reference2 in array2)
			{
				arrayList.Add(new AreaReference(reference2));
			}
			return (AreaReference[])arrayList.ToArray(typeof(AreaReference));
		}

		public CellReference[] GetAllReferencedCells()
		{
			if (_isSingleCell)
			{
				return new CellReference[1] { _firstCell };
			}
			int num = Math.Min(_firstCell.Row, _lastCell.Row);
			int num2 = Math.Max(_firstCell.Row, _lastCell.Row);
			int num3 = Math.Min(_firstCell.Col, _lastCell.Col);
			int num4 = Math.Max(_firstCell.Col, _lastCell.Col);
			string sheetName = _firstCell.SheetName;
			ArrayList arrayList = new ArrayList();
			for (int i = num; i <= num2; i++)
			{
				for (int j = num3; j <= num4; j++)
				{
					CellReference value = new CellReference(sheetName, i, j, _firstCell.IsRowAbsolute, _firstCell.IsColAbsolute);
					arrayList.Add(value);
				}
			}
			return (CellReference[])arrayList.ToArray(typeof(CellReference));
		}

		public string FormatAsString()
		{
			if (IsWholeColumnReference())
			{
				return CellReference.ConvertNumToColString(_firstCell.Col) + ":" + CellReference.ConvertNumToColString(_lastCell.Col);
			}
			StringBuilder stringBuilder = new StringBuilder(32);
			stringBuilder.Append(_firstCell.FormatAsString());
			if (!_isSingleCell)
			{
				stringBuilder.Append(':');
				if (_lastCell.SheetName == null)
				{
					stringBuilder.Append(_lastCell.FormatAsString());
				}
				else
				{
					_lastCell.AppendCellReference(stringBuilder);
				}
			}
			return stringBuilder.ToString();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(64);
			stringBuilder.Append(GetType().Name).Append(" [");
			stringBuilder.Append(FormatAsString());
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		private static string[] SeparateAreaRefs(string reference)
		{
			int length = reference.Length;
			int num = -1;
			bool flag = false;
			for (int i = 0; i < length; i++)
			{
				switch (reference[i])
				{
				case ':':
					if (!flag)
					{
						if (num >= 0)
						{
							throw new ArgumentException("More than one cell delimiter '" + ':' + "' appears in area reference '" + reference + "'");
						}
						num = i;
					}
					break;
				case '\'':
					if (!flag)
					{
						flag = true;
						break;
					}
					if (i >= length - 1)
					{
						throw new ArgumentException("Area reference '" + reference + "' ends with special name delimiter '" + '\'' + "'");
					}
					if (reference[i + 1] == '\'')
					{
						i++;
					}
					else
					{
						flag = false;
					}
					break;
				}
			}
			if (num < 0)
			{
				return new string[1] { reference };
			}
			string text = reference.Substring(0, num);
			string text2 = reference.Substring(num + 1);
			if (text2.IndexOf('!') >= 0)
			{
				throw new Exception("Unexpected " + '!' + " in second cell reference of '" + reference + "'");
			}
			int num2 = text.LastIndexOf('!');
			if (num2 < 0)
			{
				return new string[2] { text, text2 };
			}
			string text3 = text.Substring(0, num2 + 1);
			return new string[2]
			{
				text,
				text3 + text2
			};
		}
	}
	public abstract class CellRangeAddressBase
	{
		private int _firstRow;

		private int _firstCol;

		private int _lastRow;

		private int _lastCol;

		public bool IsFullColumnRange
		{
			get
			{
				if (_firstRow != 0 || _lastRow != SpreadsheetVersion.EXCEL97.LastRowIndex)
				{
					if (_firstRow == -1)
					{
						return _lastRow == -1;
					}
					return false;
				}
				return true;
			}
		}

		public bool IsFullRowRange
		{
			get
			{
				if (_firstCol != 0 || _lastCol != SpreadsheetVersion.EXCEL97.LastColumnIndex)
				{
					if (_firstCol == -1)
					{
						return _lastCol == -1;
					}
					return false;
				}
				return true;
			}
		}

		public int FirstColumn
		{
			get
			{
				return _firstCol;
			}
			set
			{
				_firstCol = value;
			}
		}

		public int FirstRow
		{
			get
			{
				return _firstRow;
			}
			set
			{
				_firstRow = value;
			}
		}

		public int LastColumn
		{
			get
			{
				return _lastCol;
			}
			set
			{
				_lastCol = value;
			}
		}

		public int LastRow
		{
			get
			{
				return _lastRow;
			}
			set
			{
				_lastRow = value;
			}
		}

		public int NumberOfCells => (_lastRow - _firstRow + 1) * (_lastCol - _firstCol + 1);

		protected CellRangeAddressBase(int firstRow, int lastRow, int firstCol, int lastCol)
		{
			_firstRow = firstRow;
			_lastRow = lastRow;
			_firstCol = firstCol;
			_lastCol = lastCol;
		}

		public void Validate(SpreadsheetVersion ssVersion)
		{
			ValidateRow(_firstRow, ssVersion);
			ValidateRow(_lastRow, ssVersion);
			ValidateColumn(_firstCol, ssVersion);
			ValidateColumn(_lastCol, ssVersion);
		}

		private static void ValidateRow(int row, SpreadsheetVersion ssVersion)
		{
			int lastRowIndex = ssVersion.LastRowIndex;
			if (row > lastRowIndex)
			{
				throw new ArgumentException("Maximum row number is " + lastRowIndex);
			}
			if (row < 0)
			{
				throw new ArgumentException("Minumum row number is 0");
			}
		}

		private static void ValidateColumn(int column, SpreadsheetVersion ssVersion)
		{
			int lastColumnIndex = ssVersion.LastColumnIndex;
			if (column > lastColumnIndex)
			{
				throw new ArgumentException("Maximum column number is " + lastColumnIndex);
			}
			if (column < 0)
			{
				throw new ArgumentException("Minimum column number is 0");
			}
		}

		public bool IsInRange(int rowInd, int colInd)
		{
			if (_firstRow <= rowInd && rowInd <= _lastRow && _firstCol <= colInd)
			{
				return colInd <= _lastCol;
			}
			return false;
		}

		public override string ToString()
		{
			CellReference cellReference = new CellReference(_firstRow, _firstCol);
			CellReference cellReference2 = new CellReference(_lastRow, _lastCol);
			return GetType().Name + " [" + cellReference.FormatAsString() + ":" + cellReference2.FormatAsString() + "]";
		}
	}
	public class CellRangeAddress : CellRangeAddressBase
	{
		public const int ENCODED_SIZE = 8;

		public CellRangeAddress(int firstRow, int lastRow, int firstCol, int lastCol)
			: base(firstRow, lastRow, firstCol, lastCol)
		{
			if (lastRow < firstRow || lastCol < firstCol)
			{
				throw new ArgumentException("lastRow < firstRow || lastCol < firstCol");
			}
		}

		public CellRangeAddress(RecordInputStream in1)
			: base(ReadUShortAndCheck(in1), in1.ReadUShort(), in1.ReadUShort(), in1.ReadUShort())
		{
		}

		private static int ReadUShortAndCheck(RecordInputStream in1)
		{
			if (in1.Remaining < 8)
			{
				throw new RuntimeException("Ran out of data readin1g CellRangeAddress");
			}
			return in1.ReadUShort();
		}

		public void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteShort(base.FirstRow);
			out1.WriteShort(base.LastRow);
			out1.WriteShort(base.FirstColumn);
			out1.WriteShort(base.LastColumn);
		}

		public string FormatAsString()
		{
			return FormatAsString(null, useAbsoluteAddress: false);
		}

		public string FormatAsString(string sheetName, bool useAbsoluteAddress)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (sheetName != null)
			{
				stringBuilder.Append(SheetNameFormatter.Format(sheetName));
				stringBuilder.Append("!");
			}
			CellReference cellReference = new CellReference(base.FirstRow, base.FirstColumn, useAbsoluteAddress, useAbsoluteAddress);
			CellReference cellReference2 = new CellReference(base.LastRow, base.LastColumn, useAbsoluteAddress, useAbsoluteAddress);
			stringBuilder.Append(cellReference.FormatAsString());
			if (!cellReference.Equals(cellReference2) || base.IsFullColumnRange || base.IsFullRowRange)
			{
				stringBuilder.Append(':');
				stringBuilder.Append(cellReference2.FormatAsString());
			}
			return stringBuilder.ToString();
		}

		public CellRangeAddress Copy()
		{
			return new CellRangeAddress(base.FirstRow, base.LastRow, base.FirstColumn, base.LastColumn);
		}

		public static int GetEncodedSize(int numberOfItems)
		{
			return numberOfItems * 8;
		}

		public static CellRangeAddress ValueOf(string reference)
		{
			int num = reference.IndexOf(":", StringComparison.Ordinal);
			CellReference cellReference;
			CellReference cellReference2;
			if (num == -1)
			{
				cellReference = new CellReference(reference);
				cellReference2 = cellReference;
			}
			else
			{
				cellReference = new CellReference(reference.Substring(0, num));
				cellReference2 = new CellReference(reference.Substring(num + 1));
			}
			return new CellRangeAddress(cellReference.Row, cellReference2.Row, cellReference.Col, cellReference2.Col);
		}
	}
	public class CellRangeAddress8Bit : CellRangeAddressBase
	{
		public const int ENCODED_SIZE = 6;

		public CellRangeAddress8Bit(int firstRow, int lastRow, int firstCol, int lastCol)
			: base(firstRow, lastRow, firstCol, lastCol)
		{
		}

		public CellRangeAddress8Bit(RecordInputStream in1)
			: base(ReadUShortAndCheck(in1), in1.ReadUShort(), in1.ReadUByte(), in1.ReadUByte())
		{
		}

		private static int ReadUShortAndCheck(RecordInputStream in1)
		{
			if (in1.Remaining < 6)
			{
				throw new Exception("Ran out of data reading CellRangeAddress");
			}
			return in1.ReadUShort();
		}

		public int Serialize(int offset, byte[] data)
		{
			LittleEndian.PutUShort(data, offset, base.FirstRow);
			LittleEndian.PutUShort(data, offset + 2, base.LastRow);
			LittleEndian.PutByte(data, offset + 4, base.FirstColumn);
			LittleEndian.PutByte(data, offset + 5, base.LastColumn);
			return 6;
		}

		public void Serialize(ILittleEndianOutput out1)
		{
			out1.WriteShort(base.FirstRow);
			out1.WriteShort(base.LastRow);
			out1.WriteByte(base.FirstColumn);
			out1.WriteByte(base.LastColumn);
		}

		public CellRangeAddress8Bit Copy()
		{
			return new CellRangeAddress8Bit(base.FirstRow, base.LastRow, base.FirstColumn, base.LastColumn);
		}

		public static int GetEncodedSize(int numberOfItems)
		{
			return numberOfItems * 6;
		}
	}
	public class CellRangeAddressList
	{
		private ArrayList _list;

		public int Size => GetEncodedSize(_list.Count);

		public CellRangeAddress[] CellRangeAddresses => (CellRangeAddress[])_list.ToArray(typeof(CellRangeAddress));

		public CellRangeAddressList()
		{
			_list = new ArrayList();
		}

		public CellRangeAddressList(int firstRow, int lastRow, int firstCol, int lastCol)
			: this()
		{
			AddCellRangeAddress(firstRow, firstCol, lastRow, lastCol);
		}

		public CellRangeAddressList(RecordInputStream in1)
		{
			int num = in1.ReadUShort();
			_list = new ArrayList(num);
			for (int i = 0; i < num; i++)
			{
				_list.Add(new CellRangeAddress(in1));
			}
		}

		public int CountRanges()
		{
			return _list.Count;
		}

		public void AddCellRangeAddress(int firstRow, int firstCol, int lastRow, int lastCol)
		{
			CellRangeAddress cra = new CellRangeAddress(firstRow, lastRow, firstCol, lastCol);
			AddCellRangeAddress(cra);
		}

		public void AddCellRangeAddress(CellRangeAddress cra)
		{
			_list.Add(cra);
		}

		public CellRangeAddress Remove(int rangeIndex)
		{
			if (_list.Count == 0)
			{
				throw new Exception("List is empty");
			}
			if (rangeIndex < 0 || rangeIndex >= _list.Count)
			{
				throw new Exception("Range index (" + rangeIndex + ") is outside allowable range (0.." + (_list.Count - 1) + ")");
			}
			CellRangeAddress result = (CellRangeAddress)_list[rangeIndex];
			_list.Remove(rangeIndex);
			return result;
		}

		public CellRangeAddress GetCellRangeAddress(int index)
		{
			return (CellRangeAddress)_list[index];
		}

		public int Serialize(int offset, byte[] data)
		{
			int size = Size;
			Serialize(new LittleEndianByteArrayOutputStream(data, offset, size));
			return size;
		}

		public void Serialize(ILittleEndianOutput out1)
		{
			int count = _list.Count;
			out1.WriteShort(count);
			for (int i = 0; i < count; i++)
			{
				CellRangeAddress cellRangeAddress = (CellRangeAddress)_list[i];
				cellRangeAddress.Serialize(out1);
			}
		}

		public static int GetEncodedSize(int numberOfRanges)
		{
			return 2 + CellRangeAddress.GetEncodedSize(numberOfRanges);
		}

		public CellRangeAddressList Copy()
		{
			CellRangeAddressList cellRangeAddressList = new CellRangeAddressList();
			int count = _list.Count;
			for (int i = 0; i < count; i++)
			{
				CellRangeAddress cellRangeAddress = (CellRangeAddress)_list[i];
				cellRangeAddressList.AddCellRangeAddress(cellRangeAddress.Copy());
			}
			return cellRangeAddressList;
		}
	}
	public enum NameType
	{
		None = 0,
		Cell = 1,
		NamedRange = 2,
		Column = 3,
		Row = 4,
		BadCellOrNamedRange = -1
	}
	public class CellReference
	{
		private const char ABSOLUTE_REFERENCE_MARKER = '$';

		private const char SHEET_NAME_DELIMITER = '!';

		private const char SPECIAL_NAME_DELIMITER = '\'';

		private const string CELL_REF_PATTERN = "^\\$?([A-Za-z]+)\\$?([0-9]+)";

		private const string COLUMN_REF_PATTERN = "^\\$?([A-Za-z]+)$";

		private const string ROW_REF_PATTERN = "^\\$?([0-9]+)$";

		private const string NAMED_RANGE_NAME_PATTERN = "^[_A-Za-z][_.A-Za-z0-9]*$";

		private int _rowIndex;

		private int _colIndex;

		private string _sheetName;

		private bool _isRowAbs;

		private bool _isColAbs;

		public int Row => _rowIndex;

		public short Col => (short)_colIndex;

		public bool IsRowAbsolute => _isRowAbs;

		public bool IsColAbsolute => _isColAbs;

		public string SheetName => _sheetName;

		public string[] CellRefParts => new string[3]
		{
			_sheetName,
			(_rowIndex + 1).ToString(CultureInfo.InvariantCulture),
			ConvertNumToColString(_colIndex)
		};

		public CellReference(string cellRef)
		{
			if (cellRef.EndsWith("#REF!", StringComparison.CurrentCulture))
			{
				throw new ArgumentException("Cell reference invalid: " + cellRef);
			}
			string[] array = SeparateRefParts(cellRef);
			_sheetName = array[0];
			string text = array[1];
			_isColAbs = text.Length > 0 && text[0] == '$';
			if (_isColAbs)
			{
				text = text.Substring(1);
			}
			if (text.Length == 0)
			{
				_colIndex = -1;
			}
			else
			{
				_colIndex = ConvertColStringToIndex(text);
			}
			string text2 = array[2];
			_isRowAbs = text2.Length > 0 && text2[0] == '$';
			if (_isRowAbs)
			{
				text2 = text2.Substring(1);
			}
			if (text2.Length == 0)
			{
				_rowIndex = -1;
			}
			else
			{
				_rowIndex = int.Parse(text2, CultureInfo.InvariantCulture) - 1;
			}
		}

		public CellReference(ICell cell)
			: this(cell.RowIndex, cell.ColumnIndex, pAbsRow: false, pAbsCol: false)
		{
		}

		public CellReference(int pRow, int pCol)
			: this(pRow, pCol, pAbsRow: false, pAbsCol: false)
		{
		}

		public CellReference(int pRow, short pCol)
			: this(pRow, pCol & 0xFFFF, pAbsRow: false, pAbsCol: false)
		{
		}

		public CellReference(int pRow, int pCol, bool pAbsRow, bool pAbsCol)
			: this(null, pRow, pCol, pAbsRow, pAbsCol)
		{
		}

		public CellReference(string pSheetName, int pRow, int pCol, bool pAbsRow, bool pAbsCol)
		{
			if (pRow < -1)
			{
				throw new ArgumentException("row index may not be negative, but had " + pRow);
			}
			if (pCol < -1)
			{
				throw new ArgumentException("column index may not be negative, but had " + pCol);
			}
			_sheetName = pSheetName;
			_rowIndex = pRow;
			_colIndex = pCol;
			_isRowAbs = pAbsRow;
			_isColAbs = pAbsCol;
		}

		public static int ConvertColStringToIndex(string ref1)
		{
			int num = 0;
			char[] array = ref1.ToUpper().ToCharArray();
			for (int i = 0; i < array.Length; i++)
			{
				char c = array[i];
				if (c == '$')
				{
					if (i != 0)
					{
						throw new ArgumentException("Bad col ref format '" + ref1 + "'");
					}
				}
				else
				{
					num = num * 26 + (c - 65 + 1);
				}
			}
			return num - 1;
		}

		public static bool IsPartAbsolute(string part)
		{
			return part[0] == '$';
		}

		public static NameType ClassifyCellReference(string str, SpreadsheetVersion ssVersion)
		{
			int length = str.Length;
			if (length < 1)
			{
				throw new ArgumentException("Empty string not allowed");
			}
			char c = str[0];
			char c2 = c;
			if (c2 != '$' && c2 != '.' && c2 != '_' && !char.IsLetter(c) && !char.IsDigit(c))
			{
				throw new ArgumentException("Invalid first char (" + c + ") of cell reference or named range.  Letter expected");
			}
			if (!char.IsDigit(str[length - 1]))
			{
				return ValidateNamedRangeName(str, ssVersion);
			}
			Regex regex = new Regex("^\\$?([A-Za-z]+)\\$?([0-9]+)");
			if (!regex.IsMatch(str))
			{
				return ValidateNamedRangeName(str, ssVersion);
			}
			MatchCollection matchCollection = regex.Matches(str);
			string value = matchCollection[0].Groups[1].Value;
			string value2 = matchCollection[0].Groups[2].Value;
			if (CellReferenceIsWithinRange(value, value2, ssVersion))
			{
				return NameType.Cell;
			}
			if (str.IndexOf('$') >= 0)
			{
				return NameType.BadCellOrNamedRange;
			}
			return NameType.NamedRange;
		}

		private static NameType ValidateNamedRangeName(string str, SpreadsheetVersion ssVersion)
		{
			Regex regex = new Regex("^\\$?([A-Za-z]+)$");
			if (regex.IsMatch(str))
			{
				Group group = regex.Matches(str)[0].Groups[1];
				if (IsColumnWithnRange(group.Value, ssVersion))
				{
					return NameType.Column;
				}
			}
			Regex regex2 = new Regex("^\\$?([0-9]+)$");
			if (regex2.IsMatch(str))
			{
				Group group2 = regex2.Matches(str)[0].Groups[1];
				if (IsRowWithnRange(group2.Value, ssVersion))
				{
					return NameType.Row;
				}
			}
			if (!Regex.IsMatch(str, "^[_A-Za-z][_.A-Za-z0-9]*$"))
			{
				return NameType.BadCellOrNamedRange;
			}
			return NameType.NamedRange;
		}

		public static string ConvertNumToColString(int col)
		{
			int num = col + 1;
			StringBuilder stringBuilder = new StringBuilder(2);
			int num2 = num;
			while (num2 > 0)
			{
				int num3 = num2 % 26;
				if (num3 == 0)
				{
					num3 = 26;
				}
				num2 = (num2 - num3) / 26;
				char value = (char)(num3 + 64);
				stringBuilder.Insert(0, value);
			}
			return stringBuilder.ToString();
		}

		private static string[] SeparateRefParts(string reference)
		{
			int num = reference.LastIndexOf('!');
			string text = ParseSheetName(reference, num);
			int num2 = num + 1;
			int length = reference.Length;
			int i = num2;
			if (reference[i] == '$')
			{
				i++;
			}
			for (; i < length; i++)
			{
				char c = reference[i];
				if (char.IsDigit(c) || c == '$')
				{
					break;
				}
			}
			return new string[3]
			{
				text,
				reference.Substring(num2, i - num2),
				reference.Substring(i)
			};
		}

		private static string ParseSheetName(string reference, int indexOfSheetNameDelimiter)
		{
			if (indexOfSheetNameDelimiter < 0)
			{
				return null;
			}
			if (reference[0] != '\'')
			{
				return reference.Substring(0, indexOfSheetNameDelimiter);
			}
			int num = indexOfSheetNameDelimiter - 1;
			if (reference[num] != '\'')
			{
				throw new Exception("Mismatched quotes: (" + reference + ")");
			}
			StringBuilder stringBuilder = new StringBuilder(indexOfSheetNameDelimiter);
			for (int i = 1; i < num; i++)
			{
				char c = reference[i];
				if (c != '\'')
				{
					stringBuilder.Append(c);
					continue;
				}
				if (i < num && reference[i + 1] == '\'')
				{
					i++;
					stringBuilder.Append(c);
					continue;
				}
				throw new Exception("Bad sheet name quote escaping: (" + reference + ")");
			}
			return stringBuilder.ToString();
		}

		public string FormatAsString()
		{
			StringBuilder stringBuilder = new StringBuilder(32);
			if (_sheetName != null)
			{
				SheetNameFormatter.AppendFormat(stringBuilder, _sheetName);
				stringBuilder.Append('!');
			}
			AppendCellReference(stringBuilder);
			return stringBuilder.ToString();
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(64);
			stringBuilder.Append(GetType().Name).Append(" [");
			stringBuilder.Append(FormatAsString());
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}

		public void AppendCellReference(StringBuilder sb)
		{
			if (_colIndex != -1)
			{
				if (_isColAbs)
				{
					sb.Append('$');
				}
				sb.Append(ConvertNumToColString(_colIndex));
			}
			if (_rowIndex != -1)
			{
				if (_isRowAbs)
				{
					sb.Append('$');
				}
				sb.Append(_rowIndex + 1);
			}
		}

		public static bool CellReferenceIsWithinRange(string colStr, string rowStr, SpreadsheetVersion ssVersion)
		{
			if (!IsColumnWithnRange(colStr, ssVersion))
			{
				return false;
			}
			return IsRowWithnRange(rowStr, ssVersion);
		}

		public static bool IsRowWithnRange(string rowStr, SpreadsheetVersion ssVersion)
		{
			int num = int.Parse(rowStr, CultureInfo.InvariantCulture);
			if (num < 0)
			{
				throw new InvalidOperationException("Invalid rowStr '" + rowStr + "'.");
			}
			if (num == 0)
			{
				return false;
			}
			return num <= ssVersion.MaxRows;
		}

		public static bool IsColumnWithnRange(string colStr, SpreadsheetVersion ssVersion)
		{
			string lastColumnName = ssVersion.LastColumnName;
			int length = lastColumnName.Length;
			int length2 = colStr.Length;
			if (length2 > length)
			{
				return false;
			}
			if (length2 == length && string.Compare(colStr.ToUpper(), lastColumnName, StringComparison.Ordinal) > 0)
			{
				return false;
			}
			return true;
		}

		public override bool Equals(object o)
		{
			if (object.ReferenceEquals(this, o))
			{
				return true;
			}
			if (!(o is CellReference))
			{
				return false;
			}
			CellReference cellReference = (CellReference)o;
			if (_rowIndex == cellReference._rowIndex && _colIndex == cellReference._colIndex && _isRowAbs == cellReference._isRowAbs)
			{
				return _isColAbs == cellReference._isColAbs;
			}
			return false;
		}

		public override int GetHashCode()
		{
			int num = 17;
			num = 31 * num + _rowIndex;
			num = 31 * num + _colIndex;
			num = 31 * num + (_isRowAbs ? 1 : 0);
			return 31 * num + (_isColAbs ? 1 : 0);
		}
	}
