namespace NPOI.SS.Util.CellWalk
{
	public interface ICellHandler
	{
		void OnCell(ICell cell, ICellWalkContext ctx);
	}
	public class CellWalk
	{
		private class SimpleCellWalkContext : ICellWalkContext
		{
			public long ordinalNumber;

			public int rowNumber;

			public int colNumber;

			public long OrdinalNumber => ordinalNumber;

			public int RowNumber => rowNumber;

			public int ColumnNumber => colNumber;
		}

		private ISheet sheet;

		private CellRangeAddress range;

		private bool traverseEmptyCells;

		public CellWalk(ISheet sheet, CellRangeAddress range)
		{
			this.sheet = sheet;
			this.range = range;
			traverseEmptyCells = false;
		}

		public bool IsTraverseEmptyCells()
		{
			return traverseEmptyCells;
		}

		public void SetTraverseEmptyCells(bool traverseEmptyCells)
		{
			this.traverseEmptyCells = traverseEmptyCells;
		}

		public void Traverse(ICellHandler handler)
		{
			int firstRow = range.FirstRow;
			int lastRow = range.LastRow;
			int firstColumn = range.FirstColumn;
			int lastColumn = range.LastColumn;
			int num = lastColumn - firstColumn + 1;
			SimpleCellWalkContext simpleCellWalkContext = new SimpleCellWalkContext();
			IRow row = null;
			ICell cell = null;
			simpleCellWalkContext.rowNumber = firstRow;
			while (simpleCellWalkContext.rowNumber <= lastRow)
			{
				row = sheet.GetRow(simpleCellWalkContext.rowNumber);
				if (row != null)
				{
					simpleCellWalkContext.colNumber = firstColumn;
					while (simpleCellWalkContext.colNumber <= lastColumn)
					{
						cell = row.GetCell(simpleCellWalkContext.colNumber);
						if (cell != null && (!IsEmpty(cell) || traverseEmptyCells))
						{
							simpleCellWalkContext.ordinalNumber = (simpleCellWalkContext.rowNumber - firstRow) * num + (simpleCellWalkContext.colNumber - firstColumn + 1);
							handler.OnCell(cell, simpleCellWalkContext);
						}
						simpleCellWalkContext.colNumber++;
					}
				}
				simpleCellWalkContext.rowNumber++;
			}
		}

		private bool IsEmpty(ICell cell)
		{
			return cell.CellType == CellType.Blank;
		}
	}
	public interface ICellWalkContext
	{
		long OrdinalNumber { get; }

		int RowNumber { get; }

		int ColumnNumber { get; }
	}
}
namespace NPOI.SS.Util
{
	public class ExpandedDouble
	{
		private static readonly BigInteger BI_FRAC_MASK = new BigInteger(4503599627370495L);

		private static readonly BigInteger BI_IMPLIED_FRAC_MSB = new BigInteger(4503599627370496L);

		private BigInteger _significand;

		private int _binaryExponent;

		private static BigInteger GetFrac(long rawBits)
		{
			return ((new BigInteger(rawBits) & BI_FRAC_MASK) | BI_IMPLIED_FRAC_MSB) << 11;
		}

		public static ExpandedDouble FromRawBitsAndExponent(long rawBits, int exp)
		{
			return new ExpandedDouble(GetFrac(rawBits), exp);
		}

		public ExpandedDouble(long rawBits)
		{
			int num = (int)(rawBits >> 52);
			if (num == 0)
			{
				BigInteger bigInteger = new BigInteger(rawBits) & BI_FRAC_MASK;
				int num2 = 64 - bigInteger.BitLength();
				_significand = bigInteger << num2;
				_binaryExponent = (num & 0x7FF) - 1023 - num2;
			}
			else
			{
				BigInteger frac = GetFrac(rawBits);
				_significand = frac;
				_binaryExponent = (num & 0x7FF) - 1023;
			}
		}

		public ExpandedDouble(BigInteger frac, int binaryExp)
		{
			if (frac.BitLength() != 64)
			{
				throw new ArgumentException("bad bit length");
			}
			_significand = frac;
			_binaryExponent = binaryExp;
		}

		public NormalisedDecimal NormaliseBaseTen()
		{
			return NormalisedDecimal.Create(_significand, _binaryExponent);
		}

		public int GetBinaryExponent()
		{
			return _binaryExponent;
		}

		public BigInteger GetSignificand()
		{
			return _significand;
		}
	}
