	public class MutableFPNumber
	{
		private class Rounder
		{
			private static BigInteger[] HALF_BITS;

			static Rounder()
			{
				BigInteger[] array = new BigInteger[33];
				long num = 1L;
				for (int i = 1; i < array.Length; i++)
				{
					array[i] = new BigInteger(num);
					num <<= 1;
				}
				HALF_BITS = array;
			}

			public static BigInteger Round(BigInteger bi, int nBits)
			{
				if (nBits < 1)
				{
					return bi;
				}
				return bi + HALF_BITS[nBits];
			}
		}

		private class TenPower
		{
			private static readonly BigInteger FIVE = new BigInteger(5L);

			private static TenPower[] _cache = new TenPower[350];

			public BigInteger _multiplicand;

			public BigInteger _divisor;

			public int _divisorShift;

			public int _multiplierShift;

			private TenPower(int index)
			{
				BigInteger bigInteger = FIVE.Pow(index);
				int num = bigInteger.BitLength();
				int num2 = 80 + num;
				BigInteger bigInteger2 = (BigInteger.One << num2) / bigInteger;
				int num3 = bigInteger2.BitLength() - 80;
				_divisor = bigInteger2 >> num3;
				num -= num3;
				_divisorShift = -(num + index + 80);
				int num4 = bigInteger.BitLength() - 68;
				if (num4 > 0)
				{
					_multiplierShift = index + num4;
					_multiplicand = bigInteger >> num4;
				}
				else
				{
					_multiplierShift = index;
					_multiplicand = bigInteger;
				}
			}

			public static TenPower GetInstance(int index)
			{
				TenPower tenPower = _cache[index];
				if (tenPower == null)
				{
					tenPower = new TenPower(index);
					_cache[index] = tenPower;
				}
				return tenPower;
			}
		}

		private const int C_64 = 64;

		private const int MIN_PRECISION = 72;

		private static readonly BigInteger BI_MIN_BASE = new BigInteger(new int[2] { -1243209484, 2147477094 }, 1);

		private static readonly BigInteger BI_MAX_BASE = new BigInteger(new int[2] { -480270031, -1610620928 }, 1);

		private BigInteger _significand;

		private int _binaryExponent;

		public MutableFPNumber(BigInteger frac, int binaryExponent)
		{
			_significand = frac;
			_binaryExponent = binaryExponent;
		}

		public MutableFPNumber Copy()
		{
			return new MutableFPNumber(_significand, _binaryExponent);
		}

		public void Normalise64bit()
		{
			int num = _significand.BitLength();
			int num2 = num - 64;
			if (num2 != 0)
			{
				if (num2 < 0)
				{
					throw new InvalidOperationException("Not enough precision");
				}
				_binaryExponent += num2;
				if (num2 > 32)
				{
					int num3 = (num2 - 1) & 0xFFFFE0;
					_significand >>= num3;
					num2 -= num3;
					num -= num3;
				}
				if (num2 < 1)
				{
					throw new InvalidOperationException();
				}
				_significand = Rounder.Round(_significand, num2);
				if (_significand.BitLength() > num)
				{
					num2++;
					_binaryExponent++;
				}
				_significand >>= num2;
			}
		}

		public int Get64BitNormalisedExponent()
		{
			return _binaryExponent + _significand.BitLength() - 64;
		}

		public bool IsBelowMaxRep()
		{
			int n = _significand.BitLength() - 64;
			return _significand.CompareTo(BI_MAX_BASE.ShiftLeft(n)) < 0;
		}

		public bool IsAboveMinRep()
		{
			int n = _significand.BitLength() - 64;
			return _significand.CompareTo(BI_MIN_BASE.ShiftLeft(n)) > 0;
		}

		public NormalisedDecimal CreateNormalisedDecimal(int pow10)
		{
			int num = _binaryExponent - 39;
			int fracPart = (_significand.IntValue() << num) & 0xFFFF80;
			long wholePart = (_significand >> 64 - _binaryExponent - 1).LongValue();
			return new NormalisedDecimal(wholePart, fracPart, pow10);
		}

		public void multiplyByPowerOfTen(int pow10)
		{
			TenPower instance = TenPower.GetInstance(Math.Abs(pow10));
			if (pow10 < 0)
			{
				mulShift(instance._divisor, instance._divisorShift);
			}
			else
			{
				mulShift(instance._multiplicand, instance._multiplierShift);
			}
		}

		private void mulShift(BigInteger multiplicand, int multiplierShift)
		{
			_significand *= multiplicand;
			_binaryExponent += multiplierShift;
			int num = (_significand.BitLength() - 72) & -32;
			if (num > 0)
			{
				_significand >>= num;
				_binaryExponent += num;
			}
		}

		public ExpandedDouble CreateExpandedDouble()
		{
			return new ExpandedDouble(_significand, _binaryExponent);
		}
	}
	public class NormalisedDecimal
	{
		private const int EXPONENT_OFFSET = 14;

		private const int LOG_BASE_10_OF_2_TIMES_2_POW_20 = 315653;

		private const int C_2_POW_19 = 524288;

		private const int FRAC_HALF = 8388608;

		private const long MAX_REP_WHOLE_PART = 1000000000000000L;

		private static readonly decimal BD_2_POW_24 = new decimal((BigInteger.One << 24).LongValue());

		private int _relativeDecimalExponent;

		private long _wholePart;

		private int _fractionalPart;

		public static NormalisedDecimal Create(BigInteger frac, int binaryExponent)
		{
			int num2;
			if (binaryExponent > 49 || binaryExponent < 46)
			{
				int num = 15204352 - binaryExponent * 315653;
				num += 524288;
				num2 = -(num >> 20);
			}
			else
			{
				num2 = 0;
			}
			MutableFPNumber mutableFPNumber = new MutableFPNumber(frac, binaryExponent);
			if (num2 != 0)
			{
				mutableFPNumber.multiplyByPowerOfTen(-num2);
			}
			switch (mutableFPNumber.Get64BitNormalisedExponent())
			{
			case 46:
				if (mutableFPNumber.IsAboveMinRep())
				{
					break;
				}
				goto case 44;
			case 44:
			case 45:
				mutableFPNumber.multiplyByPowerOfTen(1);
				num2--;
				break;
			case 49:
				if (mutableFPNumber.IsBelowMaxRep())
				{
					break;
				}
				goto case 50;
			case 50:
				mutableFPNumber.multiplyByPowerOfTen(-1);
				num2++;
				break;
			default:
				throw new InvalidOperationException("Bad binary exp " + mutableFPNumber.Get64BitNormalisedExponent() + ".");
			case 47:
			case 48:
				break;
			}
			mutableFPNumber.Normalise64bit();
			return mutableFPNumber.CreateNormalisedDecimal(num2);
		}

		public NormalisedDecimal RoundUnits()
		{
			long num = _wholePart;
			if (_fractionalPart >= 8388608)
			{
				num++;
			}
			int relativeDecimalExponent = _relativeDecimalExponent;
			if (num < 1000000000000000L)
			{
				return new NormalisedDecimal(num, 0, relativeDecimalExponent);
			}
			return new NormalisedDecimal(num / 10, 0, relativeDecimalExponent + 1);
		}

		public NormalisedDecimal(long wholePart, int fracPart, int decimalExponent)
		{
			_wholePart = wholePart;
			_fractionalPart = fracPart;
			_relativeDecimalExponent = decimalExponent;
		}

		public ExpandedDouble NormaliseBaseTwo()
		{
			MutableFPNumber mutableFPNumber = new MutableFPNumber(ComposeFrac(), 39);
			mutableFPNumber.multiplyByPowerOfTen(_relativeDecimalExponent);
			mutableFPNumber.Normalise64bit();
			return mutableFPNumber.CreateExpandedDouble();
		}

		public BigInteger ComposeFrac()
		{
			long wholePart = _wholePart;
			int fractionalPart = _fractionalPart;
			return new BigInteger(new byte[11]
			{
				(byte)(wholePart >> 56),
				(byte)(wholePart >> 48),
				(byte)(wholePart >> 40),
				(byte)(wholePart >> 32),
				(byte)(wholePart >> 24),
				(byte)(wholePart >> 16),
				(byte)(wholePart >> 8),
				(byte)wholePart,
				(byte)(fractionalPart >> 16),
				(byte)(fractionalPart >> 8),
				(byte)fractionalPart
			});
		}

		public string GetSignificantDecimalDigits()
		{
			return _wholePart.ToString(CultureInfo.InvariantCulture);
		}

		public string GetSignificantDecimalDigitsLastDigitRounded()
		{
			long value = _wholePart + 5;
			StringBuilder stringBuilder = new StringBuilder(24);
			stringBuilder.Append(value);
			stringBuilder[stringBuilder.Length - 1] = '0';
			return stringBuilder.ToString();
		}

		public int GetDecimalExponent()
		{
			return _relativeDecimalExponent + 14;
		}

		public int CompareNormalised(NormalisedDecimal other)
		{
			int num = _relativeDecimalExponent - other._relativeDecimalExponent;
			if (num != 0)
			{
				return num;
			}
			if (_wholePart > other._wholePart)
			{
				return 1;
			}
			if (_wholePart < other._wholePart)
			{
				return -1;
			}
			return _fractionalPart - other._fractionalPart;
		}

		public decimal GetFractionalPart()
		{
			return new decimal(_fractionalPart) / BD_2_POW_24;
		}

		private string GetFractionalDigits()
		{
			if (_fractionalPart == 0)
			{
				return "0";
			}
			return GetFractionalPart().ToString(CultureInfo.InvariantCulture).Substring(2);
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(GetType().Name);
			stringBuilder.Append(" [");
			string text = _wholePart.ToString(CultureInfo.InvariantCulture);
			stringBuilder.Append(text[0]);
			stringBuilder.Append('.');
			stringBuilder.Append(text.Substring(1));
			stringBuilder.Append(' ');
			stringBuilder.Append(GetFractionalDigits());
			stringBuilder.Append("E");
			stringBuilder.Append(GetDecimalExponent());
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}
	}
	public class NumberComparer
	{
		public static int Compare(double a, double b)
		{
			long num = BitConverter.DoubleToInt64Bits(a);
			long num2 = BitConverter.DoubleToInt64Bits(b);
			int biasedExponent = IEEEDouble.GetBiasedExponent(num);
			int biasedExponent2 = IEEEDouble.GetBiasedExponent(num2);
			if (biasedExponent == 2047)
			{
				throw new ArgumentException("Special double values are not allowed: " + ToHex(a));
			}
			if (biasedExponent2 == 2047)
			{
				throw new ArgumentException("Special double values are not allowed: " + ToHex(a));
			}
			bool flag = num < 0;
			bool flag2 = num2 < 0;
			if (flag != flag2)
			{
				if (!flag)
				{
					return 1;
				}
				return -1;
			}
			int num3 = biasedExponent - biasedExponent2;
			int num4 = Math.Abs(num3);
			if (num4 > 1)
			{
				if (!flag)
				{
					return num3;
				}
				return -num3;
			}
			if (num4 != 1 && num == num2)
			{
				return 0;
			}
			if (biasedExponent == 0)
			{
				if (biasedExponent2 == 0)
				{
					return CompareSubnormalNumbers(num & 0xFFFFFFFFFFFFFL, num2 & 0xFFFFFFFFFFFFFL, flag);
				}
				return -CompareAcrossSubnormalThreshold(num2, num, flag);
			}
			if (biasedExponent2 == 0)
			{
				return CompareAcrossSubnormalThreshold(num, num2, flag);
			}
			ExpandedDouble expandedDouble = ExpandedDouble.FromRawBitsAndExponent(num, biasedExponent - 1023);
			ExpandedDouble expandedDouble2 = ExpandedDouble.FromRawBitsAndExponent(num2, biasedExponent2 - 1023);
			NormalisedDecimal normalisedDecimal = expandedDouble.NormaliseBaseTen().RoundUnits();
			NormalisedDecimal other = expandedDouble2.NormaliseBaseTen().RoundUnits();
			num3 = normalisedDecimal.CompareNormalised(other);
			if (flag)
			{
				return -num3;
			}
			return num3;
		}

		private static int CompareSubnormalNumbers(long fracA, long fracB, bool isNegative)
		{
			int num = ((fracA > fracB) ? 1 : ((fracA < fracB) ? (-1) : 0));
			if (!isNegative)
			{
				return num;
			}
			return -num;
		}

		private static int CompareAcrossSubnormalThreshold(long normalRawBitsA, long subnormalRawBitsB, bool isNegative)
		{
			long num = subnormalRawBitsB & 0xFFFFFFFFFFFFFL;
			if (num == 0)
			{
				if (!isNegative)
				{
					return 1;
				}
				return -1;
			}
			long num2 = normalRawBitsA & 0xFFFFFFFFFFFFFL;
			if (num2 <= 7 && num >= 4503599627370490L)
			{
				if (num2 == 7 && num == 4503599627370490L)
				{
					return 0;
				}
				if (!isNegative)
				{
					return -1;
				}
				return 1;
			}
			if (!isNegative)
			{
				return 1;
			}
			return -1;
		}

		private static string ToHex(double a)
		{
			return "0x" + StringUtil.ToHexString(BitConverter.DoubleToInt64Bits(a)).ToUpper();
		}
	}
	public class NumberToTextConverter
	{
		private const long EXCEL_NAN_BITS = -276939487313920L;

		private const int MAX_TEXT_LEN = 20;

		private NumberToTextConverter()
		{
		}

		public static string ToText(double value)
		{
			return RawDoubleBitsToText(BitConverter.DoubleToInt64Bits(value));
		}

		public static string RawDoubleBitsToText(long pRawBits)
		{
			long num = pRawBits;
			bool flag = num < 0;
			if (flag)
			{
				num &= 0x7FFFFFFFFFFFFFFFL;
			}
			if (num == 0)
			{
				if (!flag)
				{
					return "0";
				}
				return "-0";
			}
			ExpandedDouble expandedDouble = new ExpandedDouble(num);
			if (expandedDouble.GetBinaryExponent() < -1022)
			{
				if (!flag)
				{
					return "0";
				}
				return "-0";
			}
			if (expandedDouble.GetBinaryExponent() == 1024)
			{
				if (num == -276939487313920L)
				{
					return "3.484840871308E+308";
				}
				flag = false;
			}
			NormalisedDecimal pnd = expandedDouble.NormaliseBaseTen();
			StringBuilder stringBuilder = new StringBuilder(21);
			if (flag)
			{
				stringBuilder.Append('-');
			}
			ConvertToText(stringBuilder, pnd);
			return stringBuilder.ToString();
		}

		private static void ConvertToText(StringBuilder sb, NormalisedDecimal pnd)
		{
			NormalisedDecimal normalisedDecimal = pnd.RoundUnits();
			int num = normalisedDecimal.GetDecimalExponent();
			string text;
			if (Math.Abs(num) > 98)
			{
				text = normalisedDecimal.GetSignificantDecimalDigitsLastDigitRounded();
				if (text.Length == 16)
				{
					num++;
				}
			}
			else
			{
				text = normalisedDecimal.GetSignificantDecimalDigits();
			}
			int countSigDigits = CountSignifantDigits(text);
			if (num < 0)
			{
				FormatLessThanOne(sb, text, num, countSigDigits);
			}
			else
			{
				FormatGreaterThanOne(sb, text, num, countSigDigits);
			}
		}

		private static void FormatLessThanOne(StringBuilder sb, string decimalDigits, int decExponent, int countSigDigits)
		{
			int num = -decExponent - 1;
			int nDigits = 2 + num + countSigDigits;
			if (NeedsScientificNotation(nDigits))
			{
				sb.Append(decimalDigits[0]);
				if (countSigDigits > 1)
				{
					sb.Append('.');
					sb.Append(decimalDigits.Substring(1, countSigDigits - 1));
				}
				sb.Append("E-");
				AppendExp(sb, -decExponent);
			}
			else
			{
				sb.Append("0.");
				for (int num2 = num; num2 > 0; num2--)
				{
					sb.Append('0');
				}
				sb.Append(decimalDigits.Substring(0, countSigDigits));
			}
		}

		private static void FormatGreaterThanOne(StringBuilder sb, string decimalDigits, int decExponent, int countSigDigits)
		{
			if (decExponent > 19)
			{
				sb.Append(decimalDigits[0]);
				if (countSigDigits > 1)
				{
					sb.Append('.');
					sb.Append(decimalDigits.Substring(1, countSigDigits - 1));
				}
				sb.Append("E+");
				AppendExp(sb, decExponent);
				return;
			}
			int num = countSigDigits - decExponent - 1;
			if (num > 0)
			{
				sb.Append(decimalDigits.Substring(0, decExponent + 1));
				sb.Append('.');
				sb.Append(decimalDigits.Substring(decExponent + 1, num));
				return;
			}
			sb.Append(decimalDigits.Substring(0, countSigDigits));
			for (int num2 = -num; num2 > 0; num2--)
			{
				sb.Append('0');
			}
		}

		private static bool NeedsScientificNotation(int nDigits)
		{
			return nDigits > 20;
		}

		private static int CountSignifantDigits(string sb)
		{
			int num = sb.Length - 1;
			while (sb[num] == '0')
			{
				num--;
				if (num < 0)
				{
					throw new Exception("No non-zero digits found");
				}
			}
			return num + 1;
		}

		private static void AppendExp(StringBuilder sb, int val)
		{
			if (val < 10)
			{
				sb.Append('0');
				sb.Append((char)(48 + val));
			}
			else
			{
				sb.Append(val);
			}
		}
	}
