		public static IRow CopyRow(ISheet sourceSheet, int sourceRowIndex, ISheet targetSheet, int targetRowIndex)
		{
			IRow row = targetSheet.GetRow(targetRowIndex);
			IRow row2 = sourceSheet.GetRow(sourceRowIndex);
			if (row != null)
			{
				targetSheet.RemoveRow(row);
			}
			row = targetSheet.CreateRow(targetRowIndex);
			if (row2 == null)
			{
				throw new ArgumentNullException("source row doesn't exist");
			}
			for (int i = row2.FirstCellNum; i < row2.LastCellNum; i++)
			{
				ICell cell = row2.GetCell(i);
				if (cell != null)
				{
					ICell cell2 = row.CreateCell(i);
					if (cell.CellStyle != null)
					{
						cell2.CellStyle = cell.CellStyle;
					}
					if (cell.CellComment != null)
					{
						cell2.CellComment = cell.CellComment;
					}
					if (cell.Hyperlink != null)
					{
						cell2.Hyperlink = cell.Hyperlink;
					}
					cell2.SetCellType(cell.CellType);
					switch (cell.CellType)
					{
					case CellType.Blank:
						cell2.SetCellValue(cell.StringCellValue);
						break;
					case CellType.Boolean:
						cell2.SetCellValue(cell.BooleanCellValue);
						break;
					case CellType.Error:
						cell2.SetCellErrorValue(cell.ErrorCellValue);
						break;
					case CellType.Formula:
						cell2.SetCellFormula(cell.CellFormula);
						break;
					case CellType.Numeric:
						cell2.SetCellValue(cell.NumericCellValue);
						break;
					case CellType.String:
						cell2.SetCellValue(cell.RichStringCellValue);
						break;
					}
				}
			}
			for (int j = 0; j < sourceSheet.NumMergedRegions; j++)
			{
				CellRangeAddress mergedRegion = sourceSheet.GetMergedRegion(j);
				if (mergedRegion.FirstRow == row2.RowNum)
				{
					CellRangeAddress region = new CellRangeAddress(row.RowNum, row.RowNum + (mergedRegion.LastRow - mergedRegion.FirstRow), mergedRegion.FirstColumn, mergedRegion.LastColumn);
					targetSheet.AddMergedRegion(region);
				}
			}
			return row;
		}

		public static IRow CopyRow(ISheet sheet, int sourceRowIndex, int targetRowIndex)
		{
			if (sourceRowIndex == targetRowIndex)
			{
				throw new ArgumentException("sourceIndex and targetIndex cannot be same");
			}
			IRow row = sheet.GetRow(targetRowIndex);
			IRow row2 = sheet.GetRow(sourceRowIndex);
			if (row != null)
			{
				sheet.ShiftRows(targetRowIndex, sheet.LastRowNum, 1);
			}
			else
			{
				row = sheet.CreateRow(targetRowIndex);
			}
			for (int i = row2.FirstCellNum; i < row2.LastCellNum; i++)
			{
				ICell cell = row2.GetCell(i);
				if (cell != null)
				{
					ICell cell2 = row.CreateCell(i);
					if (cell.CellStyle != null)
					{
						cell2.CellStyle = cell.CellStyle;
					}
					if (cell.CellComment != null)
					{
						cell2.CellComment = cell.CellComment;
					}
					if (cell.Hyperlink != null)
					{
						cell2.Hyperlink = cell.Hyperlink;
					}
					cell2.SetCellType(cell.CellType);
					switch (cell.CellType)
					{
					case CellType.Blank:
						cell2.SetCellValue(cell.StringCellValue);
						break;
					case CellType.Boolean:
						cell2.SetCellValue(cell.BooleanCellValue);
						break;
					case CellType.Error:
						cell2.SetCellErrorValue(cell.ErrorCellValue);
						break;
					case CellType.Formula:
						cell2.SetCellFormula(cell.CellFormula);
						break;
					case CellType.Numeric:
						cell2.SetCellValue(cell.NumericCellValue);
						break;
					case CellType.String:
						cell2.SetCellValue(cell.RichStringCellValue);
						break;
					}
				}
			}
			for (int j = 0; j < sheet.NumMergedRegions; j++)
			{
				CellRangeAddress mergedRegion = sheet.GetMergedRegion(j);
				if (mergedRegion.FirstRow == row2.RowNum)
				{
					CellRangeAddress region = new CellRangeAddress(row.RowNum, row.RowNum + (mergedRegion.LastRow - mergedRegion.FirstRow), mergedRegion.FirstColumn, mergedRegion.LastColumn);
					sheet.AddMergedRegion(region);
				}
			}
			return row;
		}

		public static double GetCellWidth(ICell cell, int defaultCharWidth, DataFormatter formatter, bool useMergedCells)
		{
			//IL_00c8: Unknown result type (might be due to invalid IL or missing references)
			//IL_00cf: Expected O, but got Unknown
			ISheet sheet = cell.Sheet;
			IWorkbook workbook = sheet.Workbook;
			IRow row = cell.Row;
			int columnIndex = cell.ColumnIndex;
			int num = 1;
			for (int i = 0; i < sheet.NumMergedRegions; i++)
			{
				CellRangeAddress mergedRegion = sheet.GetMergedRegion(i);
				if (ContainsCell(mergedRegion, row.RowNum, columnIndex))
				{
					if (!useMergedCells)
					{
						return -1.0;
					}
					cell = row.GetCell(mergedRegion.FirstColumn);
					num = 1 + mergedRegion.LastColumn - mergedRegion.FirstColumn;
				}
			}
			ICellStyle cellStyle = cell.CellStyle;
			CellType cellType = cell.CellType;
			IFont fontAt = workbook.GetFontAt(0);
			Font val = IFont2Font(fontAt);
			if (cellType == CellType.Formula)
			{
				cellType = cell.CachedFormulaResultType;
			}
			IFont fontAt2 = workbook.GetFontAt(cellStyle.FontIndex);
			double num2 = -1.0;
			Bitmap val2 = new Bitmap(1, 1);
			try
			{
				Graphics val3 = Graphics.FromImage((Image)(object)val2);
				try
				{
					if (cellType == CellType.String)
					{
						IRichTextString richStringCellValue = cell.RichStringCellValue;
						string[] array = richStringCellValue.String.Split("\n".ToCharArray());
						for (int j = 0; j < array.Length; j++)
						{
							string text = array[j] + defaultChar;
							val = IFont2Font(fontAt2);
							_ = richStringCellValue.NumFormattingRuns;
							_ = 0;
							if (cellStyle.Rotation != 0)
							{
								double num3 = (double)cellStyle.Rotation * 2.0 * Math.PI / 360.0;
								SizeF sizeF = val3.MeasureString(text, val);
								double num4 = Math.Abs((double)sizeF.Height * Math.Sin(num3));
								double num5 = Math.Abs((double)sizeF.Width * Math.Cos(num3));
								double num6 = Math.Round(num4 + num5, 0, MidpointRounding.ToEven);
								num2 = Math.Max(num2, num6 / (double)num / (double)defaultCharWidth * 2.0 + (double)cell.CellStyle.Indention);
							}
							else
							{
								double num7 = Math.Round(val3.MeasureString(text, val).Width, 0, MidpointRounding.ToEven);
								num2 = Math.Max(num2, num7 / (double)num / (double)defaultCharWidth * 2.0 + (double)cell.CellStyle.Indention);
							}
						}
					}
					else
					{
						string text2 = null;
						switch (cellType)
						{
						case CellType.Numeric:
							try
							{
								text2 = formatter.FormatCellValue(cell, dummyEvaluator);
							}
							catch (Exception)
							{
								text2 = cell.NumericCellValue.ToString();
							}
							break;
						case CellType.Boolean:
							text2 = cell.BooleanCellValue.ToString().ToUpper();
							break;
						}
						if (text2 != null)
						{
							string text3 = text2 + defaultChar;
							val = IFont2Font(fontAt2);
							if (cellStyle.Rotation != 0)
							{
								double num8 = (double)cellStyle.Rotation * 2.0 * Math.PI / 360.0;
								SizeF sizeF2 = val3.MeasureString(text3, val);
								double num9 = (double)sizeF2.Height * Math.Sin(num8);
								double num10 = (double)sizeF2.Width * Math.Cos(num8);
								double num11 = Math.Round(num9 + num10, 0, MidpointRounding.ToEven);
								num2 = Math.Max(num2, num11 / (double)num / (double)defaultCharWidth * 2.0 + (double)cell.CellStyle.Indention);
							}
							else
							{
								double num12 = Math.Round(val3.MeasureString(text3, val).Width, 0, MidpointRounding.ToEven);
								num2 = Math.Max(num2, num12 * 1.0 / (double)num / (double)defaultCharWidth * 2.0 + (double)cell.CellStyle.Indention);
							}
						}
					}
				}
				finally
				{
					((IDisposable)val3)?.Dispose();
				}
			}
			finally
			{
				((IDisposable)val2)?.Dispose();
			}
			return num2;
		}

		public static double GetColumnWidth(ISheet sheet, int column, bool useMergedCells)
		{
			IWorkbook workbook = sheet.Workbook;
			DataFormatter formatter = new DataFormatter();
			IFont fontAt = workbook.GetFontAt(0);
			Font val = IFont2Font(fontAt);
			int width = TextRenderer.MeasureText(new string(defaultChar, 1) ?? "", val).Width;
			double num = -1.0;
			foreach (IRow item in sheet)
			{
				ICell cell = item.GetCell(column);
				if (cell != null)
				{
					double cellWidth = GetCellWidth(cell, width, formatter, useMergedCells);
					num = Math.Max(num, cellWidth);
				}
			}
			return num;
		}

		public static double GetColumnWidth(ISheet sheet, int column, bool useMergedCells, int firstRow, int lastRow)
		{
			IWorkbook workbook = sheet.Workbook;
			DataFormatter formatter = new DataFormatter();
			IFont fontAt = workbook.GetFontAt(0);
			Font val = IFont2Font(fontAt);
			int width = TextRenderer.MeasureText(new string(defaultChar, 1) ?? "", val).Width;
			double num = -1.0;
			for (int i = firstRow; i <= lastRow; i++)
			{
				IRow row = sheet.GetRow(i);
				if (row != null)
				{
					ICell cell = row.GetCell(column);
					if (cell != null)
					{
						double cellWidth = GetCellWidth(cell, width, formatter, useMergedCells);
						num = Math.Max(num, cellWidth);
					}
				}
			}
			return num;
		}

		internal static Font IFont2Font(IFont font1)
		{
			//IL_0001: Unknown result type (might be due to invalid IL or missing references)
			//IL_000f: Unknown result type (might be due to invalid IL or missing references)
			//IL_0011: Unknown result type (might be due to invalid IL or missing references)
			//IL_0012: Unknown result type (might be due to invalid IL or missing references)
			//IL_001b: Unknown result type (might be due to invalid IL or missing references)
			//IL_001d: Unknown result type (might be due to invalid IL or missing references)
			//IL_001e: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Unknown result type (might be due to invalid IL or missing references)
			//IL_003b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0041: Expected O, but got Unknown
			//IL_0028: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_002b: Unknown result type (might be due to invalid IL or missing references)
			FontStyle val = (FontStyle)0;
			if (font1.Boldweight == 700)
			{
				val = (FontStyle)(val | 1);
			}
			if (font1.IsItalic)
			{
				val = (FontStyle)(val | 2);
			}
			if (font1.Underline == FontUnderlineType.Single)
			{
				val = (FontStyle)(val | 4);
			}
			return new Font(font1.FontName, (float)font1.FontHeightInPoints, val, (GraphicsUnit)3);
		}

		public static bool ContainsCell(CellRangeAddress cr, int rowIx, int colIx)
		{
			if (cr.FirstRow <= rowIx && cr.LastRow >= rowIx && cr.FirstColumn <= colIx && cr.LastColumn >= colIx)
			{
				return true;
			}
			return false;
		}

		public static string GetUniqueSheetName(IWorkbook wb, string srcName)
		{
			if (wb.GetSheetIndex(srcName) == -1)
			{
				return srcName;
			}
			int num = 2;
			string text = srcName;
			int num2 = srcName.LastIndexOf('(');
			if (num2 > 0 && srcName.EndsWith(")"))
			{
				string text2 = srcName.Substring(num2 + 1, srcName.Length - num2 - 2);
				try
				{
					num = int.Parse(text2.Trim());
					num++;
					text = srcName.Substring(0, num2).Trim();
				}
				catch (FormatException)
				{
				}
			}
			string text4;
			do
			{
				string text3 = num++.ToString();
				text4 = ((text.Length + text3.Length + 2 >= 31) ? (text.Substring(0, 31 - text3.Length - 2) + "(" + text3 + ")") : (text + " (" + text3 + ")"));
			}
			while (wb.GetSheetIndex(text4) != -1);
			return text4;
		}

		public static ICell GetCellWithMerges(ISheet sheet, int rowIx, int colIx)
		{
			IRow row = sheet.GetRow(rowIx);
			if (row != null)
			{
				ICell cell = row.GetCell(colIx);
				if (cell != null)
				{
					return cell;
				}
			}
			for (int i = 0; i < sheet.NumMergedRegions; i++)
			{
				CellRangeAddress mergedRegion = sheet.GetMergedRegion(i);
				if (mergedRegion.IsInRange(rowIx, colIx))
				{
					row = sheet.GetRow(mergedRegion.FirstRow);
					if (row != null)
					{
						return row.GetCell(mergedRegion.FirstColumn);
					}
				}
			}
			return null;
		}
	}
	public class SSCellRange<K> : ICellRange<K>, IEnumerable<K>, IEnumerable where K : ICell
	{
		internal class ArrayIterator<D> : IEnumerator<D>, IDisposable, IEnumerator
		{
			private D[] _array;

			private int _index;

			public D Current
			{
				get
				{
					if (_index >= _array.Length)
					{
						throw new ArgumentNullException(_index.ToString(CultureInfo.CurrentCulture));
					}
					return _array[_index++];
				}
			}

			object IEnumerator.Current => Current;

			public ArrayIterator(D[] array)
			{
				_array = array;
				_index = 0;
			}

			public bool MoveNext()
			{
				return _index < _array.Length;
			}

			public void Remove()
			{
				throw new NotSupportedException("Cannot remove cells from this CellRange.");
			}

			public void Reset()
			{
			}

			public void Dispose()
			{
			}
		}

		private int _height;

		private int _width;

		private K[] _flattenedArray;

		private int _firstRow;

		private int _firstColumn;

		public K TopLeftCell => _flattenedArray[0];

		public K[] FlattenedCells => (K[])_flattenedArray.Clone();

		public K[][] Cells
		{
			get
			{
				Type type = _flattenedArray.GetType();
				K[][] result = (K[][])System.Array.CreateInstance(type, _height);
				type = type.GetElementType();
				for (int num = _height - 1; num >= 0; num--)
				{
					K[] destinationArray = (K[])System.Array.CreateInstance(type, _width);
					int sourceIndex = _width * num;
					System.Array.Copy(_flattenedArray, sourceIndex, destinationArray, 0, _width);
				}
				return result;
			}
		}

		public int Height => _height;

		public int Width => _width;

		public int Size => _height * _width;

		public string ReferenceText
		{
			get
			{
				CellRangeAddress cellRangeAddress = new CellRangeAddress(_firstRow, _firstRow + _height - 1, _firstColumn, _firstColumn + _width - 1);
				return cellRangeAddress.FormatAsString();
			}
		}

		private SSCellRange(int firstRow, int firstColumn, int height, int width, K[] flattenedArray)
		{
			_firstRow = firstRow;
			_firstColumn = firstColumn;
			_height = height;
			_width = width;
			_flattenedArray = flattenedArray;
		}

		public static SSCellRange<K> Create(int firstRow, int firstColumn, int height, int width, List<K> flattenedList, Type cellClass)
		{
			int count = flattenedList.Count;
			if (height * width != count)
			{
				throw new ArgumentException("Array size mismatch.");
			}
			K[] array = (K[])System.Array.CreateInstance(cellClass, count);
			array = flattenedList.ToArray();
			return new SSCellRange<K>(firstRow, firstColumn, height, width, array);
		}

		public K GetCell(int relativeRowIndex, int relativeColumnIndex)
		{
			if (relativeRowIndex < 0 || relativeRowIndex >= _height)
			{
				throw new IndexOutOfRangeException("Specified row " + relativeRowIndex + " is outside the allowable range (0.." + (_height - 1) + ").");
			}
			if (relativeColumnIndex < 0 || relativeColumnIndex >= _width)
			{
				throw new IndexOutOfRangeException("Specified colummn " + relativeColumnIndex + " is outside the allowable range (0.." + (_width - 1) + ").");
			}
			int num = _width * relativeRowIndex + relativeColumnIndex;
			return _flattenedArray[num];
		}

		public IEnumerator<K> GetEnumerator()
		{
			return new ArrayIterator<K>(_flattenedArray);
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			throw new NotImplementedException();
		}
	}
	public class WorkbookUtil
	{
		public static string CreateSafeSheetName(string nameProposal)
		{
			return CreateSafeSheetName(nameProposal, ' ');
		}

		public static string CreateSafeSheetName(string nameProposal, char replaceChar)
		{
			if (nameProposal == null)
			{
				return "null";
			}
			if (nameProposal.Length < 1)
			{
				return "empty";
			}
			int num = Math.Min(31, nameProposal.Length);
			string value = nameProposal.Substring(0, num);
			StringBuilder stringBuilder = new StringBuilder(value);
			for (int i = 0; i < num; i++)
			{
				switch (stringBuilder[i])
				{
				case '\0':
				case '\u0003':
				case '*':
				case '/':
				case ':':
				case '?':
				case '[':
				case '\\':
				case ']':
					stringBuilder[i] = replaceChar;
					break;
				case '\'':
					if (i == 0 || i == num - 1)
					{
						stringBuilder[i] = replaceChar;
					}
					break;
				}
			}
			return stringBuilder.ToString();
		}

		public static void ValidateSheetName(string sheetName)
		{
			if (sheetName == null)
			{
				throw new ArgumentException("sheetName must not be null");
			}
			int length = sheetName.Length;
			if (length < 1 || length > 31)
			{
				throw new ArgumentException("sheetName '" + sheetName + "' is invalid - character count MUST be greater than or equal to 1 and less than or equal to 31");
			}
			for (int i = 0; i < length; i++)
			{
				char c = sheetName[i];
				switch (c)
				{
				case '*':
				case '/':
				case ':':
				case '?':
				case '[':
				case '\\':
				case ']':
					throw new ArgumentException("Invalid char (" + c + ") found at index (" + i + ") in sheet name '" + sheetName + "'");
				}
			}
			if (sheetName[0] == '\'' || sheetName[length - 1] == '\'')
			{
				throw new ArgumentException("Invalid sheet name '" + sheetName + "'. Sheet names must not begin or end with (').");
			}
		}

		public static void ValidateSheetState(SheetState state)
		{
			switch (state)
			{
			case SheetState.Visible:
			case SheetState.Hidden:
			case SheetState.VeryHidden:
				return;
			}
			throw new ArgumentException(string.Concat("Ivalid sheet state : ", state, "\nSheet state must beone of the Workbook.SHEET_STATE_* constants"));
		}
	}
