	[Serializable]
	public class BitField
	{
		private int _mask;

		private int _shift_count;

		public BitField(int mask)
		{
			_mask = mask;
			int num = 0;
			int num2 = mask;
			if (num2 != 0)
			{
				while ((num2 & 1) == 0)
				{
					num++;
					num2 >>= 1;
				}
			}
			_shift_count = num;
		}

		public BitField(uint mask)
			: this((int)mask)
		{
		}

		public int Clear(int holder)
		{
			return holder & ~_mask;
		}

		public short ClearShort(short holder)
		{
			return (short)Clear(holder);
		}

		public int GetRawValue(int holder)
		{
			return holder & _mask;
		}

		public short GetShortRawValue(short holder)
		{
			return (short)GetRawValue(holder);
		}

		public short GetShortValue(short holder)
		{
			return (short)GetValue(holder);
		}

		public int GetValue(int holder)
		{
			return Operator.UnsignedRightShift(GetRawValue(holder), _shift_count);
		}

		public bool IsAllSet(int holder)
		{
			return (holder & _mask) == _mask;
		}

		public bool IsSet(int holder)
		{
			return (holder & _mask) != 0;
		}

		public int Set(int holder)
		{
			return holder | _mask;
		}

		public int SetBoolean(int holder, bool flag)
		{
			if (flag)
			{
				return Set(holder);
			}
			return Clear(holder);
		}

		public short SetShort(short holder)
		{
			return (short)Set(holder);
		}

		public short SetShortBoolean(short holder, bool flag)
		{
			if (flag)
			{
				return SetShort(holder);
			}
			return ClearShort(holder);
		}

		public short SetShortValue(short holder, short value)
		{
			return (short)SetValue(holder, value);
		}

		public int SetValue(int holder, int value)
		{
			return (holder & ~_mask) | ((value << _shift_count) & _mask);
		}

		public byte SetByteBoolean(byte holder, bool flag)
		{
			if (flag)
			{
				return SetByte(holder);
			}
			return ClearByte(holder);
		}

		public byte ClearByte(byte holder)
		{
			return (byte)Clear(holder);
		}

		public byte SetByte(byte holder)
		{
			return (byte)Set(holder);
		}
	}
	public class BitFieldFactory
	{
		private static Hashtable instances = new Hashtable();

		public static BitField GetInstance(int mask)
		{
			BitField bitField = (BitField)instances[mask];
			if (bitField == null)
			{
				bitField = new BitField(mask);
				instances[mask] = bitField;
			}
			return bitField;
		}
	}
	public interface FixedField
	{
		void ReadFromBytes(byte[] data);

		void ReadFromStream(Stream stream);

		new string ToString();

		void WriteToBytes(byte[] data);
	}
	public class ByteField : FixedField
	{
		private const byte _default_value = 0;

		private int _offset;

		private byte _value;

		public virtual byte Value
		{
			get
			{
				return _value;
			}
			set
			{
				_value = value;
			}
		}

		public ByteField(int offset)
			: this(offset, 0)
		{
		}

		public ByteField(int offset, byte value)
		{
			if (offset < 0)
			{
				throw new IndexOutOfRangeException("offset cannot be negative");
			}
			_offset = offset;
			Value = value;
		}

		public ByteField(int offset, byte[] data)
			: this(offset)
		{
			ReadFromBytes(data);
		}

		public ByteField(int offset, byte _value, byte[] data)
			: this(offset, _value)
		{
			WriteToBytes(data);
		}

		public virtual void ReadFromBytes(byte[] data)
		{
			_value = data[_offset];
		}

		public virtual void ReadFromStream(Stream stream)
		{
			int num = stream.ReadByte();
			if (num < 0)
			{
				throw new BufferUnderflowException();
			}
			_value = (byte)num;
		}

		public virtual void Set(byte value, byte[] data)
		{
			Value = value;
			WriteToBytes(data);
		}

		public override string ToString()
		{
			return Convert.ToString(_value, CultureInfo.CurrentCulture);
		}

		public virtual void WriteToBytes(byte[] data)
		{
			data[_offset] = _value;
		}
	}
	public class Character
	{
		public static int GetNumericValue(char src)
		{
			if (src >= '0' && src <= '9')
			{
				return src;
			}
			if (src >= 'A' && src <= 'Z')
			{
				return src - 55;
			}
			if (src >= 'a' && src <= 'z')
			{
				return src - 87;
			}
			return -1;
		}
	}
	public class CodePageUtil
	{
		public const int CP_037 = 37;

