		public void Load(Stream inStream)
		{
			StreamReader streamReader = new StreamReader(inStream, Encoding.GetEncoding(1252));
			while (true)
			{
				string text = streamReader.ReadLine();
				if (text == null)
				{
					break;
				}
				if (text.Length <= 0)
				{
					continue;
				}
				int length = text.Length;
				int i;
				for (i = 0; i < length && " \t\r\n\f".IndexOf(text[i]) != -1; i++)
				{
				}
				if (i == length)
				{
					continue;
				}
				char c = text[i];
				if (c == '#' || c == '!')
				{
					continue;
				}
				while (ContinueLine(text))
				{
					string text2 = streamReader.ReadLine();
					if (text2 == null)
					{
						text2 = "";
					}
					string text3 = text.Substring(0, length - 1);
					int j;
					for (j = 0; j < text2.Length && " \t\r\n\f".IndexOf(text2[j]) != -1; j++)
					{
					}
					text2 = text2.Substring(j, text2.Length - j);
					text = text3 + text2;
					length = text.Length;
				}
				int k;
				for (k = i; k < length; k++)
				{
					char c2 = text[k];
					if (c2 == '\\')
					{
						k++;
					}
					else if ("=: \t\r\n\f".IndexOf(c2) != -1)
					{
						break;
					}
				}
				int l;
				for (l = k; l < length && " \t\r\n\f".IndexOf(text[l]) != -1; l++)
				{
				}
				if (l < length && "=:".IndexOf(text[l]) != -1)
				{
					l++;
				}
				for (; l < length && " \t\r\n\f".IndexOf(text[l]) != -1; l++)
				{
				}
				string theString = text.Substring(i, k - i);
				string theString2 = ((k < length) ? text.Substring(l, length - l) : "");
				theString = LoadConvert(theString);
				theString2 = LoadConvert(theString2);
				Add(theString, theString2);
			}
		}

		private string LoadConvert(string theString)
		{
			int length = theString.Length;
			StringBuilder stringBuilder = new StringBuilder(length);
			int num = 0;
			while (num < length)
			{
				char c = theString[num++];
				if (c == '\\')
				{
					c = theString[num++];
					switch (c)
					{
					case 'u':
					{
						int num2 = 0;
						for (int i = 0; i < 4; i++)
						{
							c = theString[num++];
							switch (c)
							{
							case '0':
							case '1':
							case '2':
							case '3':
							case '4':
							case '5':
							case '6':
							case '7':
							case '8':
							case '9':
								num2 = (num2 << 4) + c - 48;
								break;
							case 'a':
							case 'b':
							case 'c':
							case 'd':
							case 'e':
							case 'f':
								num2 = (num2 << 4) + 10 + c - 97;
								break;
							case 'A':
							case 'B':
							case 'C':
							case 'D':
							case 'E':
							case 'F':
								num2 = (num2 << 4) + 10 + c - 65;
								break;
							default:
								throw new ArgumentException("Malformed \\uxxxx encoding.");
							}
						}
						stringBuilder.Append((char)num2);
						continue;
					}
					case 't':
						c = '\t';
						break;
					case 'r':
						c = '\r';
						break;
					case 'n':
						c = '\n';
						break;
					case 'f':
						c = '\f';
						break;
					}
					stringBuilder.Append(c);
				}
				else
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}

		private bool ContinueLine(string line)
		{
			int num = 0;
			int num2 = line.Length - 1;
			while (num2 >= 0 && line[num2--] == '\\')
			{
				num++;
			}
			return num % 2 == 1;
		}
	}
	public class StringTokenizer
	{
		private int pos;

		private string str;

		private int len;

		private string delim;

		private bool retDelims;

		public StringTokenizer(string str)
			: this(str, " \t\n\r\f", retDelims: false)
		{
		}

		public StringTokenizer(string str, string delim)
			: this(str, delim, retDelims: false)
		{
		}

		public StringTokenizer(string str, string delim, bool retDelims)
		{
			len = str.Length;
			this.str = str;
			this.delim = delim;
			this.retDelims = retDelims;
			pos = 0;
		}

		public bool HasMoreTokens()
		{
			if (!retDelims)
			{
				while (pos < len && delim.IndexOf(str[pos]) >= 0)
				{
					pos++;
				}
			}
			return pos < len;
		}

		public string NextToken(string delim)
		{
			this.delim = delim;
			return NextToken();
		}

		public string NextToken()
		{
			if (pos < len && delim.IndexOf(str[pos]) >= 0)
			{
				if (retDelims)
				{
					return str.Substring(pos++, 1);
				}
				while (++pos < len && delim.IndexOf(str[pos]) >= 0)
				{
				}
			}
			if (pos < len)
			{
				int num = pos;
				while (++pos < len && delim.IndexOf(str[pos]) < 0)
				{
				}
				return str.Substring(num, pos - num);
			}
			throw new IndexOutOfRangeException();
		}

		public int CountTokens()
		{
			int num = 0;
			int num2 = 0;
			bool flag = false;
			int i = pos;
			while (i < len)
			{
				if (delim.IndexOf(str[i++]) >= 0)
				{
					if (flag)
					{
						num++;
						flag = false;
					}
					num2++;
				}
				else
				{
					flag = true;
					for (; i < len && delim.IndexOf(str[i]) < 0; i++)
					{
					}
				}
			}
			if (flag)
			{
				num++;
			}
			if (!retDelims)
			{
				return num;
			}
			return num + num2;
		}
	}
