			while ((num2 = src.ReadByte()) != -1)
			{
				for (int num3 = 1; num3 < 256; num3 <<= 1)
				{
					bool flag = (num2 & num3) > 0;
					if (flag ^ maskMeansCompressed)
					{
						int b;
