	public class Number
	{
		private static Type BoolType = typeof(bool);

		private static Type CharType = typeof(char);

		private static Type IntPtrType = typeof(IntPtr);

		private static Type UIntPtrType = typeof(UIntPtr);

		private static Type DecimalType = typeof(decimal);

		public static bool IsNumber(object value)
		{
			if (value == null)
			{
				return false;
			}
			Type type = value.GetType();
			if (type.IsPrimitive || type == DecimalType)
			{
				if (type != BoolType && type != CharType && type != IntPtrType)
				{
					return type != UIntPtrType;
				}
				return false;
			}
			return false;
		}

		public static bool IsInteger(object value)
		{
			if (value == null)
			{
				return false;
			}
			if (value is int)
			{
				return true;
			}
			if (value is uint)
			{
				return true;
			}
			if (value is long)
			{
				return true;
			}
			if (value is ulong)
			{
				return true;
			}
			if (value is sbyte)
			{
				return true;
			}
			if (value is byte)
			{
				return true;
			}
			if (value is short)
			{
				return true;
			}
			if (value is ushort)
			{
				return true;
			}
			return false;
		}
	}
	public static class Operator
	{
		public static int UnsignedRightShift(int operand, int val)
		{
			if (operand > 0)
			{
				return operand >> val;
			}
			return operand >>> val;
		}

		public static long UnsignedRightShift(long operand, int val)
		{
			if (operand > 0)
			{
				return operand >> val;
			}
			return operand >>> val;
		}

		public static short UnsignedRightShift(short operand, int val)
		{
			if (operand > 0)
			{
				return (short)(operand >> val);
			}
			return (short)((ushort)operand >> val);
		}

		public static sbyte UnsignedRightShift(sbyte operand, int val)
		{
			if (operand > 0)
			{
				return (sbyte)(operand >> val);
			}
			return (sbyte)((byte)operand >> val);
		}
	}
	public class PngUtils
	{
		private static byte[] PNG_FILE_HEADER = new byte[8] { 137, 80, 78, 71, 13, 10, 26, 10 };

		private PngUtils()
		{
		}

		public static bool MatchesPngHeader(byte[] data, int offset)
		{
			if (data == null || data.Length - offset < PNG_FILE_HEADER.Length)
			{
				return false;
			}
			for (int i = 0; i < PNG_FILE_HEADER.Length; i++)
			{
				if (PNG_FILE_HEADER[i] != data[i + offset])
				{
					return false;
				}
			}
			return true;
		}
	}
	public class POILogFactory
	{
		private static Hashtable _loggers = new Hashtable();

		private static POILogger _nullLogger = new NullLogger();

		private static string _loggerClassName = null;

		private POILogFactory()
		{
		}

		public static POILogger GetLogger(Type type)
		{
			return GetLogger(type.Name);
		}

		public static POILogger GetLogger(string cat)
		{
			POILogger pOILogger = null;
			if (_loggerClassName == null)
			{
				try
				{
					_loggerClassName = ConfigurationManager.AppSettings["loggername"];
				}
				catch (Exception)
				{
				}
				if (_loggerClassName == null)
				{
					_loggerClassName = _nullLogger.GetType().Name;
				}
			}
			if (_loggerClassName.Equals(_nullLogger.GetType().Name))
			{
				return _nullLogger;
			}
			if (_loggers.ContainsKey(cat))
			{
				pOILogger = (POILogger)_loggers[cat];
			}
			else
			{
				try
				{
					Type type = Type.GetType(_loggerClassName);
					pOILogger = Activator.CreateInstance(type) as POILogger;
					pOILogger.Initialize(cat);
				}
				catch (Exception)
				{
					pOILogger = _nullLogger;
				}
				_loggers[cat] = pOILogger;
			}
			return pOILogger;
		}
	}
	public class PushbackStream : Stream
	{
		private int buf = -1;

		private Stream s;

		public override bool CanRead => s.CanRead;

		public override bool CanSeek => s.CanSeek;

		public override bool CanWrite => s.CanWrite;

		public override long Length => s.Length;

		public override long Position
		{
			get
			{
				return s.Position;
			}
			set
			{
				s.Position = value;
			}
		}

		public PushbackStream(Stream s)
		{
			this.s = s;
		}

		protected override void Dispose(bool disposing)
		{
			s = null;
			base.Dispose(disposing);
		}

		public override int ReadByte()
		{
			if (buf != -1)
			{
				int result = buf;
				buf = -1;
				return result;
			}
			return s.ReadByte();
		}

		public override int Read(byte[] buffer, int offset, int count)
		{
			if (buf != -1 && count > 0)
			{
				buffer[offset] = (byte)buf;
				buf = -1;
				return 1;
			}
			return s.Read(buffer, offset, count);
		}

		public virtual void Unread(int b)
		{
			if (buf != -1)
			{
				throw new InvalidOperationException("Can only push back one byte");
			}
			buf = b & 0xFF;
			s.Position -= b;
		}

		public override void Close()
		{
			s.Close();
		}

		public override void Flush()
		{
			s.Flush();
		}

		public override long Seek(long offset, SeekOrigin origin)
		{
			return s.Seek(offset, origin);
		}

		public override void SetLength(long value)
		{
			s.SetLength(value);
		}

		public override void Write(byte[] buffer, int offset, int count)
		{
			s.Write(buffer, offset, count);
		}

		public override void WriteByte(byte value)
		{
			s.WriteByte(value);
		}
	}
	public class ShortField
	{
		private short _value;

		private int _offset;

		public short Value
		{
			get
			{
				return _value;
			}
			set
			{
				_value = value;
			}
		}

		public ShortField(int offset)
		{
			if (offset < 0)
			{
				throw new IndexOutOfRangeException("Illegal offset: " + offset);
			}
			_offset = offset;
		}

		public ShortField(int offset, short value)
			: this(offset)
		{
			_value = value;
		}

		public ShortField(int offset, byte[] data)
			: this(offset)
		{
			ReadFromBytes(data);
		}

		public ShortField(int offset, short value, ref byte[] data)
			: this(offset)
		{
			Set(value, ref data);
		}

		public void Set(short value, ref byte[] data)
		{
			_value = value;
			WriteToBytes(data);
		}

		public void ReadFromBytes(byte[] data)
		{
			_value = LittleEndian.GetShort(data, _offset);
		}

		public void ReadFromStream(Stream stream)
		{
			_value = LittleEndian.ReadShort(stream);
		}

		public void WriteToBytes(byte[] data)
		{
			LittleEndian.PutShort(data, _offset, _value);
		}

		public static void Write(int offset, short value, ref byte[] data)
		{
			LittleEndian.PutShort(data, offset, value);
		}

		public override string ToString()
		{
			return Convert.ToString(_value, CultureInfo.CurrentCulture);
		}
	}
	public class ShortList
	{
		private short[] _array;

		private int _limit;

		private static int _default_size = 128;

		public int Count => _limit;

		public ShortList()
			: this(_default_size)
		{
		}

		public ShortList(ShortList list)
			: this(list._array.Length)
		{
			System.Array.Copy(list._array, 0, _array, 0, _array.Length);
			_limit = list._limit;
		}

		public ShortList(int InitialCapacity)
		{
			_array = new short[InitialCapacity];
			_limit = 0;
		}

		public void Add(int index, short value)
		{
			if (index > _limit)
			{
				throw new IndexOutOfRangeException();
			}
			if (index == _limit)
			{
				Add(value);
				return;
			}
			if (_limit == _array.Length)
			{
				GrowArray(_limit * 2);
			}
			System.Array.Copy(_array, index, _array, index + 1, _limit - index);
			_array[index] = value;
			_limit++;
		}

		public bool Add(short value)
		{
			if (_limit == _array.Length)
			{
				GrowArray(_limit * 2);
			}
			_array[_limit++] = value;
			return true;
		}

		public bool AddAll(ShortList c)
		{
			if (c._limit != 0)
			{
				if (_limit + c._limit > _array.Length)
				{
					GrowArray(_limit + c._limit);
				}
				System.Array.Copy(c._array, 0, _array, _limit, c._limit);
				_limit += c._limit;
			}
			return true;
		}

		public bool AddAll(int index, ShortList c)
		{
			if (index > _limit)
			{
				throw new IndexOutOfRangeException();
			}
			if (c._limit != 0)
			{
				if (_limit + c._limit > _array.Length)
				{
					GrowArray(_limit + c._limit);
				}
				System.Array.Copy(_array, index, _array, index + c._limit, _limit - index);
				System.Array.Copy(c._array, 0, _array, index, c._limit);
				_limit += c._limit;
			}
			return true;
		}

		public void Clear()
		{
			_limit = 0;
		}

		public bool Contains(short o)
		{
			bool flag = false;
			int num = 0;
			while (!flag && num < _limit)
			{
				if (_array[num] == o)
				{
					flag = true;
				}
				num++;
			}
			return flag;
		}

		public bool ContainsAll(ShortList c)
		{
			bool flag = true;
			if (this != c)
			{
				int num = 0;
				while (flag && num < c._limit)
				{
					if (!Contains(c._array[num]))
					{
						flag = false;
					}
					num++;
				}
			}
			return flag;
		}

