		public static string ToHexString(string s)
		{
			char[] array = s.ToCharArray();
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < array.Length; i++)
			{
				if (NeedToEncode(array[i]))
				{
					string value = ToHexString(array[i]);
					stringBuilder.Append(value);
				}
				else
				{
					stringBuilder.Append(array[i]);
				}
			}
			return stringBuilder.ToString();
		}

		public static string ToHexString(char chr)
		{
			return Convert.ToString(chr, 16);
		}

		public static string ToHexString(short chr)
		{
			return ToHexString((char)chr);
		}

		public static string ToHexString(int chr)
		{
			return ToHexString((char)chr);
		}

		public static string ToHexString(long chr)
		{
			return ToHexString((char)chr);
		}

		private static bool NeedToEncode(char chr)
		{
			string text = "$-_.+!*'(),@=&";
			if (chr > '\u007f')
			{
				return true;
			}
			if (char.IsLetterOrDigit(chr) || text.IndexOf(chr) >= 0)
			{
				return false;
			}
			return true;
		}

		public static string mapMsCodepointString(string string1)
		{
			if (string1 == null || "".Equals(string1))
			{
				return string1;
			}
			InitMsCodepointMap();
			StringBuilder stringBuilder = new StringBuilder();
			int length = string1.Length;
			int num;
			for (int i = 0; i < length; i += CharCount(num))
			{
				num = char.ConvertToUtf32(string1, i);
				int utf = msCodepointToUnicode[num];
				stringBuilder.Append(char.ConvertFromUtf32(utf));
			}
			return stringBuilder.ToString();
		}

		public static int toCodePoint(char high, char low)
		{
			return (int)(((uint)high << 10) + low + (65536 - ((uint)MIN_HIGH_SURROGATE << 10) - MIN_LOW_SURROGATE));
		}

		private static int codePointAt(char[] a, int index, int limit)
		{
			char c = a[index];
			if (char.IsHighSurrogate(c) && ++index < limit)
			{
				char c2 = a[index];
				if (char.IsLowSurrogate(c2))
				{
					return toCodePoint(c, c2);
				}
			}
			return c;
		}

		public static int CharCount(int codePoint)
		{
			if (codePoint < 65536)
			{
				return 1;
			}
			return 2;
		}

		public static void mapMsCodepoint(int msCodepoint, int unicodeCodepoint)
		{
			InitMsCodepointMap();
			msCodepointToUnicode.Add(msCodepoint, unicodeCodepoint);
		}

		private static void InitMsCodepointMap()
		{
			if (msCodepointToUnicode == null)
			{
				msCodepointToUnicode = new Dictionary<int, int>();
				int num = 61472;
				int[] array = symbolMap_f020;
				foreach (int value in array)
				{
					msCodepointToUnicode.Add(num++, value);
				}
				num = 61600;
				int[] array2 = symbolMap_f0a0;
				foreach (int value2 in array2)
				{
					msCodepointToUnicode.Add(num++, value2);
				}
			}
		}
	}
	public class SystemOutLogger : POILogger
	{
		private string _cat;

		public override void Initialize(string cat)
		{
			_cat = cat;
		}

		public override void Log(int level, object obj1)
		{
			Log(level, obj1, null);
		}

		public override void Log(int level, object obj1, Exception exception)
		{
			if (Check(level))
			{
				Console.WriteLine("[" + _cat + "] " + obj1);
				if (exception != null)
				{
					Console.Write(exception.StackTrace);
				}
			}
		}

		public override bool Check(int level)
		{
			int num;
			try
			{
				string text = ConfigurationManager.AppSettings["poi.log.level"];
				if (string.IsNullOrEmpty(text))
				{
					text = 5.ToString(CultureInfo.InvariantCulture);
				}
				num = int.Parse(text, CultureInfo.InvariantCulture);
			}
			catch (Exception)
			{
				num = 1;
			}
			if (level >= num)
			{
				return true;
			}
			return false;
		}
	}
	public class TempFile
	{
		private static string dir;

		public static FileInfo CreateTempFile(string prefix, string suffix)
		{
			if (dir == null)
			{
				dir = Directory.CreateDirectory(Path.GetTempPath() + "\\poifiles").FullName;
			}
			Random random = new Random(DateTime.Now.Millisecond);
			string text = prefix + random.Next() + suffix;
			if (File.Exists(text))
			{
				text = CreateTempFile(prefix, suffix).FullName;
			}
			FileStream fileStream = File.Create(text);
			fileStream.Close();
			return new FileInfo(text);
		}

		public static string GetTempFilePath(string prefix, string suffix)
		{
			if (dir == null)
			{
				dir = Directory.CreateDirectory(Path.GetTempPath() + "\\poifiles").FullName;
			}
			Random random = new Random(DateTime.Now.Millisecond);
			Thread.Sleep(10);
			return prefix + random.Next() + suffix;
		}
	}
	[Obsolete]
	public class ULongField
	{
		private ulong _value;

		private int _offset;

		public ulong Value
		{
			get
			{
				return _value;
			}
			set
			{
				_value = value;
			}
		}

		public ULongField(int offset)
		{
			if (offset < 0)
			{
				throw new IndexOutOfRangeException("Illegal offset: " + offset);
			}
			_offset = offset;
		}

		public ULongField(int offset, ulong value)
			: this(offset)
		{
			Value = value;
		}

		public ULongField(int offset, byte[] data)
		{
			_offset = offset;
			ReadFromBytes(data);
		}

		public ULongField(int offset, ulong value, byte[] data)
		{
			_offset = offset;
			Set(value, data);
		}

		public void Set(ulong value, byte[] data)
		{
			_value = value;
			WriteToBytes(data);
		}

		public void ReadFromBytes(byte[] data)
		{
			_value = LittleEndian.GetULong(data, _offset);
		}

		public void ReadFromStream(Stream stream)
		{
			_value = LittleEndian.ReadULong(stream);
		}

		public void WriteToBytes(byte[] data)
		{
			LittleEndian.PutULong(data, _offset, _value);
		}

		public override string ToString()
		{
			return Convert.ToString(_value);
		}
	}
